# plasmati_tables.py
####################################################################################################
# Read-only cell extraction for the historical laboratory exports.
#
# XLSX: standard-library XML/ZIP, cached formula values only.
# XLS: xlrd when installed; a bounded BIFF8 cached-cell reader otherwise.
# No macros, formulas, links or external commands are executed. This is NOT an
# Excel calculation engine; cached results must have been saved by the author.
import io, math, re, struct, zipfile
from dataclasses import dataclass, field
from pathlib import Path
from xml.etree import ElementTree as ET

ERRORS={0:'#NULL!',7:'#DIV/0!',15:'#VALUE!',23:'#REF!',29:'#NAME?',36:'#NUM!',42:'#N/A',43:'#GETTING_DATA'}
@dataclass
class Sheet:
    name: str
    cells: dict = field(default_factory=dict)
    formulas: dict = field(default_factory=dict)
    nrows: int = 0
    ncols: int = 0
    def put(self,r,c,v):
        self.nrows=max(self.nrows,r+1); self.ncols=max(self.ncols,c+1)
        if v is not None and v != '': self.cells[r,c]=v
    def cell(self,r,c,default=''):return self.cells.get((r,c),default)
    def row(self,r):return [self.cell(r,c) for c in range(self.ncols)]
    def rows(self):
        for r in range(self.nrows):yield self.row(r)

def _u32(b,o=0):return struct.unpack_from('<I',b,o)[0]
def _u16(b,o=0):return struct.unpack_from('<H',b,o)[0]

def _ole_workbook(data):
    if data[:8]!=bytes.fromhex('D0CF11E0A1B11AE1'):raise ValueError('Not an OLE Excel workbook.')
    sec=1<<_u16(data,30); mini=1<<_u16(data,32)
    if sec not in (512,4096) or mini!=64:raise ValueError('Unsupported compound-document sector size.')
    count=len(data)//sec-1
    def sector(i):
        if not 0<=i<count:raise ValueError('Corrupt compound-document sector reference.')
        return data[(i+1)*sec:(i+2)*sec]
    difat=list(struct.unpack_from('<109I',data,76)); sid=_u32(data,68)
    seen=set()
    for _ in range(_u32(data,72)):
        if sid in seen:raise ValueError('Cyclic DIFAT.')
        seen.add(sid); chunk=sector(sid)
        difat.extend(struct.unpack('<'+str(sec//4-1)+'I',chunk[:-4]));sid=_u32(chunk,sec-4)
    fat=[]
    for i in [i for i in difat if i<0xFFFFFFFA][:_u32(data,44)]:
        fat.extend(struct.unpack('<'+str(sec//4)+'I',sector(i)))
    def chain(start,table,getter,limit):
        result=[];seen=set();sid=start
        while sid<0xFFFFFFFA:
            if sid in seen or sid>=len(table) or len(seen)>limit:raise ValueError('Corrupt or cyclic OLE chain.')
            seen.add(sid);result.append(getter(sid));sid=table[sid]
        return b''.join(result)
    directory=chain(_u32(data,48),fat,sector,count)
    root=None;entry=None
    for o in range(0,len(directory)-127,128):
        d=directory[o:o+128];n=_u16(d,64)
        if n<2 or n>64:continue
        name=d[:n-2].decode('utf-16le')
        if d[66]==5:root=d
        if d[66]==2 and name.lower() in ('workbook','book'):entry=d
    if entry is None:raise ValueError('OLE document has no Workbook/Book stream.')
    size=struct.unpack_from('<Q',entry,120)[0];start=_u32(entry,116)
    if size>=_u32(data,56):return chain(start,fat,sector,count)[:size]
    if root is None:raise ValueError('OLE mini-stream root missing.')
    pool=chain(_u32(root,116),fat,sector,count)
    mf=chain(_u32(data,60),fat,sector,count)
    minifat=list(struct.unpack('<'+str(len(mf)//4)+'I',mf))
    def ms(i):
        if (i+1)*mini>len(pool):raise ValueError('Corrupt mini-stream reference.')
        return pool[i*mini:(i+1)*mini]
    return chain(start,minifat,ms,len(minifat))[:size]

class _Segments:
    def __init__(self,segs):self.segs=segs;self.i=0;self.p=0
    def remaining(self):return len(self.segs[self.i])-self.p
    def next(self):
        self.i+=1;self.p=0
        if self.i>=len(self.segs):raise ValueError('Truncated BIFF string table.')
    def read(self,n):
        out=[]
        while n:
            if self.remaining()==0:self.next()
            k=min(n,self.remaining());out.append(self.segs[self.i][self.p:self.p+k]);self.p+=k;n-=k
        return b''.join(out)
    def string(self,short=False):
        n=int.from_bytes(self.read(1 if short else 2),'little');flags=self.read(1)[0]
        runs=int.from_bytes(self.read(2),'little') if flags&8 else 0
        ext=int.from_bytes(self.read(4),'little') if flags&4 else 0
        wide=bool(flags&1);parts=[]
        while n:
            if self.remaining()==0:
                self.next();wide=bool(self.read(1)[0]&1)
            width=2 if wide else 1
            k=min(n,self.remaining()//width)
            if k==0:raise ValueError('Unsupported split BIFF Unicode character.')
            parts.append(self.read(k*width).decode('utf-16le' if wide else 'latin1'));n-=k
        if runs:self.read(runs*4)
        if ext:self.read(ext)
        return ''.join(parts)

def _records(data):
    o=0
    while o+4<=len(data):
        ident,size=struct.unpack_from('<HH',data,o)
        if o+4+size>len(data):raise ValueError('Truncated BIFF record.')
        yield o,ident,data[o+4:o+4+size];o+=4+size

def _rk(n):
    if n&2:
        x=struct.unpack('<i',struct.pack('<I',n))[0]>>2
    else:x=struct.unpack('<d',struct.pack('<II',0,n&0xFFFFFFFC))[0]
    return x/100 if n&1 else x

def read_biff8(data):
    stream=_ole_workbook(data); recs=list(_records(stream));shared=[];bounds=[]
    if not recs or recs[0][1]!=0x809 or _u16(recs[0][2])!=0x600:
        raise ValueError('Fallback reader requires BIFF8. Install xlrd for older XLS files.')
    for i,(off,k,b) in enumerate(recs):
        if k==0x2F:raise ValueError('Encrypted XLS is unsupported.')
        if k==0x85:
            if b[5] != 0:continue # charts and macros are not worksheets
            bounds.append((_u32(b),_Segments([b[6:]]).string(short=True)))
        if k==0xFC:
            segs=[b];j=i+1
            while j<len(recs) and recs[j][1]==0x3C:segs.append(recs[j][2]);j+=1
            seg=_Segments(segs);seg.read(4);unique=int.from_bytes(seg.read(4),'little')
            if unique>5000000:raise ValueError('Unreasonably large shared-string count.')
            shared=[seg.string() for _ in range(unique)]
    byoffset={o:i for i,(o,k,b) in enumerate(recs)};sheets=[]
    for off,name in bounds:
        sh=Sheet(name);sheets.append(sh);pending=None
        if off not in byoffset:raise ValueError('Invalid worksheet offset.')
        for _,k,b in recs[byoffset[off]+1:]:
            if k==0x0A:break
            if k in (0xFD,0x203,0x27E,0x205,0x204,6):
                r,c=_u16(b),_u16(b,2)
                if k==0xFD:v=shared[_u32(b,6)]
                elif k==0x203:v=struct.unpack_from('<d',b,6)[0]
                elif k==0x27E:v=_rk(_u32(b,6))
                elif k==0x205:v=ERRORS.get(b[6],'#ERROR!') if b[7] else bool(b[6])
                elif k==0x204:v=_Segments([b[6:]]).string()
                else:
                    sh.formulas[r,c]=b[22:22+_u16(b,20)].hex() if len(b)>=22 else ''
                    if b[12:14]==b'\xff\xff':
                        t=b[6];v=None
                        if t==0:pending=(r,c)
                        elif t==1:v=bool(b[8])
                        elif t==2:v=ERRORS.get(b[8],'#ERROR!')
                    else:v=struct.unpack_from('<d',b,6)[0]
                sh.put(r,c,v)
            elif k==0xBD:
                r,c=_u16(b),_u16(b,2)
                for o in range(4,len(b)-2,6):sh.put(r,c,_rk(_u32(b,o+2)));c+=1
            elif k==0x207 and pending is not None:
                sh.put(*pending,_Segments([b]).string());pending=None
    if not sheets:raise ValueError('No worksheets in XLS.')
    return sheets

N={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
def _tag(t):return '{'+N['m']+'}'+t

def read_xlsx(data):
    sheets=[]
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        if sum(i.file_size for i in z.infolist())>512*1024*1024:raise ValueError('Workbook expanded size exceeds safety limit.')
        strings=[]
        if 'xl/sharedStrings.xml' in z.namelist():
            strings=[''.join(t.text or '' for t in x.iter(_tag('t')))
                     for x in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',N)]
        rels={x.attrib['Id']:x.attrib['Target'] for x in ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))}
        for node in ET.fromstring(z.read('xl/workbook.xml')).findall('m:sheets/m:sheet',N):
            rid=node.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']
            target=rels[rid];target=target.lstrip('/') if target.startswith('/') else 'xl/'+target
            sh=Sheet(node.attrib['name']);sheets.append(sh)
            tree=ET.fromstring(z.read(target))
            for c in tree.findall('.//m:sheetData/m:row/m:c',N):
                addr=c.attrib.get('r','');m=re.fullmatch(r'([A-Z]+)(\d+)',addr)
                if not m:raise ValueError('Cell address missing in XLSX.')
                col=0
                for ch in m[1]:col=col*26+ord(ch)-64
                r,col=int(m[2])-1,col-1;kind=c.attrib.get('t','n');v=c.find('m:v',N);f=c.find('m:f',N)
                if f is not None:sh.formulas[r,col]=f.text or ''
                if kind=='inlineStr':value=''.join(t.text or '' for t in c.iter(_tag('t')))
                elif v is None or v.text is None:value=None
                elif kind=='s':value=strings[int(v.text)]
                elif kind=='b':value=v.text=='1'
                elif kind in ('e','str','d'):value=v.text
                else:
                    try:value=float(v.text)
                    except ValueError:value=v.text
                sh.put(r,col,value)
    return sheets

def read_workbook(path):
    data=Path(path).read_bytes()
    if data[:2]==b'PK':return read_xlsx(data)
    if data[:8]==bytes.fromhex('D0CF11E0A1B11AE1'):
        try:import xlrd
        except ImportError:return read_biff8(data)
        book=xlrd.open_workbook(file_contents=data,on_demand=True)
        try:
            out=[]
            for raw in book.sheets():
                sh=Sheet(raw.name)
                for r in range(raw.nrows):
                    for c in range(raw.ncols):
                        val=raw.cell_value(r,c)
                        if raw.cell_type(r,c)==5:val=ERRORS.get(int(val),'#ERROR!')
                        sh.put(r,c,val)
                out.append(sh)
            return out
        finally:book.release_resources()
    raise ValueError('File is not an XLS or XLSX workbook. Text/HTML exports need a separate importer.')


####################################################################################################
# plasmati_recognition.py
####################################################################################################
# Deterministic, reviewable ICP-OES analytical-method recognition.
#
# Never infer reporting limits from spectral overlap alone. A method is applied
# without intervention only when independently identifying evidence is strong.
# All evidence, confidence metrics, and mismatches are retained for the reviewer.

import re
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple


def _recognition_method_key(label: str) -> str:
    """Canonical method identifier. Do not confuse 48-1 and 48-2."""
    text = str(label).lower().replace('_', ' ').replace('–', '-').replace('—', '-')
    m = re.search(r'\bmethod\s*(\d+)\s*[-. ]\s*(\d+)\b', text)
    if m:
        return f'method {int(m.group(1))}-{int(m.group(2))}'
    return re.sub(r'\s+', '', text.strip())


ELEMENT_LIST = re.compile(r'[A-Z][a-z]?(?:\+[A-Z][a-z]?)*')


def label_key(label: str) -> str:
    """Key used to compare a library label with a name found in the folder or file names:
    'method 48-1' for numbered methods, 'elements Ca+Na+P' for element-list tables."""
    key = _recognition_method_key(label)
    if key.startswith('method '):
        return key
    text = re.sub(r'\s+', '', str(label))
    return 'elements ' + text if ELEMENT_LIST.fullmatch(text) else key


def extract_method_hints(paths: Iterable[str]) -> List[str]:
    """Extract explicit method identifiers only, never infer one from a date.

    A numbered method ("Method 48 - 1") anywhere in the path wins. Otherwise a folder or
    file name part in brackets that is only an element list, such as "(Na)" or
    "(Ca+K+Mg+Na+P+Si+Zn)", names the element table of the same name."""
    hints = set()
    elements = set()
    for path in paths:
        p = Path(str(path))
        # A saved project may hold the original run's paths; no files need exist.
        for token in [p.name, *[part for part in p.parent.parts if part not in ('.', '..')]]:
            for match in re.finditer(r'\bmethod\s*0*(\d+)\s*[-_. ]\s*0*(\d+)\b', str(token), re.I):
                hints.add(f'method {int(match.group(1))}-{int(match.group(2))}')
            for group in re.findall(r'\(([^()]*)\)', str(token)):
                text = re.sub(r'\s+', '', group)
                if ELEMENT_LIST.fullmatch(text):
                    elements.add('elements ' + text)
    return sorted(hints) if hints else sorted(elements)


def score_method(record: dict, measured: set) -> Dict[str, Any]:
    defined = {item['channel'] for item in record.get('channels', [])}
    common = len(measured & defined)
    coverage = common / len(measured) if measured else 0.0
    specificity = common / len(defined) if defined else 0.0
    union = len(measured | defined)
    jaccard = common / union if union else 0.0
    missing = sorted(measured - defined)
    return {
        'id': record.get('id', ''),
        'label': record.get('label', ''),
        'source': record.get('source', ''),
        'sha256': record.get('sha256', ''),
        'matched_channels': common,
        'measured_channels': len(measured),
        'method_channels': len(defined),
        'coverage': round(coverage, 6),
        'specificity': round(specificity, 6),
        'jaccard': round(jaccard, 6),
        'unmatched_measured_channels': missing[:30],
        'unmatched_measured_count': len(missing),
        'source_issues': record.get('issues', []),
    }


def recognize_method(paths: Iterable[str], measured_channels: Iterable[str], library: dict) -> Tuple[dict, Optional[dict]]:
    """Return an audit-ready decision and any safely selected method snapshot.

    Priority: unique explicit method ID supported by measured channels; otherwise
    near-perfect unique full channel signature. Partial common signatures can only
    produce review suggestions, never invented LOQs or a confident match.
    """
    measured = set(measured_channels)
    # the built-in limit table is not a method: it is never offered as the run's method
    records = [r for r in library.get('methods', []) if r.get('id') != library.get('master_id')]
    hints = extract_method_hints(paths)
    scores = [(score_method(r, measured), r) for r in records]
    scores.sort(key=lambda pair: (pair[0]['jaccard'], pair[0]['coverage'], pair[0]['matched_channels']), reverse=True)
    hint_matches = [(sc, rec) for sc, rec in scores if label_key(rec.get('label', '')) in hints]

    result = {
        'status': 'UNRESOLVED',
        'label': '',
        'source': '',
        'evidence': [],
        'hints': hints,
        'measured_channel_count': len(measured),
        'candidates': [sc for sc, _ in scores[:5]],
        'unmatched_channels': [],
        'message': '',
    }
    chosen = None
    if len(hints) > 1:
        result.update(status='REVIEW', message='Conflicting method identifiers in source paths. Choose the correct method explicitly.')
        result['evidence'].append('Contradictory explicit method IDs: ' + ', '.join(hints))
        return result, None
    if hints and len(hint_matches) == 1:
        sc, candidate = hint_matches[0]
        result.update(label=candidate.get('label', ''), source=candidate.get('source', ''),
                      unmatched_channels=sc['unmatched_measured_channels'],
                      evidence=['Explicit source-path method ID: ' + hints[0],
                                f'Analytical-channel overlap: {sc["matched_channels"]}/{len(measured)} ({sc["coverage"]:.1%})',
                                f'Method table source SHA-256: {sc["sha256"]}'])
        if sc['coverage'] < 0.80 or sc['matched_channels'] < 2:
            result.update(status='REVIEW', message='The named method conflicts with too many measured channels; nothing was applied.')
        elif sc['unmatched_measured_count']:
            result.update(status='REVIEW_APPLIED', message='Identified by method ID, but some measured channels are absent from the table. Review source notes and affected results.')
            chosen = candidate
        else:
            result.update(status='MATCHED', message='Method ID and every measured analytical channel agree with the historical method snapshot.')
            chosen = candidate
        return result, chosen
    if hints:
        result.update(status='REVIEW', message='A method ID was detected, but it was not found uniquely in the local library.')
        result['evidence'].append('Unmatched explicit method ID: ' + hints[0])
        return result, None

    if not scores or not measured:
        result['message'] = 'No method or measured analytical channels to compare.'
        return result, None
    sc, candidate = scores[0]
    margin = sc['jaccard'] - (scores[1][0]['jaccard'] if len(scores) > 1 else 0)
    result['evidence'] = [
        f'No explicit method ID; compared exact element + wavelength + axial/radial identities.',
        f'Best spectral fingerprint {sc["matched_channels"]}/{len(measured)} measured channels;',
        f'Jaccard match {sc["jaccard"]:.1%}; next-best margin {margin:.1%}.',
    ]
    result['label'] = candidate.get('label', '')
    result['source'] = candidate.get('source', '')
    result['unmatched_channels'] = sc['unmatched_measured_channels']
    # Require nearly equal sized spectral line sets; otherwise a generic method
    # containing many extra lines could win from a handful of common channels.
    if (len(measured) >= 8 and sc['coverage'] == 1.0 and sc['specificity'] >= 0.98
            and sc['jaccard'] >= 0.98 and margin >= 0.08):
        result.update(status='MATCHED', message='Unique near-exact instrument channel fingerprint; verify this historical method remains approved.')
        return result, candidate
    if sc['jaccard'] >= 0.45 and sc['matched_channels'] >= 4:
        result.update(status='REVIEW', message='Several stored methods fit the measured lines, so Plasmatti cannot tell which one was used.')
    else:
        result.update(status='UNRESOLVED', message='No stored method fits the measured lines well enough. Choose the method or import its table.')
    # Nothing was applied: gaps of the best-ranked candidate are not problems of this run.
    result['unmatched_channels'] = []
    return result, None


####################################################################################################
# plasmati_core.py
####################################################################################################
# Plasmatti numerical core.
#
# The core deliberately contains no GUI logic. It is intended for transparent,
# reviewable ICP-OES post-acquisition processing (NOT instrument calibration).
# Raw measurements are never overwritten. No unknown reporting limit is invented.
#
# The calculation rules (see docs/CALCULATION_RULES.md):
# channel score = mean of four absolute blank-corrected standard deviations;
# preference 1 retained within 10 % of preference 2; the laboratory's sequential
# 5 -> 4 -> 3 raw-RSD rule; linear sample-blank and standard-response
# interpolation on the original acquisition sequence; low/high branch chosen
# from the self-consistent final solution concentration with threshold
# high/2; corrected SD = SD / |factor|; dilution and mass/volume conversion.

import csv
import hashlib
import json
import math
import os
import re
from collections import defaultdict
from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from pathlib import Path
from statistics import mean, median, stdev
from typing import Any, Dict, List, Optional, Sequence, Tuple

APP_NAME = 'Plasmatti'
APP_VERSION = '1.0.0'

APP_DEVELOPER_TEXT = ('Plasmatti was developed by the Laboratory of High Temperature Processes and Materials '
                      'at \u00c5bo Akademi University, Finland.')
APP_PAPER_TITLE = 'Plasmatti: An open-source desktop application for automated processing of ICP-OES data'
# Plain-text citation (export files) and rich text (screen). Update when the paper is published.
APP_CITATION_TEXT = ('Farzad Jafarihonar, Luis Bezerra and Emil Vainio, '
                     f'\u201c{APP_PAPER_TITLE}.\u201d')
APP_CITATION_HTML = ('Farzad Jafarihonar, Luis Bezerra and Emil Vainio, '
                     f'\u201c<b>{APP_PAPER_TITLE}</b>.\u201d')
NO_SD = 'n/a'   # shown instead of a standard deviation when none applies (below limit, blocked)
ROLES = ('Sample', 'Standard', 'Sample blank', 'Standard blank', 'Both blanks', 'Ignore')
CHANNEL_RE = re.compile(r'^\s*([A-Z][a-z]?)\s+(\d{3}\.\d{3})\s+(axial|radial|unknown)\s*$', re.I)
STANDARD_RE = re.compile(r'(?<![\d.,])(\d+(?:[.,]\d+)?)\s*(?:ppm|mg\s*/\s*l)\b', re.I)
GENERIC_ELEMENTS = {
    'Al', 'As', 'B', 'Ba', 'Be', 'Ca', 'Cd', 'Co', 'Cr', 'Cu', 'Fe', 'Hg', 'K', 'Li', 'Mg', 'Mn',
    'Mo', 'Na', 'Ni', 'P', 'Pb', 'S', 'Sb', 'Se', 'Si', 'Sn', 'Sr', 'Ti', 'V', 'Zn', 'Zr'
}

# Result-status categories shared by GUI, CLI and export.
ATTENTION_FLAGS = ('HIGH_RSD', 'SUMMARY_ONLY', 'MISSING_SD', 'REVIEW', 'ONE_STANDARD', 'OTHER_WAVELENGTH', 'OTHER_BLANK')
CATEGORY_LABELS = {'ok': 'OK', 'below_limit': 'Below reporting limit',
                   'attention': 'Needs attention', 'blocked': 'Blocked (not calculated)'}


def result_category(flags: Sequence[str]) -> str:
    """'blocked' > 'attention' > 'below_limit' > 'ok'.

    Below-limit results are ordinary reportable outcomes, not failures. A
    below-limit result that ALSO has e.g. HIGH_RSD is 'attention'.
    """
    flags = list(flags)
    if 'BLOCKED' in flags:
        return 'blocked'
    if any(f in ATTENTION_FLAGS or f.startswith('MISSING_') for f in flags):
        return 'attention'
    if any(f.startswith('BELOW_') for f in flags):
        return 'below_limit'
    return 'ok'


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _float(text: Any) -> float:
    """Legacy generic parser for typed values and vial labels (strict 'auto')."""
    pass
    return number(text)


def finite_positive(value: float, label: str) -> float:
    if value is None:
        raise ValueError(f'{label} is missing.')
    number = float(value)
    if not math.isfinite(number) or number <= 0:
        raise ValueError(f'{label} must be a finite positive number.')
    return number


def checksum(path: str) -> str:
    h = hashlib.sha256()
    with open(path, 'rb') as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def split_channel(channel: str) -> Tuple[str, str, str]:
    m = CHANNEL_RE.fullmatch(channel)
    if not m:
        raise ValueError(f'Invalid analytical channel: {channel!r}')
    return m.group(1).capitalize(), m.group(2), m.group(3).lower()


def percent_rsd(values: Sequence[float]) -> float:
    """Raw RSD = 100 * sample SD (n-1) / |mean|.

    Near-zero mean: if |mean| < 1e-14 the RSD is 0 when SD is also ~0, else
    infinite (documented convention; such a record exceeds any RSD gate).
    """
    if len(values) < 2:
        return math.inf
    s = stdev(values)
    avg = mean(values)
    if abs(avg) < 1e-14:
        return 0.0 if abs(s) < 1e-14 else math.inf
    return 100.0 * s / abs(avg)


@dataclass
class Reading:
    sequence: int
    position: int
    sample_id: str
    channel: str
    replicates: List[float] = field(default_factory=list)
    instrument_mean: Optional[float] = None
    instrument_sd: Optional[float] = None
    instrument_rsd: Optional[float] = None
    instrument_error: str = ''
    source: str = ''
    acquisition_time: str = ''
    replicate_times: List[str] = field(default_factory=list)
    exported_replicate_count: int = 0
    calibration_mean: Optional[float] = None
    sequence_inferred: bool = False
    mapped_sample_id: str = ''
    summary_source: str = ''
    import_notes: List[str] = field(default_factory=list)

    @property
    def element(self) -> str:
        return split_channel(self.channel)[0]

    @property
    def raw_mean(self) -> float:
        if self.instrument_error:
            raise ValueError(f'{self.sample_id}, {self.channel}: {self.instrument_error}')
        if self.instrument_mean is not None:
            return float(self.instrument_mean)
        if self.replicates:
            return mean(self.replicates)
        raise ValueError(f'{self.sample_id}: {self.channel} has no usable concentration ({self.instrument_error or "not measured"}).')

    @property
    def raw_sd(self) -> Optional[float]:
        return self.instrument_sd if self.instrument_sd is not None else (stdev(self.replicates) if len(self.replicates) > 1 else None)


@dataclass
class Assignment:
    sequence: int
    position: int
    sample_id: str
    role: str = 'Sample'
    standard_level: Optional[float] = None
    standard_element: str = '?'  # unresolved; '*' is an explicit all-elements override
    report_name: str = ''
    report: bool = True
    dilution: float = 1.0
    mass_g: Optional[float] = None
    volume_ml: Optional[float] = None
    moisture_pct: Optional[float] = None
    standard_multipliers: Dict[str, float] = field(default_factory=dict)
    scope_source: str = ''
    # Explicit per-element branch choice, only when a reviewer has resolved it.
    standard_overrides: Dict[str, str] = field(default_factory=dict)
    # '' = preparation values are defaults that nobody has confirmed.
    preparation_source: str = ''


@dataclass
class ChannelSetting:
    channel: str
    preference_order: Optional[int] = None
    dl_mg_l: Optional[float] = None
    dl_mg_kg: Optional[float] = None
    manual_select: bool = False
    enabled: bool = True
    limit_kind: str = 'DL'
    limit_source: str = ''
    limit_source_sha256: str = ''


@dataclass
class RunSettings:
    sample_type: str = 'Liquid'
    project: str = ''
    requester: str = ''
    method: str = ''
    rsd_limit: float = 3.0
    relative_preference_tolerance: float = 0.10
    high_standard_boundary_fraction: float = 0.50
    # True = perform up to two replicate removals; False = just flag high RSD
    auto_filter: bool = True
    # Preserve higher-precision exported mean/SD when no replicate was removed.
    statistics_basis: str = 'instrument_when_unfiltered'
    # Solid limits: 'sample_specific' = LOQ (mg/L) x final volume / mass x dilution for each sample.
    # 'lab_stored' (a fixed mg/kg value from the table) is kept only to recalculate old saved projects.
    limit_policy: str = 'sample_specific'
    # The limit applies to the measured solution, so it is multiplied by the dilution. 'as_supplied' is kept
    # only to recalculate old saved projects.
    dilution_limit_policy: str = 'scale_with_dilution'
    # Fail visibly when final-result-based branch selection is not unique.
    boundary_policy: str = 'review'
    # '' = the default 'Liquid' has not been confirmed by evidence or analyst.
    sample_type_source: str = ''
    # Solids: 'as_weighed' (default) or 'dry' (uses measured moisture).
    reporting_basis: str = 'as_weighed'
    # Defaults agreed with the laboratory (19 Oct 2026); the alternatives stay selectable.
    # 'two_point': calibration line through the blank (0), the low and the high standard (default):
    #              below the low standard the line through zero, above it the line through both standards.
    # 'single_standard': the laboratory's earlier rule: one standard, the low one if the raw mean is at
    #                    most the switch point (high level x high_standard_boundary_fraction), else the high one.
    correction_model: str = 'two_point'
    # 'dixon': Dixon's Q test at 95 %, one suspect value, only for results above the limit (default).
    # 'lab_rsd': the laboratory's rule: remove the farthest replicate while RSD > rsd_limit, at most 2.
    replicate_rule: str = 'dixon'
    # 'percent': wavelength score = mean |S - L| / L x 100 (default); 'mg_l': mean |S - L| in mg/L (earlier).
    channel_score: str = 'percent'
    # Reporting unit; '' = mg/L for liquids, mg/kg for solids.
    report_unit: str = ''
    # 'master': preference and limits from the master table (zz1) for every run (default);
    # 'method_table': the run's own method table from the library (earlier behaviour).
    method_source: str = 'master'


@dataclass
class Result:
    sequence: int
    position: int
    sample_id: str
    report_name: str
    element: str
    channel: str
    original_mean: float
    corrected_mean_mg_l: Optional[float]
    corrected_sd_mg_l: Optional[float]
    report_value: Optional[float]
    report_sd: Optional[float]
    units: str
    reported: str
    sd_display: str
    dl: Optional[float]
    rsd_initial: float
    rsd_final: float
    n_initial: int
    n_kept: int
    kept_indices: List[int]
    rejected_indices: List[int]
    raw_replicates: List[float]
    corrected_replicates_mg_l: List[float]
    blank: Optional[float]
    standard_factor: Optional[float]
    standard_level: Optional[float]
    applied_dilution: float
    status: str
    notes: List[str] = field(default_factory=list)
    flags: List[str] = field(default_factory=list)
    limit_kind: str = 'DL'
    limit_policy: str = ''
    statistics_basis: str = ''
    corrected_rsd: Optional[float] = None
    source: str = ''
    category: str = ''
    # Solids only: solution concentration in the measured digest (mg/L,
    # including the additional dilution) as shown in the laboratory's mg/L report block.
    solution_value: Optional[float] = None
    solution_sd: Optional[float] = None
    solution_limit: Optional[float] = None
    solution_reported: str = ''
    solution_sd_display: str = ''
    low_candidate_mg_l: Optional[float] = None
    high_candidate_mg_l: Optional[float] = None
    regime_threshold_mg_l: Optional[float] = None
    mass_used_g: Optional[float] = None
    volume_ml: Optional[float] = None
    # Two-point line  y = a × C + b  (a = cal_slope, b = cal_intercept, mg/L)
    correction_model: str = ''
    cal_slope: Optional[float] = None
    cal_intercept: Optional[float] = None
    solution_mg_l: Optional[float] = None          # C in the measured solution (before dilution)
    replicate_rule: str = ''
    # Information marks (they do not change the category): 'ABOVE_RANGE' (above the highest standard, ↑)
    # and 'STANDARD_OFF' (corrected with a standard reading more than 10 % from its nominal value, †).
    marks: List[str] = field(default_factory=list)


