def parse_normalized_csv(path: str) -> List[Reading]:
    """Import Plasmatti's documented long-format CSV, with 0 to N replicate columns.

    Supported headers (case insensitive): sequence, position, sample_id,
    channel; either mean_mg_l + sd_mg_l or rep1...repN. Numbers use a dot as
    the decimal mark (explicit format; commas only as valid thousands groups).
    """
    pass
    for encoding in ('utf-8-sig', 'cp1252'):
        try:
            with open(path, 'r', encoding=encoding, newline='') as f:
                rows = list(csv.DictReader(f))
            break
        except UnicodeDecodeError:
            continue
    else:
        raise ValueError('Unable to decode CSV as UTF-8 or Windows-1252.')
    if not rows:
        raise ValueError('No rows in normalized CSV.')

    def normalized(row):
        return {str(k).strip().lower(): v for k, v in row.items() if k is not None}

    def num(text):
        return number(text, decimal='dot')
    result = []
    for i, original in enumerate(rows, start=2):
        row = normalized(original)
        required = ('sequence', 'position', 'sample_id', 'channel')
        if any(not (row.get(k) or '').strip() for k in required):
            raise ValueError(f'CSV row {i}: expected columns sequence, position, sample_id and channel.')
        channel = row['channel'].strip()
        split_channel(channel)
        rep_keys = sorted((k for k in row if re.fullmatch(r'rep\d+', k)), key=lambda k: int(k[3:]))
        reps = [num(row[k]) for k in rep_keys if str(row[k] or '').strip()]
        avg = num(row['mean_mg_l']) if (row.get('mean_mg_l') or '').strip() else None
        sd = num(row['sd_mg_l']) if (row.get('sd_mg_l') or '').strip() else None
        error = str(row.get('instrument_error', '') or '').strip()
        if not reps and avg is None and not error:
            raise ValueError(f'CSV row {i}: expected mean_mg_l, rep1...repN, or an explicit instrument_error.')
        rsd = num(row['rsd_pct']) if (row.get('rsd_pct') or '').strip() else None
        count = int(num(row['replicate_count'])) if (row.get('replicate_count') or '').strip() else len(reps)
        result.append(Reading(
            sequence=int(num(row['sequence'])), position=int(num(row['position'])),
            sample_id=row['sample_id'].strip(), channel=channel,
            replicates=reps, instrument_mean=avg, instrument_sd=sd,
            instrument_rsd=rsd, instrument_error=error,
            exported_replicate_count=count,
            source=os.path.basename(path),
        ))
    keys = [(r.sequence, r.channel) for r in result]
    if len(keys) != len(set(keys)):
        raise ValueError('CSV contains multiple rows for the same sequence/channel. Use one row per channel.')
    return sorted(result, key=lambda r: (r.sequence, r.channel))


def load_files(paths: Sequence[str], autosampler_path: Optional[str] = None, details=None) -> Tuple[List[Reading], List[str]]:
    pass
    return load_run_files(paths, autosampler_path=autosampler_path, details=details)


def auto_assign(readings: Sequence[Reading]) -> Dict[int, Assignment]:
    """Compatibility wrapper around the single identification service.

    An earlier development build had a second, divergent classifier here. The roles come
    from plasmati_automation.identify() for the GUI, CLI and this function.
    """
    pass
    project = Project(list(readings), _initial_assignments(readings), lines_for_run(readings))
    identify(project)
    return project.assignments


def _initial_assignments(readings: Sequence[Reading]) -> Dict[int, Assignment]:
    first: Dict[int, Reading] = {}
    for reading in readings:
        first.setdefault(reading.sequence, reading)
    return {seq: Assignment(sequence=seq, position=r.position, sample_id=r.sample_id.strip(),
                            report_name='')
            for seq, r in sorted(first.items())}


def lines_for_run(readings: Sequence[Reading]) -> Dict[str, ChannelSetting]:
    return {channel: ChannelSetting(channel) for channel in sorted({r.channel for r in readings})}


def filter_replicates(reading: Reading, rsd_limit: float, enabled: bool = True,
                      use_instrument_statistics: bool = True, rule: str = 'lab_rsd'
                      ) -> Tuple[List[float], List[int], List[int], float, float]:
    """the laboratory's sequential 5->4->3 rule, not a formal statistical outlier test.

    The original export remains intact. Equal deviations remove the highest
    original index first (explicit deterministic tie convention).
    """
    finite_positive(rsd_limit, 'RSD threshold')
    if reading.instrument_error:
        raise ValueError(reading.instrument_error)
    values = list(reading.replicates)
    if not values:
        avg = reading.raw_mean
        initial = reading.instrument_rsd
        if initial is None:
            initial = 100 * reading.raw_sd / abs(avg) if reading.raw_sd is not None and avg else math.inf
        return [avg], [], [], initial, initial
    if len(values) < 3:
        raise ValueError('Fewer than three exported replicates: confirm completeness; no partial automatic acceptance.')
    if any(not math.isfinite(v) for v in values):
        raise ValueError('Invalid replicate concentration; partial acceptance is not automatic.')
    if reading.exported_replicate_count and len(values) != reading.exported_replicate_count:
        raise ValueError('Missing replicate attempts: complete the record before filtering.')
    initial = reading.instrument_rsd if use_instrument_statistics else None
    if initial is None:
        initial = percent_rsd(values)
    keep = list(range(len(values)))
    current = initial
    if enabled and rule == 'dixon' and len(values) >= 4:
        # At least 3 replicates are always kept (as with the RSD rule): with 3, no Dixon removal.
        idx, _, _, _ = dixon_test(values)
        if idx is not None:
            keep.remove(idx)
            current = percent_rsd([values[i] for i in keep])
    elif enabled:
        for _ in range(min(2, max(0, len(values) - 3))):
            if current <= rsd_limit:
                break
            avg = mean(values[i] for i in keep)
            furthest = max(keep, key=lambda i: (abs(values[i] - avg), i))
            keep.remove(furthest)
            current = percent_rsd([values[i] for i in keep])
    removed = [i + 1 for i in range(len(values)) if i not in keep]
    return [values[i] for i in keep], [i + 1 for i in keep], removed, initial, current


def interpolate(seq: int, a_seq: int, a_value: float, b_seq: int, b_value: float) -> float:
    if b_seq <= a_seq:
        raise ValueError('Correction endpoints must be strictly increasing.')
    if not a_seq <= seq <= b_seq:
        raise ValueError(f'Sequence {seq} is outside brackets {a_seq}-{b_seq}.')
    if not all(math.isfinite(v) for v in (a_value, b_value)):
        raise ValueError('Nonfinite correction endpoint.')
    return a_value + (b_value - a_value) * (seq - a_seq) / (b_seq - a_seq)


def reporting_decimals(value: float) -> int:
    mag = abs(float(value))
    return 3 if mag < 10 else 2 if mag < 100 else 1 if mag < 1000 else 0


def display_decimals(value: float, uf: float = 1.0) -> int:
    """Decimals for the reported mean, rechecked after rounding (9.9996 -> 10.00).

    The rule (3 decimals below 10, 2 below 100, 1 below 1000, else 0) is applied in mg/L or mg/kg.
    In another unit (uf = factor from mg/L or mg/kg) the decimals move with the unit, so the same
    digits are shown: 0.123 mg/L = 0.000123 g/L = 123 µg/L."""
    base = value / uf
    dp = reporting_decimals(base)
    dp = min(dp, reporting_decimals(round(base, dp)))
    return max(0, dp + round(math.log10(1 / uf)))


def format_sample_limit(limit: float, uf: float = 1.0) -> str:
    """A limit calculated for one sample (mg/kg of a solid), rounded half-up with the result rule:
    0.299820108 -> '0.300', 24.6986762 -> '24.70'."""
    from decimal import Decimal, ROUND_HALF_UP
    d = display_decimals(limit, uf)
    q = Decimal(repr(float(limit))).quantize(Decimal(1).scaleb(-d), rounding=ROUND_HALF_UP)
    return f'{q:.{d}f}'


def format_report(value: float, extra: int = 0, uf: float = 1.0) -> str:
    dp = display_decimals(value, uf)
    return f'{value:.{dp + extra}f}'


def format_dl(dl: float) -> str:
    return f'{dl:.9g}'


def _reading_lookup(readings: Sequence[Reading]) -> Dict[Tuple[int, str], Reading]:
    out = {}
    for r in readings:
        key = r.sequence, r.channel
        if key in out:
            raise ValueError(f'Duplicate measurement identity {key}. Do not merge separate runs.')
        out[key] = r
    return out


def _bracket_samples(assignments: Dict[int, Assignment], seq: int, roles: Tuple[str, ...]) -> Tuple[int, int]:
    seqs = sorted(a.sequence for a in assignments.values() if a.role in roles)
    pre = [s for s in seqs if s < seq]
    post = [s for s in seqs if s > seq]
    if not pre or not post:
        raise ValueError('Missing bracketing sample blank(s). Check Run roles.')
    return pre[-1], post[0]


def _scope_elements(assignment: Assignment) -> List[str]:
    return [x for x in re.split(r'[,+;\s]+', assignment.standard_element) if x]


def _scope_contains(assignment: Assignment, element: str) -> bool:
    return assignment.standard_element == '*' or element in _scope_elements(assignment)


def _standards_plain(project: Project, element: str, channel: str, sample_min: int, sample_max: int,
                     book: Dict[Tuple[int, str], Reading], blank_override: Optional[Dict[str, int]] = None
                     ) -> Dict[float, Tuple[Tuple[int, float], Tuple[int, float]]]:
    """Use element-specific preparations first, otherwise a documented group.
    Standards require a standard blank in the SAME before/after region.
    All levels are read from actual preparations; stock concentration is not
    substituted for the nominal concentration of a measured vial.
    """
    standards = [a for a in project.assignments.values() if a.role == 'Standard' and
                 a.standard_level is not None and _scope_contains(a, element)]
    by_level = defaultdict(list)
    for a in standards:
        lvl = float(a.standard_level) * a.standard_multipliers.get(element, 1.0)
        if lvl <= 0 or not math.isfinite(lvl):
            continue
        by_level[lvl].append(a)
    blanks_all = [b for b in project.assignments.values() if b.role in ('Standard blank', 'Both blanks')]
    output = {}
    for lvl, candidates in sorted(by_level.items()):
        corrected = []
        for side in ('before', 'after'):
            cs = [a for a in candidates if (a.sequence < sample_min if side == 'before' else a.sequence > sample_max)]
            cs.sort(key=lambda a: (a.standard_element != element,
                                   len(_scope_elements(a)) if a.standard_element != '*' else 999,
                                   abs(a.sequence - (sample_min if side == 'before' else sample_max))))
            val = None
            for a in cs:
                if blank_override and side in blank_override:
                    b = project.assignments[blank_override[side]]
                else:
                    blanks = [b for b in blanks_all if b.sequence < a.sequence
                              and (b.sequence < sample_min if side == 'before' else b.sequence > sample_max)]
                    if not blanks:
                        continue
                    b = max(blanks, key=lambda x: x.sequence)
                rr = book.get((a.sequence, channel))
                br = book.get((b.sequence, channel))
                if rr is None or br is None:
                    continue
                try:
                    value = rr.raw_mean - br.raw_mean
                    if not math.isfinite(value) or value <= 0:
                        continue
                except ValueError:
                    continue
                val = (a.sequence, value)
                break
            if val is not None:
                corrected.append(val)
        if len(corrected) == 2:
            output[lvl] = (corrected[0], corrected[1])
    return output


def _has_value(r) -> bool:
    return r is not None and not r.instrument_error and (bool(r.replicates) or r.instrument_mean is not None)


def _blank_check(project: Project, element: str, channel: str, sample_min: int, sample_max: int,
                 book: Dict[Tuple[int, str], Reading], side: str) -> Optional[Dict[str, Any]]:
    """Whether the standards on one side of the samples should be corrected with the standard blank of the
    other side (agreed with the laboratory, 29 October 2026).

    Used only when, on this side, a standard reads no more than its own standard blank. The raw readings of
    the lowest and highest standard on this side give a straight line; where it meets zero concentration is
    the blank that is really under these standards. The other side's standard blank is used when that point
    agrees with it (within 10 % of the low standard) and not with this side's own blank. Returns None when the
    rule does not apply, else a dict with ok=True/False and the numbers."""
    other = 'after' if side == 'before' else 'before'
    on_side = (lambda q: q < sample_min) if side == 'before' else (lambda q: q > sample_max)
    on_other = (lambda q: q < sample_min) if other == 'before' else (lambda q: q > sample_max)
    std_blanks = [b for b in project.assignments.values() if b.role in ('Standard blank', 'Both blanks')]
    readings = {}
    for lvl in _planned_levels(project, element):
        cands = [a for a in project.assignments.values() if a.role == 'Standard' and a.standard_level is not None
                 and _scope_contains(a, element) and on_side(a.sequence)
                 and abs(float(a.standard_level) * a.standard_multipliers.get(element, 1.0) - lvl) < 1e-12]
        cands.sort(key=lambda a: abs(a.sequence - (sample_min if side == 'before' else sample_max)))
        for a in cands:
            r = book.get((a.sequence, channel))
            if _has_value(r):
                readings[lvl] = (a, r.raw_mean)
                break
    if len(readings) < 2:
        return None
    lo, hi = min(readings), max(readings)

    def blank_before(seq, side_test):
        bs = [b for b in std_blanks if b.sequence < seq and side_test(b.sequence)]
        return max(bs, key=lambda b: b.sequence) if bs else None
    own = blank_before(readings[lo][0].sequence, on_side)
    if own is None or not _has_value(book.get((own.sequence, channel))):
        return None
    own_v = book[(own.sequence, channel)].raw_mean
    if all(raw - own_v > 0 for _, raw in readings.values()):
        return None                          # this side's own blank works: nothing to do
    other_stds = [a for a in project.assignments.values() if a.role == 'Standard' and a.standard_level is not None
                  and _scope_contains(a, element) and on_other(a.sequence)]
    if not other_stds:
        return None
    first_other = min(other_stds, key=lambda a: a.sequence)
    alt = blank_before(first_other.sequence, on_other)       # the standard blank in front of the other side's standards
    if alt is None or not _has_value(book.get((alt.sequence, channel))):
        return None
    alt_v = book[(alt.sequence, channel)].raw_mean
    r_lo, r_hi = readings[lo][1], readings[hi][1]
    zero = r_lo - (r_hi - r_lo) / (hi - lo) * lo
    tol = STANDARD_CHECK_TOLERANCE * lo
    ok = (abs(zero - alt_v) <= tol and abs(zero - own_v) > tol
          and all(raw - alt_v > 0 for _, raw in readings.values()))
    return {'ok': ok, 'side': side, 'other': other, 'own_seq': own.sequence, 'own_pos': own.position,
            'own_name': own.sample_id, 'own': own_v, 'used_seq': alt.sequence, 'used_pos': alt.position,
            'used_name': alt.sample_id, 'used': alt_v, 'zero': zero, 'low': lo, 'high': hi}


def blank_check_text(fix: Dict[str, Any], element: str) -> str:
    """The remark for a result whose standards were corrected with the other side's standard blank."""
    return (f'The standard blank {fix["side"]} the samples ("{fix["own_name"]}", autosampler position {fix["own_pos"]}, '
            f'measurement {fix["own_seq"]}) reads {fix["own"]:.4g} mg/L {element}, as much as or more than a standard, so '
            f'the standards {fix["side"]} the samples were corrected with the standard blank {fix["other"]} the samples '
            f'("{fix["used_name"]}", autosampler position {fix["used_pos"]}, measurement {fix["used_seq"]}, '
            f'{fix["used"]:.4g} mg/L). The standards {fix["side"]} the samples agree with it: the line '
            f'through the {fix["low"]:g} and {fix["high"]:g} mg/L standards gives {fix["zero"]:.3g} mg/L at zero '
            'concentration.')


def _standards_for_element(project: Project, element: str, channel: str, sample_min: int, sample_max: int,
                           book: Dict[Tuple[int, str], Reading], info: Optional[Dict[str, Any]] = None
                           ) -> Dict[float, Tuple[Tuple[int, float], Tuple[int, float]]]:
    """Use element-specific preparations first, otherwise a documented group.
    Standards require a standard blank in the SAME before/after region; only when that blank reads as much as a
    standard and the standards themselves show that the other side's blank fits them, that one is used
    (_blank_check; the result is then marked OTHER_BLANK)."""
    out = _standards_plain(project, element, channel, sample_min, sample_max, book)
    if len(out) >= 2 or len(_planned_levels(project, element)) < 2:
        return out
    for side in ('after', 'before'):
        fix = _blank_check(project, element, channel, sample_min, sample_max, book, side)
        if fix and fix['ok']:
            fixed = _standards_plain(project, element, channel, sample_min, sample_max, book,
                                     blank_override={side: fix['used_seq']})
            if len(fixed) >= 2:
                if info is not None:
                    info.update(fix)
                return fixed
    return out


def standard_pair_problems(project: Project, element: str, channel: str, sample_min: int, sample_max: int,
                           book: Dict[Tuple[int, str], Reading]) -> List[str]:
    """Why a standard level of this element has no usable reading before or after the samples, in plain words
    (the same checks as _standards_for_element, which takes the first usable standard on each side)."""
    unit = 'mg/L'
    out = []
    usable = _standards_for_element(project, element, channel, sample_min, sample_max, book)
    blanks_all = [b for b in project.assignments.values() if b.role in ('Standard blank', 'Both blanks')]
    for lvl in _planned_levels(project, element):
        if lvl in usable:
            continue
        cands = [a for a in project.assignments.values() if a.role == 'Standard' and a.standard_level is not None
                 and _scope_contains(a, element)
                 and abs(float(a.standard_level) * a.standard_multipliers.get(element, 1.0) - lvl) < 1e-12]
        for side, label in (('before', 'before'), ('after', 'after')):
            cs = [a for a in cands if (a.sequence < sample_min if side == 'before' else a.sequence > sample_max)]
            if not cs:
                out.append(f'no {lvl:g} {unit} standard was measured {label} the samples')
                continue
            a = min(cs, key=lambda x: abs(x.sequence - (sample_min if side == 'before' else sample_max)))
            blanks = [b for b in blanks_all if b.sequence < a.sequence
                      and (b.sequence < sample_min if side == 'before' else b.sequence > sample_max)]
            if not blanks:
                out.append(f'the {lvl:g} {unit} standard {label} the samples has no standard blank measured before it')
                continue
            b = max(blanks, key=lambda x: x.sequence)
            rr, br = book.get((a.sequence, channel)), book.get((b.sequence, channel))
            if rr is None or rr.instrument_error or (not rr.replicates and rr.instrument_mean is None):
                why = f' ({rr.instrument_error.rstrip(".")})' if rr is not None and rr.instrument_error else ''
                out.append(f'the {lvl:g} {unit} standard {label} the samples has no value{why}')
                continue
            if br is None or br.instrument_error or (not br.replicates and br.instrument_mean is None):
                out.append(f'its standard blank {label} the samples ({b.sample_id}) has no value')
                continue
            try:
                s_val, b_val = rr.raw_mean, br.raw_mean
            except ValueError:
                continue
            if s_val - b_val <= 0:
                fix = None if s_val < 0.1 * lvl else _blank_check(project, element, channel, sample_min, sample_max,
                                                                 book, side)
                if fix and not fix['ok']:
                    out.append(f'the {lvl:g} {unit} standard {label} the samples reads {s_val:.4g} {unit}, but its standard '
                               f'blank "{b.sample_id}" reads {b_val:.4g} {unit}; the standard blank {fix["other"]} the samples '
                               f'({fix["used"]:.4g} {unit}) was not used instead, because the standards {label} the samples do '
                               f'not agree with it (the line through them gives {fix["zero"]:.3g} {unit} at zero concentration)')
                    continue
                if s_val < 0.1 * lvl:
                    # the standard itself shows (almost) nothing: not a blank problem
                    out.append(f'the {lvl:g} {unit} standard {label} the samples reads only {s_val:.4g} {unit}; check that '
                               f'this standard contains {element} and that this wavelength works')
                else:
                    note = ('; this can be carry-over from the samples into the acid'
                            if side == 'after' and b_val > 0.1 * lvl else '')
                    out.append(f'the {lvl:g} {unit} standard {label} the samples reads {s_val:.4g} {unit}, but its standard '
                               f'blank "{b.sample_id}" reads {b_val:.4g} {unit}, as much or more{note}')
    return out


def _planned_levels(project: Project, element: str) -> List[float]:
    """The standard levels labelled for this element (whether or not their readings are usable)."""
    levels = set()
    for a in project.assignments.values():
        if a.role == 'Standard' and a.standard_level is not None and _scope_contains(a, element):
            lvl = float(a.standard_level) * a.standard_multipliers.get(element, 1.0)
            if lvl > 0 and math.isfinite(lvl):
                levels.add(lvl)
    return sorted(levels)


def _low_only_level(ctx, element: str) -> Optional[float]:
    planned = _planned_levels(ctx.project, element)
    if len(planned) < 2:
        return None
    low = planned[0]
    channels = [c for c, cfg in ctx.project.channels.items() if cfg.enabled and split_channel(c)[0] == element]
    usable = [sorted(ctx.standards(element, c)) for c in channels]
    if any(levels and levels != [low] for levels in usable):
        return None          # a higher standard is usable on some wavelength: the normal calculation applies
    if not any(levels == [low] for levels in usable):
        return None
    # The higher standards must be unusable because the instrument gave no value (for example saturated),
    # not because they read a value that does not fit: that points to a problem to be looked at.
    highs = [a.sequence for a in ctx.project.assignments.values() if a.role == 'Standard' and a.standard_level is not None
             and _scope_contains(a, element)
             and float(a.standard_level) * a.standard_multipliers.get(element, 1.0) > low]
    for c in channels:
        readings = [ctx.book.get((s, c)) for s in highs]
        if not any(r is None or r.instrument_error for r in readings):
            return None
    return low


ONE_STANDARD_NOTE = ('Only the {low:g} mg/L standard was usable (the instrument gave no value for the higher '
                     'standard on any wavelength, for example saturated): {what}')


SOLID_UNITS = {'mg/kg': 1.0, 'mg/100 g': 0.1, 'g/kg': 0.001, '% (w/w)': 0.0001, 'µg/kg': 1000.0}
LIQUID_UNITS = {'mg/L': 1.0, 'µg/L': 1000.0, 'g/L': 0.001}
CORRECTION_MODELS = {'two_point': 'Calibration line through the blank, the low and the high standard',
                     'single_standard': 'One standard, chosen by the size of the reading'}
REPLICATE_RULES = {'dixon': "Dixon's Q test (95 %), only above the limit",
                   'lab_rsd': 'Remove the replicate farthest from the mean while RSD > limit (at most 2)'}
CHANNEL_SCORES = {'percent': 'Average error of the standards in %', 'mg_l': 'Average error of the standards in mg/L'}
METHOD_SOURCES = {'master': 'Built-in limit table, for every run', 'method_table': "The run's own method table"}
MASTER_NAME = 'Built-in limit table'


def run_name(settings):
    """The name of the run for folders and titles: the project name, else the method name, else 'Plasmatti run'."""
    method = settings.method if settings.method != MASTER_NAME else ''
    return settings.project or method or 'Plasmatti run'
# Dixon's Q, 95 % confidence, two-sided (Rorabacher, Anal. Chem. 63 (1991) 139-146)
DIXON_Q95 = {3: 0.970, 4: 0.829, 5: 0.710, 6: 0.625, 7: 0.568, 8: 0.526, 9: 0.493, 10: 0.466}


def screen_category(r):
    """Category used on screen. A below-limit result whose only other flag is a high RSD
    counts as 'below limit' here (scatter near zero is expected); the flag itself stays
    in the details and in the export."""
    if r.category == 'attention' and any(f.startswith('BELOW_') for f in r.flags) and \
            all(f.startswith('BELOW_') or f == 'HIGH_RSD' for f in r.flags):
        return 'below_limit'
    return r.category


SCREEN_LABELS = {'ok': 'Measured', 'below_limit': 'Below limit', 'attention': 'High scatter or other check',
                 'blocked': 'Not calculated'}
CATEGORY_COLOURS = {'ok': ('#FFFFFF', '#0F172A'), 'below_limit': ('#F1F5F9', '#64748B'),
                    'attention': ('#FFEBD2', '#7C2D12'), 'blocked': ('#FDE2E2', '#7F1D1D')}


def unit_choices(sample_type):
    return SOLID_UNITS if sample_type == 'Solid' else LIQUID_UNITS


def report_unit(settings):
    units = unit_choices(settings.sample_type)
    return settings.report_unit if settings.report_unit in units else next(iter(units))


def dixon_test(values):
    """One Dixon Q test on the most extreme replicate. Returns (index or None, Q, Q_crit, side)."""
    n = len(values)
    crit = DIXON_Q95.get(n)
    if crit is None:
        return None, None, None, ''
    order = sorted(range(n), key=lambda i: (values[i], i))
    low, high = values[order[0]], values[order[-1]]
    spread = high - low
    if not spread > 0:
        return None, 0.0, crit, ''
    q_low = (values[order[1]] - low) / spread
    q_high = (high - values[order[-2]]) / spread
    if q_high >= q_low:
        q, idx, side = q_high, order[-1], 'largest'
    else:
        q, idx, side = q_low, order[0], 'smallest'
    return (idx if q > crit else None), q, crit, side


STANDARD_CHECK_TOLERANCE = 0.10      # a standard reading more than 10 % off its nominal value is reported
MARK_SYMBOLS = {'ABOVE_RANGE': '\u2191', 'STANDARD_OFF': '\u2020'}


def mark_symbols(r) -> str:
    """' ↑', ' †' or ' ↑†' after a value; '' when the result has no information mark."""
    marks = list(getattr(r, 'marks', None) or [])
    if 'ABOVE_RANGE' not in marks and any(n.startswith('Above the highest standard') for n in r.notes):
        marks.append('ABOVE_RANGE')      # results calculated before the marks existed
    text = ''.join(MARK_SYMBOLS[m] for m in ('ABOVE_RANGE', 'STANDARD_OFF') if m in marks)
    return (' ' + text) if text else ''


def _standards_off(d, standards, tolerance=None):
    """Notes for the standards actually used for this result that read more than the tolerance from their
    nominal value: below the low standard only the low one, above it both, with one standard that one."""
    tolerance = STANDARD_CHECK_TOLERANCE if tolerance is None else tolerance
    segment = d.get('segment')
    if segment in ('zero-low', 'one standard'):
        used = [d.get('low_level')]
    elif segment in ('low-high', 'both'):
        used = [d.get('low_level'), d.get('high_level')]
    else:
        used = [d.get('level')]
    out = []
    for level in used:
        if level is None or level not in standards:
            continue
        (s0, v0), (s1, v1) = standards[level]
        dev = [(v0 - level) / level, (v1 - level) / level]
        if max(abs(x) for x in dev) > tolerance:
            out.append(f'The {level:g} mg/L standard used for this result reads {v0:.4g} before ({100 * dev[0]:+.0f} %) and '
                       f'{v1:.4g} after the samples ({100 * dev[1]:+.0f} %): more than {tolerance:.0%} from its nominal '
                       'value; the result may be biased.')
    return out


def standard_checks(ctx, selected, tolerance=STANDARD_CHECK_TOLERANCE):
    """Standards of the selected wavelengths whose blank-corrected reading is more than
    `tolerance` (fraction) away from the nominal value, before or after the samples.
    Information only: nothing in the calculation changes."""
    out = []
    for element, channel in sorted(selected.items()):
        for level, ((s0, v0), (s1, v1)) in sorted(ctx.standards(element, channel).items()):
            dev = [(v0 - level) / level, (v1 - level) / level]
            if max(abs(d) for d in dev) > tolerance:
                out.append({'element': element, 'channel': channel, 'level': level,
                            'before': v0, 'after': v1, 'before_pct': 100 * dev[0], 'after_pct': 100 * dev[1],
                            'sequences': [s0, s1]})
    return out


def standard_check_text(check):
    """One plain sentence for a standard check."""
    def pct(x):
        return f'{x:+.0f} %'
    lvl = f"{check['level']:g}"
    return (f"{check['element']} ({check['channel']}): the {lvl} mg/L standard reads {check['before']:.4g} before "
            f"({pct(check['before_pct'])}) and {check['after']:.4g} after the samples ({pct(check['after_pct'])}).")


class CorrectionContext:
    """Per-analysis cache: standard pairs are prepared once per channel.

    Built from the project at the start of one analyze() call; never reused
    after any project change (the GUI separately keys whole analyses on a
    digest of the inputs, decisions and settings).
    """

    def __init__(self, project: Project):
        self.project = project
        self.book = _reading_lookup(project.readings)
        samples = sorted(a.sequence for a in project.assignments.values() if a.role == 'Sample')
        if not samples:
            raise ValueError('No sample assignments.')
        self.first, self.last = samples[0], samples[-1]
        self._standards: Dict[Tuple[str, str], Dict] = {}
        self.blank_fixes: Dict[Tuple[str, str], Dict[str, Any]] = {}

    def standards(self, element: str, channel: str):
        key = (element, channel)
        if key not in self._standards:
            info = {}
            self._standards[key] = _standards_for_element(self.project, element, channel, self.first, self.last,
                                                          self.book, info)
            if info:
                self.blank_fixes[key] = info
        return self._standards[key]

    def low_only(self, element: str):
        """The low standard level when it is the only usable standard of this element: the session was
        prepared with a higher standard too, but no wavelength has a usable value for it (for example
        saturated). None otherwise."""
        if not hasattr(self, '_low_only'):
            self._low_only = {}
        if element not in self._low_only:
            self._low_only[element] = _low_only_level(self, element)
        return self._low_only[element]


def choose_channels(project: Project, context: Optional[CorrectionContext] = None
                    ) -> Tuple[Dict[str, str], Dict[str, Optional[float]], List[str]]:
    ctx = context or CorrectionContext(project)
    first, last = ctx.first, ctx.last
    if any(first < a.sequence < last for a in project.assignments.values() if a.role == 'Standard'):
        raise ValueError('Standards occur inside the sample block. Separate runs/blocks or revise roles; Plasmatti processes one bracketed block.')
    by_element = defaultdict(list)
    for channel, cfg in project.channels.items():
        if cfg.enabled:
            by_element[split_channel(channel)[0]].append(channel)
    selected = {}
    scores = {}
    warnings = []
    for element, channels in sorted(by_element.items()):
        for channel in channels:
            standards = ctx.standards(element, channel)
            levels = sorted(standards)
            if len(levels) < 2 and not (levels and ctx.low_only(element) == levels[0]):
                scores[channel] = None
            elif project.settings.channel_score == 'mg_l':
                scores[channel] = mean(abs(obs - lvl) for lvl in (levels[0], levels[-1]) for _, obs in standards[lvl])
            else:
                scores[channel] = mean(100 * abs(obs - lvl) / lvl for lvl in (levels[0], levels[-1]) for _, obs in standards[lvl])
        manual = [c for c in channels if project.channels[c].manual_select]
        if len(manual) > 1:
            raise ValueError(f'{element}: choose only one manual channel.')
        if manual:
            selected[element] = manual[0]
            warnings.append(f'{element}: explicit channel override {manual[0]}.')
            continue
        usable = [c for c in channels if scores[c] is not None]
        if usable and ctx.low_only(element) is not None:
            warnings.append(f'{element}: only the {ctx.low_only(element):g} mg/L standard is usable on every wavelength '
                            '(the higher standard has no usable value); wavelength chosen on that standard.')
        if not usable:
            selected[element] = min(channels, key=lambda c: (project.channels[c].preference_order or 999, c))
            warnings.append(f'{element}: no complete valid standard pairs; retained as BLOCKED, not omitted.')
            continue
        preferred = [c for c in usable if project.channels[c].preference_order == 1]
        second = [c for c in usable if project.channels[c].preference_order == 2]
        # Apply the documented 10% rule to the best view within each wavelength rank.
        if preferred and second:
            one = min(preferred, key=lambda c: (scores[c], c))
            two = min(second, key=lambda c: (scores[c], c))
            chosen = one if scores[one] <= scores[two] * (1 + project.settings.relative_preference_tolerance) + 1e-12 else two
            selected[element] = chosen
        elif preferred:
            selected[element] = min(preferred, key=lambda c: (scores[c], c))
            warnings.append(f'{element}: no valid preference-2 comparator; used best valid preference 1.')
        else:
            selected[element] = min(usable, key=lambda c: (scores[c], c))
            warnings.append(f'{element}: no valid preference-1 channel; used lowest available standard score. Review preferences.')
    return selected, scores, warnings


def straddles_low_standard(signals, s_low):
    """True when blank-corrected replicate signals lie strictly on both sides of the low standard's
    reading: some below S_low and some above. A replicate exactly at S_low lies on both lines."""
    return len(signals) >= 2 and any(y < s_low for y in signals) and any(y > s_low for y in signals)


def _correct_sample(reading: Reading, project: Project, book: Dict[Tuple[int, str], Reading], first: int, last: int,
                    context: Optional[CorrectionContext] = None, allow_removal: bool = True):
    assn = project.assignments[reading.sequence]
    summary_basis = project.settings.statistics_basis == 'instrument_when_unfiltered'
    kept, ids, removed, initial, final = filter_replicates(reading, project.settings.rsd_limit,
                                                           project.settings.auto_filter and allow_removal, summary_basis,
                                                           rule=project.settings.replicate_rule)
    notes = list(reading.import_notes)
    if split_channel(reading.channel)[2] == 'unknown':
        raise ValueError('Axial/radial view not exported: confirm channel identity first.')
    if reading.calibration_mean is not None and reading.instrument_mean is not None:
        if not math.isclose(reading.calibration_mean, reading.instrument_mean, rel_tol=.0001, abs_tol=.000001):
            raise ValueError(f'The instrument file has two different concentrations: Conc (Calib) {reading.calibration_mean:g} '
                             f'and Conc (Sample) {reading.instrument_mean:g} mg/L. The instrument may already have applied a '
                             'dilution or a weight, so this result is not calculated (a dilution must not be applied twice). '
                             'Check the sample settings in the instrument method and export the run again.')
    if not reading.replicates:
        notes.append('Summary-only: replicate rejection unavailable; no replicate values were reconstructed.')
    if removed and project.settings.replicate_rule == 'dixon':
        notes.append("Dixon's Q test (95 %) removed replicate " + ', '.join(map(str, removed)) + '.')
    elif removed:
        notes.append('RSD rule removed replicate ' + ', '.join(map(str, removed)) + '.')
    raw = reading.raw_mean if summary_basis and not removed else mean(kept)
    sd = reading.raw_sd if summary_basis and not removed else (stdev(kept) if len(kept) > 1 else reading.raw_sd)
    if summary_basis and not removed and reading.instrument_mean is not None and reading.replicates:
        notes.append('Unfiltered mean/SD preserve exported instrument statistics; rounded displayed replicates may not reproduce the last digits. The affine correction is applied to the statistics and to each exported replicate separately.')
    basis = 'instrument summary (unfiltered)' if summary_basis and not removed and reading.instrument_mean is not None else 'exported retained replicates'
    b0, b1 = _bracket_samples(project.assignments, reading.sequence, ('Sample blank', 'Both blanks'))
    if (b0, reading.channel) not in book or (b1, reading.channel) not in book:
        raise ValueError('Required sample blank/channel missing.')
    blank = interpolate(reading.sequence, b0, book[(b0, reading.channel)].raw_mean, b1, book[(b1, reading.channel)].raw_mean)
    fix = {}
    if context is not None:
        standards = context.standards(reading.element, reading.channel)
        fix = context.blank_fixes.get((reading.element, reading.channel), {})
    else:
        standards = _standards_for_element(project, reading.element, reading.channel, first, last, book, fix)
    if fix:
        notes.append(blank_check_text(fix, reading.element))
    low_only = (context.low_only(reading.element) if context is not None
                else _low_only_level(CorrectionContext(project), reading.element))
    if len(standards) == 1 and low_only is not None and low_only in standards:
        # Only the low standard is usable (the higher one has no value, e.g. saturated). At or below it
        # this is exactly the usual calculation (line through zero and the low standard); above it the
        # same line is extended, and the result is marked.
        low = low_only
        s_low = interpolate(reading.sequence, *standards[low][0], *standards[low][1])
        if not (math.isfinite(s_low) and s_low > 0):
            raise ValueError(f'The low standard reads {s_low:.6g} after blank correction; no calibration is possible.')
        local = s_low / low
        y = raw - blank
        corrected = [(x - blank) / local for x in kept] if reading.replicates else []
        above = y > s_low
        notes.append(ONE_STANDARD_NOTE.format(
            low=low, what=('extrapolated above the checked range.' if above else
                           'at or below it the calculation is the usual one.')))
        return dict(corrected=corrected, kept=ids, removed=removed, initial=initial, final=final,
                    blank=blank, factor=local, level=low, mean=y / local,
                    sd=(sd / local if sd is not None else None), notes=notes, basis=basis,
                    slope=local, intercept=0.0, s_low=s_low, s_high=None, low_level=low, high_level=low,
                    segment='one standard', one_standard=above,
                    low_candidate=None, high_candidate=None, threshold=None)
    if len(standards) < 2:
        problems = standard_pair_problems(project, reading.element, reading.channel, first, last, book)
        raise ValueError('No usable pair of a low and a high standard before and after the samples on this wavelength'
                         + (': ' + '; '.join(problems) + '.' if problems else
                            '. Check the standard composition and the standard-blank roles.'))
    levels = sorted(standards)
    low, high = levels[0], levels[-1]
    if project.settings.correction_model == 'two_point':
        s_low = interpolate(reading.sequence, *standards[low][0], *standards[low][1])
        s_high = interpolate(reading.sequence, *standards[high][0], *standards[high][1])
        slope = (s_high - s_low) / (high - low)
        if not (math.isfinite(slope) and slope > 0):
            raise ValueError(f'The high standard does not read higher than the low standard (S_low {s_low:.6g}, '
                             f'S_high {s_high:.6g}); no calibration line is possible.')
        if not (math.isfinite(s_low) and s_low > 0):
            raise ValueError(f'The low standard reads {s_low:.6g} after blank correction; no calibration is possible.')
        intercept = s_low - slope * low

        def concentration(y):
            # Calibration points: the blank (0, 0), the low and the high standard, joined by straight
            # lines. Below the low standard the line runs through zero (= the low standard's factor),
            # so a sample at the blank level stays at zero; above it, the line through both standards.
            return y * low / s_low if y <= s_low else low + (y - s_low) / slope

        y = raw - blank
        lower = y <= s_low
        local = s_low / low if lower else slope
        corrected = [concentration(x - blank) for x in kept] if reading.replicates else []
        avg_corr = concentration(y)
        sd_corr = sd / local if sd is not None else None
        segment = 'zero-low' if lower else 'low-high'
        if straddles_low_standard([x - blank for x in kept] if reading.replicates else [], s_low):
            # The kept replicates lie on both calibration lines. Converting the mean with one line
            # and dividing the SD by one slope would not match the corrected replicates, so the mean
            # and the sample SD are taken from the corrected replicates themselves.
            avg_corr = mean(corrected)
            sd_corr = stdev(corrected)
            segment = 'both'
            basis = 'corrected retained replicates (on both calibration lines)'
            notes.append(f'Replicates on both sides of the low standard (S_low {s_low:.6g}): mean and SD from the '
                         'corrected replicates.')
        return dict(corrected=corrected, kept=ids, removed=removed, initial=initial, final=final,
                    blank=blank, factor=local, level=None, mean=avg_corr, sd=sd_corr, notes=notes, basis=basis,
                    slope=local, intercept=(0.0 if lower else intercept), s_low=s_low, s_high=s_high,
                    low_level=low, high_level=high, segment=segment,
                    low_candidate=None, high_candidate=None, threshold=None)
    factors = {}
    for level in (low, high):
        (p0, v0), (p1, v1) = standards[level]
        factors[level] = finite_positive(interpolate(reading.sequence, p0, v0, p1, v1) / level, 'Standard correction factor')
    threshold = project.settings.high_standard_boundary_fraction * high
    override = assn.standard_overrides.get(reading.element, '')
    if project.settings.correction_model == 'single_standard':
        # The laboratory's rule: decided on the raw mean (as measured), not on a corrected value.
        if override in ('low', 'high'):
            level = low if override == 'low' else high
            notes.append(f'Manual {override}-standard choice by the analyst.')
        else:
            level = low if raw <= threshold else high
        factor = factors[level]
        corrected = [(x - blank) / factor for x in kept] if reading.replicates else []
        return dict(corrected=corrected, kept=ids, removed=removed, initial=initial, final=final,
                    blank=blank, factor=factor, level=level, mean=(raw - blank) / factor,
                    sd=(sd / abs(factor) if sd is not None else None), notes=notes, basis=basis,
                    slope=None, intercept=None, low_candidate=(raw - blank) / factors[low],
                    high_candidate=(raw - blank) / factors[high], threshold=threshold)
    lo = (raw - blank) / factors[low]
    hi = (raw - blank) / factors[high]
    lo_ok = lo <= threshold
    hi_ok = hi > threshold
    candidates = dict(low_candidate=lo, high_candidate=hi, threshold=threshold)
    if override in ('low', 'high'):
        level = low if override == 'low' else high
        notes.append(f'Manual {override}-standard regime override; candidates low={lo:.9g}, high={hi:.9g}, threshold={threshold:.9g} mg/L.')
    elif lo_ok != hi_ok:
        level = low if lo_ok else high
    elif project.settings.boundary_policy == 'legacy_low_first':
        level = low if lo_ok else (low if raw - blank <= threshold else high)
        notes.append(f'Boundary ambiguity; explicit legacy fallback applied. Candidates low={lo:.9g}, high={hi:.9g} mg/L.')
    else:
        err = ValueError(f'BOUNDARY_REVIEW: final-result switching is not unique (low candidate {lo:.9g}, high candidate {hi:.9g}, threshold {threshold:.9g} mg/L). Select low/high explicitly on Results; neither candidate is silently accepted.')
        err.candidates = candidates  # type: ignore[attr-defined]
        raise err
    factor = factors[level]
    corrected = [(x - blank) / factor for x in kept] if reading.replicates else []
    # With a shared blank/factor the affine transform of supplied mean/SD is exact.
    avg_corr = (raw - blank) / factor
    sd_corr = sd / abs(factor) if sd is not None else None
    return dict(corrected=corrected, kept=ids, removed=removed, initial=initial, final=final,
                blank=blank, factor=factor, level=level, mean=avg_corr, sd=sd_corr, notes=notes, basis=basis,
                slope=None, intercept=None, **candidates)


def _sd_text(sd: Optional[float], value: float, uf: float = 1.0) -> str:
    if sd is None:
        return NO_SD
    return f'{sd:.{display_decimals(value, uf) + 1}f}'


def analyze(project: Project) -> Analysis:
    if project.settings.sample_type not in ('Liquid', 'Solid'):
        raise ValueError('Sample type must be Liquid or Solid.')
    if project.settings.limit_policy not in ('lab_stored', 'sample_specific'):
        raise ValueError('Unknown reporting-limit policy.')
    if project.settings.statistics_basis not in ('instrument_when_unfiltered', 'exported_replicates'):
        raise ValueError('Unknown statistics basis.')
    if project.settings.reporting_basis not in ('as_weighed', 'dry'):
        raise ValueError('Unknown reporting basis.')
    if project.settings.correction_model not in ('two_point', 'single_standard', 'candidates'):
        raise ValueError('Unknown standard correction model.')
    if project.settings.replicate_rule not in ('dixon', 'lab_rsd'):
        raise ValueError('Unknown replicate rule.')
    if project.settings.channel_score not in ('percent', 'mg_l'):
        raise ValueError('Unknown wavelength score.')
    finite_positive(project.settings.rsd_limit, 'RSD limit')
    ctx = CorrectionContext(project)
    selected, scores, notes = choose_channels(project, ctx)
    analysis = Analysis(selected_channels=selected, channel_scores=scores,
                        notes=list(project.source_warnings) + list(project.method_notes) + notes)
    book = ctx.book
    all_samples = sorted(a.sequence for a in project.assignments.values() if a.role == 'Sample')
    samples = [project.assignments[i] for i in all_samples if project.assignments[i].report]
    first, last = ctx.first, ctx.last
    solid = project.settings.sample_type == 'Solid'
    dry = solid and project.settings.reporting_basis == 'dry'
    if dry:
        analysis.notes.append('Dry-basis reporting selected: mass = weighed mass x (1 - moisture/100).')
    def compute(assn, element, ch):
        r = book.get((assn.sequence, ch))
        cfg = project.channels[ch]
        units = 'mg/kg' if solid else 'mg/L'
        flags = []
        notes = []
        value = sd = avg_corr = sd_corr = blank = factor = level = limit = None
        raw = math.nan
        initial = final = math.inf
        ids = []
        removed = []
        corrected = []
        basis = 'unavailable'
        mult = None
        cand = {}
        mass_used = None
        marks = []
        sol = {}
        cal = (None, None)
        reps = list(r.replicates) if r else []
        try:
            if r is None:
                raise ValueError('Selected analytical channel was not measured for this sample.')
            raw = r.raw_mean
            try:
                d = _correct_sample(r, project, book, first, last, ctx)
            except ValueError as exc:
                cand = getattr(exc, 'candidates', {}) or {}
                raise
            dilution = finite_positive(assn.dilution, 'Additional dilution')
            mult = dilution
            if solid:
                mass = finite_positive(assn.mass_g, 'Sample mass in grams')
                volume = finite_positive(assn.volume_ml, 'Final solution volume in mL')
                if dry:
                    if assn.moisture_pct is None:
                        raise ValueError('Dry-basis reporting is selected but no measured moisture was entered for this sample.')
                    if not math.isfinite(assn.moisture_pct) or not 0 <= assn.moisture_pct < 100:
                        raise ValueError('Moisture must be in [0,100)%.')
                    mass *= 1 - assn.moisture_pct / 100
                elif assn.moisture_pct is not None:
                    notes.append('Moisture is recorded but NOT applied: reporting basis is as-weighed.')
                mass_used = mass
                mult *= volume / mass
            kind = cfg.limit_kind or 'DL'
            limit_notes = []
            if solid and project.settings.limit_policy == 'lab_stored':
                limit = cfg.dl_mg_kg
                limit_notes.append(f'{kind}: stored method mg/kg value; not replaced by sample-specific mass/volume scaling.')
                if dry:
                    limit_notes.append('Stored solid reporting limit retained for a dry-basis result; confirm method applicability.')
            else:
                limit = cfg.dl_mg_l
                if solid and limit is not None:
                    limit *= mult
            if limit is not None and not (solid and project.settings.limit_policy == 'sample_specific'):
                if project.settings.dilution_limit_policy == 'scale_with_dilution':
                    limit *= assn.dilution
            # Dixon's Q test is used only for results above the limit: decided on the result
            # WITHOUT removal (near zero a high scatter is normal and removal would mean nothing).
            if project.settings.replicate_rule == 'dixon' and d['removed'] and limit is not None:
                d0 = _correct_sample(r, project, book, first, last, ctx, allow_removal=False)
                if d0['mean'] * mult < limit:
                    d = d0
                    d['notes'].append("Below the limit: Dixon's Q test not applied; all replicates kept.")
            cand = {k: d.get(k) for k in ('low_candidate', 'high_candidate', 'threshold')}
            avg_corr, sd_corr = d['mean'], d['sd']
            blank, factor, level = d['blank'], d['factor'], d['level']
            initial, final = d['initial'], d['final']
            ids, removed = d['kept'], d['removed']
            corrected = d['corrected']
            basis = d['basis']
            cal = (d.get('slope'), d.get('intercept'))
            notes.extend(d['notes'])
            notes.extend(limit_notes)
            value = avg_corr * mult
            sd = sd_corr * mult if sd_corr is not None else None
            if not math.isfinite(value) or (sd is not None and not math.isfinite(sd)):
                raise ValueError('Nonfinite calculated result.')
            if final > project.settings.rsd_limit:
                flags.append('HIGH_RSD')
            if not reps:
                flags.append('SUMMARY_ONLY')
            if sd is None:
                flags.append('MISSING_SD')
            if any('Boundary ambiguity' in x or 'regime override' in x for x in notes):
                flags.append('REVIEW')
            if d.get('one_standard'):
                flags.append('ONE_STANDARD')
            if any(n.startswith('The standard blank ') and 'were corrected with the standard blank' in n for n in d['notes']):
                flags.append('OTHER_BLANK')
            if limit is None:
                flags.append('MISSING_' + kind)
            else:
                finite_positive(limit, 'Reporting limit')
                if value < limit:
                    flags.append('BELOW_' + kind)
            top = max(ctx.standards(element, ch) or [0])
            if top and avg_corr > top:
                notes.append(f'Above the highest standard: {avg_corr:.4g} mg/L in the measured solution is more than the '
                             f'{top:g} mg/L standard (extrapolated; dilute and measure again).')
                marks.append('ABOVE_RANGE')
            off = _standards_off(d, ctx.standards(element, ch))
            if off:
                marks.append('STANDARD_OFF')
                notes.extend(off)
            if solid:
                sol = _solution_block(avg_corr, sd_corr, dilution, cfg, project.settings.dilution_limit_policy)
        except (ValueError, TypeError, ZeroDivisionError, OverflowError) as exc:
            flags.insert(0, 'BLOCKED')
            notes.append(str(exc))
        status = ' + '.join(flags) if flags else 'OK'
        units = report_unit(project.settings)
        uf = unit_choices(project.settings.sample_type)[units]
        solution_c = avg_corr
        if uf != 1.0:
            value = value * uf if value is not None else None
            sd = sd * uf if sd is not None else None
            limit = limit * uf if limit is not None else None
        if 'BLOCKED' in flags:
            display, sd_display = 'BLOCKED', NO_SD
        elif any(f.startswith('BELOW_') for f in flags):
            if solid and project.settings.limit_policy == 'sample_specific':
                # a limit calculated for this sample (LOQ x V / m x d): rounded with the result rule
                display, sd_display = '<' + format_sample_limit(limit, uf), NO_SD
            else:
                display, sd_display = '<' + format_dl(limit), NO_SD
        else:
            display = format_report(value, uf=uf)
            sd_display = _sd_text(sd, value, uf)
        return Result(
            assn.sequence, assn.position, assn.sample_id,
            assn.report_name.strip() or assn.sample_id, element, ch, raw, avg_corr, sd_corr, value, sd, units, display, sd_display,
            limit, initial, final, len(reps), len(ids), ids, removed, reps, corrected, blank, factor, level, assn.dilution, status,
            notes=notes, flags=flags, limit_kind=cfg.limit_kind, limit_policy=project.settings.limit_policy,
            statistics_basis=basis, corrected_rsd=(100 * sd_corr / abs(avg_corr) if sd_corr is not None and avg_corr else None),
            source=r.source if r else '', category=result_category(flags),
            solution_value=sol.get('value'), solution_sd=sol.get('sd'), solution_limit=sol.get('limit'),
            solution_reported=sol.get('reported', ''), solution_sd_display=sol.get('sd_display', ''),
            low_candidate_mg_l=cand.get('low_candidate'), high_candidate_mg_l=cand.get('high_candidate'),
            regime_threshold_mg_l=cand.get('threshold'), mass_used_g=mass_used,
            volume_ml=assn.volume_ml if solid else None,
            correction_model=project.settings.correction_model, cal_slope=cal[0], cal_intercept=cal[1],
            solution_mg_l=solution_c, replicate_rule=project.settings.replicate_rule, marks=marks)

    for assn in samples:
        for element, ch in sorted(selected.items()):
            analysis.results.append(compute(assn, element, ch))
    _wavelength_fallback(project, analysis, samples, compute, book)
    analysis.standard_checks = standard_checks(ctx, selected)
    return analysis


# Another wavelength for a sample without a value on the chosen one (agreed with the laboratory, 23 October 2026).
FALLBACK_MIN_SAMPLES = 5      # samples above the limit on both wavelengths
FALLBACK_TOLERANCE = 0.10     # median ratio within 0.90-1.10, and "agree" means within 10 %
FALLBACK_SHARE = 0.75         # at least 75 % of the compared samples agree


def _no_sample_value(reading) -> bool:
    """True when the instrument gave no usable value for this sample on this wavelength
    (not measured, an instrument error such as saturation, or an empty cell)."""
    return reading is None or bool(reading.instrument_error) or (not reading.replicates and reading.instrument_mean is None)


def _comparable(res) -> bool:
    return ('BLOCKED' not in res.flags and not any(f.startswith('BELOW_') for f in res.flags)
            and res.corrected_mean_mg_l is not None and res.corrected_mean_mg_l > 0)


def wavelength_agreement(chosen: Dict[int, 'Result'], other: Dict[int, 'Result'], exclude=()) -> Dict[str, Any]:
    """How well another wavelength agrees with the chosen one on the samples of the session
    that are above the limit on both. ok=True when all three agreement rules are met."""
    ratios = [other[q].corrected_mean_mg_l / a.corrected_mean_mg_l for q, a in chosen.items()
              if q not in exclude and q in other and _comparable(a) and _comparable(other[q])]
    n = len(ratios)
    out = {'n': n, 'median': median(ratios) if ratios else None,
           'share': (sum(abs(x - 1) <= FALLBACK_TOLERANCE + 1e-12 for x in ratios) / n) if n else 0.0}
    if n < FALLBACK_MIN_SAMPLES:
        out['ok'] = False
        count = 'no sample is' if n == 0 else f'only {n} sample{"" if n == 1 else "s"} {"is" if n == 1 else "are"}'
        out['reason'] = (f'{count} above the limit on both wavelengths, and at least {FALLBACK_MIN_SAMPLES} are needed '
                         'to compare them')
    elif abs(out['median'] - 1) > FALLBACK_TOLERANCE + 1e-12:
        out['ok'] = False
        out['reason'] = (f'it reads {out["median"]:.2f} times the chosen wavelength on the other samples (median of {n}; '
                         f'between {1 - FALLBACK_TOLERANCE:.2f} and {1 + FALLBACK_TOLERANCE:.2f} is needed)')
    elif out['share'] < FALLBACK_SHARE - 1e-12:
        out['ok'] = False
        out['reason'] = (f'only {100 * out["share"]:.0f} % of the {n} compared samples agree within '
                         f'{100 * FALLBACK_TOLERANCE:.0f} % (at least {100 * FALLBACK_SHARE:.0f} % is needed)')
    else:
        out['ok'] = True
        out['reason'] = ''
    return out


def _wavelength_fallback(project, analysis, samples, compute, book):
    """A sample without a value on the chosen wavelength is calculated on the next wavelength of the
    same element (method order, then score) when that wavelength has usable standards, has a value for
    the sample, and agrees with the chosen one on the other samples of the session. The result is marked
    OTHER_WAVELENGTH (needs attention). No other result changes."""
    by_seq = {a.sequence: a for a in samples}
    for element, chosen in sorted(analysis.selected_channels.items()):
        if analysis.channel_scores.get(chosen) is None or project.channels[chosen].manual_select:
            continue
        index = {res.sequence: i for i, res in enumerate(analysis.results) if res.element == element}
        a_res = {q: analysis.results[i] for q, i in index.items()}
        missing = [q for q, res in a_res.items() if 'BLOCKED' in res.flags and _no_sample_value(book.get((q, chosen)))]
        if not missing:
            continue
        others = sorted((c for c, cfg in project.channels.items()
                         if cfg.enabled and c != chosen and split_channel(c)[0] == element
                         and analysis.channel_scores.get(c) is not None),
                        key=lambda c: (project.channels[c].preference_order or 999, analysis.channel_scores[c], c))
        if not others:
            for q in missing:
                a_res[q].notes.append(f'No other wavelength of {element} has usable standards, so none could be used instead.')
            continue
        tried = []
        for other in others:
            b_res = {q: compute(by_seq[q], element, other) for q in a_res}
            tried.append((other, b_res, wavelength_agreement(a_res, b_res, set(missing))))
        for q in missing:
            reasons = []
            for other, b_res, ag in tried:
                rb = b_res[q]
                if 'BLOCKED' in rb.flags:
                    reasons.append(f'{other} has no usable value for this sample either')
                    continue
                if not ag['ok']:
                    reasons.append(f'{other}: {ag["reason"]}')
                    continue
                rb.flags.append('OTHER_WAVELENGTH')
                rb.category = result_category(rb.flags)
                rb.status = ' + '.join(rb.flags)
                reading = book.get((q, chosen))
                err = reading.instrument_error if reading is not None else ''
                why = (' (it was not measured)' if reading is None
                       else '' if not err or 'unavailable' in err
                       else f' ({err.rstrip(".")})')
                rb.notes.insert(0, f'Calculated on {other} because {chosen} has no value for this sample{why}. '
                                   f'The two wavelengths agree on the other samples of this session: {ag["n"]} samples above '
                                   f'the limit on both, median ratio {ag["median"]:.3f}, {100 * ag["share"]:.0f} % within '
                                   f'{100 * FALLBACK_TOLERANCE:.0f} %.')
                analysis.results[index[q]] = rb
                break
            else:
                a_res[q].notes.append('Another wavelength was not used: ' + '; '.join(reasons) + '.')


def _solution_block(avg_corr, sd_corr, dilution, cfg, dilution_limit_policy):
    """Digest-solution mg/L values for a solid sample (the laboratory's mg/L report block).

    Same censoring rule as a liquid result: compared with the channel's mg/L
    limit, scaled by the additional dilution when that policy is selected.
    """
    value = avg_corr * dilution
    sd = sd_corr * dilution if sd_corr is not None else None
    limit = cfg.dl_mg_l
    if limit is not None and dilution_limit_policy == 'scale_with_dilution':
        limit *= dilution
    if limit is not None and value < limit:
        reported, sd_display = '<' + format_dl(limit), NO_SD
    else:
        reported, sd_display = format_report(value), _sd_text(sd, value)
    return {'value': value, 'sd': sd, 'limit': limit, 'reported': reported, 'sd_display': sd_display}


def load_method_config(path: str, channels: Dict[str, ChannelSetting]) -> int:
    """Import an XLS/XLSX/CSV method table as a COMPLETE replacement of ``channels``.

    Validated before anything changes; channels the table does not define are
    reset to unresolved (no preference/limit). Manual choices are cleared.
    """
    pass
    imported = read_method_file(path)
    new, matched = replace_channel_settings(channels, imported, method_label=Path(path).stem)
    channels.clear()
    channels.update(new)
    return len(matched)


def export_method_template(path: str, channels: Dict[str, ChannelSetting]):
    with open(path, 'w', encoding='utf-8-sig', newline='') as fh:
        wr = csv.writer(fh)
        wr.writerow(['channel', 'preference_order', 'dl_mg_l', 'dl_mg_kg', 'limit_kind'])
        for ch, cfg in sorted(channels.items()):
            wr.writerow([ch, cfg.preference_order or '', cfg.dl_mg_l if cfg.dl_mg_l is not None else '',
                         cfg.dl_mg_kg if cfg.dl_mg_kg is not None else '', cfg.limit_kind])


def generate_demo_csv(folder: str) -> str:
    """Deterministic, explicitly SIMULATED unit-test fixture (not the GUI/CLI demo)."""
    os.makedirs(folder, exist_ok=True)
    p = os.path.join(folder, 'Plasmatti_SIMULATED_demo.csv')
    headings = ['sequence', 'position', 'sample_id', 'channel', 'rep1', 'rep2', 'rep3', 'rep4', 'rep5']
    groups = [
        (1, 'HNO3 1.5%', {'Ca 317.933 axial': 0.02, 'Fe 238.204 radial': 0.01}),
        (2, 'Multi 1 ppm', {'Ca 317.933 axial': 1.04, 'Fe 238.204 radial': 0.99}),
        (3, 'Multi 20 ppm', {'Ca 317.933 axial': 20.2, 'Fe 238.204 radial': 19.7}),
        (4, 'Blank 1', {'Ca 317.933 axial': 0.03, 'Fe 238.204 radial': 0.02}),
        (5, 'Sample A', {'Ca 317.933 axial': 8.0, 'Fe 238.204 radial': 0.65}),
        (6, 'Sample B', {'Ca 317.933 axial': 14.0, 'Fe 238.204 radial': 0.90}),
        (7, 'Blank 2', {'Ca 317.933 axial': 0.05, 'Fe 238.204 radial': 0.03}),
        (8, 'HNO3 1.5%', {'Ca 317.933 axial': 0.04, 'Fe 238.204 radial': 0.02}),
        (9, 'Multi 1 ppm', {'Ca 317.933 axial': 1.02, 'Fe 238.204 radial': 1.03}),
        (10, 'Multi 20 ppm', {'Ca 317.933 axial': 19.9, 'Fe 238.204 radial': 20.1}),
    ]
    with open(p, 'w', encoding='utf-8', newline='') as fh:
        wr = csv.writer(fh)
        wr.writerow(headings)
        for seq, sample, chans in groups:
            for ch, val in chans.items():
                vals = [val * factor for factor in (0.995, 1.002, 1.001, 0.998, 1.004)]
                if sample == 'Sample B' and ch.startswith('Fe'):
                    vals[-1] = val * 1.70  # intentional outlier for QC demonstration
                wr.writerow([seq, seq, sample, ch] + [f'{v:.7f}' for v in vals])
    return p


def make_project(readings: Sequence[Reading], paths: Sequence[str] = (), demo: bool = False,
                 warnings: Sequence[str] = (), source_comparison: Optional[dict] = None) -> Project:
    """Build a project: source hashes, method/sample-type recognition, identification."""
    project = Project(list(readings), _initial_assignments(readings), lines_for_run(readings),
                      source_paths=list(paths), demo=demo, source_warnings=list(warnings))
    project.source_manifest = [{'path': os.path.basename(str(p)), 'sha256': checksum(str(p))} for p in paths if os.path.isfile(p)]
    project.source_comparison = dict(source_comparison or {})
    pass
    pass
    configure_project(project)
    identify(project)
    return project




####################################################################################################
# plasmati_importers.py
####################################################################################################
# Explicit adapters for file layouts observed in the laboratory's 2016--2026 archive.
#
# Raw records, summary exports, edited calculation workbooks and final reports
# are different sources. In particular an edited AVG file is NEVER an implicit
# replacement for a native measurement export. See docs/ARCHIVE_FINDINGS.md.
#
# Parsing rules
# -------------
# * Numbers are parsed with an explicit format ('dot', 'comma' or a strict
#   'auto' that refuses genuinely ambiguous text such as ``1,234``).
# * The PerkinElmer replicate PDF reader uses the observed en-US export format
#   (dot decimal, comma thousands), reads ``%RSD: 1,594.93`` correctly, records
#   every timestamped replicate attempt, and marks concentration-less attempts
#   as explicit instrument errors.
# * CSV/PDF cross-checks report coverage, identity, replicate counts, replicate
#   values, summary statistics, error states and acquisition times separately.
# * Standard-group aliases match with token boundaries, not substrings.
# * Method application is a complete, validated, transactional replacement.

import copy
from collections import defaultdict
import csv
import io
import json
import math
import re
import unicodedata
from collections import Counter
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Optional

pass

CHANNEL_PATTERN = re.compile(r'^\s*([A-Z][a-z]?)\s+(\d{3}(?:[.,]\d{1,4})?)\s*(axial|radial|unknown)?\s*$', re.I)
WAVE_PATTERN = re.compile(r'^\s*(\d{3}(?:[.,]\d{1,4})?)\s*(axial|radial)\s*$', re.I)

_THOUSANDS_DOT = re.compile(r'^[+\-]?\d{1,3}(?:,\d{3})+(?:\.\d*)?(?:[eE][+\-]?\d+)?$')
_THOUSANDS_COMMA = re.compile(r'^[+\-]?\d{1,3}(?:\.\d{3})+(?:,\d*)?$')
_AMBIGUOUS_GROUPING = re.compile(r'^[+\-]?[1-9]\d{0,2}(?:,\d{3})+$')


def number(value, *, decimal='auto'):
    """Convert one exported cell/text to a finite float.

    decimal='dot'   : ``.`` is the decimal mark; commas must be valid
                      thousands groups (``11,786.66``). Used for PerkinElmer
                      CSV/PDF/XLS exports and Plasmatti's own CSV formats.
    decimal='comma' : ``,`` is the decimal mark; dots must be thousands groups.
    decimal='auto'  : legacy convenience for typed/labelled values. A value
                      with both marks is unambiguous; a comma-only value is a
                      decimal comma UNLESS it is a valid thousands grouping
                      such as ``1,234`` -- that is refused as ambiguous.

    Censored values, saturation markers, booleans and nonfinite numbers are
    never converted.
    """
    if isinstance(value, bool):
        raise ValueError('Boolean is not a concentration.')
    if isinstance(value, (int, float)):
        result = float(value)
        if not math.isfinite(result):
            raise ValueError('Nonfinite number.')
        return result
    text = unicodedata.normalize('NFKC', str(value)).strip().replace('−', '-').replace(' ', '')
    text = re.sub(r"[\s'’]", '', text)
    if not text or any(c in text for c in '<>~='):
        raise ValueError(f'Not a numerical value: {value!r}')
    if decimal == 'dot':
        if ',' in text:
            if not _THOUSANDS_DOT.match(text):
                raise ValueError(f'Not a dot-decimal number with valid thousands groups: {value!r}')
            text = text.replace(',', '')
    elif decimal == 'comma':
        if '.' in text:
            if not _THOUSANDS_COMMA.match(text):
                raise ValueError(f'Not a comma-decimal number with valid thousands groups: {value!r}')
            text = text.replace('.', '')
        text = text.replace(',', '.')
    elif decimal == 'auto':
        if ',' in text and '.' in text:
            text = text.replace(',', '') if text.rfind('.') > text.rfind(',') else text.replace('.', '').replace(',', '.')
        elif ',' in text:
            if _AMBIGUOUS_GROUPING.match(text):
                raise ValueError(f'Ambiguous number {value!r}: thousands separator or decimal comma? '
                                 'Enter it without grouping (e.g. 1234 or 1.234).')
            if text.count(',') > 1:
                raise ValueError(f'Not a numerical value: {value!r}')
            text = text.replace(',', '.')
    else:
        raise ValueError(f'Unknown decimal convention {decimal!r}.')
    try:
        result = float(text)
    except ValueError:
        raise ValueError(f'Not a numerical value: {value!r}') from None
    if not math.isfinite(result):
        raise ValueError('Nonfinite number.')
    return result


def optional_number(value, *, decimal='auto'):
    if value is None or str(value).strip() == '':
        return None
    try:
        return number(value, decimal=decimal)
    except (ValueError, TypeError):
        return None


def label_number(text):
    """Number inside a vial label such as ``Hg 0,2 ppm`` (decimal comma allowed).

    ``1,000 ppm`` is refused as ambiguous rather than read as 1 mg/L.
    """
    return number(text, decimal='auto')


def canonical_channel(value, *, allow_unknown=True):
    m = CHANNEL_PATTERN.fullmatch(str(value))
    if not m:
        raise ValueError(f'Unresolved analytical channel: {value!r}')
    wave = number(m[2].replace(',', '.'), decimal='dot')
    rounded = round(wave, 3)
    if abs(wave - rounded) > 1e-8:
        raise ValueError(f'Unsupported wavelength precision: {value!r}')
    view = (m[3] or 'unknown').lower()
    if view == 'unknown' and not allow_unknown:
        raise ValueError(f'Axial/radial view is not given: {value!r}')
    return f'{m[1].capitalize()} {rounded:.3f} {view}'


def normalized_name(value):
    return re.sub(r'\s+', ' ', unicodedata.normalize('NFKC', str(value))).strip().casefold()


def decode_file(path):
    b = Path(path).read_bytes()
    if b[:2] in (b'\xff\xfe', b'\xfe\xff'):
        return b.decode('utf-16')
    try:
        return b.decode('utf-8-sig')
    except UnicodeDecodeError:
        return b.decode('cp1252')


@dataclass
class Imported:
    readings: list = field(default_factory=list)
    warnings: list = field(default_factory=list)
    source_format: str = ''
    processed: bool = False


# --------------------------------------------------------------------------
# Native PerkinElmer replicate CSV (Crystal Reports layout)
# --------------------------------------------------------------------------

def _time_text(text):
    return re.sub(r'\s+', ' ', str(text or '')).strip()


def parse_crystal_csv(path):
    """The 56-column Crystal Reports export found in the three September runs.

    Labels AND shape are checked. Every CSV row is a measurement attempt;
    repeated values are NOT deduplicated. The actual sample concentration is
    the second concentration, not net intensity or calibration concentration.
    """
    pass
    results = {}
    warnings = []
    for lineno, row in enumerate(csv.reader(io.StringIO(decode_file(path))), 1):
        if not any(str(x).strip() for x in row):
            continue
        cells = [str(x).strip() for x in row]
        if len(cells) != 56 or cells[8] != 'Seq. No.' or cells[11] != 'AS Loc:' or cells[16] != 'Analyte':
            raise ValueError(f'CSV row {lineno}: not the verified Crystal replicate layout (56 columns).')
        seq, pos = int(number(cells[10], decimal='dot')), int(number(cells[12], decimal='dot'))
        name = cells[9]
        ch = canonical_channel(cells[24], allow_unknown=False)
        key = seq, ch
        if key not in results:
            results[key] = Reading(seq, pos, name, ch, source=str(path), acquisition_time=cells[14])
        item = results[key]
        if item.sample_id != name or item.position != pos:
            raise ValueError('Duplicate sequence has conflicting identity.')
        item.exported_replicate_count += 1
        item.replicate_times.append(cells[32])
        if cells[27] != 'mg/L' or cells[29] != 'mg/L':
            item.instrument_error = 'Instrument value/units unavailable: ' + repr(cells[26:30])
            item.import_notes.append(f'CSV row {lineno}: {cells[26:30]}')
        else:
            val = optional_number(cells[28], decimal='dot')
            if val is None:
                item.instrument_error = f'Instrument result unavailable: {cells[28] or cells[26]}'
                item.import_notes.append(f'CSV row {lineno}: {cells[26:30]}')
            else:
                item.replicates.append(val)
        for label, field_name, delta in [('Mean:', 'instrument_mean', 3), ('SD:', 'instrument_sd', 3), ('%RSD:', 'instrument_rsd', 1)]:
            try:
                idx = cells.index(label)
            except ValueError:
                continue
            v = optional_number(cells[idx + delta], decimal='dot')
            old = getattr(item, field_name)
            if old is not None and v is not None and abs(old - v) > 1e-9:
                raise ValueError(f'Inconsistent repeated {label} for sequence {seq}, {ch}.')
            setattr(item, field_name, v)
        # Conc (Calib) of the Mean row: the number right after "Mean:", when the headings read
        # Conc (Calib) then Conc (Sample) (until 21 October 2026 a fixed column was read, which held the
        # word "Mean:", so the double-dilution check never ran on CSV runs).
        if 'Mean:' in cells and 'Conc (Calib)' in cells and 'Conc (Sample)' in cells and \
                cells.index('Conc (Calib)') < cells.index('Conc (Sample)'):
            m = cells.index('Mean:')
            if m + 2 < len(cells) and cells[m + 2] in ('mg/L', 'mg/l'):
                item.calibration_mean = optional_number(cells[m + 1], decimal='dot')
    if not results:
        raise ValueError('No replicate records in CSV.')
    counts = sorted({x.exported_replicate_count for x in results.values()})
    if any(n != 5 for n in counts):
        warnings.append(f'Nonstandard replicate counts: {counts}; confirm report completeness.')
    if any(n > 5 for n in counts):
        raise ValueError('More than five attempts per sequence/channel: possible combined or duplicated reports.')
    for item in results.values():
        if len(item.replicates) != item.exported_replicate_count:
            item.import_notes.append('At least one replicate attempt has no concentration; no automatic partial acceptance.')
    return Imported(list(results.values()), warnings, 'PerkinElmer Crystal replicate CSV')


# --------------------------------------------------------------------------
# Native-text PerkinElmer replicate PDF
# --------------------------------------------------------------------------

_PDF_NUM = r'[+\-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?(?:[eE][+\-]?\d+)?'
_PDF_TIME = re.compile(r'(\d{1,2}-[A-Za-z]{3}-\d{2}\s+\d{1,2}:\d{2}:\d{2})')
PDF_SAMPLE_ROW_RE = re.compile(r'^\s*(' + _PDF_NUM + r')\s+mg/L\s+(' + _PDF_NUM + r')\s+mg/L\b', re.I)
PDF_SEQ_RE = re.compile(r'Seq\.\s*No\.\s*(\d+)\s+AS\s*Loc:\s*(\d+)(?:.*?Date:\s*(.+?))?\s*$', re.I)
PDF_ID_RE = re.compile(r'^\s*Sample\s*ID:\s*(.*?)\s*$', re.I)
PDF_MGL_RE = re.compile(r'(' + _PDF_NUM + r')\s*mg/L', re.I)
PDF_RSD_RE = re.compile(r'%RSD:\s*(' + _PDF_NUM + r')', re.I)
PDF_ERROR_RE = re.compile(r'saturat|\bcode\s*\d+|overrange|over\s*range|error', re.I)


def _decimals(text):
    text = str(text)
    if 'e' in text.lower():
        return None
    return len(text.split('.', 1)[1]) if '.' in text else 0


def _open_pdf(path):
    try:
        import pymupdf as fitz  # PyMuPDF >= 1.24 preferred module name
    except ImportError:
        try:
            import fitz  # type: ignore
        except ImportError as exc:
            raise RuntimeError('PDF import requires PyMuPDF. Install requirements.txt.') from exc
    return fitz.open(path)


def classify_pdf(path):
    """Say what a PDF is from its first pages, not from its name.

    ``'replicate'``: PerkinElmer per-replicate report (Seq. No., Sample ID, Conc (Sample));
    ``'summary'``: the mean-data (AVG+STDEV) printout; ``'other'``: readable text of
    something else; ``'unknown'``: unreadable, scanned or PyMuPDF missing.
    Many laboratory files are named after the person or the date ("11102021 - analyst.pdf"),
    so the name alone would hide most replicate reports.
    """
    try:
        doc = _open_pdf(path)
        try:
            text = ''.join(doc[i].get_text() for i in range(min(2, len(doc))))
        finally:
            doc.close()
    except Exception:
        return 'unknown'
    if not text.strip():
        return 'unknown'
    if 'Conc (Sample)' in text and 'Sample ID' in text and 'Seq. No' in text:
        return 'replicate'
    if 'Mean Data' in text:
        return 'summary'
    return 'other'


def classify_csv(path):
    """``'replicate'`` for the native Crystal Reports replicate CSV or Plasmatti's normalized CSV, else ``'other'``."""
    try:
        with open(path, 'rb') as fh:
            head = fh.read(1200).decode('utf-8', errors='replace')
    except OSError:
        return 'unknown'
    if 'Seq. No.' in head or head.lstrip().lower().startswith('sequence,position,sample_id,channel'):
        return 'replicate'
    return 'other'


BASIS_NOTE_START = 'Dilution check not possible: '
EXCEL_BASIS_NOTE = (BASIS_NOTE_START + 'made from an Excel summary without a Conc (Calib) column, so Plasmatti could '
                    'not check that the instrument did not already apply a dilution or a weight (the replicate CSV and '
                    'PDF have both Conc (Calib) and Conc (Sample)).')


def basis_note(missing, total):
    return (BASIS_NOTE_START + f'the file has no Conc (Calib) for {missing} of {total} measurements, so for these '
            'Plasmatti could not check that the instrument did not already apply a dilution or a weight. Check the '
            'sample settings of the instrument method, or export the run again with both concentration columns.')


def parse_perkinelmer_replicate_pdf(path, precision=None):
    """Parse a native-text Optima replicate report.

    Format interpretation (explicit, observed in the 2026 exports): dot decimal
    mark, comma thousands separators (``3,491.3``; ``%RSD: 1,594.93``). Sample
    identity switches at the ``Seq. No. / Sample ID`` header lines, which do not
    repeat on continuation pages. Each timestamped row inside a channel block
    is one replicate attempt; attempts without a ``mg/L`` concentration (for
    example intensity-only or ``Saturated ... (code 2)`` rows) make the record
    an explicit instrument error, never a shorter replicate list.

    ``precision`` (optional dict) receives the printed decimals of each value,
    keyed by (sequence, channel), for tolerance-aware cross-checks.
    Scanned image-only PDFs are unsupported (no silent OCR).
    """
    pass
    doc = _open_pdf(path)
    if len(doc) == 0:
        raise ValueError('The PDF has no pages.')
    measurements: Dict[tuple, Reading] = {}
    current_sample = None
    pending_seq = None
    current = None
    rows_with_values = 0
    saw_header = False
    calib_first = None   # True when the column headings read "Conc (Calib)" then "Conc (Sample)"
    try:
        for page_idx, page in enumerate(doc):
            for line in page.get_text(sort=True).splitlines():
                stripped = line.strip()
                if not stripped:
                    continue
                if 'Conc (Calib)' in stripped and 'Conc (Sample)' in stripped:
                    order = stripped.index('Conc (Calib)') < stripped.index('Conc (Sample)')
                    calib_first = order if calib_first in (None, order) else False
                    continue
                seq_match = PDF_SEQ_RE.search(stripped)
                if seq_match:
                    pending_seq = (int(seq_match.group(1)), int(seq_match.group(2)), _time_text(seq_match.group(3)))
                    continue
                id_match = PDF_ID_RE.match(stripped)
                if id_match and pending_seq is not None:
                    current_sample = (pending_seq[0], pending_seq[1], id_match.group(1).strip(), pending_seq[2])
                    pending_seq = None
                    current = None
                    saw_header = True
                    continue
                if current_sample is None:
                    continue
                if CHANNEL_PATTERN.fullmatch(stripped):
                    try:
                        elem, wave, view = split_channel(canonical_channel(stripped))
                    except ValueError:
                        current = None
                        continue
                    channel = f'{elem} {wave} {view}'
                    key = (current_sample[0], channel)
                    if key not in measurements:
                        measurements[key] = Reading(
                            sequence=current_sample[0], position=current_sample[1],
                            sample_id=current_sample[2], channel=channel,
                            source=str(path), acquisition_time=current_sample[3])
                        if precision is not None:
                            precision[key] = {'replicates': [], 'mean': None, 'sd': None, 'rsd': None}
                    current = measurements[key]
                    continue
                if current is None:
                    continue
                key = (current.sequence, current.channel)
                prec = precision.get(key) if precision is not None else None
                row = PDF_SAMPLE_ROW_RE.match(line)
                time_match = _PDF_TIME.search(stripped)
                if row:
                    current.replicates.append(number(row.group(2), decimal='dot'))
                    current.exported_replicate_count += 1
                    if time_match:
                        current.replicate_times.append(_time_text(time_match.group(1)))
                    if prec is not None:
                        prec['replicates'].append(_decimals(row.group(2)))
                    rows_with_values += 1
                elif re.match(r'^\s*Mean:', line):
                    nums = PDF_MGL_RE.findall(line)
                    if nums:
                        current.instrument_mean = number(nums[-1], decimal='dot')
                        if calib_first and len(nums) >= 2:
                            # Kept for the check that the instrument did not already apply a dilution.
                            current.calibration_mean = number(nums[0], decimal='dot')
                        if prec is not None:
                            prec['mean'] = _decimals(nums[-1])
                elif re.match(r'^\s*SD:', line):
                    nums = PDF_MGL_RE.findall(line)
                    if nums:
                        current.instrument_sd = number(nums[-1], decimal='dot')
                        if prec is not None:
                            prec['sd'] = _decimals(nums[-1])
                elif re.match(r'^\s*%RSD:', line):
                    m = PDF_RSD_RE.search(line)
                    if m:
                        current.instrument_rsd = number(m.group(1), decimal='dot')
                        if prec is not None:
                            prec['rsd'] = _decimals(m.group(1))
                elif time_match:
                    # A replicate attempt without a sample concentration.
                    current.exported_replicate_count += 1
                    current.replicate_times.append(_time_text(time_match.group(1)))
                    rest = stripped.replace(time_match.group(1), ' ').strip()
                    if PDF_ERROR_RE.search(rest):
                        current.instrument_error = 'Instrument error: ' + re.sub(r'\s+', ' ', rest)
                    elif not current.instrument_error:
                        current.instrument_error = 'Instrument result unavailable: no mg/L concentration reported for an attempt.'
                elif PDF_ERROR_RE.search(stripped):
                    current.instrument_error = 'Instrument error: ' + re.sub(r'\s+', ' ', stripped)
            if page_idx == 0 and not saw_header:
                raise ValueError('This PDF is not a supported PerkinElmer replicate report (older reports with channel names '
                                 'that lack the axial/radial view, or truncated names such as "Ca 317.933 r", are not read).')
    finally:
        doc.close()
    if not measurements or rows_with_values == 0:
        if measurements:
            raise ValueError('This report has no concentration (mg/L) values, only intensities, so nothing can be '
                             'calculated. Re-export it after the calibration (a method without a calibration cannot be reported).')
        raise ValueError('No numerical replicates were extracted. Use a native-text PerkinElmer report '
                         '(a scanned image or a report in an older layout without axial/radial views is not supported).')
    for item in measurements.values():
        if not calib_first:
            item.calibration_mean = None   # column order not established: no guess
        if item.instrument_error and item.replicates:
            item.import_notes.append('At least one replicate attempt has no concentration; no automatic partial acceptance.')
    return sorted(measurements.values(), key=lambda r: (r.sequence, r.element, r.channel))


# --------------------------------------------------------------------------
# Summary / AVG workbooks (optional, historical, cross-check)
# --------------------------------------------------------------------------

def _find_label(row, label):
    target = normalized_name(label)
    for c, v in enumerate(row):
        if normalized_name(v) == target:
            return c
    return None


def _after(row, label):
    c = _find_label(row, label)
    return row[c + 1] if c is not None and c + 1 < len(row) else ''


def parse_summary_workbook(path):
    """Untouched 28-column and cleaned 5/6-column AVG+STDEV reports."""
    pass
    out = []
    ordinal = 0
    ident = None
    fields = None
    warnings = []
    for sh in read_workbook(path):
        for r, row in enumerate(sh.rows()):
            strings = [str(x).strip() for x in row]
            if 'Analyte' in strings:
                start = strings.index('Analyte')
                headers = strings[start:]
                if 'Conc (Sample)' in headers and ('Std. Dev.' in headers or 'RSD' in headers):
                    fields = headers
            if any('Mean Data' in x for x in strings):
                ordinal += 1
                seq = optional_number(_after(row, 'Seq. No.:'), decimal='dot')
                pos = optional_number(_after(row, 'A/S Pos:'), decimal='dot')
                name = str(_after(row, 'ID:')).strip()
                ident = (int(seq) if seq is not None else ordinal, int(pos) if pos is not None else None,
                         name or f'Position {int(pos)}' if pos is not None else name or f'Entry {ordinal}', seq is None)
            if not strings or not CHANNEL_PATTERN.fullmatch(strings[0]):
                continue
            if ident is None:
                raise ValueError('Summary concentrations precede a sample identity block.')
            if fields is None:
                raise ValueError('Summary column labels missing; refusing to infer concentrations from column numbers.')
            ch = canonical_channel(strings[0])

            def at(c):
                return row[c] if c < len(row) else ''
            ci = fields.index('Conc (Sample)')
            if ci + 1 < len(fields) and fields[ci + 1] == 'Std. Dev.':
                si = ci + 1
            elif 'Std. Dev.' in fields:
                si = fields.index('Std. Dev.')
            else:
                si = None
            ri = fields.index('RSD') if 'RSD' in fields else None
            ui = fields.index('Sample Units') if 'Sample Units' in fields else None
            if ui is None or str(at(ui)).strip() not in ('mg/L', 'mg/l'):
                if optional_number(at(ci), decimal='dot') is not None:
                    raise ValueError('Summary has unsupported units.')
            avg = optional_number(at(ci), decimal='dot')
            item = Reading(ident[0], ident[1], ident[2], ch, instrument_mean=avg,
                           instrument_sd=optional_number(at(si), decimal='dot') if si is not None else None,
                           instrument_rsd=optional_number(at(ri), decimal='dot') if ri is not None else None,
                           source=str(path), sequence_inferred=ident[3])
            if 'Conc (Calib)' in fields:
                item.calibration_mean = optional_number(at(fields.index('Conc (Calib)')), decimal='dot')
            if avg is None:
                item.instrument_error = str(at(ci)) or 'No concentration in summary export'
            out.append(item)
    if not out:
        raise ValueError('No supported AVG+STDEV blocks found.')
    if any(x.sequence_inferred for x in out):
        warnings.append('Sequence numbers not exported; original summary-block order retained until a richer source is matched.')
    return Imported(out, warnings, 'PerkinElmer AVG+STDEV workbook')


def parse_average_workbook(path):
    """Wide untouched AVG report, with channel headers and a mg/L units row.
    Edited workbooks are explicitly refused as primary acquisition data.
    """
    pass
    sheets = read_workbook(path)
    for sh in sheets:
        for (r, c), v in sh.cells.items():
            if r < 10 and re.search(r'blank\s*corr|std\s*corr|standard\s*correction', str(v), re.I):
                return Imported([], ['Edited AVG workbook: available for comparison, not used as raw measurement source.'],
                                'Edited calculation workbook', True)
    sh = sheets[0]
    head = None
    channels = {}
    warnings = []
    for r in range(min(sh.nrows, 15)):
        cand = {}
        for c, v in enumerate(sh.row(r)):
            try:
                cand[c] = canonical_channel(v)
            except ValueError:
                pass
        if cand:
            head = r
            channels = cand
            break
    if head is None:
        raise ValueError('No wavelength columns in AVG workbook.')
    if any(str(sh.cell(head + 1, c)).strip().lower() != 'mg/l' for c in channels):
        raise ValueError('AVG units row does not give mg/L for every recognized channel.')
    out = []
    seq = 0
    for r in range(head + 2, sh.nrows):
        name = str(sh.cell(r, 0)).strip()
        if not name:
            continue
        if re.search(r'LOQ|LOD|pref\.|waveleng', name, re.I):
            break
        seq += 1
        for c, ch in channels.items():
            val = sh.cell(r, c)
            avg = optional_number(val, decimal='dot')
            out.append(Reading(seq, None, name, ch, instrument_mean=avg, source=str(path), sequence_inferred=True,
                               instrument_error='' if avg is not None else str(val) or 'Unavailable concentration'))
    if not out:
        raise ValueError('No sample rows in AVG workbook.')
    warnings.append('AVG contains no autosampler positions/replicates: sequence uses original row order; SD is unavailable without a summary export.')
    if any(' unknown' in ch for ch in channels.values()):
        warnings.append('Legacy channels omit axial/radial view; left UNKNOWN, not inferred from a modern method.')
    return Imported(out, warnings, 'PerkinElmer wide AVG workbook')


# --------------------------------------------------------------------------
# Autosampler maps
# --------------------------------------------------------------------------

def parse_autosampler(path):
    """Read an autosampler CSV, or the laboratory's repeated Excel ordinal/position/name blocks.

    CSV must have explicit position and sample_id/name headings. Never interpret
    the worksheet's first ordinal column as the actual A/S position.
    """
    mapping = {}
    warnings = []
    if Path(path).suffix.lower() == '.csv':
        reader = csv.DictReader(io.StringIO(decode_file(path)))
        headers = {str(h).strip().casefold().replace(' ', '_'): h for h in (reader.fieldnames or [])}
        poscol = next((headers[k] for k in ('position', 'autosampler_position', 'as_position', 'a/s_position') if k in headers), None)
        namecol = next((headers[k] for k in ('sample_id', 'sample_name', 'name', 'sample') if k in headers), None)
        if poscol is None or namecol is None:
            raise ValueError('Autosampler CSV must have position and sample_id (or sample_name) columns.')
        for index, row in enumerate(reader, 2):
            position = optional_number(row.get(poscol), decimal='dot')
            if position is None or position < 1 or position != int(position):
                raise ValueError(f'Autosampler CSV row {index} has an invalid position.')
            pos = int(position)
            name = str(row.get(namecol) or '').strip()
            if not name:
                raise ValueError(f'Autosampler CSV row {index} has a missing sample name.')
            if pos in mapping and mapping[pos] != name:
                raise ValueError(f'Autosampler position {pos} has conflicting sample names.')
            mapping[pos] = name
        if not mapping:
            raise ValueError('Autosampler CSV contains no mapping rows.')
        return mapping, warnings
    for sh in read_workbook(path):
        for r in range(sh.nrows):
            row = sh.row(r)
            for c in range(len(row) - 2):
                a, b, name = row[c:c + 3]
                ai = optional_number(a, decimal='dot')
                bi = optional_number(b, decimal='dot')
                if ai is None or bi is None or ai != int(ai) or bi != int(bi) or bi < 1:
                    continue
                if not isinstance(name, str) or not name.strip() or optional_number(name) is not None:
                    continue
                pos = int(bi)
                text = name.strip()
                if pos in mapping and mapping[pos] != text:
                    raise ValueError(f'Autosampler position {pos} has conflicting sample names in {Path(path).name}.')
                mapping[pos] = text
    if not mapping:
        raise ValueError('No [ordinal, autosampler position, sample name] blocks found.')
    return mapping, warnings


# --------------------------------------------------------------------------
# Method tables and the bundled library
# --------------------------------------------------------------------------

def parse_method_workbook(path):
    """Use only the first mg/L + mg/kg block of the method's Results order sheet.
    Many files contain a SECOND full-universe template sheet; it must not
    overwrite the actual method. Legacy view-unspecified tables are skipped.
    Returns channels in the sheet's column order (the report order).
    """
    pass
    sheets = read_workbook(path)
    sh = next((s for s in sheets if normalized_name(s.name) == 'results order'), sheets[0])
    wave_row = None
    for r in range(min(sh.nrows, 25)):
        if sum(bool(WAVE_PATTERN.fullmatch(str(v))) for v in sh.row(r)):
            wave_row = r
            break
    if wave_row is None:
        raise ValueError('Method lacks explicit axial/radial wavelength labels; no view was inferred.')
    li = ki = None
    kind = 'DL'
    for r in range(wave_row + 1, min(sh.nrows, wave_row + 6)):
        label = ' '.join(str(x) for x in sh.row(r)[:3])
        if re.search(r'(?:LOQ|LOD|DL).*mg\s*/\s*l', label, re.I):
            li = r
            kind = re.search(r'LOQ|LOD|DL', label, re.I)[0].upper()
        if re.search(r'mg\s*/\s*kg', label, re.I):
            ki = r
    if li is None:
        raise ValueError('Method mg/L reporting-limit row not found.')
    out = {}
    sha = checksum(str(path))
    for c, v in enumerate(sh.row(wave_row)):
        match = WAVE_PATTERN.fullmatch(str(v))
        if not match:
            continue
        element = str(sh.cell(wave_row + 1, c)).strip()
        if not re.fullmatch(r'[A-Z][a-z]?', element):
            continue
        ch = canonical_channel(element + ' ' + str(v), allow_unknown=False)
        rank = optional_number(sh.cell(wave_row - 1, c))
        cfg = ChannelSetting(ch, preference_order=int(rank) if rank is not None and rank == int(rank) and rank > 0 else None,
                             dl_mg_l=optional_number(sh.cell(li, c)), dl_mg_kg=optional_number(sh.cell(ki, c)) if ki is not None else None,
                             limit_kind=kind, limit_source=f'{Path(path).name} | {sh.name} | row {li + 1}, column {c + 1}',
                             limit_source_sha256=sha)
        out[ch] = cfg
    if not out:
        raise ValueError('No complete analytical channels found in method.')
    return out


def parse_method_csv(path):
    """Plasmatti's portable method CSV (channel, preference_order, dl_mg_l, dl_mg_kg, limit_kind)."""
    pass
    imported = {}
    sha = checksum(str(path))
    reader = csv.DictReader(io.StringIO(decode_file(path)))
    if not reader.fieldnames or 'channel' not in reader.fieldnames:
        raise ValueError('Method CSV must contain a channel column.')
    for index, row in enumerate(reader, 2):
        ch = canonical_channel(str(row.get('channel', '')).strip(), allow_unknown=False)
        if ch in imported:
            raise ValueError(f'Method CSV row {index}: duplicate channel {ch}.')
        pref = optional_number(row.get('preference_order'), decimal='dot')
        if str(row.get('preference_order') or '').strip() and (pref is None or pref < 1 or pref != int(pref)):
            raise ValueError(f'Method CSV row {index}: preference must be a positive integer.')
        values = {}
        for key in ('dl_mg_l', 'dl_mg_kg'):
            text = str(row.get(key) or '').strip()
            values[key] = number(text, decimal='dot') if text else None
        kind = (str(row.get('limit_kind') or '').strip() or 'DL').upper()
        if kind not in ('LOQ', 'LOD', 'DL'):
            raise ValueError(f'Method CSV row {index}: limit kind must be LOQ, LOD or DL.')
        imported[ch] = ChannelSetting(ch, preference_order=int(pref) if pref is not None else None,
                                      dl_mg_l=values['dl_mg_l'], dl_mg_kg=values['dl_mg_kg'], limit_kind=kind,
                                      limit_source=f'{Path(path).name} | row {index}', limit_source_sha256=sha)
    if not imported:
        raise ValueError('Method CSV contains no channels.')
    return imported


def read_method_file(path):
    if Path(path).suffix.lower() in ('.xls', '.xlsx'):
        return parse_method_workbook(path)
    return parse_method_csv(path)


def load_library(path=None):
    if not path:                                   # one-file release: the library is embedded
        return json.loads(embedded_file('method_library.json').decode('utf-8'))
    path = Path(path)
    return json.loads(path.read_text(encoding='utf-8')) if path.exists() else {'methods': [], 'standard_groups': []}


def method_elements(entry):
    """Sorted element symbols covered by a library method (from its channel table)."""
    return sorted({str(c['channel']).split()[0] for c in entry.get('channels', [])})


def describe_method(label, library=None, limit=6):
    """Name plus what the method covers, e.g. 'Method 48 - 1 (35 elements: Ag, Al, As, B, Ba, Be ...)'.

    Method names are free text chosen by each laboratory, so the name alone says
    little. Labels that already list their elements are returned unchanged.
    Unknown labels are returned unchanged (nothing is guessed).
    """
    library = library if library is not None else load_library()
    key = method_key(label)
    entry = next((m for m in library.get('methods', []) if method_key(m['label']) == key), None)
    if not entry:
        return label
    elements = method_elements(entry)
    if not elements or {x.lower() for x in re.split(r'\s*\+\s*', label)} == {e.lower() for e in elements}:
        return label
    shown = ', '.join(elements[:limit]) + (f' and {len(elements) - limit} more' if len(elements) > limit else '')
    return f'{label} ({len(elements)} element{"" if len(elements) == 1 else "s"}: {shown})'


def method_key(text):
    text = normalized_name(text)
    m = re.search(r'method\s*(\d+)\s*[-.]\s*(\d+)', text)
    if m:
        return f'method {int(m[1])}-{int(m[2])}'
    return re.sub(r'\s+', '', text)


def _validate_method_channels(channels):
    problems = []
    for ch, cfg in channels.items():
        if cfg.channel != ch:
            problems.append(f'{ch}: inconsistent channel key.')
        for label, value in (('mg/L limit', cfg.dl_mg_l), ('mg/kg limit', cfg.dl_mg_kg)):
            if value is not None and (not isinstance(value, (int, float)) or not math.isfinite(value) or value <= 0):
                problems.append(f'{ch}: {label} must be a finite positive number.')
        if cfg.preference_order is not None and (int(cfg.preference_order) != cfg.preference_order or cfg.preference_order < 1):
            problems.append(f'{ch}: preference must be a positive integer.')
        if cfg.limit_kind not in ('LOQ', 'LOD', 'DL'):
            problems.append(f'{ch}: limit kind must be LOQ, LOD or DL.')
    return problems


def replace_channel_settings(current, imported, *, method_label='', keep_manual=False):
    """Return a NEW complete channel dictionary for the measured channels.

    Every measured channel defined by the method receives the method's values.
    Every measured channel the method does not define is reset to an explicit
    unresolved state (no preference, no limit) -- never left with a previous
    method's values. Manual channel choices are retained only when
    ``keep_manual`` (same method re-applied).
    """
    pass
    problems = _validate_method_channels(imported)
    if problems:
        raise ValueError('Method table is invalid; nothing was changed:\n' + '\n'.join(problems[:20]))
    matched = [ch for ch in current if ch in imported]
    if not matched:
        raise ValueError('No analytical channels in this method match the imported run; nothing was changed.')
    new = {}
    for ch, old in current.items():
        if ch in imported:
            cfg = copy.deepcopy(imported[ch])
        else:
            cfg = ChannelSetting(ch, limit_source=f'Not defined by method {method_label}'.strip())
        cfg.manual_select = bool(old.manual_select) if keep_manual else False
        cfg.enabled = bool(old.enabled) if keep_manual else True
        new[ch] = cfg
    return new, matched


def _method_identity(project):
    rec = project.method_recognition or {}
    return (project.settings.method or '', rec.get('sha256', '') or rec.get('source', ''))


def replace_method(project, imported_channels, *, label, source='', sha256='', status='MANUAL_SELECTED',
                   message='', issues=(), evidence=(), element_order=None):
    """Transactional complete method replacement on ``project``.

    The new channel table is validated and built completely before anything is
    committed. On a change of method, manual channel overrides, disabled
    channels and recorded low/high regime decisions are cleared (they were
    made against another preference/limit table) and the clearing is recorded.
    Returns a summary dict. Raises ValueError without changing the project.
    """
    same = (label, sha256 or source) == _method_identity(project) and bool(label)
    new_channels, matched = replace_channel_settings(project.channels, imported_channels,
                                                     method_label=label, keep_manual=same)
    cleared = {'manual_channels': 0, 'disabled_channels': 0, 'regime_decisions': 0}
    if not same:
        cleared['manual_channels'] = sum(1 for c in project.channels.values() if c.manual_select)
        cleared['disabled_channels'] = sum(1 for c in project.channels.values() if not c.enabled)
        cleared['regime_decisions'] = sum(len(a.standard_overrides) for a in project.assignments.values())
    unmatched = sorted(set(project.channels) - set(imported_channels))
    notes = []
    for issue in issues:
        notes.append('Method source issue: ' + issue)
    if unmatched:
        notes.append(f'Method {label} does not define these measured channels: ' + ', '.join(unmatched)
                     + '. They have no preference order or reporting limit; nothing was inferred.')
    if any(cleared.values()):
        notes.append('Method change cleared earlier analyst choices made for another method: '
                     f'{cleared["manual_channels"]} manual channel override(s), {cleared["disabled_channels"]} '
                     f'disabled channel(s), {cleared["regime_decisions"]} low/high regime decision(s).')
    notes.append(f'Method: {label} ({source}); historical reference table, not an instrument recalibration.')
    order = list(element_order) if element_order else []
    if not order:
        for ch in imported_channels:
            el = ch.split()[0]
            if el not in order:
                order.append(el)
    # ---- commit (no exceptions past this point) ----
    pass
    project.channels = new_channels
    if not same:
        for a in project.assignments.values():
            a.standard_overrides = {}
    project.settings.method = label
    project.method_notes = notes
    project.method_element_order = order
    project.method_recognition = dict(project.method_recognition or {})
    project.method_recognition.update(status=status, label=label, source=source, sha256=sha256,
                                      message=message or project.method_recognition.get('message', ''),
                                      unmatched_channels=unmatched)
    if evidence:
        project.method_recognition['evidence'] = list(evidence)
    project.decision_log.append({'action': 'method_applied', 'time': utc_now(), 'method': label,
                                 'source': source, 'status': status, 'matched_channels': len(matched),
                                 'unmatched_channels': unmatched, 'cleared': cleared})
    return {'matched': len(matched), 'unmatched': unmatched, 'cleared': cleared}


def library_channels(record):
    pass
    out = {}
    for data in record['channels']:
        cfg = ChannelSetting(**data)
        out[cfg.channel] = cfg
    return out


def apply_method(project, record, *, status='MANUAL_SELECTED', message='Analytical method explicitly selected.',
                 evidence=()):
    """Apply a bundled library snapshot as a complete replacement. Returns matched count."""
    summary = replace_method(project, library_channels(record), label=record.get('label', record.get('source', '')),
                             source=record.get('source', ''), sha256=record.get('sha256', ''), status=status,
                             message=message, issues=record.get('issues', []), evidence=evidence,
                             element_order=None)
    return summary['matched']


WAVELENGTH_TOLERANCE_NM = 0.01   # the analyst may move a peak by a few thousandths of a nm in the instrument software


def master_record(lib=None):
    lib = lib if lib is not None else load_library()
    mid = lib.get('master_id')
    return next((m for m in lib.get('methods', []) if m.get('id') == mid), None) if mid else None


def master_channels(measured, record, tol=WAVELENGTH_TOLERANCE_NM):
    """Settings for the measured channels from the master table. A measured line matches a master
    line of the same element and view whose wavelength differs by at most `tol` nm."""
    pass
    table = library_channels(record)
    by_key = defaultdict(list)
    for ch, cfg in table.items():
        el, wl, view = split_channel(ch)
        by_key[(el, view)].append((float(wl), cfg))
    out = {}
    for ch in measured:
        el, wl, view = split_channel(ch)
        try:
            wl = float(wl)
        except ValueError:
            continue
        near = sorted((abs(w - wl), w, cfg) for w, cfg in by_key.get((el, view), []) if abs(w - wl) <= tol + 1e-9)
        if not near:
            continue
        _, w, cfg = near[0]
        new = copy.deepcopy(cfg)
        new.channel = ch
        if abs(w - wl) > 1e-9:
            new.limit_source += f' | table line {el} {w:.3f} {view}, {abs(w - wl):.3f} nm from the measured {ch}'
        out[ch] = new
    return out


def apply_master(project, master, outcome, method):
    """Preference order and limits from the master table for every measured line.
    The method name (from the folder or file names, when present) is kept for the report only."""
    name = ''
    if method is not None and outcome.get('hints'):
        name = method.get('label', '')
    elif method is not None:
        name = method.get('label', '')
    chans = master_channels(project.channels, master)
    if not chans:
        project.method_notes = ['LIMIT TABLE: no measured line is in the built-in limit table.']
        return
    pass
    label = name or MASTER_NAME
    for cfg in chans.values():               # the table's file name is not shown anywhere
        where = (cfg.limit_source or '').split(' | ', 1)
        cfg.limit_source = MASTER_NAME + (' | ' + where[1] if len(where) > 1 else '')
    evidence = list(outcome.get('evidence', []))
    replace_method(project, chans, label=label, source=MASTER_NAME, sha256=master.get('sha256', ''),
                   status='MASTER', message='Preference order and limits from the built-in limit table for every measured line.',
                   issues=[], evidence=evidence)
    project.method_notes = [n for n in project.method_notes if not n.startswith('Method: ')]
    project.method_notes.append('Preference order and limits: built-in limit table'
                                + (f'; method name from the file names: {name}' if name else '') + '.')
    project.method_recognition['method_name'] = name
    project.method_recognition['master'] = master.get('id', '')
    project.decision_log[-1]['action'] = 'master_table_applied'


def import_method_file(project, path):
    """Import an XLS/XLSX/CSV method table as a complete, validated replacement."""
    pass
    imported = read_method_file(path)
    return replace_method(project, imported, label=Path(path).stem, source=Path(path).name,
                          sha256=checksum(str(path)), status='MANUAL_SELECTED',
                          message='User-imported method table; review the source.')


# --------------------------------------------------------------------------
# Standard compositions
# --------------------------------------------------------------------------

def _alias_regex(alias):
    """Token-bounded, separator-tolerant pattern for a documented alias.

    ``SS-028228`` matches ``SS028228`` and ``ss 028228``; ``CMS-1`` does NOT
    match ``CMS-10``; ``Multi 5`` does NOT match ``Multi 50``.
    """
    pieces = re.findall(r'[A-Za-z]+|\d+', alias)
    if not pieces:
        return None
    body = r'[\s\-_./]*'.join(re.escape(p) for p in pieces)
    return re.compile(r'(?<![A-Za-z0-9])' + body + r'(?![A-Za-z0-9])', re.I)


def standard_group_matches(prefix, library):
    hits = []
    for rec in library.get('standard_groups', []):
        for alias in rec.get('aliases', []):
            rx = _alias_regex(alias)
            if rx is not None and rx.search(prefix):
                hits.append(rec)
                break
    return hits


STANDARD_LEVEL_RE = re.compile(r'(?<![\d.,])(\d+(?:[.,]\d+)?)\s*(?:ppm|mg\s*/\s*l)\b', re.I)


def standard_scope(name, library=None):
    """Resolve only explicit element names or archive-documented standard codes."""
    m = STANDARD_LEVEL_RE.search(name)
    prefix = name[:m.start()].strip() if m else name
    # 'K 1 ppm' explicitly names the K-specific preparation, not all constituents
    # of the SS stock from which the solution may have been prepared.
    direct = re.fullmatch(r'([A-Z][a-z]?)(?:\s*\+\s*[A-Z][a-z]?)*', prefix)
    if direct:
        return ','.join(re.findall(r'[A-Z][a-z]?', prefix)), {}, 'explicit sample label'
    parens = re.findall(r'\(([A-Z][a-z]?(?:\s*\+\s*[A-Z][a-z]?)*)\)', prefix)
    if parens:
        return ','.join(re.findall(r'[A-Z][a-z]?', parens[-1])), {}, 'explicit element in label'
    lib = library or load_library()
    candidates = standard_group_matches(prefix, lib)
    if len(candidates) == 1:
        rec = candidates[0]
        return ','.join(rec['elements']), dict(rec.get('nominal_multipliers', {})), rec.get('source', 'archive standard table')
    if len(candidates) > 1:
        return '?', {}, 'Label matches more than one documented standard group: ' + ', '.join(c['name'] for c in candidates)
    return '?', {}, 'Unrecognized standard composition; enter its verified composition.'


# --------------------------------------------------------------------------
# CSV/PDF comparison
# --------------------------------------------------------------------------

def _tol(decimals, fallback=0.0011):
    if decimals is None:
        return fallback
    return 0.5 * 10 ** (-decimals) + 1e-12


def compare_replicate_sources(primary, secondary, precision=None, *, primary_name='CSV', secondary_name='PDF'):
    """Independent comparison of two exports of (supposedly) the same run.

    Tolerances follow the secondary report's printed decimals (half a unit in
    the last printed place); without that information a 0.0011 mg/L absolute
    tolerance is used. Categories are kept separate so a high overlap with a
    small secondary report is never presented as complete agreement.
    """
    precision = precision or {}
    a = {(x.sequence, x.channel): x for x in primary}
    b = {(x.sequence, x.channel): x for x in secondary}
    overlap = sorted(set(a) & set(b))
    only_primary = sorted(set(a) - set(b))
    only_secondary = sorted(set(b) - set(a))
    cats = {k: [] for k in ('coverage', 'identity', 'replicate_counts', 'replicate_values',
                            'summary_statistics', 'error_states', 'acquisition_time')}
    checked_values = 0
    both_errors = 0
    identity_conflicts = 0
    time_conflicts = time_checked = 0
    for key in overlap:
        x, y = a[key], b[key]
        prec = precision.get(key, {})
        ident = []
        if x.position != y.position:
            ident.append(f'autosampler position {x.position} vs {y.position}')
        if normalized_name(x.sample_id) != normalized_name(y.sample_id):
            ident.append(f'sample ID "{x.sample_id}" vs "{y.sample_id}"')
        if ident:
            identity_conflicts += 1
            cats['identity'].append(f'{key}: ' + '; '.join(ident))
        if bool(x.instrument_error) != bool(y.instrument_error):
            cats['error_states'].append(f'{key}: {primary_name} {"error" if x.instrument_error else "valid"} '
                                        f'vs {secondary_name} {"error" if y.instrument_error else "valid"}')
        nx = x.exported_replicate_count or len(x.replicates)
        ny = y.exported_replicate_count or len(y.replicates)
        if x.instrument_error and y.instrument_error and not x.replicates and not y.replicates:
            # Both exports agree the record failed. The PDF prints ONE line for a
            # saturated record ("Saturated in preshot (code 2)") where the CSV has
            # one row per attempt (observed for all 257/123/61 such records in
            # the 16/17/18 Sept 2026 runs); attempt counts are not comparable.
            both_errors += 1
        elif nx != ny or len(x.replicates) != len(y.replicates):
            cats['replicate_counts'].append(f'{key}: {primary_name} {len(x.replicates)}/{nx} vs '
                                            f'{secondary_name} {len(y.replicates)}/{ny} (values/attempts)')
        elif x.replicates:
            decs = prec.get('replicates') or [None] * len(y.replicates)
            for idx, (v1, v2, d) in enumerate(zip(x.replicates, y.replicates, decs), 1):
                checked_values += 1
                if abs(v1 - v2) > _tol(d):
                    cats['replicate_values'].append(f'{key} replicate {idx}: {primary_name} {v1:.8g} vs {secondary_name} {v2:.8g}')
        for attr, pkey, fb in (('instrument_mean', 'mean', 0.0011), ('instrument_sd', 'sd', 0.00011), ('instrument_rsd', 'rsd', 0.011)):
            av, bv = getattr(x, attr), getattr(y, attr)
            label = attr.replace('instrument_', '')
            if (av is None) != (bv is None):
                if not (x.instrument_error and y.instrument_error):
                    cats['summary_statistics'].append(f'{key}: {label} present only in '
                                                      f'{primary_name if av is not None else secondary_name}')
            elif av is not None and abs(av - bv) > _tol(prec.get(pkey), fb):
                cats['summary_statistics'].append(f'{key}: {label} {primary_name}={av:.8g}, {secondary_name}={bv:.8g}')
        tx = [_time_text(t) for t in x.replicate_times]
        ty = [_time_text(t) for t in y.replicate_times]
        if tx and ty and len(tx) == len(ty):
            time_checked += 1
            if tx != ty:
                time_conflicts += 1
                if len(cats['acquisition_time']) < 200:
                    cats['acquisition_time'].append(f'{key}: replicate times differ ({tx[0]} vs {ty[0]})')
    if only_primary:
        cats['coverage'].append(f'{len(only_primary)} of {len(a)} {primary_name} sequence/channel records are absent from the '
                                f'{secondary_name} (e.g. {only_primary[0]}). The {secondary_name} does not cover the complete run.')
    if only_secondary:
        cats['coverage'].append(f'{len(only_secondary)} {secondary_name} records are absent from the {primary_name} '
                                f'(e.g. {only_secondary[0]}).')
    different_run = (not overlap or identity_conflicts >= max(1, 0.5 * len(overlap))
                     or (time_checked >= 2 and time_conflicts >= 0.5 * time_checked))
    summary = {
        'primary_records': len(a), 'secondary_records': len(b), 'overlap': len(overlap),
        'coverage_of_primary': round(len(overlap) / len(a), 6) if a else 0.0,
        'replicate_values_checked': checked_values, 'acquisition_times_checked': time_checked,
        'matching_error_records': both_errors,
        'different_run': bool(different_run),
        'counts': {k: len(v) for k, v in cats.items()},
        'details': {k: v[:200] for k, v in cats.items()},
    }
    summary['agreement'] = (not different_run and not any(summary['counts'].values()))
    return summary


def comparison_notes(summary, secondary_label):
    c = summary['counts']
    head = (f'PDF cross-check {secondary_label}: covers {summary["overlap"]} of {summary["primary_records"]} primary '
            f'sequence/channel records ({summary["coverage_of_primary"]:.1%}); {summary["replicate_values_checked"]} replicate values '
            f'and {summary["acquisition_times_checked"]} acquisition-time lists checked; {summary.get("matching_error_records", 0)} records are '
            f'instrument errors in both exports. '
            + ('All checked categories agree.' if summary['agreement'] else
               'Discrepancies: ' + ', '.join(f'{k.replace("_", " ")} {v}' for k, v in c.items() if v) + '.'))
    notes = [head]
    for cat, items in summary['details'].items():
        for item in items[:10]:
            notes.append(f'CSV/PDF discrepancy [{cat.replace("_", " ")}]: {item}')
        if summary['counts'][cat] > 10:
            notes.append(f'CSV/PDF discrepancy [{cat.replace("_", " ")}]: ... {summary["counts"][cat] - 10} more.')
    return notes


# --------------------------------------------------------------------------
# One-run import
# --------------------------------------------------------------------------

def classify_workbook(path):
    """Say what an Excel file is, by its content (never by its name).

    'summary'     AVG+STDEV report (means and SDs per sample and line)
    'average'     untouched wide AVG report (means per sample and line)
    'edited'      a workbook with corrections or formulas added by someone: not instrument data
    'unknown'     anything else
    """
    for parser, kind in ((parse_summary_workbook, 'summary'), (parse_average_workbook, 'average')):
        try:
            got = parser(path)
        except Exception:
            continue
        if getattr(got, 'processed', False):
            return 'edited'
        if got.readings:
            return kind
    return 'unknown'


def load_run_files(paths, *, prefer='auto', autosampler_path=None, details=None):
    """Import ONE run. Source selection is explicit, sidecars are cross-checked.
    Native CSV > PDF > summary > untouched AVG. Related files are not added as
    extra replicates. Multiple primary candidates need an explicit choice.

    ``details`` (optional dict) receives the structured CSV/PDF comparison.
    """
    pass
    files = [str(Path(p)) for p in paths if Path(p).is_file() and not Path(p).name.startswith(('._', '~$'))]
    sidecars = [p for p in files if (autosampler_path and Path(p) == Path(autosampler_path)) or 'autosampler' in Path(p).stem.casefold()]
    measurement_files = [p for p in files if p not in sidecars]
    csvs = [p for p in measurement_files if Path(p).suffix.lower() == '.csv']
    pdfs = []
    for p in measurement_files:
        if Path(p).suffix.lower() != '.pdf':
            continue
        kind = classify_pdf(p)
        if kind == 'replicate' or (kind == 'unknown' and re.search(r'replicat|\brep\b', Path(p).stem, re.I)):
            pdfs.append(p)
    summaries = [p for p in measurement_files if Path(p).suffix.lower() in ('.xls', '.xlsx') and re.search(r'avg.*std|average.*std', Path(p).name, re.I)]
    averages = [p for p in measurement_files if Path(p).suffix.lower() in ('.xls', '.xlsx') and p not in summaries and re.search(r'\bavg\b|cross.?table', Path(p).name, re.I)]
    spreadsheet_problems = []
    for p in measurement_files:
        if Path(p).suffix.lower() in _SPREADSHEET and p not in summaries and p not in averages:
            kind = classify_workbook(p)
            if kind == 'summary':
                summaries.append(p)
            elif kind == 'average':
                averages.append(p)
            elif kind == 'edited':
                spreadsheet_problems.append(f'{Path(p).name}: this workbook holds corrected or edited results, not instrument readings.')
            else:
                spreadsheet_problems.append(f'{Path(p).name}: this Excel layout is not recognised. Plasmatti needs the replicate '
                                            'readings (CSV or PDF) or an AVG or AVG+STDEV report.')
    errors = list(spreadsheet_problems)
    imported = None
    primary = None
    precision_by_path = {}
    groups = [('csv', csvs), ('pdf', pdfs), ('summary', summaries), ('average', averages)]
    if prefer != 'auto':
        groups = sorted(groups, key=lambda pair: pair[0] != prefer)
    for kind, candidates in groups:
        successful = []
        for path in candidates:
            try:
                if kind == 'csv':
                    with open(path, 'rb') as peek:
                        first = peek.read(800).decode('utf-8', errors='replace')
                    if 'Seq. No.' in first:
                        got = parse_crystal_csv(path)
                    else:
                        got = Imported(parse_normalized_csv(path), [], 'Plasmatti normalized CSV')
                elif kind == 'pdf':
                    prec = {}
                    got = Imported(parse_perkinelmer_replicate_pdf(path, precision=prec), [], 'PerkinElmer replicate PDF')
                    precision_by_path[path] = prec
                elif kind == 'summary':
                    got = parse_summary_workbook(path)
                else:
                    got = parse_average_workbook(path)
                if got.processed:
                    errors.extend(got.warnings)
                    continue
                if got.readings:
                    successful.append((path, got))
            except Exception as exc:
                errors.append(f'{Path(path).name}: {exc}')
        if len(successful) > 1:
            unique = {checksum(p) for p, g in successful}
            if len(unique) > 1:
                raise ValueError(f'Multiple {kind} sources found. Select one run/source explicitly: ' + ', '.join(Path(p).name for p, g in successful))
        if successful:
            primary, imported = successful[0]
            break
    if imported is None:
        raise ValueError('No readable measurement file.\n' + '\n'.join(errors[:12]))
    notes = [f'Primary source: {Path(primary).name} [{imported.source_format}].'] + imported.warnings
    if (primary in summaries or primary in averages) and not any(
            r.calibration_mean is not None for r in imported.readings):
        notes.append(EXCEL_BASIS_NOTE)
    elif imported.source_format != 'Plasmatti normalized CSV':
        # Plasmatti's own normalized CSV (the anonymized demo) has no Conc (Calib) by design.
        with_mean = [r for r in imported.readings if r.instrument_mean is not None and not r.instrument_error]
        missing = sum(r.calibration_mean is None for r in with_mean)
        if missing:
            notes.append(basis_note(missing, len(with_mean)))
    records = imported.readings
    comparisons = []
    if primary in csvs and pdfs:
        for pdf_path in pdfs:
            try:
                prec = {}
                pdf_records = parse_perkinelmer_replicate_pdf(pdf_path, precision=prec)
            except Exception as exc:
                notes.append(f'PDF cross-check FAILED for {Path(pdf_path).name}: {exc}. The CSV remains the sole measurement source; review before reporting.')
                comparisons.append({'secondary': Path(pdf_path).name, 'failed': str(exc)})
                continue
            summary = compare_replicate_sources(records, pdf_records, prec)
            summary['secondary'] = Path(pdf_path).name
            if summary['different_run']:
                raise ValueError('Selected PDF and CSV do not appear to represent the same analytical run '
                                 f'({summary["overlap"]} shared records; identity conflicts {summary["counts"]["identity"]}; '
                                 f'time conflicts {summary["counts"]["acquisition_time"]}). '
                                 'Please import the matching pair, or remove the optional PDF.')
            comparisons.append(summary)
            notes.extend(comparison_notes(summary, Path(pdf_path).name))
    if details is not None:
        details['comparisons'] = comparisons
    identity = {}
    for x in records:
        key = (x.position, x.channel) if x.position is not None else None
        if key is not None:
            identity.setdefault(key, []).append(x)
    for path in summaries:
        if path == primary:
            continue
        try:
            side = parse_summary_workbook(path)
        except Exception as exc:
            notes.append(f'Summary not read: {Path(path).name}: {exc}')
            continue
        matched = conflicts = unmatched = other_name = 0
        conflict_text = []
        staged = []
        for src in side.readings:
            matches = identity.get((src.position, src.channel), []) if src.position is not None else []
            if len(matches) != 1:
                unmatched += 1
                continue
            dest = matches[0]
            if not src.sequence_inferred and src.sequence != dest.sequence:
                unmatched += 1
                continue
            if not src.sample_id.startswith(('Position ', 'Entry ')) and normalized_name(src.sample_id) not in {
                    normalized_name(dest.sample_id), normalized_name(dest.mapped_sample_id or dest.sample_id)}:
                # The workbook names a different sample at this position: not the same measurement.
                unmatched += 1
                other_name += 1
                continue
            staged.append((src, dest))
        name = Path(path).name
        if len(side.readings) == 0 or len(staged) < 0.5 * len(side.readings):
            # Not this run's summary (or unusable): never attach it, never block the import.
            notes.append(f'{name}: only {len(staged)} of {len(side.readings)} summary records match this run '
                         '(positions/channels/sequence); ignored as a cross-check. Check that it belongs to this run.')
            comparisons.append({'secondary': name, 'kind': 'summary', 'ignored':
                                f'does not match this run ({len(staged)} of {len(side.readings)} records)'})
            continue
        for src, dest in staged:
            for key in ('instrument_mean', 'instrument_sd', 'instrument_rsd'):
                old, new = getattr(dest, key), getattr(src, key)
                if old is not None and new is not None and not math.isclose(old, new, rel_tol=1e-8, abs_tol=1e-10):
                    conflicts += 1
                    text = f'sequence {dest.sequence} {dest.channel} {key}: primary {old}; {name} {new}'
                    conflict_text.append(text)
                    dest.import_notes.append(f'Summary conflict {key}: primary {old}; {name} {new}. Primary retained.')
                # A value missing in the replicate file is never taken from the workbook: the workbook
                # only cross-checks, it never supplies a number to the calculation.
            dest.summary_source = path
            matched += 1
        notes.append(f'{name}: cross-check only, not used in the calculation: {matched} measurements compared, '
                     f'{conflicts} differing values (the replicate file is used); {unmatched} not matched'
                     + (f', of which {other_name} with a different sample name at the same position' if other_name else '')
                     + '.')
        comparisons.append({'secondary': name, 'kind': 'summary', 'overlap': matched, 'primary_records': len(records),
                            'counts': {'summary_statistics': conflicts}, 'details': {'summary_statistics': conflict_text[:50]},
                            'unmatched': unmatched, 'agreement': conflicts == 0})
    for p in sidecars:
        if Path(p).suffix.lower() in ('.xls', '.xlsx', '.csv'):
            mapping, _ = parse_autosampler(p)
            filled = conflicts = 0
            for rec in records:
                if rec.position not in mapping:
                    continue
                mapname = mapping[rec.position]
                rec.mapped_sample_id = mapname
                if rec.sample_id.startswith(('Position ', 'Entry ')):
                    rec.sample_id = mapname
                    filled += 1
                elif normalized_name(rec.sample_id) != normalized_name(mapname):
                    conflicts += 1
            measured_positions = {rec.position for rec in records if rec.position is not None}
            matched_positions = measured_positions & set(mapping)
            if len(matched_positions) < len(measured_positions):
                notes.append(f'AUTOSAMPLER REVIEW: {len(matched_positions)}/{len(measured_positions)} '
                             'measured positions matched the mapping. Unmapped sample names require review.')
            differing = len({rec.sequence for rec in records if rec.mapped_sample_id and normalized_name(rec.sample_id) != normalized_name(rec.mapped_sample_id)})
            notes.append(f'{Path(p).name}: {len(mapping)} mapped positions; {len(matched_positions)} matched instrument positions; '
                         f'{filled} unnamed records resolved; {differing} measurement(s) whose autosampler label differs from the '
                         'instrument label (both retained; identification checks whether they are equivalent).')
    if not sidecars and records:
        notes.append('No autosampler file was supplied: sample identities are the labels the instrument recorded.')
    if errors:
        notes.extend('Source note: ' + e for e in errors[:12])
    return records, notes


def check_sample_names(records, has_map):
    """Refuse a run whose samples cannot be named. An autosampler file is optional only
    when the measurement files carry the sample labels themselves."""
    if not records:
        return
    placeholders = {r.sequence for r in records if r.sample_id.startswith(('Position ', 'Entry '))}
    total = len({r.sequence for r in records})
    if has_map:
        if not any(r.mapped_sample_id for r in records):
            raise ValueError('No autosampler position matches the measurements. Choose the autosampler file of this run.')
    elif total and len(placeholders) > 0.5 * total:
        raise ValueError('These measurement files do not contain sample names. Choose the autosampler file of this run.')


def _name_is(path, pattern):
    return re.search(pattern, Path(path).stem, re.I) is not None


_SPREADSHEET = ('.xls', '.xlsx', '.xlsm')


def discover_run_files(chosen, include_pdf=False):
    """Find the other files of ONE run beside the file(s) the analyst chose.

    Nothing is guessed: a kind of file is proposed only when exactly one file in
    the same folder carries its name pattern (and, for the autosampler map,
    parses as a position map).  The result is a proposal; the identity of every
    file is still checked on import.  Returns a dict with ``replicates`` (CSV /
    PDF paths), ``autosampler``, ``summary`` (AVG+STDEV workbook or ''), and
    ``notes`` (what was found or left to the analyst).  A replicate PDF beside a
    CSV is only reported unless ``include_pdf`` (reading a long PDF takes about a
    minute, so adding it is the analyst's choice).
    """
    chosen = [Path(p) for p in chosen]
    out = {'replicates': [str(p) for p in chosen if p.suffix.lower() in ('.csv', '.pdf') + _SPREADSHEET],
           'autosampler': '', 'summary': '', 'notes': []}
    if not chosen or len({p.parent.resolve() for p in chosen}) != 1:
        return out
    folder = chosen[0].parent
    try:
        files = sorted(p for p in folder.iterdir() if p.is_file() and not p.name.startswith(('._', '~$')))
    except OSError:
        return out
    have = {p.suffix.lower() for p in chosen}
    for ext in ('.csv', '.pdf'):
        if ext in have:
            continue
        if ext == '.pdf':
            cand = [p for p in files if p.suffix.lower() == '.pdf' and p not in chosen and
                    (classify_pdf(p) == 'replicate' or (classify_pdf(p) == 'unknown' and _name_is(p, r'replicat')))]
        else:
            cand = [p for p in files if p.suffix.lower() == '.csv' and p not in chosen and classify_csv(p) == 'replicate']
        if len(cand) == 1 and (include_pdf or ext != '.pdf'):
            out['replicates'].append(str(cand[0]))
            out['notes'].append(f'Also found {cand[0].name} (used as an independent cross-check).')
        elif len(cand) == 1:
            out['pdf_available'] = str(cand[0])
            out['notes'].append(f'{cand[0].name} is also here: add it with "Choose measurement file" for an independent '
                                'cross-check (reading a long PDF takes about a minute).')
        elif len(cand) > 1:
            out['notes'].append(f'{len(cand)} possible replicate {ext[1:].upper()} files; none chosen automatically.')
    out['replicates'].sort(key=lambda p: Path(p).suffix.lower() != '.csv')
    maps = [p for p in files if p.suffix.lower() in _SPREADSHEET + ('.csv',) and p not in chosen and
            (_name_is(p, r'auto.?sampler') or _name_is(p, r'(?:^|\W)(?:a.?s.?list|sample.?list)(?:\W|$)'))]
    valid = []
    for cand in maps:
        try:
            mapping, _ = parse_autosampler(cand)
        except Exception:
            continue
        if mapping:
            valid.append(cand)
    if len(valid) == 1:
        out['autosampler'] = str(valid[0])
        out['notes'].append(f'Autosampler file: {valid[0].name}.')
    elif len(valid) > 1:
        out['notes'].append('More than one autosampler file in this folder; choose it manually.')
    sums = [p for p in files if p.suffix.lower() in _SPREADSHEET and p not in chosen and
            _name_is(p, r'(?:avg|average).*(?:std|stdev|sd)')]
    if len(sums) == 1:
        out['summary'] = str(sums[0])
        out['notes'].append(f'Also found {sums[0].name} (AVG+STDEV; compared with the replicates, never added to them).')
    elif len(sums) > 1:
        out['notes'].append(f'{len(sums)} AVG+STDEV workbooks in this folder; none used automatically.')
    return out


def apply_method_source(project):
    """Set preference order and limits for the measured lines: from the master table (default)
    or from the run's own method table recognised from the file names and lines."""
    pass
    lib = load_library()
    outcome, method = recognize_method(project.source_paths, project.channels, lib)
    project.method_recognition = outcome
    master = master_record(lib)
    if project.settings.method_source == 'master' and master is not None:
        apply_master(project, master, outcome, method)
    elif method is not None:
        evidence = list(outcome.get('evidence', []))
        message = outcome.get('message', '')
        status = outcome['status']
        replace_method(project, library_channels(method), label=method.get('label', ''), source=method.get('source', ''),
                       sha256=method.get('sha256', ''), status=status, message=message,
                       issues=method.get('issues', []), evidence=evidence)
        project.method_recognition.update({k: v for k, v in outcome.items() if k not in ('status', 'label', 'source', 'message', 'evidence')})
        project.decision_log[-1]['action'] = 'method_recognized_automatically'
    else:
        project.method_notes = ['METHOD RECOGNITION: ' + outcome['message']]


def configure_project(project):
    """Automatically recognize the method and the sample type evidence.

    Role and standard identification is done by the single identification
    service in plasmati_automation (called by make_project).
    """
    apply_method_source(project)
    labels = set()
    for folder in {Path(p).parent.name for p in project.source_paths}:
        for label in re.findall(r'\(([^)]+)\)', folder):
            if label.strip().lower() in ('liquid', 'solid'):
                labels.add(label.strip().title())
    if len(labels) == 1:
        kind = labels.pop()
        project.settings.sample_type = kind
        project.settings.sample_type_source = f'run folder label "({kind.lower()})"'
    elif len(labels) > 1:
        project.method_notes.append('Run folder labels disagree about liquid/solid; sample type requires confirmation.')
    return project


####################################################################################################
# plasmati_preparation.py
####################################################################################################
# Sample-preparation information: status, atomic edits, bulk tables.
#
# Preparation values (sample type, additional dilution, solid mass, final
# volume, optional moisture) are information Plasmatti cannot infer. The default
# ``sample_type='Liquid'`` and ``dilution=1.0`` are NOT evidence; this module
# tracks where each value came from and whether anyone confirmed it.
#
# All multi-row edits are validated completely as a draft and committed only
# when every row is valid. Opening or displaying anything never changes the
# project. Name-derived dilution suggestions (``Sample 1:10``) are computed on
# demand and only become values when explicitly accepted.

import copy
import csv
import io
import json
import math
import re
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Dict, List, Optional, Sequence

pass
pass

SUGGESTION_RE = re.compile(r'(?<!\d)1\s*:\s*(\d+(?:\.\d+)?)\s*$')


def dilution_suggestion(name: str) -> Optional[float]:
    """A dilution suggested by a name suffix such as '1:10'. Never applied by itself."""
    m = SUGGESTION_RE.search(str(name))
    if not m:
        return None
    value = float(m.group(1))
    return value if value > 1 and math.isfinite(value) else None


@dataclass
class PreparationRow:
    sequence: int
    report_name: str
    report: bool
    dilution: float
    mass_g: Optional[float] = None
    volume_ml: Optional[float] = None
    moisture_pct: Optional[float] = None


def sample_assignments(project) -> List[core.Assignment]:
    return sorted((a for a in project.assignments.values() if a.role == 'Sample'), key=lambda a: a.sequence)


def rows_from_project(project) -> List[PreparationRow]:
    return [PreparationRow(a.sequence, a.report_name or a.sample_id, a.report, a.dilution,
                           a.mass_g, a.volume_ml, a.moisture_pct) for a in sample_assignments(project)]


def pending_suggestions(project) -> Dict[int, float]:
    """Name suggestions for samples whose preparation has not been confirmed."""
    out = {}
    for a in sample_assignments(project):
        s = dilution_suggestion(a.sample_id)
        if s is not None and not a.preparation_source and a.dilution != s:
            out[a.sequence] = s
    return out


def preparation_status(project) -> dict:
    """What preparation information is still missing or unconfirmed.

    ready=True means: sample type known, every reported sample's preparation
    values confirmed, solids have mass and volume, dry basis has moisture.
    """
    st = project.settings
    items = []
    reported = [a for a in sample_assignments(project) if a.report]
    if not st.sample_type_source:
        items.append({'code': 'sample_type', 'message': 'Sample type (liquid or solid) has not been confirmed.',
                      'sequences': []})
    unconfirmed = [a.sequence for a in reported if not a.preparation_source]
    if unconfirmed:
        items.append({'code': 'unconfirmed', 'sequences': unconfirmed,
                      'message': f'{len(unconfirmed)} sample(s) have default preparation values (dilution 1, no mass/volume) '
                                 'that nobody has confirmed.'})
    sugg = pending_suggestions(project)
    sugg = {k: v for k, v in sugg.items() if project.assignments[k].report}
    if sugg:
        items.append({'code': 'suggestion', 'sequences': sorted(sugg),
                      'message': f'{len(sugg)} sample name(s) suggest a dilution (e.g. "1:10") that has not been accepted or rejected.'})
    if st.sample_type == 'Solid':
        missing = [a.sequence for a in reported if a.mass_g is None or a.volume_ml is None]
        if missing:
            items.append({'code': 'solid_missing', 'sequences': missing,
                          'message': f'{len(missing)} solid sample(s) lack the weighed mass and/or final solution volume.'})
        if st.reporting_basis == 'dry':
            moist = [a.sequence for a in reported if a.moisture_pct is None]
            if moist:
                items.append({'code': 'moisture_missing', 'sequences': moist,
                              'message': f'Dry-basis reporting is selected; {len(moist)} sample(s) lack measured moisture.'})
    return {'ready': not items, 'items': items, 'sample_type': st.sample_type,
            'sample_type_source': st.sample_type_source, 'reporting_basis': st.reporting_basis}


def validate_rows(project, sample_type: str, rows: Sequence[PreparationRow], reporting_basis: str) -> List[str]:
    problems = []
    if sample_type not in ('Liquid', 'Solid'):
        problems.append('Sample type must be Liquid or Solid.')
    if reporting_basis not in ('as_weighed', 'dry'):
        problems.append('Reporting basis must be as-weighed or dry.')
    seen = set()
    for row in rows:
        a = project.assignments.get(row.sequence)
        label = f'Sequence {row.sequence}'
        if a is None or a.role != 'Sample':
            problems.append(f'{label}: not a research-sample measurement in this run.')
            continue
        label = f'{a.sample_id} (sequence {row.sequence})'
        if row.sequence in seen:
            problems.append(f'{label}: listed more than once.')
        seen.add(row.sequence)
        if not str(row.report_name or '').strip():
            problems.append(f'{label}: report name is empty.')
        for name, value, positive in (('dilution', row.dilution, True), ('mass (g)', row.mass_g, True),
                                      ('final volume (mL)', row.volume_ml, True), ('moisture (%)', row.moisture_pct, False)):
            if value is None:
                continue
            if not isinstance(value, (int, float)) or isinstance(value, bool) or not math.isfinite(value):
                problems.append(f'{label}: {name} must be a finite number.')
            elif positive and value <= 0:
                problems.append(f'{label}: {name} must be positive.')
        if row.dilution is None:
            problems.append(f'{label}: dilution factor is required (1 = no additional dilution).')
        if row.moisture_pct is not None and isinstance(row.moisture_pct, (int, float)) and not 0 <= row.moisture_pct < 100:
            problems.append(f'{label}: moisture must be at least 0 % and below 100 %.')
        if row.report and sample_type == 'Solid':
            if row.mass_g is None:
                problems.append(f'{label}: solid sample needs the weighed mass (g).')
            if row.volume_ml is None:
                problems.append(f'{label}: solid sample needs the final solution volume (mL).')
            if reporting_basis == 'dry' and row.moisture_pct is None:
                problems.append(f'{label}: dry-basis reporting needs the measured moisture (%).')
    included = {a.sequence: a.report for a in sample_assignments(project)}
    included.update({r.sequence: bool(r.report) for r in rows if r.sequence in included})
    if not any(included.values()):
        problems.append('At least one sample must be included in the report.')
    return problems


def apply_preparation(project, sample_type: str, rows: Sequence[PreparationRow], *, source: str,
                      reporting_basis: Optional[str] = None, sample_type_source: Optional[str] = None,
                      reason: str = '') -> dict:
    """Validate the complete draft, then commit atomically. Raises ValueError listing ALL problems."""
    basis = reporting_basis or project.settings.reporting_basis
    rows = [copy.deepcopy(r) for r in rows]
    problems = validate_rows(project, sample_type, rows, basis)
    if problems:
        raise ValueError('Preparation not saved; please correct:\n' + '\n'.join(problems[:40])
                         + (f'\n... {len(problems) - 40} more.' if len(problems) > 40 else ''))
    # ---- commit ----
    st = project.settings
    changed_type = st.sample_type != sample_type
    st.sample_type = sample_type
    st.reporting_basis = basis
    if sample_type_source is not None:
        st.sample_type_source = sample_type_source
    elif changed_type or not st.sample_type_source:
        st.sample_type_source = source
    for row in rows:
        a = project.assignments[row.sequence]
        a.report_name = row.report_name.strip()
        a.report = bool(row.report)
        a.dilution = float(row.dilution)
        a.mass_g = row.mass_g
        a.volume_ml = row.volume_ml
        a.moisture_pct = row.moisture_pct
        a.preparation_source = source
    event = {'action': 'preparation_confirmed', 'time': core.utc_now(), 'source': source, 'reason': reason,
             'sample_type': sample_type, 'reporting_basis': basis, 'rows': [asdict(r) for r in rows]}
    project.decision_log.append(event)
    return {'rows': len(rows), 'sample_type': sample_type}


def confirm_current(project, *, source='Analyst confirmed the shown preparation values', sample_type=None,
                    accept_suggestions=False, reason=''):
    """One-step confirmation of the current values for all samples (optionally accepting name suggestions)."""
    rows = rows_from_project(project)
    if accept_suggestions:
        sugg = pending_suggestions(project)
        for r in rows:
            if r.sequence in sugg:
                r.dilution = sugg[r.sequence]
    return apply_preparation(project, sample_type or project.settings.sample_type, rows, source=source, reason=reason)


def with_common_value(rows: Sequence[PreparationRow], sequences, field_name: str, value) -> List[PreparationRow]:
    """Preview: a NEW row list with ``field_name`` set for the selected sequences."""
    if field_name not in ('dilution', 'mass_g', 'volume_ml', 'moisture_pct'):
        raise ValueError('Only dilution, mass, volume or moisture can be applied to a selection.')
    selected = set(sequences)
    out = []
    for r in rows:
        r = copy.deepcopy(r)
        if r.sequence in selected:
            setattr(r, field_name, value)
        out.append(r)
    return out


# --------------------------------------------------------------------------
# Bulk preparation tables (paste from Excel, CSV/TSV, or XLSX)
# --------------------------------------------------------------------------

_HEADERS = {
    'sequence': 'sequence', 'seq': 'sequence', 'seqno': 'sequence', 'sequenceno': 'sequence',
    'sample': 'sample', 'sampleid': 'sample', 'samplename': 'sample', 'name': 'sample',
    'reportname': 'report_name', 'reportas': 'report_name',
    'include': 'report', 'report': 'report', 'included': 'report',
    'dilution': 'dilution', 'dilutionfactor': 'dilution', 'additionaldilution': 'dilution', 'dilutionx': 'dilution',
    'massg': ('mass_g', 1.0), 'weightg': ('mass_g', 1.0), 'massmg': ('mass_g', 0.001), 'weightmg': ('mass_g', 0.001),
    'volumeml': ('volume_ml', 1.0), 'finalvolumeml': ('volume_ml', 1.0), 'volumel': ('volume_ml', 1000.0),
    'finalvolumel': ('volume_ml', 1000.0),
    'moisture': 'moisture_pct', 'moisturepct': 'moisture_pct', 'moisture%': 'moisture_pct',
}
_UNITLESS = {'mass', 'weight', 'volume', 'finalvolume'}


def _header_key(text):
    t = str(text).strip().casefold().replace('×', 'x')
    t = re.sub(r'[\s_()\[\]./\-]+', '', t)
    return t.replace('percent', '%').replace('pct', 'pct')


def _split_rows(text):
    lines = [ln for ln in str(text).replace('\r\n', '\n').replace('\r', '\n').split('\n') if ln.strip()]
    if not lines:
        return []
    delim = '\t' if '\t' in lines[0] else (';' if ';' in lines[0] else ',')
    return [[c.strip() for c in row] for row in csv.reader(io.StringIO('\n'.join(lines)), delimiter=delim)]


def parse_preparation_table(source, project, *, decimal='dot'):
    """Parse a preparation table and match it to this run's samples.

    ``source``: pasted text (TSV from Excel, CSV or semicolon-separated) or a
    path to .csv/.tsv/.txt/.xlsx/.xls. Columns are identified by explicit
    headers including units (Mass (g), Mass (mg), Volume (mL), Volume (L),
    Dilution, Moisture (%), Report name, Include). Rows are matched by
    ``Sequence`` or by an EXACT (case/space-insensitive) sample name that is
    unique in the run -- never by fuzzy matching. Blank cells leave values
    unchanged. ``decimal`` is 'dot' or 'comma' and is applied strictly.

    Returns (rows, problems): rows are complete PreparationRow drafts for the
    whole run with the table applied; nothing in ``project`` changes.
    """
    if decimal not in ('dot', 'comma'):
        raise ValueError('Choose the decimal separator: dot or comma.')
    if isinstance(source, (str, Path)) and Path(str(source)).suffix.lower() in ('.xlsx', '.xls') and Path(str(source)).is_file():
        pass
        sh = read_workbook(str(source))[0]
        table = [[v if isinstance(v, (int, float)) and not isinstance(v, bool) else str(v if v is not None else '').strip()
                  for v in sh.row(r)] for r in range(sh.nrows)]
        table = [row for row in table if any(str(c).strip() for c in row)]
    else:
        text = Path(str(source)).read_text(encoding='utf-8-sig') if (isinstance(source, Path) or (
            isinstance(source, str) and '\n' not in source and Path(source).suffix.lower() in ('.csv', '.tsv', '.txt')
            and Path(source).is_file())) else str(source)
        table = _split_rows(text)
    problems = []
    if len(table) < 2:
        return rows_from_project(project), ['The table needs a header row and at least one data row.']
    header = table[0]
    columns = {}
    for idx, h in enumerate(header):
        if not str(h).strip():
            continue
        key = _header_key(h)
        target = _HEADERS.get(key)
        if target is None and key in _UNITLESS:
            problems.append(f'Column "{h}": state the unit, e.g. "Mass (g)" or "Volume (mL)".')
            continue
        if target is None:
            problems.append(f'Column "{h}" is not recognised (use Sequence or Sample, Report name, Include, Dilution, '
                            'Mass (g), Volume (mL), Moisture (%)).')
            continue
        name, factor = (target, 1.0) if isinstance(target, str) else target
        if name in [c[0] for c in columns.values()]:
            problems.append(f'Column for {name.replace("_", " ")} appears more than once.')
            continue
        columns[idx] = (name, factor)
    names = [c[0] for c in columns.values()]
    if 'sequence' not in names and 'sample' not in names:
        problems.append('The table needs a Sequence column or a Sample column to identify rows.')
    if problems:
        return rows_from_project(project), problems
    samples = sample_assignments(project)
    by_name = {}
    for a in samples:
        for nm in {normalized_name(a.sample_id), normalized_name(a.report_name or a.sample_id)}:
            by_name.setdefault(nm, set()).add(a.sequence)
    drafts = {r.sequence: r for r in rows_from_project(project)}
    touched = set()

    def num(value, label):
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return float(value)   # a numeric workbook cell: no text interpretation needed
        return number(value, decimal=decimal)
    for line_no, row in enumerate(table[1:], start=2):
        cells = {columns[i][0]: (row[i] if i < len(row) else '', columns[i][1]) for i in columns}
        cells = {k: (v if isinstance(v, (int, float)) and not isinstance(v, bool) else str(v).strip(), f)
                 for k, (v, f) in cells.items()}
        seq = None
        if 'sequence' in cells and cells['sequence'][0]:
            try:
                value = num(cells['sequence'][0], 'sequence')
                if value != int(value):
                    raise ValueError
                seq = int(value)
            except (ValueError, TypeError):
                problems.append(f'Row {line_no}: sequence "{cells["sequence"][0]}" is not a whole number.')
                continue
            if seq not in drafts:
                problems.append(f'Row {line_no}: sequence {seq} is not a research sample in this run.')
                continue
            if 'sample' in cells and cells['sample'][0]:
                a = project.assignments[seq]
                if normalized_name(cells['sample'][0]) not in {normalized_name(a.sample_id), normalized_name(a.report_name or '')}:
                    problems.append(f'Row {line_no}: sequence {seq} is "{a.sample_id}", not "{cells["sample"][0]}".')
                    continue
        elif 'sample' in cells and cells['sample'][0]:
            hits = by_name.get(normalized_name(cells['sample'][0]), set())
            if not hits:
                problems.append(f'Row {line_no}: no sample named "{cells["sample"][0]}" in this run (names must match exactly).')
                continue
            if len(hits) > 1:
                problems.append(f'Row {line_no}: {len(hits)} measurements are named "{cells["sample"][0]}" '
                                f'(sequences {", ".join(map(str, sorted(hits)))}); add a Sequence column.')
                continue
            seq = next(iter(hits))
        else:
            if any(v for v, _ in cells.values()):
                problems.append(f'Row {line_no}: no sequence or sample name.')
            continue
        if seq in touched:
            problems.append(f'Row {line_no}: sequence {seq} appears more than once in the table.')
            continue
        touched.add(seq)
        draft = drafts[seq]
        for name, (text, factor) in cells.items():
            if name in ('sequence', 'sample') or not str(text).strip():
                continue
            if name == 'report_name':
                draft.report_name = str(text).strip()
            elif name == 'report':
                t = str(text).strip().casefold()
                if t in ('yes', 'y', 'true', '1', 'x', 'include', 'kyllä'):
                    draft.report = True
                elif t in ('no', 'n', 'false', '0', 'exclude', 'ei'):
                    draft.report = False
                else:
                    problems.append(f'Row {line_no}: Include must be yes or no, not "{text}".')
            else:
                try:
                    setattr(draft, name, num(text, name) * factor)
                except (ValueError, TypeError) as exc:
                    problems.append(f'Row {line_no}: {name.replace("_", " ")} "{text}": {exc}')
    if not touched and not problems:
        problems.append('No table row matched a sample of this run.')
    return [drafts[k] for k in sorted(drafts)], problems


# --------------------------------------------------------------------------
# Packaged preparation record for the bundled real demo
# --------------------------------------------------------------------------

def apply_demo_preparation(project, folder):
    """Apply PREPARATION.json shipped with the bundled demo, ONLY if the demo
    files are byte-identical to those the record was written for."""
    folder = Path(folder)
    meta_path = folder / 'PREPARATION.json'
    if not meta_path.is_file():
        return False
    meta = json.loads(meta_path.read_text(encoding='utf-8'))
    if meta.get('schema') != 'plasmati-demo-preparation-1':
        raise ValueError('Unknown demo preparation record.')
    for name, sha in meta.get('applies_to', {}).items():
        if core.checksum(str(folder / name)) != sha:
            raise ValueError(f'Demo preparation record does not belong to this {name}; not applied.')
    current = {r.sequence: r for r in rows_from_project(project)}
    rows = []
    for item in meta['samples']:
        row = current.get(int(item['sequence']))
        if row is None:
            raise ValueError('Demo preparation record refers to an unknown sample.')
        row.dilution = float(item['dilution'])
        rows.append(row)
    apply_preparation(project, meta['sample_type'], rows,
                      source='Packaged demo preparation record (PREPARATION.json)',
                      reporting_basis=meta.get('reporting_basis', 'as_weighed'),
                      sample_type_source='Packaged demo record: ' + meta.get('sample_type_evidence', ''),
                      reason='Bundled real-demo metadata, bound to the demo files by SHA-256.')
    return True


####################################################################################################
# plasmati_dissolution.py
####################################################################################################
# Read a dissolution (digestion) file: the weighed mass, and when given the final volume, dilution and
# moisture, of each solid sample.
#
# The file is a spreadsheet written by hand, so the table can start anywhere: Plasmatti looks for a row with a
# sample column and a mass column (for example "Sample" and "Weight (g)"). Other columns (bomb, reagents) are
# ignored. The final volume can be a column, or written once above the table, for example "to 50 ml". Rows
# without a mass ("xxx", empty, for example a blank) are skipped. Nothing is guessed: a column without a unit,
# a name that appears twice or two different volumes are reported, not used.
#
# Samples are matched by their exact name (ignoring capitals and extra spaces), also when the instrument name
# has a dilution added, for example "Algae 1:10" for "Algae" in the file.

import csv
import io
import math
import re
from pathlib import Path
from typing import Dict, List, Optional

pass

DISSOLUTION_KEY = 'dissolution_file'
HEADER_SEARCH_ROWS = 40

_DISS_SAMPLE_KEYS = {'sample', 'samples', 'samplename', 'sampleid', 'sampleidentification', 'sampledescription', 'name'}
_DISS_NO_VALUE = {'', 'xxx', 'xx', 'x', '-', '--', '—', 'n/a', 'na', 'nan', 'none'}
_DISS_VOLUME_NOTE_RE = re.compile(
    r'^\s*(?:(?:made\s+)?(?:up\s+)?to|ad|final\s+volume\s*:?|volume\s*:?|diluted\s+to)\s*'
    r'(\d+(?:[.,]\d+)?)\s*(ml|l)\s*\.?\s*$', re.IGNORECASE)


def _diss_key(text) -> str:
    t = str(text).strip().casefold().replace('×', 'x').replace('µ', 'u')
    return re.sub(r'[\s_()\[\]./\-:]+', '', t)


def _diss_column_kind(header):
    """(kind, factor to the standard unit) for a header cell, ('unitless', kind) or None."""
    k = _diss_key(header)
    if not k:
        return None
    if k in _DISS_SAMPLE_KEYS:
        return ('sample', 1.0)
    for word in ('weight', 'mass', 'samplemass', 'sampleweight', 'weighedmass', 'weighed', 'weighing'):
        if k.startswith(word) or k.endswith(word) or word in k:
            unit = k.replace('samplemass', '').replace('sampleweight', '').replace('weighedmass', '')
            unit = unit.replace('weight', '').replace('mass', '').replace('weighed', '').replace('weighing', '')
            unit = unit.replace('of', '').replace('sample', '')
            if unit == 'g':
                return ('mass_g', 1.0)
            if unit == 'mg':
                return ('mass_g', 0.001)
            if unit == 'kg':
                return ('mass_g', 1000.0)
            return ('unitless', 'mass') if unit == '' else None
    if 'volume' in k:
        unit = k.replace('finalvolume', '').replace('volume', '').replace('final', '').replace('total', '')
        if unit == 'ml':
            return ('volume_ml', 1.0)
        if unit == 'l':
            return ('volume_ml', 1000.0)
        return ('unitless', 'volume') if unit == '' else None
    if k in ('dilution', 'dilutionfactor', 'df', 'dil', 'additionaldilution', 'dilutionx', 'dilutionfold'):
        return ('dilution', 1.0)
    if k in ('moisture', 'moisture%', 'moisturepercent', 'moisturepct', 'watercontent%', 'watercontent'):
        return ('moisture_pct', 1.0)
    return None


def _diss_number(value) -> Optional[float]:
    """A number from a cell; None for an empty cell or a placeholder such as 'xxx'. Raises for other text."""
    if isinstance(value, bool):
        raise ValueError(str(value))
    if isinstance(value, (int, float)):
        v = float(value)
        if not math.isfinite(v):
            raise ValueError(str(value))
        return v
    text = str(value if value is not None else '').strip()
    if text.casefold() in _DISS_NO_VALUE:
        return None
    t = text.replace(' ', '')
    if t.count(',') == 1 and '.' not in t:
        t = t.replace(',', '.')
    v = float(t)
    if not math.isfinite(v):
        raise ValueError(text)
    return v


def _diss_read_grids(path):
    """[(sheet name, rows)] with the cells as numbers or stripped text."""
    p = Path(path)
    suffix = p.suffix.lower()
    if suffix in ('.xls', '.xlsx', '.xlsm'):
        pass
        out = []
        for sh in read_workbook(str(p)):
            rows = []
            for r in range(sh.nrows):
                rows.append([v if isinstance(v, (int, float)) and not isinstance(v, bool)
                             else str(v if v is not None else '').strip() for v in sh.row(r)])
            out.append((getattr(sh, 'name', ''), rows))
        return out
    if suffix in ('.csv', '.tsv', '.txt'):
        for encoding in ('utf-8-sig', 'cp1252'):
            try:
                text = p.read_text(encoding=encoding)
                break
            except UnicodeDecodeError:
                continue
        lines = text.replace('\r\n', '\n').replace('\r', '\n').split('\n')
        sample = '\n'.join(lines[:50])
        delim = '\t' if '\t' in sample else (';' if sample.count(';') > sample.count(',') else ',')
        rows = [[c.strip() for c in row] for row in csv.reader(io.StringIO('\n'.join(lines)), delimiter=delim)]
        return [('', rows)]
    raise ValueError('Use an Excel file (XLS or XLSX) or a CSV file.')


def _diss_find_header(rows):
    """(row index, {column: (kind, factor)}, problems) of the first row with a sample and a mass column."""
    for i, row in enumerate(rows[:HEADER_SEARCH_ROWS]):
        kinds = {c: _diss_column_kind(v) for c, v in enumerate(row) if isinstance(v, str) and v.strip()}
        kinds = {c: k for c, k in kinds.items() if k}
        has_sample = any(k[0] == 'sample' for k in kinds.values())
        has_mass = any(k[0] == 'mass_g' or k == ('unitless', 'mass') for k in kinds.values())
        if has_sample and has_mass:
            problems = []
            columns = {}
            for c, k in kinds.items():
                if k[0] == 'unitless':
                    problems.append(f'The {k[1]} column "{row[c]}" has no unit, so its values are not used; write the '
                                    f'unit in the header, for example "{k[1].capitalize()} ({"g" if k[1] == "mass" else "mL"})".')
                    continue
                if k[0] in [x[0] for x in columns.values()]:
                    problems.append(f'More than one {k[0].split("_")[0]} column; only the first is used.')
                    continue
                columns[c] = k
            return i, columns, problems
    return None, {}, []


def _diss_volume_notes(rows, header_row):
    """Volumes written once outside the table, for example 'to 50 ml': [(value in mL, text, row number)]."""
    notes = []
    for i, row in enumerate(rows):
        if header_row is not None and i > header_row:
            break
        for v in row:
            if isinstance(v, str):
                m = _DISS_VOLUME_NOTE_RE.match(v)
                if m:
                    value = float(m.group(1).replace(',', '.')) * (1000.0 if m.group(2).lower() == 'l' else 1.0)
                    notes.append((value, v.strip(), i + 1))
    return notes


def read_dissolution_file(path) -> dict:
    """Everything that could be read from the file, and why anything could not. Never raises for the content."""
    info = {'path': str(path), 'file_name': Path(str(path)).name, 'sheet': '', 'header_row': None,
            'entries': [], 'volume_ml': None, 'volume_text': '', 'skipped': [], 'problems': []}
    try:
        grids = _diss_read_grids(path)
    except Exception as exc:
        info['problems'].append(f'The file could not be opened ({exc}).')
        return info
    for sheet, rows in grids:
        header_row, columns, problems = _diss_find_header(rows)
        if header_row is None:
            continue
        info['sheet'] = sheet
        info['header_row'] = header_row + 1
        info['problems'] += problems
        sample_col = next(c for c, k in columns.items() if k[0] == 'sample')
        notes = _diss_volume_notes(rows, header_row)
        values = sorted({round(n[0], 9) for n in notes})
        if len(values) == 1:
            info['volume_ml'] = values[0]
            info['volume_text'] = notes[0][1]
        elif len(values) > 1:
            info['problems'].append('Several final volumes are written above the table (' +
                                    ', '.join(f'"{n[1]}"' for n in notes) + '), so none of them is used.')
        seen = {}
        for r in range(header_row + 1, len(rows)):
            row = rows[r]
            name = str(row[sample_col]).strip() if sample_col < len(row) else ''
            if isinstance(row[sample_col] if sample_col < len(row) else '', float) and float(row[sample_col]).is_integer():
                name = str(int(row[sample_col]))
            if not name:
                continue
            entry = {'row': r + 1, 'name': name}
            bad = []
            for c, (kind, factor) in columns.items():
                if kind == 'sample':
                    continue
                cell = row[c] if c < len(row) else ''
                try:
                    v = _diss_number(cell)
                except ValueError:
                    bad.append(f'{kind.split("_")[0]} "{cell}"')
                    continue
                if v is not None:
                    entry[kind] = v * factor
            if bad:
                entry['note'] = 'not a number: ' + ', '.join(bad)
            if entry.get('mass_g') is None:
                info['skipped'].append({'row': r + 1, 'name': name, 'reason': entry.get('note', 'no mass')})
                continue
            if entry['mass_g'] <= 0:
                info['skipped'].append({'row': r + 1, 'name': name, 'reason': 'the mass is not positive'})
                continue
            seen.setdefault(normalized_name(name), []).append(entry)
            info['entries'].append(entry)
        for key, entries in seen.items():
            if len(entries) > 1:
                info['problems'].append(f'"{entries[0]["name"]}" appears {len(entries)} times in the file (rows '
                                        + ', '.join(str(e['row']) for e in entries) + '), so its values are not used.')
                for e in entries:
                    e['duplicate'] = True
        if not info['entries']:
            info['problems'].append('The table was found, but no sample in it has a mass.')
        return info
    info['problems'].append('No table with a sample column and a mass column (for example "Sample" and "Weight (g)") '
                            'was found in the file.')
    return info


def _diss_base_name(name: str) -> str:
    """The sample name without a dilution added at the end, for example 'Algae 1:10' -> 'Algae'."""
    return SUGGESTION_RE.sub('', str(name)).strip()


def match_dissolution(info: dict, project) -> dict:
    """{'by_sequence': {sequence: entry}, 'unmatched_samples': [names], 'unused_entries': [entries]}."""
    entries = [e for e in (info or {}).get('entries', []) if not e.get('duplicate')]
    by_name = {normalized_name(e['name']): e for e in entries}
    by_sequence: Dict[int, dict] = {}
    unmatched: List[str] = []
    used = set()
    for a in sample_assignments(project):
        e = by_name.get(normalized_name(a.sample_id)) or by_name.get(normalized_name(_diss_base_name(a.sample_id)))
        if e is None:
            unmatched.append(a.sample_id)
            continue
        by_sequence[a.sequence] = e
        used.add(id(e))
    unused = [e for e in entries if id(e) not in used]
    return {'by_sequence': by_sequence, 'unmatched_samples': unmatched, 'unused_entries': unused}


def describe(info: dict, match: dict) -> str:
    """One paragraph for step 3: what was filled in from the file, and what was not."""
    name = info.get('file_name', 'the dissolution file')
    if not info.get('entries') and info.get('problems'):
        return f'No values could be read from the dissolution file "{name}": ' + ' '.join(info['problems']) + \
               ' Enter the values below.'
    parts = []
    n = len(match['by_sequence'])
    if n:
        what = 'masses' if n != 1 else 'mass'
        parts.append(f'From the dissolution file "{name}": the {what} of {n} sample{"s" if n != 1 else ""}')
        if info.get('volume_ml') is not None:
            parts[-1] += f' and the final volume {info["volume_ml"]:g} mL ("{info["volume_text"]}")'
        parts[-1] += '.'
    else:
        parts.append(f'No sample of this session was found in the dissolution file "{name}" (the names must be the same).')
    if match['unmatched_samples']:
        parts.append('Not in the file: ' + ', '.join(match['unmatched_samples']) + '.')
    if match['unused_entries']:
        parts.append('In the file but not measured in this session: ' +
                     ', '.join(e['name'] for e in match['unused_entries']) + '.')
    if info.get('problems'):
        parts.append(' '.join(info['problems']))
    return ' '.join(parts)


def find_dissolution_file(paths) -> Optional[str]:
    """The one spreadsheet among `paths` that reads as a dissolution file, or None (none or several)."""
    found = []
    for p in paths:
        if Path(p).suffix.lower() not in ('.xls', '.xlsx', '.csv'):
            continue
        stem = Path(p).stem.casefold()
        if 'autosampler' in stem or 'replicate' in stem or 'avg' in stem:
            continue
        try:
            info = read_dissolution_file(p)
        except Exception:
            continue
        if info['entries']:
            found.append(str(p))
    return found[0] if len(found) == 1 else None


####################################################################################################
# plasmati_automation.py
####################################################################################################
# Automatic identification with exception-only review.
#
# This module is the ONE identification service. make_project(), the GUI, the
# CLI and the compatibility wrapper core.auto_assign() all use identify().
#
# Identification is deterministic and separate from numerical QC. Nothing here
# changes Reading records, infers concentrations, or substitutes missing blanks.
# Only one bracketed sample block is supported. Corrections still use sequence,
# not autosampler position. Decisions are bound to the imported measurements.

import copy
import hashlib
import json
import re
import unicodedata
from collections import Counter, defaultdict
from dataclasses import asdict
from pathlib import Path

pass
pass

ROLE_FIELDS = ('sample_id', 'role', 'standard_level', 'standard_element',
               'standard_multipliers', 'scope_source')
ELEMENTS = set('H He Li Be B C N O F Ne Na Mg Al Si P S Cl Ar K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se Br Kr Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe Cs Ba La Ce Pr Nd Pm Sm Eu Gd Tb Dy Ho Er Tm Yb Lu Hf Ta W Re Os Ir Pt Au Hg Tl Pb Bi Po At Rn Fr Ra Ac Th Pa U Np Pu Am Cm Bk Cf Es Fm Md No Lr Rf Db Sg Bh Hs Mt Ds Rg Cn Nh Fl Mc Lv Ts Og'.split())
SIGNATURE_SCHEMA = 2
_LIBRARY = None


def library():
    global _LIBRARY
    if _LIBRARY is None:
        _LIBRARY = load_library()
    return _LIBRARY


def normalized(text):
    text = unicodedata.normalize('NFKC', str(text))
    return re.sub(r'\s+', ' ', text).strip().casefold()


def digest(value):
    text = json.dumps(value, sort_keys=True, ensure_ascii=False, default=str)
    return hashlib.sha256(text.encode('utf-8')).hexdigest()


utc_now = core.utc_now


def grouped_readings(project):
    groups = defaultdict(list)
    for reading in project.readings:
        groups[reading.sequence].append(reading)
    return dict(groups)


def _signature_v1(project):
    """Earlier development algorithm, kept ONLY to recognise decisions saved by development builds."""
    return digest({'records': [asdict(r) for r in sorted(
        project.readings, key=lambda r: (r.sequence, r.channel))],
        'sources': project.source_manifest})


def identity_signature(project):
    """Content fingerprint of the imported records and source hashes.

    Includes every value as well as identities: a same-named NEW run must never
    inherit confirmations of an old run. Built from plain tuples rather than
    deep-copied dataclasses (measured ~4x faster than the earlier algorithm on a 21,888-record
    run). This is an identifier, not anonymization.
    """
    h = hashlib.sha256()
    for r in sorted(project.readings, key=lambda r: (r.sequence, r.channel)):
        h.update(json.dumps([r.sequence, r.position, r.sample_id, r.channel, r.replicates, r.instrument_mean,
                             r.instrument_sd, r.instrument_rsd, r.instrument_error, r.source, r.acquisition_time,
                             r.replicate_times, r.exported_replicate_count, r.calibration_mean, r.sequence_inferred,
                             r.mapped_sample_id, r.summary_source, r.import_notes],
                            ensure_ascii=False, default=str).encode('utf-8'))
        h.update(b'\n')
    h.update(json.dumps(project.source_manifest, sort_keys=True, default=str).encode('utf-8'))
    return 'v2:' + h.hexdigest()


def state_for(project):
    signature = identity_signature(project)
    state = project.automatic_run
    if isinstance(state, dict) and state.get('signature') and state.get('signature') != signature:
        # Decisions saved by development builds used the older fingerprint; accept them once
        # if the imported records are unchanged, then store the new one.
        if not str(state['signature']).startswith('v2:') and state['signature'] == _signature_v1(project):
            state['signature'] = signature
            state['schema'] = SIGNATURE_SCHEMA
            state.setdefault('events', []).append({'action': 'signature_migrated_from_development_build', 'time': utc_now()})
    if not isinstance(state, dict) or state.get('signature') != signature:
        legacy = isinstance(state, dict) and bool(state.get('legacy_pending'))
        state = {'schema': SIGNATURE_SCHEMA, 'signature': signature, 'overrides': {},
                 'source_acknowledgement': '', 'method_acknowledgement': '',
                 'legacy_pending': legacy, 'events': []}
        project.automatic_run = state
    return state


def valid_scope(scope):
    if scope == '*':
        return True
    if not re.fullmatch(r'[A-Z][a-z]?(?:[,;+\s]+[A-Z][a-z]?)*', scope):
        return False
    return all(x in ELEMENTS for x in re.split(r'[,;+\s]+', scope))


def validate_standard(assignment):
    core.finite_positive(assignment.standard_level, 'Prepared standard concentration')
    if not valid_scope(assignment.standard_element):
        raise ValueError('Enter the verified standard elements (for example Ca,Fe).')
    for element, factor in assignment.standard_multipliers.items():
        if element not in ELEMENTS:
            raise ValueError('Unknown element in standard multipliers: ' + element)
        if not core._scope_contains(assignment, element):
            raise ValueError('Multiplier is outside the standard composition: ' + element)
        core.finite_positive(factor, element + ' nominal concentration multiplier')


# Names of blanks, written in many ways: "Blank samples", "sampleblank", "sample-blank", "Blank (std)", "stdblank",
# and common misspellings. Only a name made of these words alone (with at most one number at the end) is a blank,
# so "Blank spike", "Blank QC" or "Black liquor" are never taken as blanks ("black" is deliberately not a spelling).
_BLANK_WORDS = {'blank', 'blnak', 'balnk', 'blakn', 'blnk', 'blamk', 'blanl'}
_SAMPLE_WORDS = {'sample', 'smaple', 'sampel', 'sapmle', 'samlpe', 'saple', 'smple'}
_STD_WORDS = {'std', 'standard', 'stnadard', 'standrad', 'stadard'}
_FILLER_WORDS = {'for', 'the', 'of', 'before', 'after'}


def _blank_vocab():
    vocab = {}
    for kind, words in (('blank', _BLANK_WORDS), ('sample', _SAMPLE_WORDS), ('std', _STD_WORDS)):
        for w_ in words:
            vocab[w_] = kind
            vocab[w_ + 's'] = kind
    for w_ in _FILLER_WORDS:
        vocab[w_] = 'filler'
    return vocab


_BLANK_VOCAB = _blank_vocab()


def _split_words(token):
    """Split a run of letters into known words ("sampleblank" -> sample, blank); None when it cannot be done."""
    best = {0: []}
    for i in range(1, len(token) + 1):
        for j in range(max(0, i - 9), i):
            if j in best and token[j:i] in _BLANK_VOCAB:
                best[i] = best[j] + [_BLANK_VOCAB[token[j:i]]]
                break
    return best.get(len(token))


def _blank_label_kind(label):
    """'Sample blank', 'Standard blank' or None for a name that consists only of blank words."""
    low = unicodedata.normalize('NFKC', str(label)).casefold()
    tokens = re.findall(r'[a-z]+|\d+', low)
    if not tokens or re.search(r'[^a-z0-9\s\-_.,;:/()\[\]#%]', low):
        return None
    numbers = [i for i, t in enumerate(tokens) if t.isdigit()]
    if len(numbers) > 1 or (numbers and numbers[0] != len(tokens) - 1):
        return None
    kinds = []
    for t in tokens:
        if t.isdigit():
            continue
        parts = _split_words(t)
        if parts is None:
            return None
        kinds += parts
    if 'blank' not in kinds:
        return None
    if 'std' in kinds:
        return None if 'sample' in kinds else 'Standard blank'
    return 'Sample blank'


def classify_label(label, lib=None):
    """Return kind, prepared level, composition, multipliers, evidence.

    Acid STD suffixes alone are NOT roles: real archive styles use STD 2
    as either a cleanup vial or the second correcting blank. The position
    relative to the standard region resolves the role, not the number.
    """
    lib = lib or library()
    label = unicodedata.normalize('NFKC', str(label)).strip()
    low = normalized(label)
    blank_kind = _blank_label_kind(label)
    if blank_kind == 'Sample blank':
        return 'Sample blank', None, '?', {}, 'Explicit sample-blank label'
    if blank_kind == 'Standard blank':
        return 'Standard blank', None, '?', {}, 'Explicit standard-blank label'
    if re.fullmatch(r'(?:sample[s]?\s+)?blank\s*(?:\d+|before|after)?', low):
        return 'Sample blank', None, '?', {}, 'Explicit sample-blank label'
    if re.fullmatch(r'(?:standard|std\.?)\s+blank\s*(?:\d+|before|after)?', low):
        return 'Standard blank', None, '?', {}, 'Explicit standard-blank label'
    if re.fullmatch(r'(?:rinse|cleaning|cleanup)(?:\s+(?:solution|before|after|\d+))*', low):
        return 'Ignore', None, '?', {}, 'Explicit rinse/cleaning label'
    if re.match(r'^(?:hno\s*3|nitric\s+acid|hcl\b|hydrochloric\s+acid)', low):
        tail = re.sub(r'\s+', ' ', re.sub(r'[(),;]', ' ', low)).strip()
        if re.search(r'\bsamples?\s*(?:and|&|\+|/)?\s*(?:std\.?|standards?)\s*(?:\d+)?$', tail):
            # "HNO3 1.5% samples, std": the acid after the samples, used for the samples and
            # for the standards after them (the laboratory's naming since March 2026).
            return 'Both blanks', None, '?', {}, 'Explicit acid-for-samples-and-standards label'
        if re.search(r'\bsamples?\s*(?:blank\s*)?(?:\d+|before|after)?\s*$', tail):
            return 'Sample blank', None, '?', {}, 'Explicit acid-for-samples label'
        return 'Acid', None, '?', {}, 'Acid label; use verified sequence context'
    match = STANDARD_LEVEL_RE.search(label)
    if match:
        try:
            level = label_number(match.group(1))
        except ValueError:
            return 'Unresolved', None, '?', {}, f'Ambiguous prepared level "{match.group(1)}" in the label; enter the actual concentration.'
        scope, factors, evidence = standard_scope(label, lib)
        return 'Standard', level, scope, factors, evidence
    if re.search(r'\b(?:standard|std|qc|check|blank|control|crm|spike)\b|cms[-\s]*1|ss[-\s]*0\d{5}|ims[-\s]*104', low):
        return 'Unresolved', None, '?', {}, 'QC-like label needs its actual identity/concentration'
    return 'Sample', None, '?', {}, 'Unknown-sample label; verify mapping and bracketing'


def standard_family_key(label):
    """Label without its prepared level: groups 'MysteryMix 1 ppm' and 'MysteryMix 20 ppm'."""
    m = STANDARD_LEVEL_RE.search(label)
    prefix = label[:m.start()] if m else label
    return normalized(prefix)


def equivalent_identity(first, second, lib=None):
    lib = lib or library()
    if normalized(first) == normalized(second):
        return True
    if re.fullmatch(r'blank\s*\d+', normalized(first)):
        return re.sub(r'\s+', '', normalized(first)) == re.sub(r'\s+', '', normalized(second))

    def acid_key(text):
        value = normalized(text)
        if not re.match(r'^(?:hno\s*3|hcl\b)', value):
            return None
        value = re.sub(r'\s+(?:std\.?|standards?|samples?)\s*\d+\s*$', '', value)
        return re.sub(r'\s+', '', value)
    akey, bkey = acid_key(first), acid_key(second)
    if akey and akey == bkey:
        abase = re.sub(r'\s+', '', normalized(first)) == akey
        bbase = re.sub(r'\s+', '', normalized(second)) == bkey
        if abase or bbase:
            return True
        if re.sub(r'\s+', '', normalized(first)) == re.sub(r'\s+', '', normalized(second)):
            return True
    a, b = classify_label(first, lib), classify_label(second, lib)
    return (a[0] == b[0] == 'Standard' and a[2] != '?'
            and a[1:4] == b[1:4])


def remember_override(project, assignment, reason=''):
    if not (reason or '').strip():
        reason = f'Answered in step 2: measurement {assignment.sequence} is {assignment.role.lower()}.'
    if assignment.role not in core.ROLES:
        raise ValueError('Unknown measurement role.')
    if not assignment.sample_id.strip():
        raise ValueError('Sample identity cannot be empty.')
    if assignment.role == 'Standard':
        validate_standard(assignment)
    state = state_for(project)
    record = {k: copy.deepcopy(getattr(assignment, k)) for k in ROLE_FIELDS}
    record.update(reason=reason.strip(), confirmed_utc=utc_now())
    state['overrides'][str(assignment.sequence)] = record
    state['events'].append({'action': 'identify_measurement',
                            'sequence': assignment.sequence, 'decision': copy.deepcopy(record)})


def remember_group_standard(project, sequences, elements, multipliers, reason='', levels=None):
    """One answer for several measurements of the SAME unresolved standard label.

    Each measurement keeps its own prepared level (from its own label unless
    ``levels`` gives it explicitly) and its own before/after position. The
    whole group is validated before anything is recorded.
    """
    if not (reason or '').strip():
        reason = f'Answered in step 2: standard with {elements} (measurements {", ".join(str(x) for x in sequences)}).'
    drafts = []
    for seq in sequences:
        a = copy.deepcopy(project.assignments[seq])
        a.role = 'Standard'
        a.report = False
        level = (levels or {}).get(seq)
        if level is None:
            m = STANDARD_LEVEL_RE.search(a.sample_id)
            if not m:
                raise ValueError(f'Sequence {seq}: the label gives no prepared level; enter it for this measurement.')
            level = label_number(m.group(1))
        a.standard_level = level
        a.standard_element = elements
        a.standard_multipliers = dict(multipliers)
        a.scope_source = 'Analyst-confirmed composition (grouped answer)'
        validate_standard(a)
        drafts.append(a)
    for a in drafts:
        project.assignments[a.sequence] = a
        remember_override(project, a, reason)


def keep_legacy_assignments(project):
    state = state_for(project)
    for assignment in project.assignments.values():
        remember_override(project, assignment, 'Analyst retained assignments from an older saved project.')
    state['legacy_pending'] = False


def method_token(project):
    # Same formula as the development builds so their saved acknowledgements stay valid.
    return digest({'recognition': project.method_recognition, 'method': project.settings.method,
                   'channels': {ch: asdict(cfg) for ch, cfg in project.channels.items()}})


def acknowledge_method(project, reason='Method discrepancies reviewed.'):
    state = state_for(project)
    state['method_acknowledgement'] = method_token(project)
    event = {'action': 'method_settings_reviewed', 'time': utc_now(),
             'method': project.settings.method, 'reason': reason,
             'unmatched_channels': (project.method_recognition or {}).get('unmatched_channels', [])}
    state['events'].append(event)
    project.decision_log.append(dict(event))


def method_record(project):
    """The library record of the method in use (None for an imported table)."""
    rec = project.method_recognition or {}
    for m in library().get('methods', []):
        if m.get('label') == project.settings.method and (not rec.get('sha256') or m.get('sha256') == rec.get('sha256')):
            return m
    return None


def _undefined(cfg):
    return cfg.preference_order is None and cfg.dl_mg_l is None and cfg.dl_mg_kg is None


def _wavelength_of(channel):
    parts = channel.split()
    try:
        return float(parts[1])
    except (IndexError, ValueError):
        return None


def view_columns(project):
    """Columns of the method's limits file that do not say axial or radial, for a
    wavelength measured in this session. Returns a list of dicts with the column,
    a stable key, the measured channels without a limit, and any recorded answer."""
    m = method_record(project)
    if not m:
        return []
    answers = state_for(project).get('view_answers', {})
    out = []
    for col in m.get('unresolved_columns', []):
        wl = float(col['wavelength'])
        measured = sorted(ch for ch in project.channels if ch.split()[0] == col['element']
                          and _wavelength_of(ch) is not None and abs(_wavelength_of(ch) - wl) < 0.0015)
        if not measured:
            continue
        key = f"{m.get('sha256', '')}|{col['element']} {col['wavelength']}"
        open_channels = [ch for ch in measured if _undefined(project.channels[ch])]
        out.append({'column': col, 'key': key, 'measured': measured, 'open': open_channels,
                    'answer': (answers.get(key) or {}).get('answer')})
    return out


def _apply_view(project, item, answer):
    col = item['column']
    target = f"{col['element']} {col['wavelength']} {answer}"
    if answer in ('axial', 'radial') and target in project.channels and _undefined(project.channels[target]):
        cfg = project.channels[target]
        cfg.preference_order = col['preference_order']
        cfg.dl_mg_l = col['dl_mg_l']
        cfg.dl_mg_kg = col['dl_mg_kg']
        cfg.limit_kind = col['limit_kind']
        cfg.limit_source = col['limit_source'] + f' (column without axial/radial; analyst answered {answer})'
        cfg.limit_source_sha256 = col['limit_source_sha256']
        return target
    return None


def answer_view_column(project, key, answer, reason='Answered in the questions list.'):
    """Record whether a limits-file column without axial/radial is axial or radial
    ('unknown' = do not use it). Only the analyst's answer is used; nothing is guessed."""
    if answer not in ('axial', 'radial', 'unknown'):
        raise ValueError('Answer must be axial, radial or unknown.')
    item = next((i for i in view_columns(project) if i['key'] == key), None)
    if item is None:
        raise ValueError('This question no longer applies.')
    state = state_for(project)
    acknowledged = bool(state.get('method_acknowledgement')) and state['method_acknowledgement'] == method_token(project)
    state.setdefault('view_answers', {})[key] = {'answer': answer, 'time': utc_now(), 'reason': reason}
    used = _apply_view(project, item, answer)
    col = item['column']
    name = f"{col['element']} {col['source_label']}"
    if used:
        note = (f'Method limits file column "{name}" has no axial/radial label. The analyst answered {answer}; '
                f'its {col["limit_kind"]} {col["dl_mg_l"]} mg/L / {col["dl_mg_kg"]} mg/kg ({col["limit_source"]}) is used for {used}.')
    else:
        note = (f'Method limits file column "{name}" has no axial/radial label. The analyst answered '
                f'{"do not know" if answer == "unknown" else answer}; the column is not used.')
    project.method_notes = [n for n in project.method_notes if not n.startswith(f'Method limits file column "{name}"')] + [note]
    if acknowledged:
        # The method itself was already confirmed; adding its own limit does not change that.
        state['method_acknowledgement'] = method_token(project)
    event = {'action': 'method_column_view_answered', 'time': utc_now(), 'method': project.settings.method,
             'column': name, 'answer': answer, 'applied_to': used or '', 'reason': reason}
    state['events'].append(event)
    project.decision_log.append(dict(event))
    return used


def _reapply_view_answers(project):
    """Keep recorded answers in force after the method table is applied again."""
    state = state_for(project)
    acknowledged = bool(state.get('method_acknowledgement')) and state['method_acknowledgement'] == method_token(project)
    changed = False
    for item in view_columns(project):
        if item['answer'] in ('axial', 'radial') and _apply_view(project, item, item['answer']):
            changed = True
    if changed and acknowledged:
        state['method_acknowledgement'] = method_token(project)


def _view_question(project, item):
    col = item['column']
    el, wl = col['element'], col['wavelength']
    label = project.settings.method
    name = f'{el} {col["source_label"]}'
    lines = [f'Is the "{name}" column in the limits file of "{label}" axial or radial?',
             f'The limits file of this method has a column "{name}" that does not say axial or radial. '
             f'Its limit is {col["dl_mg_l"]:g} mg/L ({col["dl_mg_kg"]:g} mg/kg).']
    if item['open']:
        lines.append(f'Your files measured {" and ".join(item["open"])}, and the method has no limit for '
                     f'{"it" if len(item["open"]) == 1 else "them"}.')
    open_txt = ' and '.join(item['open']) or 'the measured wavelength'
    for view in ('axial', 'radial'):
        target = f'{el} {wl} {view}'
        if target in item['open']:
            lines.append(f'If you answer {view.capitalize()}: Plasmatti uses this limit for {target}. '
                         f'{target} then has priority {col["preference_order"]} in the method, like the other '
                         f'{el} wavelengths, and can be chosen for the {el} result.')
        elif target in project.channels:
            lines.append(f'If you answer {view.capitalize()}: the method already has its own limit for {target}, '
                         f'so this column is not used, and {open_txt} stays without a limit.')
        else:
            lines.append(f'If you answer {view.capitalize()}: {target} was not measured, so this column is not used, '
                         f'and {open_txt} stays without a limit.')
    lines.append(f'If you answer "I don\'t know": the column is not used, and {open_txt} stays without a limit. '
                 'Plasmatti does not guess.')
    return '\n'.join(lines)


def source_problems(project):
    """Discrepancies of the optional secondary source, from the structured comparison."""
    problems = []
    comp = project.source_comparison or {}
    for item in comp.get('comparisons', []):
        if item.get('ignored'):
            continue  # an unrelated optional summary: reported in the notes, nothing to decide
        if item.get('failed'):
            kind = 'Summary' if item.get('kind') == 'summary' else 'PDF'
            problems.append(f'{kind} cross-check FAILED for {item.get("secondary", kind)}: {item["failed"]}')
            continue
        for cat, n in item.get('counts', {}).items():
            if n:
                problems.append(f'{item.get("secondary", "PDF")}: {cat.replace("_", " ")} discrepancies: {n}')
                problems.extend('    ' + d for d in item.get('details', {}).get(cat, [])[:3])
    if not comp:
        # Projects saved by early development builds only have text notes.
        problems = [w for w in project.source_warnings if
                    'csv/pdf discrepancy' in w.casefold() or 'pdf cross-check failed' in w.casefold() or
                    (w.casefold().startswith('source note:') and ('.csv' in w.casefold() or '.pdf' in w.casefold()))]
    return problems


def acknowledge_source(project, token, reason='Primary CSV retained; discrepancy reviewed.'):
    state = state_for(project)
    state['source_acknowledgement'] = token
    event = {'action': 'source_discrepancy_acknowledged', 'time': utc_now(), 'token': token, 'reason': reason}
    state['events'].append(event)
    project.decision_log.append(dict(event))


def _is_synthetic_fixture(project):
    return project.demo and any(Path(p).name == 'Plasmatti_SIMULATED_demo.csv' for p in project.source_paths)


def identify(project, lib=None, state=None):
    """Assign roles from labels + sequence context; return unresolved items.

    Recorded analyst decisions (bound to these imported records) take
    precedence. Preparation fields, report names and inclusion choices are not
    touched. Returns {sequence: reason} for measurements needing an answer.
    """
    lib = lib or library()
    state = state if state is not None else state_for(project)
    groups = grouped_readings(project)
    unresolved, acids = {}, set()
    synthetic = _is_synthetic_fixture(project)
    for sequence, assignment in project.assignments.items():
        if sequence not in groups:
            continue
        previous = assignment.role
        override = state['overrides'].get(str(sequence))
        if override:
            for fld in ROLE_FIELDS:
                setattr(assignment, fld, copy.deepcopy(override[fld]))
        else:
            reading = groups[sequence][0]
            assignment.sample_id = reading.sample_id
            kind, level, scope, factors, evidence = classify_label(reading.sample_id, lib)
            if kind == 'Standard' and scope == '?' and synthetic and reading.sample_id.startswith('Multi '):
                # Old automated unit tests use a visibly fictional 'Multi'
                # solution. Only that named fixture gets an explicit wildcard;
                # real data (including the anonymized demo) never invents scope.
                scope, evidence = '*', 'Explicit all-element synthetic test fixture (not for laboratory data)'
            if kind == 'Unresolved':
                unresolved[sequence] = evidence
                assignment.role = 'Ignore'   # never silently report an unidentified QC measurement
            else:
                assignment.role = 'Ignore' if kind == 'Acid' else kind
            assignment.standard_level = level
            assignment.standard_element = scope
            assignment.standard_multipliers = dict(factors)
            assignment.scope_source = evidence
            if kind == 'Acid':
                acids.add(sequence)
            if kind == 'Standard' and scope == '?':
                unresolved[sequence] = evidence
        if assignment.role != 'Sample':
            assignment.report = False
        elif previous != 'Sample':
            assignment.report = True
        if assignment.role == 'Sample' and not assignment.report_name:
            assignment.report_name = assignment.sample_id
    _standards_summary(project, unresolved)
    if any(not k.startswith('Unrecognized standard') and 'documented standard group' not in k
           for k in unresolved.values()):
        return unresolved
    samples = sorted(a.sequence for a in project.assignments.values() if a.role == 'Sample')
    if not samples:
        return unresolved
    first, last = samples[0], samples[-1]
    _acid_sample_blanks(project, acids, first, last, state)
    _final_acid_after_standards(project, last, state)
    sample_blanks = sorted(a.sequence for a in project.assignments.values()
                           if a.role in ('Sample blank', 'Both blanks'))
    for side in ('before', 'after'):
        stds = sorted(a.sequence for a in project.assignments.values() if a.role == 'Standard'
                      and (a.sequence < first if side == 'before' else a.sequence > last))
        if not stds:
            continue
        start, end = stds[0], stds[-1]
        explicit = [a.sequence for a in project.assignments.values()
                    if a.role in ('Standard blank', 'Both blanks') and a.sequence < start
                    and (a.sequence < first if side == 'before' else a.sequence > last)]
        potential = [s for s in acids if s < start
                     and project.assignments[s].role not in ('Sample blank', 'Both blanks')
                     and (s < first if side == 'before' else s > last)]
        if not explicit and len(potential) == 1:
            a = project.assignments[potential[0]]
            a.role = 'Standard blank'
            a.scope_source = 'Unique acid preceding the ' + side + ' standard region'
        elif potential:
            for sequence in potential:
                unresolved[sequence] = 'Which acid solution is the standard blank?\nBefore these standards there is more than one acid solution. One of them is the standard blank; the others are rinses.\nPlasmatti uses the standard blank to correct the standards, so it must know which one it is.\nChoose the role of this solution: standard blank, or rinse (ignored).'
        for sequence in acids:
            a = project.assignments[sequence]
            if a.role in ('Standard blank', 'Sample blank', 'Both blanks') or sequence in unresolved:
                continue
            if not (sequence < first if side == 'before' else sequence > last):
                continue
            cleanup = (sequence > end and
                       (side == 'after' or any(sequence < b < first for b in sample_blanks)))
            if cleanup:
                a.scope_source = 'Cleanup acid after the ' + side + ' standard region'
            else:
                unresolved[sequence] = 'What is this acid solution: a blank, a rinse or something else?\nPlasmatti found an acid solution, but its place in the order of the measurements does not show what it was used for.\nChoose its role. A rinse is ignored in the calculation.'
    for sequence in acids:
        if first <= sequence <= last and str(sequence) not in state['overrides']:
            a = project.assignments[sequence]
            if a.role == 'Ignore' and a.scope_source.startswith(RINSE_SOURCE):
                continue
            unresolved[sequence] = 'What is this acid solution: a blank, a rinse or something else?\nIt was measured between the samples. Plasmatti does not decide on its own what an acid solution between samples is.\nChoose its role. A rinse is ignored in the calculation.'
    return unresolved


RINSE_SOURCE = 'Rinse between the samples'


def _final_acid_after_standards(project, last, state):
    """An acid named as a sample blank at the very end, after the standards that follow the
    samples, is not used when a blank already stands between the last sample and those
    standards (e.g. "HNO3 1.5% samples std" just after the samples). The blank closest to the
    samples is the sample blank; the last acid of the session is not used (Luis, October 2026)."""
    stds = [a.sequence for a in project.assignments.values() if a.role == 'Standard' and a.sequence > last]
    if not stds:
        return
    inner = [a for a in project.assignments.values() if a.role in ('Sample blank', 'Both blanks')
             and last < a.sequence < min(stds)]
    outer = [a for a in project.assignments.values() if a.role == 'Sample blank' and a.sequence > max(stds)
             and str(a.sequence) not in state['overrides']]
    if len(inner) == 1 and outer:
        for a in outer:
            a.role = 'Ignore'
            a.scope_source = (f'Last acid of the session, after the standards: not used (the blank after the samples '
                              f'is measurement {inner[0].sequence})')


def _acid_sample_blanks(project, acids, first, last, state):
    """The laboratory's rule when no measurement is labelled as a blank (Luis, October 2026):
    the sample blank is the acid (HNO3 1.5 %) measured just before the first sample and the
    acid measured just after the last sample. The acid after the samples also serves as the
    standard blank of the standards that follow it. An acid between the samples is a rinse
    after very high samples and is not used in the calculation.
    Applied only when no measurement is labelled or answered as a sample blank, and only
    when exactly one acid stands in each gap; anything else is still asked."""
    roles = {a.sequence: a.role for a in project.assignments.values()}
    if any(r in ('Sample blank', 'Both blanks') for r in roles.values()):
        return
    free = [s for s in acids if str(s) not in state['overrides']]
    others = [s for s, r in roles.items() if r != 'Ignore' and s not in acids]
    before_others = [s for s in others if s < first]
    after_others = [s for s in others if s > last]
    gap_before = [s for s in acids if s < first and (not before_others or s > max(before_others))]
    gap_after = [s for s in acids if s > last and (not after_others or s < min(after_others))]
    if len(gap_before) != 1 or len(gap_after) != 1 or gap_before[0] not in free or gap_after[0] not in free:
        return
    a = project.assignments[gap_before[0]]
    a.role, a.scope_source = 'Sample blank', 'Acid just before the first sample: the sample blank (no measurement is labelled as a blank)'
    a = project.assignments[gap_after[0]]
    if after_others:
        a.role = 'Both blanks'
        a.scope_source = 'Acid just after the last sample: the sample blank, and the standard blank of the standards after it'
    else:
        a.role, a.scope_source = 'Sample blank', 'Acid just after the last sample: the sample blank (no measurement is labelled as a blank)'
    for s in free:
        if first < s < last:
            a = project.assignments[s]
            a.role, a.scope_source = 'Ignore', RINSE_SOURCE + ' (cleaning after high samples; not used in the calculation)'


def _standards_summary(project, unresolved):
    details = [{'sequence': a.sequence, 'standard': a.sample_id,
                'elements': a.standard_element, 'source': a.scope_source}
               for a in sorted(project.assignments.values(), key=lambda x: x.sequence) if a.role == 'Standard']
    bad = sum(d['sequence'] in unresolved for d in details)
    project.standards_recognition = {'recognized': len(details) - bad, 'unresolved': bad, 'details': details,
                                     'status': 'MATCHED' if details and not bad else 'REVIEW'}


def _plain_row(text):
    """Plain-language question (headline) and details for an identification problem."""
    if text.startswith('Unrecognized standard'):
        return ('What does this standard contain?\n'
                'Plasmatti could not find this standard in its library, so it does not know which elements it contains or their concentration.\n'
                'Enter the elements and their concentration. Plasmatti needs them to correct the results.')
    if 'documented standard group' in text:
        names = text.split(':', 1)[-1].strip()
        return ('Which standard is this?\n'
                f'The name fits more than one known standard: {names}.\n'
                'Choose the one that was used. Its composition is then used to correct the results.')
    if text.startswith('Ambiguous prepared level'):
        return ('What is the concentration of this standard?\n' + text)
    if text.startswith('QC-like label'):
        return ('What is this solution?\n'
                'It looks like a quality-control solution, but its name does not tell what it contains or what it was used for.\n'
                'Choose its role and, for a standard, enter what it contains.')
    return text


def _method_question(project, outcome):
    status = outcome.get('status', 'UNRESOLVED')
    label = project.settings.method or outcome.get('label', '')
    if status == 'REVIEW_APPLIED':
        missing = [ch for ch in project.channels if _undefined(project.channels[ch])]
        views = {ch: item for item in view_columns(project) for ch in item['open']}
        hints = outcome.get('hints') or []
        lines = [f'Was "{label}" the method used?']
        if hints:
            lines.append(f'Plasmatti found "{hints[0]}" in the names of your files, so this is probably the right method.')
        else:
            lines.append('The wavelengths in your files fit this method best, so this is probably the right method.')
        n = len(missing)
        if n:
            lines.append(f'But the instrument measured {n} wavelength{"" if n == 1 else "s"} that '
                         f'{"is" if n == 1 else "are"} not in this method\'s list of wavelengths and limits:')
            for ch in missing:
                if ch in views:
                    name = f'{views[ch]["column"]["element"]} {views[ch]["column"]["source_label"]}'
                    lines.append(f'\u2022  {ch}: the method\'s limits file has a column "{name}" but does not say whether '
                                 'it is axial or radial, so Plasmatti did not use it. The next question asks about it.')
                else:
                    lines.append(f'\u2022  {ch}: not in this method.')
            for ch in missing:
                el = ch.split()[0]
                others = [c for c in project.channels if c.split()[0] == el and c != ch
                          and not _undefined(project.channels[c]) and project.channels[c].enabled]
                if others:
                    names = sorted(others)
                    joined = names[0] if len(names) == 1 else ', '.join(names[:-1]) + ' and ' + names[-1]
                    lines.append(f'{el} is also measured at {joined}, which '
                                 f'{"is" if len(others) == 1 else "are"} in the method, so the {el} result normally uses '
                                 f'{"that wavelength" if len(others) == 1 else "one of those"}.')
                else:
                    lines.append(f'{el} has no other wavelength in this method, so the {el} result uses {ch}.')
            lines.append('If you answer Yes: Plasmatti calculates all results with this method. A wavelength that is not '
                         'in the method is used only when its element has no other usable wavelength. Such a result is '
                         'marked "no reporting limit", because Plasmatti has no limit for it and does not guess one.')
        else:
            lines.append('Every measured wavelength now has a limit in this method.')
            lines.append('If you answer Yes: all results are calculated with this method.')
        lines.append('If you answer No: you choose the correct method from the list.')
        return '\n'.join(lines)
    if status == 'REVIEW' and outcome.get('candidates'):
        cands = sorted(outcome['candidates'][:3], key=lambda c: (len(c.get('unmatched_measured_channels') or []), -c.get('jaccard', 0)))
        lines = '; '.join(f'{c["label"]} ({c["matched_channels"]} of {c["measured_channels"]} measured wavelengths)' for c in cands)
        return ('Several methods fit these files. Which one was used?\n'
                'The wavelengths in your files fit more than one method, and the file names do not say which method was used.\n'
                f'Closest methods: {lines}.\n'
                'Check the method name in the instrument software or in your records, then choose it from the list.')
    if status in ('UNRESOLVED', 'REVIEW'):
        return ('Which method was used?\n'
                'Plasmatti could not find a method in its library that fits the wavelengths in your files.\n'
                'Choose the method from the list, or import your own method table.')
    return outcome.get('message') or 'Which method was used?\nChoose the method, or confirm it.'


def inspect_run(project):
    """Automatically identify then validate; return questions, never fake data."""
    state = state_for(project)
    lib = library()
    groups = grouped_readings(project)
    issues = []
    problems_src = []

    def add(kind, message, sequences=(), **extra):
        issue = {'kind': kind, 'message': message, 'sequences': sorted(set(sequences)),
                 'type': 'problem' if kind in ('input', 'structure') else 'question'}
        issue.update(extra)
        issue['id'] = digest({k: issue[k] for k in ('kind', 'message', 'sequences')})
        issues.append(issue)

    def finish():
        report = {'ready': not issues, 'issues': issues,
                  'counts': dict(Counter(a.role for a in project.assignments.values())),
                  'method': project.settings.method, 'method_token': method_token(project),
                  'source_token': digest(problems_src), 'review_only': bool(problems_src)}
        state['last_check'] = copy.deepcopy(report)
        return report
    if state.get('legacy_pending'):
        add('legacy', 'Keep the roles saved in this older project?\nThis project was saved by a development version of Plasmatti. It contains the roles (sample, blank, standard, rinse) chosen at that time.\n"Yes, keep these roles": Plasmatti keeps them and continues.\n"No": the identification list opens, so you can check the roles first.')
        return finish()
    if not groups:
        add('input', 'No measurements were imported.\nPlasmatti found no readable measurements in the chosen files.\nGo back to Step 1, choose the files of one session and import them again.')
    if set(groups) != set(project.assignments):
        add('input', 'The saved roles do not match the measurements.\nThe project file and the measurement files do not belong together.\nGo back to Step 1 and import the files again.')
    for sequence, records in groups.items():
        if len({(r.position, r.sample_id) for r in records}) != 1:
            add('input', f'Measurement {sequence} has two different identities in the files.\nThe files you imported do not agree about this measurement. They may come from different sessions.\nGo back to Step 1 and import the files of one session only.')
        if len({r.channel for r in records}) != len(records):
            add('input', f'Measurement {sequence} has the same wavelength twice.\nThis happens when exports are combined into one file.\nGo back to Step 1 and import the original files of one session.')
    if issues:
        return finish()
    unknown = identify(project, lib, state)
    row_problems = defaultdict(list)
    # Without any autosampler file, the instrument's own sample labels are the identity
    # (older exports); that is one stated fact about the run, not a question per sample.
    no_map_supplied = not any(r.mapped_sample_id for records in groups.values() for r in records)
    for sequence, assignment in project.assignments.items():
        if sequence in unknown:
            row_problems[sequence].append(_plain_row(unknown[sequence]))
        records = groups[sequence]
        reading = records[0]
        mapped = {r.mapped_sample_id for r in records if r.mapped_sample_id}
        confirmed = str(sequence) in state['overrides']
        if len(mapped) > 1:
            add('input', f'Measurement {sequence} has two different names in the autosampler file.\nPlasmatti cannot tell which name is correct.\nCorrect the autosampler file, then go back to Step 1 and import it again.')
        elif not confirmed:
            if mapped and not equivalent_identity(reading.sample_id, next(iter(mapped)), lib):
                row_problems[sequence].append(f'Which name is correct: "{reading.sample_id}" (instrument) or "{next(iter(mapped))}" (autosampler file)?\nThe instrument file and the autosampler file give different names for the same measurement.\nChoose the correct name. It is the name shown in the results.')
            elif not mapped and assignment.role == 'Sample' and not no_map_supplied:
                row_problems[sequence].append('What is the name of this sample?\nThis measurement is not in the autosampler file, so Plasmatti cannot check its name.\nConfirm the name shown, or go back to Step 1 and add the matching autosampler file.')
        if assignment.role not in core.ROLES:
            row_problems[sequence].append('What is this measurement: a sample, a blank or a standard?\nPlasmatti could not tell its role from its name or its place in the order of the measurements.\nChoose its role.')
        if assignment.role == 'Standard' and sequence not in unknown:
            try:
                validate_standard(assignment)
            except (ValueError, TypeError) as exc:
                row_problems[sequence].append(str(exc))
    # Group repeated consequences of ONE missing composition: same label family,
    # same single problem -> one question listing every affected measurement.
    grouped = defaultdict(list)
    singles = {}
    for sequence, messages in sorted(row_problems.items()):
        a = project.assignments[sequence]
        if (len(messages) == 1 and a.role == 'Standard' and a.standard_element == '?'
                and str(sequence) not in state['overrides']):
            grouped[standard_family_key(a.sample_id)].append(sequence)
        else:
            singles[sequence] = messages
    for family, seqs in sorted(grouped.items(), key=lambda kv: kv[1][0]):
        if len(seqs) == 1:
            singles[seqs[0]] = row_problems[seqs[0]]
            continue
        labels = sorted({project.assignments[s].sample_id for s in seqs})
        add('standard_group', f'What does the standard "{family}" contain?\nPlasmatti could not find this standard in its library, so it does not know which elements it contains or their concentration.\n'
            f'It was measured {len(seqs)} times: ' + ', '.join(labels) + '.\nEnter the elements and their concentration once. Plasmatti uses them for all these measurements.', seqs)
    for sequence, messages in sorted(singles.items()):
        add('row', '\n'.join(messages), [sequence])
    if not row_problems:
        assignments = list(project.assignments.values())
        samples = sorted(a.sequence for a in assignments if a.role == 'Sample')
        blanks = sorted(a.sequence for a in assignments if a.role in ('Sample blank', 'Both blanks'))
        if not samples:
            add('structure', 'No samples were found.\nEvery measurement was identified as a blank, a standard or a rinse.\nCheck the roles with the Identification button, or go back to Step 1 and choose the right files.', list(project.assignments))
        elif len(blanks) != 2:
            add('structure', 'A session needs two sample blanks: one before and one after the samples.\nPlasmatti uses these two blanks to correct the samples. A rinse cannot replace a missing blank.\nCheck the roles with the Identification button, or go back to Step 1 and import the complete session.',
                [a.sequence for a in assignments if a.role != 'Standard'])
        elif not (blanks[0] < samples[0] <= samples[-1] < blanks[1]):
            add('structure', 'The sample blanks are not placed before and after all samples.\nOne sample blank must be measured before the first sample and one after the last sample.\nCheck the roles with the Identification button, or go back to Step 1 and import one complete block of samples.', samples + blanks)
        if samples:
            first, last = samples[0], samples[-1]
            inside = [a.sequence for a in assignments if a.role == 'Standard' and first < a.sequence < last]
            if inside:
                add('structure', 'Standards were found between the samples.\nPlasmatti handles one block of samples, with standards before and after it.\nCheck the roles with the Identification button, or split this session into separate blocks and process each one.', inside)
            for side in ('before', 'after'):
                standards = [a for a in assignments if a.role == 'Standard'
                             and (a.sequence < first if side == 'before' else a.sequence > last)]
                if not standards:
                    add('structure', f'No standards were found {side} the samples.\nPlasmatti needs standards both before and after the samples to correct the results.\nCheck the roles with the Identification button, or go back to Step 1 and import the complete session.')
                    continue
                start = min(a.sequence for a in standards)
                candidates = [a for a in assignments if a.role in ('Standard blank', 'Both blanks')
                              and a.sequence < start
                              and (a.sequence < first if side == 'before' else a.sequence > last)]
                if len(candidates) != 1:
                    add('structure', f'The standards {side} the samples need one standard blank.\nPlasmatti uses the standard blank to correct the standards, but it could not find one clearly.\nCheck which acid solution is the standard blank with the Identification button.',
                        [a.sequence for a in assignments if a.sequence < start
                         and (a.sequence < first if side == 'before' else a.sequence > last)])
                extras = [a.sequence for a in assignments if a.role in ('Standard blank', 'Both blanks')
                          and start < a.sequence < max(s.sequence for s in standards)]
                if extras:
                    add('structure', 'More than one group of standards was found on the same side of the samples.\nPlasmatti expects one group of standards before and one after the samples.\nCheck the roles with the Identification button, or split the session.', extras)
            if not issues:
                missing = []
                elements = {core.split_channel(ch)[0] for ch, cfg in project.channels.items() if cfg.enabled}
                if not elements:
                    add('method', 'No wavelengths are enabled.\nAll wavelengths are switched off in the method settings, so nothing can be calculated.\nOpen the method with the Method button and enable at least one wavelength.')
                for element in sorted(elements):
                    before, after = set(), set()
                    for a in assignments:
                        if a.role != 'Standard' or not core._scope_contains(a, element):
                            continue
                        level = a.standard_level * a.standard_multipliers.get(element, 1.0)
                        if a.sequence < first:
                            before.add(level)
                        elif a.sequence > last:
                            after.add(level)
                    if len(before & after) < 2:
                        missing.append(element)
                if missing:
                    add('structure', 'Standards are missing for: ' + ', '.join(missing) + '.\nEach element needs a low and a high standard, both before and after the samples. These elements do not have them.\nCheck the standard compositions with the Identification button, or go back to Step 1 and import the complete session.',
                        [a.sequence for a in assignments if a.role == 'Standard'])
    _reapply_view_answers(project)
    outcome = project.method_recognition or {}
    method_ok = bool(project.settings.method) and (
        outcome.get('status') in ('MATCHED', 'MANUAL_SELECTED', 'MASTER') or
        (outcome.get('status') == 'REVIEW_APPLIED' and
         state['method_acknowledgement'] == method_token(project)))
    if not method_ok:
        add('method', _method_question(project, outcome), status=outcome.get('status', 'UNRESOLVED'))
    for item in view_columns(project):
        if item['answer'] is None and item['open']:
            add('method_view', _view_question(project, item), key=item['key'])
    problems_src[:] = source_problems(project)
    if problems_src and state['source_acknowledgement'] != digest(problems_src):
        add('source', 'Your files do not agree. Continue with the main measurement file only?\n'
            'You imported more than one file with the same measurements, and their values are different:\n'
            + '\n'.join(problems_src[:10]) +
            '\nIf you answer Yes: Plasmatti uses only the main measurement file. The results are marked "for review only".\n'
            'If you do not want this: go back to Step 1 and remove the other file.')
    _standards_summary(project, {s: '' for s in row_problems})
    return finish()


def identification_summary(project, report=None):
    """Short text used on Results: what was identified and from what evidence."""
    report = report or (project.automatic_run or {}).get('last_check') or {}
    c = report.get('counts', {})
    overrides = len((project.automatic_run or {}).get('overrides', {}))
    rec = project.method_recognition or {}
    lib_ = library()
    def n(count, word):
        return f'{count} {word}{"" if count == 1 else "s"}'
    parts = [', '.join([n(c.get('Sample', 0), 'sample'), n(c.get('Sample blank', 0) + c.get('Both blanks', 0), 'sample blank'),
                        n(c.get('Standard', 0), 'standard'), n(c.get('Standard blank', 0) + c.get('Both blanks', 0), 'standard blank')])
             + (f', {c.get("Ignore", 0)} ignored (rinse/cleanup)' if c.get('Ignore') else ''),
             f'Method: {describe_method(project.settings.method, lib_) if project.settings.method else "not identified"} ({rec.get("status", "UNRESOLVED").replace("_", " ").lower()})',
             f'Analyst identification decisions: {overrides}']
    if report.get('review_only'):
        parts.append('REVIEW-ONLY: a source discrepancy was acknowledged.')
    return ' | '.join(parts)


def analyze_identified(project):
    report = inspect_run(project)
    if not report['ready']:
        raise ValueError('Identification needs attention:\n' + '\n'.join(i['message'] for i in report['issues']))
    analysis = core.analyze(project)
    analysis.notes.append('Automatic run identification: no unresolved identification items. This is NOT analytical QC approval.')
    if report['review_only']:
        analysis.notes.append('REVIEW-ONLY: analyst acknowledged a source discrepancy. Resolve the conflicting export before laboratory reporting.')
    return analysis


DEMO_DIR = demo_folder()              # one-file release: the embedded demo is written here when used
DEMO_REPLICATES = 'Demo session replicates as csv.csv'
DEMO_AUTOSAMPLER = 'Autosampler file.csv'
SOLID_DEMO_DIR = demo_folder('solid')     # one-file release: written here when used
DEMO_DISSOLUTION = 'Dissolution file.csv'
# The anonymised real run used by the test suite (not part of the program; see tests/fixtures).
REAL_DEMO_DIR = Path(__file__).resolve().parent / 'tests' / 'fixtures' / 'real_demo' / 'Run (Method 48 - 1)'


def demo_paths():
    """The measurement file and the autosampler file of the invented demo session."""
    extract_demo()
    paths = [str(DEMO_DIR / DEMO_REPLICATES), str(DEMO_DIR / DEMO_AUTOSAMPLER)]
    if not all(Path(p).is_file() for p in paths):
        raise FileNotFoundError('The embedded demo could not be written to ' + str(DEMO_DIR) + '.')
    return paths


def solid_demo_paths():
    """The measurement file, the autosampler file and the dissolution file of the invented solid demo."""
    extract_demo('solid')
    paths = [str(SOLID_DEMO_DIR / DEMO_REPLICATES), str(SOLID_DEMO_DIR / DEMO_AUTOSAMPLER),
             str(SOLID_DEMO_DIR / DEMO_DISSOLUTION)]
    if not all(Path(p).is_file() for p in paths):
        raise FileNotFoundError('The solid demo files are missing. Extract the entire package including data/.')
    return paths


def load_demo(prepared=False):
    """The invented demo session (no laboratory data). With prepared=True the preparation questions are answered
    as a person would (liquid, the dilutions written in the names accepted), for the command line."""
    paths = demo_paths()
    details = {}
    readings, notes = core.load_files(paths, autosampler_path=paths[1], details=details)
    project = core.make_project(readings, paths, demo=True, warnings=notes, source_comparison=details)
    project.settings.project = 'Demo session'
    if prepared:
        pass
        rows = rows_from_project(project)
        suggested = pending_suggestions(project)
        for row in rows:
            row.dilution = suggested.get(row.sequence, 1.0)
        apply_preparation(project, 'Liquid', rows, source='Demo: liquid, dilutions from the sample names',
                          reason='Demo session (command line)')
    return project


def load_solid_demo():
    """The invented solid demo (same measurements as the liquid demo, solid sample names and a dissolution file)."""
    pass
    rep, amap, diss = solid_demo_paths()
    details = {}
    readings, notes = core.load_files([rep, amap], autosampler_path=amap, details=details)
    project = core.make_project(readings, [rep, amap], demo=True, warnings=notes, source_comparison=details)
    project.settings.project = 'Solid demo session'
    project.extra_fields[DISSOLUTION_KEY] = read_dissolution_file(diss)
    return project


def load_real_demo():
    """The anonymised real run of the test suite, with its packaged preparation record."""
    pass
    paths = [str(REAL_DEMO_DIR / 'replicates.csv'), str(REAL_DEMO_DIR / 'autosampler.csv')]
    if not all(Path(p).is_file() for p in paths):
        raise FileNotFoundError('The real test run is missing (tests/fixtures/real_demo).')
    details = {}
