def check_real_demo():
    """`--check-demo`: import, identify and calculate the demo session without the desktop."""
    project = load_demo(prepared=True)
    before = digest([asdict(r) for r in project.readings])
    report = inspect_run(project)
    if before != digest([asdict(r) for r in project.readings]):
        raise AssertionError('Identification changed raw measurement records.')
    if not report['ready']:
        print(json.dumps(report, indent=2, ensure_ascii=False))
        return 2
    pass
    analysis = analyze_identified(project)
    print(json.dumps({'identification': 'READY', 'method': project.settings.method,
                      'counts': report['counts'], 'raw_readings_unchanged': True,
                      'preparation_ready': preparation_status(project)['ready'],
                      'results': [{'element': r.element, 'result': r.reported, 'sd': r.sd_display,
                                   'units': r.units, 'status': r.status, 'category': r.category}
                                  for r in analysis.results]}, indent=2))
    return 0


