# plasmati_history.py
####################################################################################################
# Read an entire history without combining separate analytical runs.
#
# ZIP members are copied only after selection, never extractall(). Archives are
# inputs, not executable projects. Excel formulae/macros are never executed.
import csv, json, math, os, re, shutil, stat, zipfile
from pathlib import Path, PurePosixPath
from collections import defaultdict, Counter
from dataclasses import dataclass, asdict, fields
pass
pass

SUPPORTED={'.csv','.pdf','.xls','.xlsx'}

def substantive(name):
    return not any(p.startswith(('._','~$')) or p in ('__MACOSX','.DS_Store') for p in PurePosixPath(name).parts)

def safe_member(name):
    p=PurePosixPath(name.replace('\\','/'))
    if p.is_absolute() or '..' in p.parts or any(':' in x for x in p.parts):
        raise ValueError(f'Unsafe ZIP path: {name!r}')
    return p

@dataclass
class RunFolder:
    path:str
    files:list
    size_bytes:int=0
    references:list=None
    def __post_init__(self):
        if self.references is None:self.references=[]
    @property
    def label(self):return f'{self.path}  [{len(self.files)} files]'


def index_history(path):
    """Return single-run folders; documentation/master tables are not runs."""
    path=Path(path);bydir=defaultdict(list);sizes={};allfiles=[]
    if path.is_file() and zipfile.is_zipfile(path):
        with zipfile.ZipFile(path) as z:
            for info in z.infolist():
                if info.is_dir() or not substantive(info.filename):continue
                safe_member(info.filename)
                if Path(info.filename).suffix.lower() in SUPPORTED:
                    allfiles.append(info.filename);sizes[info.filename]=info.file_size
                    bydir[str(PurePosixPath(info.filename).parent)].append(info.filename)
    elif path.is_dir():
        for file in path.rglob('*'):
            rel=file.relative_to(path).as_posix()
            if file.is_file() and not file.is_symlink() and substantive(rel) and file.suffix.lower() in SUPPORTED:
                allfiles.append(rel);sizes[rel]=file.stat().st_size;bydir[str(PurePosixPath(rel).parent)].append(rel)
    else:raise ValueError('Choose a history ZIP or extracted history folder.')
    out=[]
    for folder,files in bydir.items():
        if 'detection limits' in folder.lower():continue
        sources=[x for x in files if re.search(r'replicat|\bavg\b|avg\+|average',Path(x).stem,re.I)]
        if not sources and not (re.match(r'20\d{2}[.\-_ ]\d{2}',Path(folder).name) and any(Path(x).suffix.lower() in ('.xls','.pdf','.csv') for x in files)):continue
        date=re.search(r'(20\d{2})[.\-_ ](\d{2})[.\-_ ](\d{2})',Path(folder).name)
        refs=[]
        if date:
            ds='.'.join(date.groups());parent=PurePosixPath(folder).parent
            refs=[x for x in allfiles if PurePosixPath(x).parent==parent and Path(x).name.startswith(ds)
                  and 'result' in Path(x).stem.lower()]
        out.append(RunFolder(folder,sorted(files),sum(sizes[x] for x in files),sorted(refs)))
    return sorted(out,key=lambda r:r.path,reverse=True)


def materialize_run(archive,run:RunFolder,destination,max_bytes=1_000_000_000):
    """Extract ONLY run inputs. Nearby final reports are references, not imports."""
    archive=Path(archive);destination=Path(destination);destination.mkdir(parents=True,exist_ok=True)
    if archive.is_dir():return [str(archive/x) for x in run.files]
    total=0;out=[]
    with zipfile.ZipFile(archive) as z:
        for name in run.files:
            rel=safe_member(name);info=z.getinfo(name)
            if stat.S_ISLNK(info.external_attr>>16):raise ValueError('ZIP symbolic links are not accepted.')
            total+=info.file_size
            if total>max_bytes:raise ValueError('Selected run exceeds extraction size limit.')
            target=destination.joinpath(*rel.parts)
            if not target.resolve().is_relative_to(destination.resolve()):raise ValueError('Unsafe extraction target.')
            target.parent.mkdir(parents=True,exist_ok=True)
            # Exclusive creation avoids overwriting a pre-existing filesystem link.
            with z.open(info) as src, target.open('xb') as dst:shutil.copyfileobj(src,dst)
            out.append(str(target))
    return out


def manual_calculation_rows(path):
    """Read the laboratory's edited AVG calculation ledger, without evaluating formulas.

    Compare two different things separately:
    A. stored raw/blank/% correction -> cached final cell (arithmetic audit);
    B. complete automatic Plasmatti result -> that historical cached cell.
    Historical overrides, earlier rules and rounding make B nontrivial.
    """
    sh=next((s for s in read_workbook(path) if normalized_name(s.name)=='results'),None)
    if sh is None:raise ValueError('No Results sheet in this edited AVG workbook.')
    selected={};header=None
    for r in range(min(10,sh.nrows)):
        for c in range(sh.ncols-2):
            try:ch=canonical_channel(sh.cell(r,c),allow_unknown=False)
            except ValueError:continue
            hints=' '.join(str(sh.cell(rr,c+1)) for rr in (r,r+1))
            hints2=' '.join(str(sh.cell(rr,c+2)) for rr in (r,r+1))
            if re.search('blank.*corr',hints,re.I) and re.search('std.*corr|standard.*corr',hints2,re.I):
                selected[c]=ch;header=r
        if selected:break
    if not selected:raise ValueError('No selected channel followed by blank and standard correction columns.')
    # Initial raw sample block ends at its first blank-name row.
    start=header+2;rawrows=[]
    for r in range(start,sh.nrows):
        name=str(sh.cell(r,0)).strip()
        if not name:break
        rawrows.append((r,name))
    out=[]
    for r,name in rawrows:
        # The earliest later occurrence of the exact sample label after the raw
        # block is the first correction block. Do not use the rounded duplicate.
        later=[rr for rr in range(rawrows[-1][0]+1,sh.nrows)
               if str(sh.cell(rr,0)).strip()==name]
        if not later:continue
        target=later[0]
        for c,ch in selected.items():
            vals=[optional_number(sh.cell(rr,cc)) for rr,cc in ((r,c),(r,c+1),(r,c+2),(target,c))]
            raw,blank,error,final=vals
            if None in vals or abs(1+error/100)<1e-12:continue
            recomputed=(raw-blank)/(1+error/100)
            out.append(dict(sample=name,channel=ch,element=ch.split()[0],raw=raw,blank=blank,error_percent=error,
                            stored_corrected=final,recomputed=recomputed,arithmetic_delta=recomputed-final,
                            raw_row=r+1,corrected_row=target+1,column=c+1,source=Path(path).name))
    return out


def compare_manual(project,analysis,manual_path):
    """Exact identity comparison; no rounding-to-match, hidden overrides or fuzzy names."""
    rows=manual_calculation_rows(manual_path)
    candidates=defaultdict(list)
    for r in analysis.results:candidates[(normalized_name(r.sample_id),r.element)].append(r)
    for item in rows:
        rr=candidates.get((normalized_name(item['sample']),item['element']),[])
        item.update(software_corrected=None,software_delta=None,comparison='unmatched sample',software_channel='')
        if len(rr)>1:item['comparison']='ambiguous repeated sample identity';continue
        if len(rr)!=1:continue
        r=rr[0];item['software_channel']=r.channel
        item['software_corrected']=r.corrected_mean_mg_l
        why=[]
        if r.channel!=item['channel']:why.append('channel selection differs')
        if r.channel==item['channel'] and math.isfinite(r.original_mean) and not math.isclose(r.original_mean,item['raw'],rel_tol=1e-8,abs_tol=1e-8):why.append('historical raw value differs / may have been edited')
        if r.rejected_indices:why.append('replicate filtering applied')
        if r.corrected_mean_mg_l is not None:
            delta=r.corrected_mean_mg_l-item['stored_corrected'];item['software_delta']=delta
            if not why:why.append('numeric match' if abs(delta)<=1e-10 else 'correction/rounding difference')
        else:why.append(r.status)
        item['comparison']='; '.join(why)
    return rows


def save_comparison(rows,path):
    if not rows:raise ValueError('No matched calculation cells in historical workbook.')
    with open(path,'w',newline='',encoding='utf-8-sig') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)


PROJECT_SCHEMA = 'plasmati-project-2'
LEGACY_SCHEMAS = ('plasmati-project-1',)


def save_project(project, path):
    """Portable settings + cached source records. No pickle or code execution.

    Written to a temporary file first, then moved into place, so a failed save
    never leaves a truncated project.
    """
    pass
    data = {'schema': PROJECT_SCHEMA, 'app_version': APP_VERSION, 'project': asdict(project)}
    text = json.dumps(data, indent=2, ensure_ascii=False, allow_nan=False)
    target = Path(path)
    tmp = target.with_name(target.name + '.tmp')
    tmp.write_text(text, encoding='utf-8')
    os.replace(tmp, target)


def _build(cls, data, where, extra, notes):
    """Construct a dataclass; unknown keys are preserved in ``extra`` with a note (never silently dropped)."""
    names = {f.name for f in fields(cls)}
    known = {k: v for k, v in data.items() if k in names}
    unknown = {k: v for k, v in data.items() if k not in names}
    if unknown:
        extra[where] = unknown
        notes.append(f'{where}: unrecognised saved field(s) preserved but not used: ' + ', '.join(sorted(unknown)))
    return cls(**known)


def _migrate_v1(p, notes):
    """plasmati-project-1 -> plasmati-project-2 (development-build project files)."""
    moved = 0
    for a in p.get('assignments', {}).values():
        if a.pop('dilution_suggestion_shown', None) is not None:
            moved += 1
        a.setdefault('preparation_source', '')
    notes.append('Migrated from a development-version project: the "dilution suggestion shown" display flag was removed; '
                 'saved preparation values are retained but must be confirmed once (their origin was not recorded).')
    settings = p.setdefault('settings', {})
    settings.setdefault('sample_type_source', '')
    if any((a.get('moisture_pct') is not None) for a in p.get('assignments', {}).values()
           if a.get('role') == 'Sample') and settings.get('sample_type') == 'Solid':
        settings['reporting_basis'] = 'dry'
        notes.append('Moisture values were saved; that version applied them automatically, so dry-basis reporting is selected '
                     'to keep the saved calculation unchanged. Change the basis in Preparation if as-weighed was intended.')
    else:
        settings.setdefault('reporting_basis', 'as_weighed')
    method_markers = ('Method source issue', 'Method snapshot', 'METHOD REVIEW', 'METHOD RECOGNITION', 'No verified method')
    warnings = p.get('source_warnings', [])
    p['method_notes'] = [w for w in warnings if w.startswith(method_markers)]
    p['source_warnings'] = [w for w in warnings if not w.startswith(method_markers)]
    return p


def load_project(path):
    pass
    if Path(path).stat().st_size > 300_000_000:
        raise ValueError('Project file is too large.')
    data = json.loads(Path(path).read_text(encoding='utf-8'))
    schema = data.get('schema')
    if schema not in (PROJECT_SCHEMA,) + LEGACY_SCHEMAS:
        raise ValueError('Unknown project file schema.')
    p = data['project']
    notes = list(p.get('migration_notes', []))
    if schema in LEGACY_SCHEMAS:
        p = _migrate_v1(p, notes)
    if 'correction_model' not in (p.get('settings') or {}):
        # Saved by a development version: reopen with the rules it was calculated with, so its numbers do not change.
        p = dict(p, settings=dict(p.get('settings') or {}, correction_model='candidates', replicate_rule='lab_rsd',
                                  channel_score='mg_l', method_source='method_table'))
        notes.append('Saved by a development version of Plasmatti: reopened with the calculation rules of that time '
                     '(one standard chosen per result, the RSD rule for replicates, wavelength score in mg/L, '
                     "the run's own method table). Change them in Calculation rules if wanted.")
    extra = dict(p.get('extra_fields', {}) or {})
    top = {f.name for f in fields(Project)}
    unknown_top = {k: v for k, v in p.items() if k not in top}
    if unknown_top:
        extra['project'] = unknown_top
        notes.append('project: unrecognised saved field(s) preserved but not used: ' + ', '.join(sorted(unknown_top)))
    result = Project(
        readings=[_build(Reading, x, 'readings', extra, notes) for x in p['readings']],
        assignments={int(k): _build(Assignment, v, 'assignments', extra, notes) for k, v in p['assignments'].items()},
        channels={k: _build(ChannelSetting, v, 'channels', extra, notes) for k, v in p['channels'].items()},
        settings=_build(RunSettings, p['settings'], 'settings', extra, notes),
        source_paths=p.get('source_paths', []), demo=p.get('demo', False),
        source_warnings=p.get('source_warnings', []),
        source_manifest=p.get('source_manifest', []),
        method_recognition=p.get('method_recognition', {}),
        standards_recognition=p.get('standards_recognition', {}),
        automatic_run=p.get('automatic_run', {'legacy_pending': True}),
        method_notes=p.get('method_notes', []),
        method_element_order=p.get('method_element_order', []),
        source_comparison=p.get('source_comparison', {}),
        decision_log=p.get('decision_log', []),
        migration_notes=list(dict.fromkeys(notes)),
        extra_fields=extra,
    )
    _reading_lookup(result.readings)
    return result


def final_report_rows(path):
    """Read the final paired avg./stdev. layout observed in the laboratory's report XLS files.

    Only labelled units and element columns are accepted. Blank template cells
    are kept explicitly as 'unfilled', never converted to concentrations of zero.
    No optical channel is inferred from the final-report element label.
    """
    results=[]
    for sh in read_workbook(path):
        for header in range(min(sh.nrows,12)):
            names=[c for c,v in enumerate(sh.row(header)) if str(v).strip().casefold()=='sample']
            if not names:continue
            name_col=names[0];columns=[]
            for c in range(name_col+1,sh.ncols):
                if str(sh.cell(header,c)).strip().casefold() not in ('avg.','avg','average'):continue
                el=str(sh.cell(header-2,c)).strip() if header>=2 else ''
                unit=re.sub(r'[\s()]','',str(sh.cell(header-1,c))).lower() if header else ''
                if not re.fullmatch(r'[A-Z][a-z]?',el) or unit not in ('mg/l','mg/kg','mg/100g'):continue
                columns.append((c,el,{'mg/l':'mg/L','mg/kg':'mg/kg','mg/100g':'mg/100g'}[unit]))
            if not columns:continue
            for row in range(header+1,sh.nrows):
                sample=str(sh.cell(row,name_col)).strip()
                if not sample or re.search(r'LOQ\s*:|LOD\s*:|limit of|detection limit',sample,re.I):continue
                for c,el,unit in columns:
                    raw=sh.cell(row,c);sd=sh.cell(row,c+1);value=optional_number(raw)
                    censored=re.fullmatch(r'\s*<\s*([\d.,+eE-]+)\s*',str(raw))
                    state='number' if value is not None else 'below_limit' if censored else 'unfilled' if str(raw).strip()=='' else 'text'
                    results.append(dict(sample=sample,element=el,units=unit,original_text=str(raw),value=value,
                        report_state=state,limit=optional_number(censored[1]) if censored else None,
                        sd=optional_number(sd),sd_text=str(sd),source=Path(path).name,sheet=sh.name,row=row+1,column=c+1))
            break
    if not results:raise ValueError('Final report has no recognized Sample / element / avg. / stdev. / unit header.')
    return results


def compare_final_report(analysis,path):
    rows=final_report_rows(path);book=defaultdict(list)
    for r in analysis.results:book[(normalized_name(r.report_name),r.element,r.units)].append(r)
    for item in rows:
        rr=book.get((normalized_name(item['sample']),item['element'],item['units']),[])
        item.update(software_value=None,software_sd=None,software_limit=None,value_delta=None,sd_delta=None,comparison='unmatched identity/unit')
        if item['report_state']=='unfilled':item['comparison']='historical report cell unfilled';continue
        if len(rr)!=1:
            if len(rr)>1:item['comparison']='ambiguous repeated report identity'
            continue
        r=rr[0];item.update(software_value=r.report_value,software_sd=r.report_sd,software_limit=r.dl)
        if 'BLOCKED' in r.flags:item['comparison']='automatic result BLOCKED';continue
        if item['report_state']=='below_limit':
            same_limit=item['limit'] is not None and r.dl is not None and math.isclose(item['limit'],r.dl,rel_tol=1e-9,abs_tol=1e-12)
            item['comparison']='censor and limit agree' if same_limit and any(f.startswith('BELOW_') for f in r.flags) else 'censor / reporting limit differs'
        elif item['value'] is not None and r.report_value is not None:
            item['value_delta']=r.report_value-item['value']
            item['comparison']='numeric result agrees' if abs(item['value_delta'])<=1e-10 else 'numeric / rounding / processing difference'
            if item['sd'] is not None and r.report_sd is not None:item['sd_delta']=r.report_sd-item['sd']
        else:item['comparison']='historical nonnumeric result requires review'
    return rows


####################################################################################################
# plasmati_export.py
####################################################################################################
# Export: researcher workbook + supporting analysis records.
#
# Output layout (a NEW folder every time; nothing is overwritten)::
#
#     <chosen folder>/<run name> - Plasmatti <date>[ (n)]/
#         ICP results - review.xlsx     the results for checking in the lab (coloured as on the Results page, with remarks)
#         ICP results - report.xlsx     the results for the researcher (no colours, remarks or marks; numbers stored rounded)
#         Detailed explanations.docx    Word report: the formulas, then per element the wavelength choice,
#                                       standards, one worked example and every sample
#         Detailed calculations.xlsx    the same numbers as tables (every replicate, blank, standard, decision)
#         Project.plasmati.json         the saved project (reopen it with "Open saved project")
#
# Results.csv and Audit.json are written only on request (extra_files=True).
#
# Numeric results stay numeric Excel cells with display formats; below-limit
# results are text such as ``<0.007`` with SD ``n/a``. User-controlled text is
# always written as a literal string (no formula execution).

import csv
import json
import math
import os
import re
from collections import defaultdict
from dataclasses import asdict
from datetime import datetime, timezone
from pathlib import Path
from typing import Dict

pass
pass
pass

LIMIT_MEANING = {'LOQ': 'Limit of quantification', 'LOD': 'Limit of detection', 'DL': 'Detection limit'}


def _safe_name(text, fallback='Plasmatti run'):
    text = re.sub(r'[^\w.\- ()+]+', '_', str(text or ''), flags=re.U).strip(' ._')
    return (text or fallback)[:80]


def unique_output_folder(parent, run_name):
    if not str(parent or '').strip():
        raise ValueError('Choose the folder to save the results in.')
    parent = Path(parent).expanduser().resolve()     # a relative path (command line) means the current folder
    if parent.exists() and not parent.is_dir():
        raise ValueError('Output location exists but is not a folder.')
    parent.mkdir(parents=True, exist_ok=True)
    stem = f'{_safe_name(run_name)} - Plasmatti {datetime.now().strftime("%Y-%m-%d")}'
    for i in range(1, 10000):
        candidate = parent / (stem if i == 1 else f'{stem} ({i})')
        try:
            candidate.mkdir()
            return candidate
        except FileExistsError:
            continue
    raise RuntimeError('Unable to create an unused output folder.')


def _literal_strings(wb):
    for sheet in wb.worksheets:
        for row in sheet.iter_rows():
            for cell in row:
                if isinstance(cell.value, str) and cell.value.startswith(('=', '+', '-', '@')):
                    cell.data_type = 's'
                elif isinstance(cell.value, float) and not math.isfinite(cell.value):
                    cell.value = None


def _csv_safe(text):
    text = str(text)
    return "'" + text if text.startswith(('=', '+', '-', '@', '\t', '\r')) else text


def _num_format(decimals):
    return '0' + ('.' + '0' * decimals if decimals else '')


def _round_half_up(x, decimals):
    """Normal rounding (0.0125 -> 0.013), not the round-half-to-even of Python's round()."""
    from decimal import Decimal, ROUND_HALF_UP
    if not isinstance(x, (int, float)) or isinstance(x, bool) or not math.isfinite(x):
        return x
    return float(Decimal(repr(float(x))).quantize(Decimal(1).scaleb(-decimals), rounding=ROUND_HALF_UP))


def _quant(r, solution=False):
    """(value cell, sd cell, numeric?) for one result in the researcher workbook."""
    if solution:
        if 'BLOCKED' in r.flags or r.solution_value is None:
            return 'BLOCKED', NO_SD, False
        if r.solution_reported.startswith('<'):
            return r.solution_reported, NO_SD, False
        return r.solution_value, (r.solution_sd if r.solution_sd is not None else NO_SD), True
    if 'BLOCKED' in r.flags or r.report_value is None:
        return 'BLOCKED', NO_SD, False
    if any(f.startswith('BELOW_') for f in r.flags):
        return r.reported, NO_SD, False
    return r.report_value, (r.report_sd if r.report_sd is not None else NO_SD), True


def element_order(project, analysis):
    present = {r.element for r in analysis.results}
    order = [e for e in (project.method_element_order or []) if e in present]
    return order + sorted(present - set(order))


def remarks_for(results):
    out = []
    for r in results:
        if r.category in ('attention', 'blocked'):
            words = {'ONE_STANDARD': 'only the low standard usable, extrapolated',
                     'OTHER_WAVELENGTH': f'calculated on {r.channel} (no value on the chosen wavelength)',
                     'OTHER_BLANK': 'standards corrected with the standard blank from the other side of the samples'}
            flags = [words.get(f, f) for f in r.flags if not f.startswith('BELOW_')]
            text = f'{r.element}: ' + ', '.join(flags)
            if 'BLOCKED' in r.flags and r.notes:
                text += f' ({r.notes[-1][:120]})'
            out.append(text)
    return '; '.join(out)


def _style_header(cell, fill='20334B'):
    from openpyxl.styles import Font, PatternFill, Alignment
    cell.fill = PatternFill('solid', fgColor=fill)
    cell.font = Font(bold=True, color='FFFFFF')
    cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)


def _paint_result(cell, r):
    """The same colours as on the Results page (background and text)."""
    from openpyxl.styles import Font, PatternFill
    bg, fg = core.CATEGORY_COLOURS[core.screen_category(r)]
    cell.fill = PatternFill('solid', fgColor=bg.lstrip('#'))
    cell.font = Font(color=fg.lstrip('#'), bold=core.screen_category(r) in ('attention', 'blocked'))


def _colour_key(ws, row, col):
    """One row: 'Colour key:' and the four groups in their own colours (as the filter buttons on screen)."""
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    ws.cell(row, col, 'Colour key:').font = Font(name='Arial', size=10, bold=True)
    c = col + 1
    edge = Side(style='thin', color='CBD5E1')
    for key in ('ok', 'below_limit', 'attention', 'blocked'):
        bg, fg = core.CATEGORY_COLOURS[key]
        span = 3 if key == 'attention' else 2
        ws.merge_cells(start_row=row, start_column=c, end_row=row, end_column=c + span - 1)
        for k in range(span):
            part = ws.cell(row, c + k)
            part.fill = PatternFill('solid', fgColor=bg.lstrip('#'))
            part.border = Border(top=edge, bottom=edge, left=edge if k == 0 else None,
                                 right=edge if k == span - 1 else None)
        cell = ws.cell(row, c, core.SCREEN_LABELS[key])
        cell.font = Font(name='Arial', size=10, color=fg.lstrip('#'), bold=key in ('attention', 'blocked'))
        cell.alignment = Alignment(horizontal='center')
        c += span + 1
    return row + 1


def _report_text(text):
    """'<0.5' is written '< 0.5' in the results workbook, as in the laboratory's reports."""
    return '< ' + text[1:] if isinstance(text, str) and text.startswith('<') and not text.startswith('< ') else text


def round_limit_up(x):
    """A limit rounded UP to a simple number (agreed with the laboratory, 29 October 2026): steps of 5 in the
    second digit (24.92 -> 25, 0.21 -> 0.25, 25.31 -> 30), steps of 1 when the number starts with 1
    (1.03 -> 1.1, 0.0123 -> 0.013), so a limit is never raised by more than about 25 %."""
    from decimal import Decimal, ROUND_CEILING
    v = Decimal(f'{float(x):.10g}')             # 1.3000000000000003 (floating-point noise) is 1.3, not above it
    if v <= 0:
        return float(v)
    e = v.adjusted()                             # position of the first digit
    lead = int(v.scaleb(-e))                     # the first digit
    step = Decimal(1 if lead == 1 else 5).scaleb(e - 1)
    return float((v / step).to_integral_value(rounding=ROUND_CEILING) * step)


def _limit_number_text(x):
    from decimal import Decimal
    return format(Decimal(repr(float(x))).normalize(), 'f')


COMMON_LIMIT_SPREAD = 1.5      # one limit per element only when the highest is at most 1.5 x the lowest


def common_solid_limits(project, analysis):
    """For the researcher's report of solid samples with a limit per sample: per element, the average of the
    per-sample limits rounded up (round_limit_up; the laboratory's choice, 29 October 2026), or None when the
    samples' limits differ too much (highest > 1.5 x lowest) and each sample keeps its own limit."""
    if project.settings.sample_type != 'Solid' or project.settings.limit_policy != 'sample_specific':
        return {}
    by_el = defaultdict(list)
    for r in analysis.results:
        # only results on the element's chosen wavelength (a result on another wavelength keeps its own limit)
        if (r.dl is not None and r.dl > 0 and 'BLOCKED' not in r.flags
                and r.channel == analysis.selected_channels.get(r.element)):
            by_el[r.element].append(r.dl)
    out = {}
    for el, limits in by_el.items():
        out[el] = (round_limit_up(sum(limits) / len(limits)) if max(limits) <= COMMON_LIMIT_SPREAD * min(limits)
                   else None)
    return out


def _rounded_limit_text(text, uf=1.0):
    """'< 0.299820108' (a mg/kg limit calculated for one sample) as '< 0.300': the limit rounded with the result rule."""
    if not (isinstance(text, str) and text.startswith('< ')):
        return text
    try:
        x = float(text[2:])
    except ValueError:
        return text
    d = display_decimals(x, uf)
    return f'< {_round_half_up(x, d):.{d}f}'


def _mark_format(fmt, symbols):
    """A number format that shows the information marks after the number; the cell stays a number."""
    return fmt + (f'"{symbols}"' if symbols else '')


def _mark_words(r):
    """The information marks of one result in words."""
    words = []
    if '\u2191' in core.mark_symbols(r):
        words.append('above the highest standard (\u2191)')
    if 'STANDARD_OFF' in (getattr(r, 'marks', None) or []):
        words.append(f'corrected with a standard more than {STANDARD_CHECK_TOLERANCE:.0%} from its nominal value (\u2020)')
    return words


def _below_own_limit_remarks(results, common):
    """Results the researcher's report shows as a number although they are below their own sample's limit
    (the report uses the average limit of the element)."""
    out = []
    for r in results:
        lim = common.get(r.element)
        if (lim is not None and any(f.startswith('BELOW_') for f in r.flags) and r.report_value is not None
                and r.report_value >= lim):
            out.append(f'{r.element} {r.report_value:.4g} is below this sample\'s own limit ({r.dl:.4g} {r.units}); the '
                       f'report shows it as a number because it uses the average limit ({_limit_number_text(lim)})')
    return '; '.join(out)


def _remarks(results, common=None):
    """Remarks for one sample: quality flags, the information marks, and elements for which only the low
    standard was usable."""
    results = list(results)
    out = remarks_for(results)
    if common:
        extra = _below_own_limit_remarks(results, common)
        out = '; '.join(x for x in (out, extra) if x)
    marks = ', '.join(f'{r.element}{core.mark_symbols(r)}' for r in results if core.mark_symbols(r))
    low = ', '.join(f'{r.element}: only the low standard usable' for r in results
                    if any(n.startswith('Only the ') and 'standard was usable' in n for n in r.notes)
                    and 'ONE_STANDARD' not in r.flags)
    return '; '.join(x for x in [out, marks, low] if x)


def write_researcher_workbook(project, analysis, path, prep_status=None, ident_summary='', colour=True):
    """The results for the researcher in the laboratory's report layout (Arial 10; per element a box with
    the element, the unit and avg. | stdev.; thin borders round every value; the limit row and its meaning
    under the table). colour=False writes the same workbook in black and white."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
    wb = Workbook()
    ws = wb.active
    ws.title = 'ICP results'
    solid = project.settings.sample_type == 'Solid'
    uf_report = core.unit_choices(project.settings.sample_type)[core.report_unit(project.settings)]
    elements = element_order(project, analysis)
    by_sample = defaultdict(dict)
    order = []
    for r in analysis.results:
        key = (r.sequence, r.report_name)
        if key not in by_sample:
            order.append(key)
        by_sample[key][r.element] = r
    kinds = {r.limit_kind or 'DL' for r in analysis.results}
    kind = kinds.pop() if len(kinds) == 1 else 'Reporting limit'
    thin, medium = Side(style='thin'), Side(style='medium')
    font = Font(name='Arial', size=10)
    bold = Font(name='Arial', size=10, bold=True)
    col = 2
    weight_col = None
    if solid:
        col += 1
        weight_col = col
    blocks = [('solution', 'mg/L')] if solid and colour else []   # the researcher's report: mg/kg only
    blocks.append(('main', core.report_unit(project.settings)))
    common = common_solid_limits(project, analysis) if not colour else {}
    review_common = common_solid_limits(project, analysis) if colour else {}
    positions = []   # (block, element, column)
    for bi, (block, unit) in enumerate(blocks):
        if bi:
            col += 1   # empty separator column, as in the laboratory's reports
        for el in elements:
            col += 1
            positions.append((block, el, col))
            ws.cell(1, col, el)
            ws.cell(2, col, f'({unit})')
            ws.merge_cells(start_row=1, start_column=col, end_row=1, end_column=col + 1)
            ws.merge_cells(start_row=2, start_column=col, end_row=2, end_column=col + 1)
            ws.cell(3, col, 'avg.')
            ws.cell(3, col + 1, 'stdev.')
            col += 1
    last_col = col
    remarks_col = col + 2
    # header
    for r_ in (1, 2, 3):
        for c in range(2, last_col + 1):
            ws.cell(r_, c).font = bold
            ws.cell(r_, c).alignment = Alignment(horizontal='center', vertical='center')
    ws.cell(3, 2, 'Sample').alignment = Alignment(horizontal='center', vertical='bottom')
    ws.cell(1, 2).border = Border(left=thin, right=thin, top=thin)
    ws.cell(2, 2).border = Border(left=thin, right=thin)
    ws.cell(3, 2).border = Border(left=thin, right=thin, bottom=thin)
    if weight_col:
        # the Weight column has a thick line on both sides, from the top to the limit row
        ws.cell(2, weight_col, 'Weight')
        ws.cell(3, weight_col, '(g)')
        ws.cell(1, weight_col).border = Border(left=medium, right=medium, top=thin)
        ws.cell(2, weight_col).border = Border(left=medium, right=medium)
        ws.cell(3, weight_col).border = Border(left=medium, right=medium, bottom=thin)
    for _, _, c in positions:
        # element and unit: one thin box over avg. and stdev.; avg. and stdev. in thin boxes below
        ws.cell(1, c).border = Border(left=thin, top=thin)
        ws.cell(1, c + 1).border = Border(right=thin, top=thin)
        ws.cell(2, c).border = Border(left=thin)
        ws.cell(2, c + 1).border = Border(right=thin)
        for k in (0, 1):
            ws.cell(3, c + k).border = Border(left=thin, right=thin, top=thin, bottom=thin)
    if colour:
        ws.cell(3, remarks_col, 'Remarks (Plasmatti quality flags and marks)').font = bold
    box = Border(left=thin, right=thin, top=thin, bottom=thin)
    weight_box = Border(left=medium, right=medium, top=thin, bottom=thin)
    widths = defaultdict(int)
    row = 4
    for key in order:
        results = by_sample[key]
        name = ws.cell(row, 2, key[1])
        name.font, name.border = font, box
        name.alignment = Alignment(horizontal='right')
        if weight_col:
            a = project.assignments.get(key[0])
            wc = ws.cell(row, weight_col, a.mass_g if a is not None and a.mass_g is not None else NO_SD)
            if a is not None and a.mass_g is not None:
                wc.number_format = '0.0000'
            wc.font, wc.border = font, weight_box
            wc.alignment = Alignment(horizontal='right')
        for block, el, c in positions:
            r = results.get(el)
            if r is None:
                cells = (ws.cell(row, c, 'n/a'), ws.cell(row, c + 1, NO_SD))
                for cell in cells:
                    cell.font, cell.border = font, box
                    cell.alignment = Alignment(horizontal='right')
                continue
            value, sd, numeric = _quant(r, solution=(block == 'solution'))
            symbols = core.mark_symbols(r) if block == 'main' and colour else ''
            lim = (common.get(el) if block == 'main' and r.channel == analysis.selected_channels.get(el) else None)
            if lim is not None and 'BLOCKED' not in r.flags:
                # one limit for the element (the average of the samples' limits, rounded up): below it is
                # "< limit"; at or above it the number is shown, also when it is below the sample's own limit
                if r.report_value is not None and r.report_value >= lim:
                    if not numeric:
                        value, sd, numeric = r.report_value, (r.report_sd if r.report_sd is not None else NO_SD), True
                else:
                    value, sd, numeric = '< ' + _limit_number_text(lim), NO_SD, False
            shown = _report_text(value)
            if (not numeric and block == 'main' and solid and lim is None
                    and project.settings.limit_policy == 'sample_specific'):
                shown = _rounded_limit_text(shown, uf_report)
            if not numeric and symbols and isinstance(shown, str) and shown.startswith('<'):
                shown += symbols
            d = display_decimals(value, 1.0 if block == 'solution' else uf_report) if numeric else None
            if numeric and not colour:
                # black and white: the stored number is the rounded one (normal rounding, the shown decimals)
                shown = _round_half_up(value, d)
                if isinstance(sd, (int, float)):
                    sd = _round_half_up(sd, d + 1)
            vc = ws.cell(row, c, shown)
            sc = ws.cell(row, c + 1, sd)
            text = str(value)
            if numeric:
                vc.number_format = _mark_format(_num_format(d), symbols)
                text = f'{value:.{d}f}{symbols}'
                if isinstance(sd, (int, float)):
                    sc.number_format = _num_format(d + 1)
            widths[c] = max(widths[c], len(text))
            widths[c + 1] = max(widths[c + 1], len(f'{sd:.6g}' if isinstance(sd, float) else str(sd)))
            for cell in (vc, sc):
                cell.border = box
                cell.alignment = Alignment(horizontal='right')
                if colour:
                    _paint_result(cell, r)
                    cell.font = Font(name='Arial', size=10, color=cell.font.color, bold=cell.font.bold)
                else:
                    cell.font = font
        if colour:
            rem = ws.cell(row, remarks_col, _remarks(results.values(), review_common))
            rem.font = font
        row += 1
    # Limit row
    lim = ws.cell(row, 2, f'{kind} :')
    lim.font, lim.border = bold, box
    lim.alignment = Alignment(horizontal='right')
    if weight_col:
        wc = ws.cell(row, weight_col, NO_SD)
        wc.font, wc.border = bold, Border(left=medium, right=medium, top=thin, bottom=thin)
        wc.alignment = Alignment(horizontal='center')
    varied = False
    for block, el, c in positions:
        rs = [by_sample[k][el] for k in order if el in by_sample[k]]
        if block == 'solution':
            ch = analysis.selected_channels.get(el) or (rs[0].channel if rs else '')
            base = project.channels[ch].dl_mg_l if ch in project.channels else None
        elif solid and project.settings.limit_policy == 'lab_stored':
            ch = analysis.selected_channels.get(el) or (rs[0].channel if rs else '')
            base = project.channels[ch].dl_mg_kg if ch in project.channels else None
        elif solid and common.get(el) is not None:
            base = common[el]
            varied = True
        elif solid:
            base = None
            varied = True
        else:
            ch = analysis.selected_channels.get(el) or (rs[0].channel if rs else '')
            base = project.channels[ch].dl_mg_l if ch in project.channels else None
        if base is not None and block != 'solution' and not (solid and common.get(el) is not None):
            base = float(f'{base * uf_report:.12g}')   # the limit in the unit of this block (0.01 mg/L = 10 µg/L)
        cell = ws.cell(row, c, base if base is not None else ('for each sample' if solid and block == 'main' and project.settings.limit_policy == 'sample_specific' else 'missing'))
        if base is not None:
            cell.number_format = 'General'
        cell.font = bold
        cell.alignment = Alignment(horizontal='center')
        cell.border = Border(left=thin, top=thin, bottom=thin)
        ws.cell(row, c + 1).border = Border(right=thin, top=thin, bottom=thin)
        ws.merge_cells(start_row=row, start_column=c, end_row=row, end_column=c + 1)
        if any(abs(a.dilution - 1) > 1e-12 for a in project.assignments.values() if a.role == 'Sample' and a.report):
            varied = True
    row += 1
    lines = ['; '.join(f'{k} : {LIMIT_MEANING.get(k, k)}' for k in sorted({r.limit_kind or 'DL' for r in analysis.results}))]
    if not colour:
        # black and white: only the limit meaning and, for solids, how the mg/kg limit of each sample is calculated
        if solid and project.settings.limit_policy == 'sample_specific':
            if any(v is not None for v in common.values()):
                lines.append('The mg/kg limit of each sample = LOQ (mg/L) × final volume (mL) ÷ mass (g) × dilution. '
                             'The limit shown is the average of the samples\' limits, rounded up; a result below it is shown '
                             'as "< limit".')
            own = sorted(el for el, v in common.items() if v is None)
            if own:
                lines.append(f'{", ".join(own)}: the samples\' limits differ too much (highest more than '
                             f'{COMMON_LIMIT_SPREAD:g} × lowest), so each sample\'s own limit is shown.')
            if not any(v is not None for v in common.values()):
                lines.append('The mg/kg limit of each sample = LOQ (mg/L) × final volume (mL) ÷ mass (g) × dilution; '
                             'a result below it is shown as "< limit".')
    else:
        if varied and project.settings.dilution_limit_policy == 'scale_with_dilution':
            lines.append('Limits shown are for the undiluted solution/method; a diluted sample\'s "<" value includes its dilution factor.')
        if solid:
            basis = 'dry mass' if project.settings.reporting_basis == 'dry' else 'as-weighed mass'
            lines.append(f'mg/kg results use the {basis}, the final solution volume and any additional dilution.')
            if project.settings.limit_policy == 'sample_specific':
                lines.append('The mg/kg limit of each sample = LOQ (mg/L) × final volume (mL) ÷ mass (g) × dilution; '
                             'a result below it is shown as "< limit".')
        lines.append('SD (stdev.) is the corrected within-measurement replicate SD, not a combined measurement uncertainty.')
        lines.append('\u2191 after a value: above the highest standard (extrapolated; dilute and measure again).  '
                     f'\u2020 after a value: corrected with a standard more than {STANDARD_CHECK_TOLERANCE:.0%} from its nominal value. '
                     'Both are information; see the Remarks.')
    for text in lines:
        ws.cell(row, 2, text).font = font
        row += 1
    if colour:
        row += 1
        _colour_key(ws, row, 2)
        ws.cell(row + 1, 2, 'A below-limit result with high scatter counts as "Below limit" (scatter near zero is expected); '
                            'its flag is in the Remarks.').font = font
    ws.column_dimensions['A'].width = 3
    ws.column_dimensions['B'].width = max(16, min(40, max((len(str(k[1])) for k in order), default=10) + 4))
    if weight_col:
        ws.column_dimensions[get_column_letter(weight_col)].width = 9
    for _, _, c in positions:
        for k in (0, 1):
            ws.column_dimensions[get_column_letter(c + k)].width = max(8.7, widths[c + k] + 2)
    if colour:
        ws.column_dimensions[get_column_letter(remarks_col)].width = 60
    ws.freeze_panes = 'C4'
    ws.page_setup.orientation = 'landscape'
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    # Notes sheet
    notes = wb.create_sheet('Notes')
    notes.append(['Field', 'Value'])
    st = project.settings
    info = [
        ('Run / project', st.project), ('Requester', st.requester),
        ('ICP-OES method', (('not named in the file names' if st.method == core.MASTER_NAME else st.method)
                            + ' (preference order and limits from the built-in limit table)'
                            if (project.method_recognition or {}).get('status') == 'MASTER'
                            else describe_method(st.method, load_library())) if st.method else ''),
        ('Sample type', st.sample_type + (f' ({st.sample_type_source})' if st.sample_type_source else ' (NOT CONFIRMED)')),
        ('Reporting basis', 'dry mass' if solid and st.reporting_basis == 'dry' else ('as-weighed' if solid else 'solution')),
        ('Generated', datetime.now(timezone.utc).isoformat(timespec='seconds') + ' (UTC)'),
        ('Software', f'{APP_NAME} - development software; results require laboratory review'),
        ('Run identification', ident_summary),
        ('Standard correction', core.CORRECTION_MODELS.get(st.correction_model, st.correction_model)),
        ('Outlying replicates', core.REPLICATE_RULES.get(st.replicate_rule, st.replicate_rule)
         + ('' if st.auto_filter else ' (switched off)')),
        ('Choosing the wavelength', core.CHANNEL_SCORES.get(st.channel_score, st.channel_score)),
        ('Preference and limits from', core.METHOD_SOURCES.get(st.method_source, st.method_source)),
        ('How to cite Plasmatti', APP_CITATION_TEXT),
    ]
    if prep_status is not None and not prep_status.get('ready'):
        info.append(('PREPARATION NOT CONFIRMED', '; '.join(i['message'] for i in prep_status['items'])))
    last = (project.automatic_run or {}).get('last_check', {})
    if last.get('review_only'):
        info.append(('REVIEW ONLY', 'A discrepancy between the CSV and PDF exports was acknowledged; resolve it before reporting.'))
    for note in project.method_notes:
        if note.startswith('Method limits file column'):
            info.append(('Method limit answered by the analyst', note))
    info.append(('Source cross-checks', source_check_text(project)))
    pass
    for note in project.source_warnings or []:
        if note.startswith(BASIS_NOTE_START):
            info.append(('DILUTION CHECK NOT POSSIBLE', note[len(BASIS_NOTE_START):]))
    low_only = sorted({r.element for r in analysis.results
                       if any(n.startswith('Only the ') and 'standard was usable' in n for n in r.notes)})
    if low_only:
        info.append(('Only the low standard usable', ', '.join(low_only) + ': the instrument gave no value for the higher '
                     'standard on any wavelength; results above the low standard are extrapolated (marked).'))
    above = defaultdict(int)
    for r in analysis.results:
        if any(n.startswith('Above the highest standard') for n in r.notes):
            above[r.element] += 1
    if above:
        info.append(('Above the highest standard (extrapolated; dilute and measure again)',
                     ', '.join(f'{el}: {n} result{"" if n == 1 else "s"}' for el, n in sorted(above.items()))))
    checks = getattr(analysis, 'standard_checks', None) or []
    if checks:
        info.append((f'Standards more than {STANDARD_CHECK_TOLERANCE:.0%} from their nominal value',
                     ' '.join(standard_check_text(c) for c in checks)
                     + ' Results corrected with these standards may be biased; please review.'))
    for k, v in info:
        notes.append([k, v])
    notes.append([])
    notes.append(['Results needing attention', ''])
    flagged = [r for r in analysis.results if r.category in ('attention', 'blocked')]
    if not flagged:
        notes.append(['None', 'No high RSD, missing limit, blocked calculation or other attention flag.'])
    for label, text in grouped_attention(flagged):
        notes.append([label, text])
    for c in notes[1]:
        _style_header(c)
    notes.column_dimensions['A'].width = 34
    notes.column_dimensions['B'].width = 110
    _literal_strings(wb)
    wb.save(path)


def source_check_text(project):
    """One line per optional source that was compared with the primary replicates."""
    lines = []
    for item in (project.source_comparison or {}).get('comparisons', []):
        name = item.get('secondary', '')
        if item.get('ignored'):
            lines.append(f'{name}: not used ({item["ignored"]})')
        elif item.get('failed'):
            lines.append(f'{name}: comparison FAILED ({item["failed"]})')
        elif item.get('kind') == 'summary':
            n = item.get('counts', {}).get('summary_statistics', 0)
            lines.append(f'{name} (AVG+STDEV, cross-check only, no value taken from it): {item.get("overlap", 0)} records compared; ' +
                         ('mean/SD/RSD agree' if not n else f'{n} DIFFERING values'))
        else:
            diff = sum(item.get('counts', {}).values())
            lines.append(f'{name} (PDF): {item.get("overlap", 0)} records compared; ' +
                         ('all categories agree' if not diff else f'{diff} discrepancies'))
    return '; '.join(lines) if lines else 'none (replicate source only)'


def grouped_attention(flagged, limit=12, show=4):
    """(label, text) rows for the Notes sheet: one row per result when there are few,
    otherwise one row per element and status with the affected samples named."""
    if len(flagged) <= limit:
        return [(f'{r.report_name} - {r.element}', f'{CATEGORY_LABELS[r.category]}: {r.status}. ' +
                 ('; '.join(r.notes[-2:]) if r.category == 'blocked' else '')) for r in flagged]
    groups = {}
    for r in flagged:
        groups.setdefault((r.element, r.category, r.status), []).append(r.report_name)
    rows = []
    for (element, category, status), names in sorted(groups.items()):
        extra = f' and {len(names) - show} more' if len(names) > show else ''
        rows.append((element, f'{CATEGORY_LABELS[category]}: {status} - {len(names)} result(s): ' +
                     ', '.join(names[:show]) + extra + '. Individual records are in the detailed workbook.'))
    return rows


def write_detailed_workbook(project, analysis, path, prep_status=None, ident_summary=''):
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter
    wb = Workbook()
    report = wb.active
    report.title = 'Results'
    uf_report = core.unit_choices(project.settings.sample_type)[core.report_unit(project.settings)]
    hdr = ['Sample', 'Element', 'Wavelength / view', 'Result', 'SD', 'Units', 'Status', 'Category', 'Marks']
    report.append(hdr)
    for r in analysis.results:
        concentration, uncertainty, numeric = _quant(r)
        report.append([r.report_name, r.element, r.channel, concentration, uncertainty, r.units, r.status,
                       core.SCREEN_LABELS[core.screen_category(r)], '; '.join(_mark_words(r))])
        for col in (4, 5, 8):
            _paint_result(report.cell(report.max_row, col), r)
        if numeric:
            d = display_decimals(concentration, uf_report)
            report.cell(report.max_row, 4).number_format = _num_format(d)
            if isinstance(uncertainty, (float, int)):
                report.cell(report.max_row, 5).number_format = _num_format(d + 1)
    matrix = wb.create_sheet('Sample matrix', 1)
    elements = element_order(project, analysis)
    matrix.append(['Sequence', 'Sample (' + core.report_unit(project.settings) + ')']
                  + [cell for element in elements for cell in (element, element + ' SD')])
    grouped = defaultdict(dict)
    for r in analysis.results:
        grouped[(r.sequence, r.report_name)][r.element] = r
    for (seq, name), values in sorted(grouped.items()):
        row = [seq, name]
        for element in elements:
            result = values.get(element)
            if result:
                v, s, _ = _quant(result)
                row.extend((v, s))
            else:
                row.extend(('-', NO_SD))
        matrix.append(row)
        for j, element in enumerate(elements):
            result = values.get(element)
            if result:
                _paint_result(matrix.cell(matrix.max_row, 3 + 2 * j), result)
                _paint_result(matrix.cell(matrix.max_row, 4 + 2 * j), result)
                v, s, numeric = _quant(result)
                if numeric:
                    d = display_decimals(v, uf_report)
                    matrix.cell(matrix.max_row, 3 + 2 * j).number_format = _num_format(d)
                    if isinstance(s, (int, float)):
                        matrix.cell(matrix.max_row, 4 + 2 * j).number_format = _num_format(d + 1)
    qc = wb.create_sheet('QC and calculation trail')
    qc_headers = ['Sequence', 'Autosampler pos', 'Sample ID', 'Element', 'Channel', 'Raw mean mg/L',
                  'Blank mg/L', 'Standard level mg/L', 'Standard factor', 'Corrected mean mg/L',
                  'Corrected SD mg/L', 'Dilution', 'Final numeric result', 'Final SD', 'Reporting limit',
                  'Initial raw RSD %', 'Retained raw RSD %', 'N kept', 'Kept replicates', 'Rejected replicates',
                  'Status', 'Notes', 'Limit kind', 'Limit policy', 'Statistics basis', 'Corrected RSD %',
                  'Low-standard candidate mg/L', 'High-standard candidate mg/L', 'Switch threshold mg/L',
                  'Mass used g', 'Final volume mL', 'Solution mg/L (solids)', 'Solution SD mg/L (solids)', 'Category',
                  'Standard correction', 'Calibration slope a', 'Calibration intercept b mg/L',
                  'Concentration in measured solution mg/L', 'Replicate rule', 'Unit']
    qc.append(qc_headers)
    for r in analysis.results:
        qc.append([r.sequence, r.position, r.sample_id, r.element, r.channel,
                   r.original_mean, r.blank, r.standard_level, r.standard_factor,
                   r.corrected_mean_mg_l, r.corrected_sd_mg_l, r.applied_dilution,
                   r.report_value, r.report_sd, r.dl, r.rsd_initial if math.isfinite(r.rsd_initial) else None,
                   r.rsd_final if math.isfinite(r.rsd_final) else None, r.n_kept,
                   ', '.join(map(str, r.kept_indices)), ', '.join(map(str, r.rejected_indices)),
                   r.status, '; '.join(r.notes), r.limit_kind, r.limit_policy, r.statistics_basis, r.corrected_rsd,
                   r.low_candidate_mg_l, r.high_candidate_mg_l, r.regime_threshold_mg_l, r.mass_used_g, r.volume_ml,
                   r.solution_value, r.solution_sd, CATEGORY_LABELS.get(r.category, r.category),
                   core.CORRECTION_MODELS.get(r.correction_model, r.correction_model), r.cal_slope, r.cal_intercept,
                   r.solution_mg_l, core.REPLICATE_RULES.get(r.replicate_rule, r.replicate_rule), r.units])
    ranks = wb.create_sheet('Channel selection')
    ranks.append(['Element', 'Channel', 'Mean abs standard difference ' + ('%' if project.settings.channel_score == 'percent' else 'mg/L'), 'Preference order',
                  'Selected', 'Solution limit mg/L', 'Stored solid limit mg/kg', 'Limit kind', 'Source table', 'Source SHA256'])
    for ch, cfg in sorted(project.channels.items()):
        ranks.append([split_channel(ch)[0], ch, analysis.channel_scores.get(ch), cfg.preference_order,
                      'Yes' if analysis.selected_channels.get(split_channel(ch)[0]) == ch else '',
                      cfg.dl_mg_l, cfg.dl_mg_kg, cfg.limit_kind, cfg.limit_source, cfg.limit_source_sha256])
    meta = wb.create_sheet('Run information')
    meta.append(['Field', 'Value'])
    last = (project.automatic_run or {}).get('last_check', {})
    for key, value in [('Application', APP_NAME), ('Run', project.settings.project),
                       ('Demo data', str(project.demo)), ('Sample type', project.settings.sample_type),
                       ('Sample type evidence', project.settings.sample_type_source or 'NOT CONFIRMED'),
                       ('Reporting basis (solids)', project.settings.reporting_basis),
                       ('Requester', project.settings.requester), ('Method', project.settings.method),
                       ('Method recognition', (project.method_recognition or {}).get('status', '')),
                       ('RSD limit %', project.settings.rsd_limit),
                       ('Identification ready', str(last.get('ready', 'not checked'))),
                       ('Identification summary', ident_summary),
                       ('Review-only source discrepancy', str(last.get('review_only', False))),
                       ('Preparation confirmed', str(bool(prep_status and prep_status.get('ready'))))]:
        meta.append([key, value])
    for key in ('statistics_basis', 'limit_policy', 'dilution_limit_policy', 'boundary_policy', 'auto_filter'):
        meta.append([key, str(getattr(project.settings, key))])
    meta.append(['SD definition', 'Corrected within-measurement replicate SD; not combined measurement uncertainty.'])
    meta.append(['IMPORTANT', 'DEVELOPMENT SOFTWARE: review flags, identification and preferences before laboratory use. Export is not validation.'])
    for item in project.source_manifest:
        meta.append(['Source file SHA256 (import snapshot)', f'{item["path"]}: {item["sha256"]}'])
    for event in project.decision_log:
        meta.append(['Recorded decision', json.dumps({k: v for k, v in event.items() if k != 'rows'}, ensure_ascii=False, default=str)])
    for note in project.migration_notes:
        meta.append(['Project migration', note])
    for note in analysis.notes:
        meta.append(['Processing note', note])
    replicates_sheet = wb.create_sheet('Replicate audit')
    replicates_sheet.append(['Sequence', 'Sample', 'Element', 'Analytical channel',
                             'Raw replicate index', 'Raw concentration mg/L', 'Accepted',
                             'Corrected concentration mg/L'])
    for r in analysis.results:
        corrected_lookup = dict(zip(r.kept_indices, r.corrected_replicates_mg_l))
        for idx, raw in enumerate(r.raw_replicates, start=1):
            replicates_sheet.append([r.sequence, r.report_name, r.element, r.channel,
                                     idx, raw, 'Not processed' if 'BLOCKED' in r.flags else ('Yes' if idx in r.kept_indices else 'No'),
                                     corrected_lookup.get(idx)])
    for sheet in wb.worksheets:
        sheet.freeze_panes = 'A2'
        sheet.auto_filter.ref = sheet.dimensions if sheet != meta else None
        sheet.row_dimensions[1].height = 27
        for c in sheet[1]:
            _style_header(c)
            c.alignment = Alignment(vertical='center', wrap_text=True)
        for column in sheet.columns:
            letter = get_column_letter(column[0].column)
            lengths = [len(str(cell.value or '')) for cell in list(column)[:150]]
            sheet.column_dimensions[letter].width = min(max(13, max(lengths, default=10) + 2), 45)
        if sheet.title not in ('Results', 'Sample matrix'):        # those carry the result colours instead
            for i in range(2, sheet.max_row + 1):
                if i % 2 == 0:
                    for cell in sheet[i]:
                        cell.fill = PatternFill('solid', fgColor='F1F5F9')
        if sheet.title == 'QC and calculation trail':
            status_col = 21
            for row_idx in range(2, sheet.max_row + 1):
                status = str(sheet.cell(row_idx, status_col).value or '')
                if core.result_category(status.split(' + ')) in ('attention', 'blocked'):
                    sheet.cell(row_idx, status_col).font = Font(bold=True, color='9A3412')
    _literal_strings(wb)
    wb.save(path)


def write_results_csv(analysis, path):
    with open(path, 'x', encoding='utf-8-sig', newline='') as fh:
        writer = csv.writer(fh)
        writer.writerow(['Sample', 'Element', 'Wavelength / view', 'Result', 'SD', 'Units', 'Status', 'Category'])
        for r in analysis.results:
            writer.writerow([_csv_safe(r.report_name), r.element, r.channel, r.reported, r.sd_display, r.units,
                             r.status, r.category])


def _clean(item):
    if isinstance(item, float) and not math.isfinite(item):
        return None
    if isinstance(item, dict):
        return {str(k): _clean(v) for k, v in item.items()}
    if isinstance(item, (list, tuple)):
        return [_clean(v) for v in item]
    return item


def write_audit(project, analysis, path, prep_status=None):
    audit = {
        'app': APP_NAME, 'version': APP_VERSION, 'citation': APP_CITATION_TEXT, 'generated_utc': datetime.now(timezone.utc).isoformat(),
        'demo': project.demo,
        'automatic_run': project.automatic_run,
        'method_recognition': project.method_recognition,
        'method_notes': project.method_notes,
        'standards_recognition': project.standards_recognition,
        'source_comparison': project.source_comparison,
        'preparation_status': prep_status,
        'decision_log': project.decision_log,
        'migration_notes': project.migration_notes,
        'settings': asdict(project.settings),
        'sources': project.source_manifest,
        'assignments': [asdict(a) for a in sorted(project.assignments.values(), key=lambda a: a.sequence)],
        'method': [asdict(s) for s in sorted(project.channels.values(), key=lambda s: s.channel)],
        'input_record_count': len(project.readings),
        'input_notes': [{'sequence': r.sequence, 'channel': r.channel, 'notes': r.import_notes,
                         'summary_source': os.path.basename(r.summary_source)} for r in project.readings if r.import_notes],
        'selected_channels': analysis.selected_channels, 'channel_scores': analysis.channel_scores,
        'warnings': analysis.notes, 'standard_checks': getattr(analysis, 'standard_checks', []),
        'results': [asdict(r) for r in analysis.results],
        'category_counts': {k: sum(r.category == k for r in analysis.results) for k in CATEGORY_LABELS},
    }
    with open(path, 'x', encoding='utf-8') as fh:
        json.dump(_clean(audit), fh, indent=2, allow_nan=False, ensure_ascii=False)


def export_analysis(project, analysis, output_folder, extra_files=False) -> Dict[str, str]:
    """Write the outputs into a new, uniquely named folder (one folder, five files). Returns their paths.

    Keys: 'Folder', 'ICP results - review', 'ICP results - report', 'Detailed explanations' (Word), 'Detailed calculations' (= 'Excel'),
    'Project' (= 'Session'). With extra_files=True also 'CSV' (Results.csv) and 'Audit JSON' (Audit.json).
    """
    try:
        import openpyxl  # noqa: F401
    except ImportError as exc:
        raise RuntimeError('Excel export requires openpyxl.') from exc
    pass
    pass
    pass
    prep = preparation_status(project)
    ident = identification_summary(project)
    folder = unique_output_folder(output_folder, core.run_name(project.settings))
    paths = {'Folder': str(folder), 'ICP results - review': str(folder / 'ICP results - review.xlsx'),
             'ICP results - report': str(folder / 'ICP results - report.xlsx'),
             'Detailed explanations': str(folder / CALC_DOCX_NAME),
             'Detailed calculations': str(folder / 'Detailed calculations.xlsx'),
             'Project': str(folder / 'Project.plasmati.json')}
    if extra_files:
        paths.update({'CSV': str(folder / 'Results.csv'), 'Audit JSON': str(folder / 'Audit.json')})
    paths['Excel'] = paths['Detailed calculations']         # older name, kept for scripts
    paths['Session'] = paths['Project']
    paths['ICP results'] = paths['ICP results - review']                     # older names, kept for scripts
    paths['ICP results (black and white)'] = paths['ICP results - report']
    write_researcher_workbook(project, analysis, paths['ICP results - review'], prep, ident)
    write_researcher_workbook(project, analysis, paths['ICP results - report'], prep, ident, colour=False)
    write_calculation_docx(project, analysis, paths['Detailed explanations'])
    write_detailed_workbook(project, analysis, paths['Detailed calculations'], prep, ident)
    save_project(project, paths['Project'])
    if extra_files:
        write_results_csv(analysis, paths['CSV'])
        write_audit(project, analysis, paths['Audit JSON'], prep)
    return paths


# --------------------------------------------------------------------------
# Calculations explained: every result written out as equations. The plain text is the
# independent recalculation (used by the tests and as the worked examples); the export
# writes it as a Word report (write_calculation_docx, below).
# --------------------------------------------------------------------------

CALC_TEXT_NAME = 'Calculations explained.txt'


def _n(x, digits=6):
    """A number for the text: up to `digits` significant figures, no exponent for normal sizes."""
    if x is None:
        return '-'
    if not math.isfinite(x):
        return 'infinite' if x > 0 else '-infinite'
    if x == 0:
        return '0'
    text = f'{x:.{digits}g}'
    if 'e' in text:
        mag = abs(x)
        text = f'{x:.{max(0, digits - 1 - int(math.floor(math.log10(mag))))}f}' if 1e-9 < mag < 1e12 else text
    return text


def _lab_rule_steps(values, initial_rsd, rsd_limit):
    """Replay of the laboratory replicate rule (same rule as plasmati_core.filter_replicates)."""
    steps = []
    keep = list(range(len(values)))
    current = initial_rsd
    for _ in range(min(2, max(0, len(values) - 3))):
        if current <= rsd_limit:
            break
        avg = core.mean(values[i] for i in keep)
        furthest = max(keep, key=lambda i: (abs(values[i] - avg), i))
        keep.remove(furthest)
        current = core.percent_rsd([values[i] for i in keep])
        steps.append((furthest + 1, avg, current))
    return steps, [i + 1 for i in keep]


def _standard_blank_for(project, standard_seq, first, last):
    """The standard blank the program subtracts from a standard (same rule as the engine)."""
    side_before = standard_seq < first
    blanks = [b for b in project.assignments.values() if b.role in ('Standard blank', 'Both blanks')
              and b.sequence < standard_seq and (b.sequence < first if side_before else b.sequence > last)]
    return max(blanks, key=lambda b: b.sequence) if blanks else None


def _rules_text(w, st, solid, dry, unit):
    model, rule = st.correction_model, st.replicate_rule
    w('SYMBOLS AND RULES (settings of this run)')
    w('-' * 100)
    w('  i          measurement number (the instrument sequence number) of the sample')
    w('  x_1..x_n   the replicate concentrations exported by the instrument (mg/L in the measured solution)')
    w('  x̄, s       mean and standard deviation (n - 1) of the replicates; RSD = 100 × s / x̄ (%)')
    if not st.auto_filter:
        w('  Replicates: removal is switched OFF for this run; all replicates are kept.')
    elif rule == 'dixon':
        w("  Replicates: Dixon's Q test at 95 % on the most extreme replicate (the smallest or the largest):")
        w('             Q = |suspect - nearest replicate| / (largest - smallest); the suspect is removed only if')
        w('             Q > Q_crit (3 replicates 0.970, 4: 0.829, 5: 0.710, 6: 0.625, 7: 0.568). One test only.')
        w('             Used only when the result without removal is above the limit; otherwise all replicates are kept.')
    else:
        w(f'  Replicates: RSD rule: while RSD > {_n(st.rsd_limit)} % and more than 3 replicates remain (at most 2 removals),')
        w('             remove the replicate farthest from the current mean.')
    w(f'             RSD above {_n(st.rsd_limit)} % after this step is flagged HIGH_RSD.')
    w('             If nothing is removed, the instrument\'s own mean and SD are used (they have more digits')
    w('             than the exported replicates); otherwise x̄ and s are recalculated from the kept replicates.')
    w('  B(i)       sample blank at measurement i, linear between the sample blanks before (a) and after (b)')
    w('             the samples:  B(i) = B(a) + (i - a)/(b - a) × (B(b) - B(a));   y = x̄ - B(i)')
    w('  S          corrected standard reading = standard reading - the standard blank measured before it')
    w('  S_L(i)     reading of the standard with nominal level L at measurement i (linear between before and after):')
    w('             S_L(i) = S_before + (i - p)/(q - p) × (S_after - S_before),  p, q = standard measurements')
    if model == 'two_point':
        w('  Correction: calibration line through the blank (0), the low (L1) and the high (L2) standard:')
        w('             if y ≤ S_L1(i):  C = y × L1 / S_L1(i)                              (line through zero and L1)')
        w('             if y > S_L1(i):  C = L1 + (y - S_L1(i)) × (L2 - L1) / (S_L2(i) - S_L1(i))   (line through L1 and L2)')
        w('             i.e. y = a × C + b with slope a = (S_L2 - S_L1)/(L2 - L1) and intercept b = S_L1 - a × L1.')
        w('             s is divided by the slope of the line used. When the kept replicates lie on both sides of')
        w('             S_L1(i), each replicate is converted with its own line; C and SD are their mean and SD.')
    elif model == 'single_standard':
        w(f'  Correction: one standard. T = {_n(st.high_standard_boundary_fraction)} × high level. If the raw mean x̄ ≤ T the low')
        w('             standard is used, otherwise the high one (unless the analyst chose). f = S_L(i) / L;  C = y / f.')
    else:
        w(f'  Correction: one standard, asking when unclear. f_L(i) = S_L(i) / L;  C_low = y / f_low;  C_high = y / f_high;')
        w(f'             T = {_n(st.high_standard_boundary_fraction)} × high level. Low if only C_low ≤ T; high if only C_high > T;')
        w('             otherwise the analyst decides.')
    w('  D          additional dilution of the sample')
    if solid:
        w('  m, V       sample mass (g) and final solution volume (mL)' + ('; dry mass m_dry = m × (1 - moisture/100)' if dry else ''))
        w('  Result     = C × V / m × D  (mg/kg)')
    else:
        w('  Result     = C × D  (mg/L)')
    if unit not in ('mg/kg', 'mg/L'):
        factor = core.unit_choices(st.sample_type)[unit]
        w(f'  Unit       results, SD and limits are reported in {unit}: value in {"mg/kg" if solid else "mg/L"} × {_n(factor)}')
    w('  Limit      the limit (LOQ) of the wavelength' + (' × D' if st.dilution_limit_policy == 'scale_with_dilution' else '')
      + ('; for solids the method table mg/kg value' if solid and st.limit_policy == 'lab_stored'
         else '; for solids the mg/L limit × V/m × D' if solid else '') + '.')
    w('             A result below the limit is reported as "<limit" with SD "n/a".')
    w('  Rounding   results below 10: 3 decimals; below 100: 2; below 1000: 1; otherwise 0. SD: one more decimal.')
    w('             The rule is applied in mg/L or mg/kg; in another unit the decimals move with the unit.')
    unit_s = '%' if st.channel_score == 'percent' else 'mg/L'
    expr = '|S - L| / L × 100' if st.channel_score == 'percent' else '|S - L|'
    w(f'  Wavelength choice: score = mean of {expr} over the low and the high standard, before and after')
    w(f'             the samples ({unit_s}; smaller is better). The best preference-1 wavelength is kept unless its')
    w(f'             score is more than {_n(100 * st.relative_preference_tolerance)} % worse than the best preference-2 wavelength.')
    w('  Preference and limits: ' + core.METHOD_SOURCES.get(st.method_source, st.method_source) + '.')
    w('')


def calculation_text(project, analysis):
    """All calculations of the run as plain text. Every number is recomputed here from the
    instrument values and compared with the program's own result; any difference is written
    as a line starting with 'CHECK:' (there should be none)."""
    text, checks, _ = calculation_model(project, analysis)
    return text, checks


def calculation_model(project, analysis):
    """(text, checks, model): the plain-text explanation plus the same numbers in a structure
    (used for the Word report). model = {'elements': [{element, chosen, channels, sentence,
    standards, standard_checks, blanks, limit, results: [(result, text lines, record)]}]}."""
    st = project.settings
    solid = st.sample_type == 'Solid'
    dry = solid and st.reporting_basis == 'dry'
    unit = core.report_unit(st)
    ctx = core.CorrectionContext(project)
    book = ctx.book
    first, last = ctx.first, ctx.last
    names = {a.sequence: a for a in project.assignments.values()}
    out = []
    w = out.append
    checks = []
    model = {'elements': []}

    def check(label, ours, program, rel=1e-7, abs_=1e-9):
        if ours is None or program is None:
            return
        if not math.isclose(ours, program, rel_tol=rel, abs_tol=abs_):
            line = f'CHECK: {label} recomputed here as {ours!r}, the program has {program!r}.'
            checks.append(line)
            w('    ' + line)

    def flag(line):
        checks.append(line)
        w('    ' + line)

    rule = '=' * 100
    w(f'{core.APP_NAME} - CALCULATIONS EXPLAINED')
    w(rule)
    w(f'Run:            {st.project or "(no name)"}')
    w(f'Method:         {st.method if st.method and st.method != core.MASTER_NAME else "(not named)"}')
    w(f'Sample type:    {st.sample_type}' + (f' (reporting basis: {"dry mass" if dry else "as weighed"})' if solid else ''))
    w(f'Unit:           {unit}')
    w(f'Generated:      {datetime.now(timezone.utc).isoformat(timespec="seconds")} (UTC)')
    w(f'Files:          ' + '; '.join(Path(p).name for p in project.source_paths))
    w('')
    w('Every result below is written out with the numbers that were used. Concentrations are in mg/L of the')
    w('measured solution unless stated. Numbers are shown with up to 6 significant figures; the program')
    w('calculates with full precision, so the last digit of a hand calculation can differ slightly.')
    w('')
    _rules_text(w, st, solid, dry, unit)

    by_element = defaultdict(list)
    for r in analysis.results:
        by_element[r.element].append(r)
    for element in sorted(by_element):
        results = sorted(by_element[element], key=lambda r: r.sequence)
        chosen = analysis.selected_channels.get(element)
        el = {'element': element, 'chosen': chosen, 'channels': [], 'standards': [], 'standard_checks': [],
              'blanks': [], 'limit': '', 'results': [], 'sentence': ''}
        model['elements'].append(el)
        w(rule)
        w(f'ELEMENT {element}')
        w(rule)
        channels = sorted(c for c in project.channels if core.split_channel(c)[0] == element and project.channels[c].enabled)
        w('Wavelength choice')
        for ch in channels:
            cfg = project.channels[ch]
            stds = ctx.standards(element, ch)
            levels = sorted(stds)
            pref = f'preference {cfg.preference_order}' if cfg.preference_order else 'no preference'
            row = {'channel': ch, 'preference': cfg.preference_order, 'terms': [], 'score': None, 'chosen': ch == chosen}
            el['channels'].append(row)
            if len(levels) >= 2 or (levels and analysis.channel_scores.get(ch) is not None):
                terms = [(lvl, v) for lvl in sorted({levels[0], levels[-1]}) for _, v in stds[lvl]]
                row['terms'] = [(lvl, v, 100 * (v - lvl) / lvl, abs(v - lvl)) for lvl, v in terms]
                if st.channel_score == 'percent':
                    score = sum(100 * abs(v - lvl) / lvl for lvl, v in terms) / len(terms)
                    row['score'] = score
                    parts = ' + '.join(f'{100 * abs(v - lvl) / lvl:.2f}' for lvl, v in terms)
                    w(f'  {ch:<24} ({pref}): ({parts})/{len(terms)} = {_n(score, 4)} %' + ('   <- chosen' if ch == chosen else ''))
                else:
                    score = sum(abs(v - lvl) for lvl, v in terms) / len(terms)
                    row['score'] = score
                    w(f'  {ch:<24} ({pref}): (' + ' + '.join(f'|{_n(v)} - {_n(lvl)}|' for lvl, v in terms)
                      + f')/{len(terms)} = {_n(score, 4)}' + ('   <- chosen' if ch == chosen else ''))
                check(f'score of {ch}', score, analysis.channel_scores.get(ch))
            else:
                w(f'  {ch:<24} ({pref}): no complete low and high standard pair, no score'
                  + ('   <- chosen' if ch == chosen else ''))
        el['sentence'] = _choice_sentence(project, analysis, channels, chosen)
        w('  ' + el['sentence'])
        if not chosen:
            continue
        cfg = project.channels[chosen]
        w('')
        stds = ctx.standards(element, chosen)
        w(f'Standards ({chosen}); S = reading - standard blank')
        for lvl in sorted(stds):
            fix = getattr(ctx, 'blank_fixes', {}).get((element, chosen), {})
            for label, (seq, value) in zip(('before', 'after '), stds[lvl]):
                a = names.get(seq)
                b = _standard_blank_for(project, seq, first, last)
                if fix and fix['side'] == label.strip():
                    # this side's own standard blank read as much as a standard; the other side's was used
                    b = project.assignments.get(fix['used_seq'], b)
                try:
                    raw = book[(seq, chosen)].raw_mean
                    braw = book[(b.sequence, chosen)].raw_mean if b else None
                except (KeyError, ValueError):
                    raw = braw = None
                el['standards'].append({'level': lvl, 'when': label.strip(), 'seq': seq, 'name': a.sample_id if a else '',
                                        'raw': raw if braw is not None else None, 'blank_seq': b.sequence if b else None,
                                        'blank': braw, 'S': value, 'pct': 100 * (value - lvl) / lvl})
                if raw is not None and braw is not None:
                    w(f'  {_n(lvl)} mg/L {label}: measurement {seq} "{a.sample_id if a else ""}" {_n(raw)} - standard blank '
                      f'(measurement {b.sequence}) {_n(braw)} = {_n(value)}   ({100 * (value - lvl) / lvl:+.1f} % of nominal)')
                    check(f'{element} {_n(lvl)} mg/L standard {label.strip()}', raw - braw, value)
                else:
                    w(f'  {_n(lvl)} mg/L {label}: measurement {seq}: S = {_n(value)}')
        for c in getattr(analysis, 'standard_checks', None) or []:
            if c['element'] == element:
                el['standard_checks'].append(core.standard_check_text(c))
                w('  Standard check: ' + core.standard_check_text(c))
        sb = sorted(a.sequence for a in project.assignments.values() if a.role in ('Sample blank', 'Both blanks'))
        if sb:
            vals = []
            for s in sb:
                try:
                    vals.append(f'measurement {s} = {_n(book[(s, chosen)].raw_mean)}')
                    el['blanks'].append((s, book[(s, chosen)].raw_mean))
                except (KeyError, ValueError):
                    vals.append(f'measurement {s} = no value')
                    el['blanks'].append((s, None))
            w('Sample blanks: ' + '; '.join(vals))
        el['limit'] = (f'{cfg.limit_kind or "DL"} {_n(cfg.dl_mg_l)} mg/L' + (f', {_n(cfg.dl_mg_kg)} mg/kg' if cfg.dl_mg_kg is not None else '')
                       + (f'  ({cfg.limit_source})' if cfg.limit_source else ''))
        w('Limit: ' + el['limit'])
        w('')
        for r in results:
            start, rec = len(out), {}
            _explain_result(w, check, flag, project, analysis, ctx, r, cfg, solid, dry, unit, rec)
            el['results'].append((r, out[start:], rec))
    w(rule)
    w(f'{len(analysis.results)} results written out. Recomputation differences (CHECK lines): {len(checks)}.')
    w('How to cite Plasmatti: ' + core.APP_CITATION_TEXT)
    return '\n'.join(out) + '\n', checks, model


def _choice_sentence(project, analysis, channels, chosen):
    """Why this wavelength was used (the same rule as plasmati_core.choose_channels)."""
    sc = analysis.channel_scores
    tol = project.settings.relative_preference_tolerance
    u = ' %' if project.settings.channel_score == 'percent' else ''
    if chosen and project.channels[chosen].manual_select:
        return f'Used: {chosen}, chosen by the analyst.'
    usable = [c for c in channels if sc.get(c) is not None]
    one = [c for c in usable if project.channels[c].preference_order == 1]
    two = [c for c in usable if project.channels[c].preference_order == 2]
    if not usable:
        return f'Used: {chosen} (no wavelength has complete standards; its results cannot be calculated).'
    expected = (min(one, key=lambda c: (sc[c], c)) if one and not two else
                min(usable, key=lambda c: (sc[c], c)) if not one else None)
    if one and two:
        b1, b2 = min(one, key=lambda c: (sc[c], c)), min(two, key=lambda c: (sc[c], c))
        expected = b1 if sc[b1] <= sc[b2] * (1 + tol) + 1e-12 else b2
    if expected != chosen:
        return f'Used: {chosen}. CHECK: the rule written here would give {expected}.'
    if one and two:
        limit = sc[b2] * (1 + tol)
        if sc[b1] <= limit + 1e-12:
            return (f'Best preference 1: {b1} ({_n(sc[b1], 4)}{u}); best preference 2: {b2} ({_n(sc[b2], 4)}{u}). '
                    f'{_n(sc[b1], 4)} ≤ {_n(1 + tol)} × {_n(sc[b2], 4)} = {_n(limit, 4)}, so preference 1 is kept. Used: {chosen}')
        return (f'Best preference 1: {b1} ({_n(sc[b1], 4)}{u}); best preference 2: {b2} ({_n(sc[b2], 4)}{u}). '
                f'{_n(sc[b1], 4)} > {_n(1 + tol)} × {_n(sc[b2], 4)} = {_n(limit, 4)}, so preference 2 is used. Used: {chosen}')
    if one:
        return f'Only preference-1 wavelengths have complete standards; the best one is used: {chosen}'
    return f'No preference-1 wavelength has complete standards; the lowest score is used: {chosen}'


def _explain_result(w, check, flag, project, analysis, ctx, r, cfg, solid, dry, unit, rec=None):
    rec = {} if rec is None else rec
    st = project.settings
    a = project.assignments[r.sequence]
    book = ctx.book
    head = f'{r.element}, {r.report_name} (measurement {r.sequence}'
    if r.sample_id != r.report_name:
        head += f', instrument name "{r.sample_id}"'
    w(head + f') - {r.channel}')
    reading = book.get((r.sequence, r.channel))
    if reading is None:
        rec['stop'] = 'Not measured at this wavelength'
        w('  Not calculated: this wavelength was not measured for this sample.')
        w('')
        return
    if reading.instrument_error:
        rec['stop'] = f'No value in the instrument file ({reading.instrument_error})'
        w(f'  Not calculated: the instrument file has no value ({reading.instrument_error}).')
        w('')
        return
    values = list(reading.replicates)
    summary = st.statistics_basis == 'instrument_when_unfiltered'
    removed_idx = []
    rec['values'] = values
    if values:
        w(f'  Replicates (mg/L): {", ".join(_n(v) for v in values)}')
        initial = reading.instrument_rsd if summary and reading.instrument_rsd is not None else core.percent_rsd(values)
        w(f'  RSD = {_n(initial, 4)} %' + (' (instrument value)' if summary and reading.instrument_rsd is not None else ''))
        if not st.auto_filter:
            w('    Replicate removal is switched off: all replicates kept.')
        elif st.replicate_rule == 'dixon' and len(values) < 4:
            w(f'    Dixon test not used with {len(values)} replicates: at least 3 are always kept; all kept.')
            rec['test'] = 'none (3 replicates)'
        elif st.replicate_rule == 'dixon':
            idx, q, crit, side = core.dixon_test(values)
            if q is None:
                w(f'    Dixon test not possible with {len(values)} replicates; all kept.')
            else:
                order = sorted(values)
                if side == 'largest':
                    w(f'    Dixon: suspect = largest {_n(order[-1])}; Q = ({_n(order[-1])} - {_n(order[-2])}) / ({_n(order[-1])} - {_n(order[0])})'
                      f' = {q:.3f}')
                elif side == 'smallest':
                    w(f'    Dixon: suspect = smallest {_n(order[0])}; Q = ({_n(order[1])} - {_n(order[0])}) / ({_n(order[-1])} - {_n(order[0])})'
                      f' = {q:.3f}')
                else:
                    w('    Dixon: all replicates equal; Q = 0.')
                rec['test'] = f'Q {q:.3f} ' + ('≤' if idx is None else '>') + f' {crit:.3f}'
                if idx is None:
                    w(f'    Q = {q:.3f} ≤ Q_crit {crit:.3f} ({len(values)} replicates): no outlier, all replicates kept.')
                elif any('Dixon' in n and 'not applied' in n for n in r.notes):
                    rec['test'] += ' (below limit)'
                    w(f'    Q = {q:.3f} > Q_crit {crit:.3f}, but the result without removal is below the limit: all replicates kept.')
                else:
                    w(f'    Q = {q:.3f} > Q_crit {crit:.3f}: replicate {idx + 1} ({_n(values[idx])}) is an outlier and is removed.')
                    removed_idx = [idx]
        else:
            steps, kept = _lab_rule_steps(values, initial, st.rsd_limit)
            for i, avg, rsd in steps:
                w(f'    RSD > {_n(st.rsd_limit)} %: replicate {i} ({_n(values[i - 1])}) is farthest from the mean {_n(avg)}; '
                  f'removed. New RSD = {_n(rsd, 4)} %')
            if not steps:
                w('    ' + ('All replicates kept.' if initial <= st.rsd_limit else
                         'No removal possible (3 replicates or the limit of 2 removals).'))
            removed_idx = [i - 1 for i, _, _ in steps]
            rec['test'] = f'RSD rule: {len(steps)} removed' if steps else 'RSD rule: none removed'
        rec['removed'] = [i + 1 for i in removed_idx]
        kept_ids = [i + 1 for i in range(len(values)) if i not in removed_idx]
        if r.category != 'blocked' and kept_ids != list(r.kept_indices):
            flag(f'CHECK: kept replicates here {kept_ids}, the program kept {list(r.kept_indices)}.')
        if removed_idx:
            kv = [values[i - 1] for i in kept_ids]
            xbar, s = core.mean(kv), (core.stdev(kv) if len(kv) > 1 else reading.raw_sd)
            w(f'  x̄ = ({" + ".join(_n(v) for v in kv)})/{len(kv)} = {_n(xbar)} mg/L;  s = {_n(s)} mg/L;  '
              f'RSD = {_n(core.percent_rsd(kv), 4)} %')
        else:
            xbar, s = reading.raw_mean, reading.raw_sd
            if summary and reading.instrument_mean is not None:
                w(f'  x̄ = {_n(xbar)} mg/L, s = {_n(s)} mg/L (the instrument\'s mean and SD of all replicates)')
            else:
                w(f'  x̄ = {_n(xbar)} mg/L, s = {_n(s)} mg/L')
        if 'HIGH_RSD' in r.flags:
            w(f'  Note: the final RSD is above {_n(st.rsd_limit)} % (flag HIGH_RSD).')
    else:
        xbar, s = reading.raw_mean, reading.raw_sd
        w(f'  No replicates exported; instrument mean x̄ = {_n(xbar)} mg/L, SD = {_n(s)} mg/L (no replicate rule possible).')
    rec['xbar'], rec['s'] = xbar, s
    if not removed_idx:
        check(f'{r.element} {r.report_name} mean', xbar, r.original_mean)
    if r.category == 'blocked' and not any('BOUNDARY_REVIEW' in n for n in r.notes):
        rec['stop'] = r.notes[-1] if r.notes else 'Not calculated'
        w('  Not calculated: ' + (r.notes[-1] if r.notes else 'see the notes in Detailed calculations.xlsx'))
        w('')
        return
    try:
        b0, b1 = core._bracket_samples(project.assignments, r.sequence, ('Sample blank', 'Both blanks'))
        B0, B1 = book[(b0, r.channel)].raw_mean, book[(b1, r.channel)].raw_mean
    except (KeyError, ValueError) as exc:
        rec['stop'] = str(exc)
        w(f'  Not calculated: {exc}')
        w('')
        return
    B = core.interpolate(r.sequence, b0, B0, b1, B1)
    y = xbar - B
    rec['B'], rec['y'] = B, y
    w(f'  B({r.sequence}) = {_n(B0)} + ({r.sequence} - {b0})/({b1} - {b0}) × ({_n(B1)} - {_n(B0)}) = {_n(B)} mg/L')
    w(f'  y = x̄ - B = {_n(xbar)} - {_n(B)} = {_n(y)} mg/L')
    if r.blank is not None:
        check(f'{r.element} {r.report_name} blank', B, r.blank)
    stds = ctx.standards(r.element, r.channel)
    levels = sorted(stds)
    low, high = levels[0], levels[-1]
    S = {}
    for lvl in (low, high):
        (p, sp), (q, sq) = stds[lvl]
        S[lvl] = core.interpolate(r.sequence, p, sp, q, sq)
        w(f'  S_{_n(lvl)}({r.sequence}) = {_n(sp)} + ({r.sequence} - {p})/({q} - {p}) × ({_n(sq)} - {_n(sp)}) = {_n(S[lvl])}')
    model = st.correction_model
    s_override = None
    if low == high:
        # Only the low standard is usable: line through zero and that standard (extended above it).
        local = S[low] / low
        C = y / local
        rec['segment'] = f'{_n(low)} std only'
        w(f'  Only the {_n(low)} mg/L standard is usable (the higher standard has no usable value):')
        w(f'  C = y × {_n(low)} / S_{_n(low)} = {_n(y)} × {_n(low)} / {_n(S[low])} = {_n(C)} mg/L'
          + ('   (above the standard: extrapolated)' if y > S[low] else ''))
        check(f'{r.element} {r.report_name} slope', local, r.cal_slope)
    elif model == 'two_point':
        slope = (S[high] - S[low]) / (high - low)
        intercept = S[low] - slope * low
        if y <= S[low]:
            C = y * low / S[low]
            local = S[low] / low
            rec['segment'] = f'0 to {_n(low)}'
            w(f'  y ≤ S_{_n(low)}: line through zero and the low standard:  C = {_n(y)} × {_n(low)} / {_n(S[low])} = {_n(C)} mg/L')
        else:
            C = low + (y - S[low]) / slope
            local = slope
            rec['segment'] = f'{_n(low)} to {_n(high)}'
            w(f'  y > S_{_n(low)}: line through both standards, slope a = ({_n(S[high])} - {_n(S[low])}) / ({_n(high)} - {_n(low)}) = {_n(slope)}')
            w(f'  C = {_n(low)} + ({_n(y)} - {_n(S[low])}) / {_n(slope)} = {_n(C)} mg/L   (intercept b = {_n(intercept)} mg/L)')
        check(f'{r.element} {r.report_name} slope', local, r.cal_slope)
        kv = [values[i] for i in range(len(values)) if i not in removed_idx]
        ys = [v - B for v in kv]
        if core.straddles_low_standard(ys, S[low]):
            def conc(v):
                return v * low / S[low] if v <= S[low] else low + (v - S[low]) / slope
            cs = [conc(v) for v in ys]
            C, s_override = core.mean(cs), core.stdev(cs)
            rec['segment'] = 'both lines'
            w(f'  The kept replicates lie on both sides of S_{_n(low)} = {_n(S[low])}, so each replicate is converted with its own line:')
            w(f'  C_i = {", ".join(_n(c) for c in cs)} mg/L;  C = mean = {_n(C)} mg/L;  SD = {_n(s_override)} mg/L')
    else:
        f = {lvl: S[lvl] / lvl for lvl in (low, high)}
        T = st.high_standard_boundary_fraction * high
        override = a.standard_overrides.get(r.element, '')
        c_low, c_high = y / f[low], y / f[high]
        w(f'  f_{_n(low)} = {_n(S[low])} / {_n(low)} = {_n(f[low])};   f_{_n(high)} = {_n(S[high])} / {_n(high)} = {_n(f[high])}')
        if model == 'single_standard':
            if override in ('low', 'high'):
                level = low if override == 'low' else high
                w(f'  The analyst chose the {override} standard.')
            else:
                level = low if xbar <= T else high
                w(f'  Raw mean x̄ = {_n(xbar)} ' + ('≤' if xbar <= T else '>') + f' T = {_n(T)}  ->  the {"low" if level == low else "high"} standard is used.')
        else:
            w(f'  C_low  = {_n(y)} / {_n(f[low])} = {_n(c_low)} mg/L   ' + ('≤' if c_low <= T else '>') + f' T = {_n(T)}')
            w(f'  C_high = {_n(y)} / {_n(f[high])} = {_n(c_high)} mg/L   ' + ('>' if c_high > T else '≤') + f' T = {_n(T)}')
            check(f'{r.element} {r.report_name} C_low', c_low, r.low_candidate_mg_l)
            check(f'{r.element} {r.report_name} C_high', c_high, r.high_candidate_mg_l)
            if r.category == 'blocked':
                rec['stop'] = 'Analyst must choose the low or the high standard'
                w('  Both or neither fit: NOT CALCULATED until the analyst chooses the low or the high standard on the Results page.')
                w('')
                return
            lo_ok, hi_ok = c_low <= T, c_high > T
            if override in ('low', 'high'):
                level = low if override == 'low' else high
                w(f'  The analyst chose the {override} standard.')
            elif lo_ok != hi_ok:
                level = low if lo_ok else high
            else:
                level = low if lo_ok else (low if y <= T else high)
        local = f[level]
        C = y / local
        rec['segment'] = f'{_n(level)} std'
        w(f'  C = {_n(y)} / {_n(local)} = {_n(C)} mg/L   (the {_n(level)} mg/L standard)')
        check(f'{r.element} {r.report_name} standard level', level, r.standard_level)
    check(f'{r.element} {r.report_name} concentration', C, r.corrected_mean_mg_l)
    top = high
    if C > top:
        w(f'  Note: {_n(C)} mg/L is above the highest standard ({_n(top)} mg/L): extrapolated; dilute and measure again.')
    sd_c = s_override if s_override is not None else (s / abs(local) if s is not None else None)
    D = a.dilution
    rec['C'], rec['D'], rec['above'] = C, D, C > top
    uf = core.unit_choices(st.sample_type)[unit]
    if solid:
        m = a.mass_g
        if dry:
            m_used = m * (1 - a.moisture_pct / 100)
            w(f'  m_dry = {_n(m)} × (1 - {_n(a.moisture_pct)}/100) = {_n(m_used)} g')
        else:
            m_used = m
        mult = D * a.volume_ml / m_used
        base = C * mult
        w(f'  Result = {_n(C)} × {_n(a.volume_ml)} mL / {_n(m_used)} g × {_n(D)} = {_n(base)} mg/kg')
        factor_text = f' × {_n(a.volume_ml)} / {_n(m_used)} × {_n(D)}'
    else:
        mult = D
        base = C * mult
        w(f'  Result = {_n(C)} × {_n(D)} = {_n(base)} mg/L')
        factor_text = f' × {_n(D)}' if D != 1 else ''
    sd_base = sd_c * mult if sd_c is not None else None
    if sd_base is not None:
        first_sd = _n(s_override) if s_override is not None else f'{_n(s)} / {_n(local)}'
        tail = '' if (s_override is not None and not factor_text) else factor_text + f' = {_n(sd_base)}'
        w(f'  SD     = {first_sd}' + tail + f' {"mg/kg" if solid else "mg/L"}')
    value, sdv = base * uf, (sd_base * uf if sd_base is not None else None)
    rec['value'], rec['sd'] = value, sdv
    if sdv is not None and r.report_sd is not None:
        check(f'{r.element} {r.report_name} SD', sdv, r.report_sd)
    if solid:
        rec['m'], rec['V'] = m_used, a.volume_ml
    if uf != 1.0:
        w(f'  In {unit}: {_n(base)} × {_n(uf)} = {_n(value)} {unit}' + (f';  SD {_n(sdv)} {unit}' if sdv is not None else ''))
    check(f'{r.element} {r.report_name} result', value, r.report_value)
    if r.dl is None:
        w(f'  No limit for this wavelength. Reported: {r.reported} {r.units}')
    else:
        if solid and st.limit_policy == 'lab_stored':
            how = (f'(method table {_n(cfg.dl_mg_kg)} mg/kg'
                   + (f' × D {_n(D)}' if st.dilution_limit_policy == 'scale_with_dilution' and D != 1 else '')
                   + (f' × {_n(uf)}' if uf != 1 else '') + ')')
        elif solid:
            how = f'({_n(cfg.dl_mg_l)} mg/L × V/m × D' + (f' × {_n(uf)}' if uf != 1 else '') + ')'
        elif (st.dilution_limit_policy == 'scale_with_dilution' and D != 1) or uf != 1:
            how = (f'({_n(cfg.dl_mg_l)} mg/L' + (f' × D {_n(D)}' if st.dilution_limit_policy == 'scale_with_dilution' and D != 1 else '')
                   + (f' × {_n(uf)}' if uf != 1 else '') + ')')
        else:
            how = ''
        below = value < r.dl
        w(f'  Limit {_n(r.dl)} {r.units} {how}'.rstrip() + f':  {_n(value)} ' + ('<' if below else '≥') + f' {_n(r.dl)}'
          + f'  ->  reported {r.reported}' + ('' if below else f' ± {r.sd_display}') + f' {r.units}')
        if not below:
            expected = core.format_report(value, uf=uf)
            if expected != r.reported:
                flag(f'CHECK: rounding here gives {expected}, the program reported {r.reported}.')
    if solid and r.solution_reported:
        w(f'  Digest solution (mg/L block): {_n(C)} × {_n(D)} = {_n(C * D)} mg/L -> reported {r.solution_reported}')
    w('')


def write_calculation_text(project, analysis, path):
    text, checks = calculation_text(project, analysis)
    Path(path).write_text(text, encoding='utf-8')
    return checks


# --------------------------------------------------------------------------
# Calculations explained as a Word file (.docx, written with the standard library)
# --------------------------------------------------------------------------

CALC_DOCX_NAME = 'Detailed explanations.docx'

_DX_W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
_DX_M = 'http://schemas.openxmlformats.org/officeDocument/2006/math'
_DX_R = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
_DX_PAGE_W, _DX_PAGE_H, _DX_MARGIN = 16838, 11906, 720      # A4 landscape, 1.27 cm margins (twips)
_DX_TEXT_W = _DX_PAGE_W - 2 * _DX_MARGIN
_DX_HEAD_FILL, _DX_ATTENTION, _DX_BLOCKED, _DX_CHOSEN = '20334B', 'FCE4D6', 'E7E6E6', 'E2EFDA'


def _dx_esc(text):
    text = '' if text is None else str(text)
    text = re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f]', '', text)
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')


class _DxRaw(str):
    """Ready-made run XML (a plain str is escaped and wrapped in a run)."""


def _dx_run(text, bold=False, italic=False, strike=False, color=None, size=None, font=None, vert=None):
    props = []
    if font:
        props.append(f'<w:rFonts w:ascii="{font}" w:hAnsi="{font}" w:cs="{font}"/>')
    if bold:
        props.append('<w:b/>')
    if italic:
        props.append('<w:i/>')
    if strike:
        props.append('<w:strike/>')
    if color:
        props.append(f'<w:color w:val="{color}"/>')
    if size:
        props.append(f'<w:sz w:val="{size}"/><w:szCs w:val="{size}"/>')
    if vert:
        props.append(f'<w:vertAlign w:val="{vert}"/>')
    rpr = f'<w:rPr>{"".join(props)}</w:rPr>' if props else ''
    return _DxRaw(f'<w:r>{rpr}<w:t xml:space="preserve">{_dx_esc(text)}</w:t></w:r>')


def _dx_runs(content):
    if content is None:
        return ''
    if isinstance(content, _DxRaw):
        return str(content)
    if isinstance(content, (list, tuple)):
        return ''.join(_dx_runs(c) for c in content)
    return str(_dx_run(content))


def _dx_link(anchor, text):
    return _DxRaw(f'<w:hyperlink w:anchor="{anchor}" w:history="1"><w:r><w:rPr><w:rStyle w:val="Hyperlink"/></w:rPr>'
                  f'<w:t xml:space="preserve">{_dx_esc(text)}</w:t></w:r></w:hyperlink>')


class _DxDoc:
    def __init__(self):
        self.body = []
        self._bookmark = 0

    def bookmark(self, name, content):
        self._bookmark += 1
        i = self._bookmark
        return _DxRaw(f'<w:bookmarkStart w:id="{i}" w:name="{name}"/>{_dx_runs(content)}<w:bookmarkEnd w:id="{i}"/>')

    def para(self, content='', style=None, align=None, page_break=False, keep_next=False, indent=None, after=None):
        ppr = []
        if style:
            ppr.append(f'<w:pStyle w:val="{style}"/>')
        if keep_next:
            ppr.append('<w:keepNext/>')
        if page_break:
            ppr.append('<w:pageBreakBefore/>')
        if after is not None:
            ppr.append(f'<w:spacing w:after="{after}"/>')
        if indent:
            ppr.append(f'<w:ind w:left="{indent}"/>')
        if align:
            ppr.append(f'<w:jc w:val="{align}"/>')
        p = f'<w:pPr>{"".join(ppr)}</w:pPr>' if ppr else ''
        self.body.append(f'<w:p>{p}{_dx_runs(content)}</w:p>')

    def heading(self, level, text, anchor=None, page_break=False):
        content = self.bookmark(anchor, text) if anchor else text
        self.para(content, style=f'Heading{level}', page_break=page_break, keep_next=True)

    def lead(self, text):
        """A sentence that introduces the equation below it (kept on the same page)."""
        self.para(text, keep_next=True)

    def math(self, omml, note=None):
        """One or more equations (a list is written side by side) and an optional note."""
        parts = omml if isinstance(omml, (list, tuple)) else [omml]
        gap = '<w:r><w:t xml:space="preserve">          </w:t></w:r>'
        eqs = gap.join(f'<m:oMath>{o}</m:oMath>' for o in parts)
        extra = _dx_runs(['        ', _dx_run(note, italic=True, color='595959')]) if note else ''
        self.body.append(f'<w:p><w:pPr><w:pStyle w:val="Formula"/></w:pPr>{eqs}{extra}</w:p>')

    def table(self, rows, widths, header=1, size=16, fills=None, align=None):
        """rows: list of lists of cell content; fills: {row index: hex}; align: per column 'left'/'right'/'center'."""
        grid = ''.join(f'<w:gridCol w:w="{w}"/>' for w in widths)
        border = 'w:val="single" w:sz="4" w:space="0" w:color="BFBFBF"'
        out = [f'<w:tbl><w:tblPr><w:tblW w:w="{sum(widths)}" w:type="dxa"/>'
               f'<w:tblBorders><w:top {border}/><w:left {border}/><w:bottom {border}/><w:right {border}/>'
               f'<w:insideH {border}/><w:insideV {border}/></w:tblBorders><w:tblLayout w:type="fixed"/>'
               '<w:tblCellMar><w:top w:w="15" w:type="dxa"/><w:left w:w="60" w:type="dxa"/>'
               '<w:bottom w:w="15" w:type="dxa"/><w:right w:w="60" w:type="dxa"/></w:tblCellMar></w:tblPr>'
               f'<w:tblGrid>{grid}</w:tblGrid>']
        for ri, row in enumerate(rows):
            head = ri < header
            trpr = '<w:trPr><w:cantSplit/>' + ('<w:tblHeader/>' if head else '') + '</w:trPr>'
            cells = []
            for ci, (cell, w) in enumerate(zip(row, widths)):
                fill = _DX_HEAD_FILL if head else (fills or {}).get(ri)
                shd = f'<w:shd w:val="clear" w:color="auto" w:fill="{fill}"/>' if fill else ''
                jc = (align[ci] if align and not head else 'left')
                if head:
                    runs = _dx_run(cell, bold=True, color='FFFFFF', size=size) if isinstance(cell, str) and not isinstance(cell, _DxRaw) else _dx_runs(cell)
                else:
                    runs = str(_dx_run(cell, size=size)) if isinstance(cell, str) and not isinstance(cell, _DxRaw) else _dx_runs(cell)
                cells.append(f'<w:tc><w:tcPr><w:tcW w:w="{w}" w:type="dxa"/>{shd}</w:tcPr>'
                             f'<w:p><w:pPr><w:spacing w:before="0" w:after="0"/><w:jc w:val="{jc}"/></w:pPr>{runs}</w:p></w:tc>')
            out.append(f'<w:tr>{trpr}{"".join(cells)}</w:tr>')
        out.append('</w:tbl>')
        self.body.append(''.join(out))
        self.para('', after=60)

    def save(self, path, title, footer_text):
        import zipfile
        sect = (f'<w:sectPr><w:footerReference w:type="default" r:id="rIdFooter"/>'
                f'<w:pgSz w:w="{_DX_PAGE_W}" w:h="{_DX_PAGE_H}" w:orient="landscape"/>'
                f'<w:pgMar w:top="{_DX_MARGIN}" w:right="{_DX_MARGIN}" w:bottom="{_DX_MARGIN}" w:left="{_DX_MARGIN}" '
                'w:header="360" w:footer="360" w:gutter="0"/></w:sectPr>')
        document = (f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
                    f'<w:document xmlns:w="{_DX_W}" xmlns:m="{_DX_M}" xmlns:r="{_DX_R}"><w:body>'
                    + ''.join(self.body) + sect + '</w:body></w:document>')
        footer = (f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<w:ftr xmlns:w="{_DX_W}" xmlns:r="{_DX_R}">'
                  f'<w:p><w:pPr><w:pStyle w:val="Footer"/></w:pPr>{_dx_runs(footer_text)}'
                  '<w:r><w:t xml:space="preserve">   |   page </w:t></w:r>'
                  '<w:fldSimple w:instr=" PAGE "><w:r><w:t>1</w:t></w:r></w:fldSimple>'
                  '<w:r><w:t xml:space="preserve"> of </w:t></w:r>'
                  '<w:fldSimple w:instr=" NUMPAGES "><w:r><w:t>1</w:t></w:r></w:fldSimple></w:p></w:ftr>')
        now = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        files = {
            '[Content_Types].xml': (
                '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
                '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                '<Default Extension="xml" ContentType="application/xml"/>'
                '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
                '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>'
                '<Override PartName="/word/settings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml"/>'
                '<Override PartName="/word/footer1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/>'
                '<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>'
                '<Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>'
                '</Types>'),
            '_rels/.rels': (
                '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
                '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'
                '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>'
                '<Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/>'
                '</Relationships>'),
            'word/_rels/document.xml.rels': (
                '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
                '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                '<Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
                '<Relationship Id="rIdSettings" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/>'
                '<Relationship Id="rIdFooter" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/>'
                '</Relationships>'),
            'word/document.xml': document,
            'word/styles.xml': _DX_STYLES,
            'word/settings.xml': (f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<w:settings xmlns:w="{_DX_W}" xmlns:m="{_DX_M}">'
                                  '<w:defaultTabStop w:val="720"/><w:characterSpacingControl w:val="doNotCompress"/>'
                                  '<w:compat><w:compatSetting w:name="compatibilityMode" w:uri="http://schemas.microsoft.com/office/word" w:val="15"/></w:compat>'
                                  '<m:mathPr><m:mathFont m:val="Cambria Math"/><m:dispDef/></m:mathPr>'
                                  '</w:settings>'),
            'word/footer1.xml': footer,
            'docProps/core.xml': (
                '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
                '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" '
                'xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" '
                'xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">'
                f'<dc:title>{_dx_esc(title)}</dc:title><dc:creator>{_dx_esc(APP_NAME)}</dc:creator>'
                f'<dcterms:created xsi:type="dcterms:W3CDTF">{now}</dcterms:created>'
                f'<dcterms:modified xsi:type="dcterms:W3CDTF">{now}</dcterms:modified></cp:coreProperties>'),
            'docProps/app.xml': (
                '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
                '<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties">'
                f'<Application>{_dx_esc(APP_NAME)}</Application></Properties>'),
        }
        with zipfile.ZipFile(path, 'w', zipfile.ZIP_DEFLATED) as z:
            for name, data in files.items():
                z.writestr(name, data.encode('utf-8'))


