# --- small OMML (Word equation) builders --------------------------------------------------------

def _mr(text, plain=False):
    sty = '<m:rPr><m:sty m:val="p"/></m:rPr>' if plain else ''
    return f'<m:r>{sty}<m:t xml:space="preserve">{_dx_esc(text)}</m:t></m:r>'


def _mt(text):
    """Upright text inside an equation (numbers, operators); words are written as normal text."""
    if re.search(r'[A-Za-z]{2,}', text):
        return f'<m:r><m:rPr><m:nor/></m:rPr><m:t xml:space="preserve">{_dx_esc(text)}</m:t></m:r>'
    return _mr(text, plain=True)


def _mf(num, den):
    return f'<m:f><m:num>{num}</m:num><m:den>{den}</m:den></m:f>'


def _msub(base, sub):
    return f'<m:sSub><m:e>{base}</m:e><m:sub>{sub}</m:sub></m:sSub>'


def _md(inner, beg='(', end=')'):
    pr = '' if (beg, end) == ('(', ')') else f'<m:dPr><m:begChr m:val="{beg}"/><m:endChr m:val="{end}"/></m:dPr>'
    return f'<m:d>{pr}<m:e>{inner}</m:e></m:d>'


def _mv(name, sub=None):
    return _msub(_mr(name), _mt(sub) if sub and not sub[0].isalpha() else _mr(sub)) if sub else _mr(name)


def _calc_formulas(doc, st, solid, dry, unit):
    """Section 1: the general equations of this run, written once."""
    model, rule = st.correction_model, st.replicate_rule
    x_bar = '<m:bar><m:barPr><m:pos m:val="top"/></m:barPr><m:e>' + _mr('x') + '</m:e></m:bar>'
    doc.heading(1, '1  How each result is calculated', 'formulas', page_break=True)
    doc.para('Every result in section 2 follows these steps, in this order. i is the measurement number of the sample '
             '(its place in the instrument sequence). Concentrations are in mg/L of the measured solution until step 5.')

    doc.heading(2, 'Step 1 - Replicates: mean, SD and outlying replicates')
    doc.lead('The instrument exports n replicate readings x₁ to xₙ. Their mean, standard deviation and relative standard deviation are')
    doc.math([x_bar + _mt(' = ') + _mf(_mt('1'), _mr('n')) + _mt(' Σ ') + _mv('x', 'k')
             , _mr('s') + _mt(' = ') + f'<m:rad><m:radPr><m:degHide m:val="1"/></m:radPr><m:deg/><m:e>'
             + _mf(_mt('Σ ') + f'<m:sSup><m:e>{_md(_mv("x", "k") + _mt(" − ") + x_bar)}</m:e><m:sup>{_mt("2")}</m:sup></m:sSup>',
                   _mr('n') + _mt(' − 1')) + '</m:e></m:rad>'
             , _mt('RSD') + _mt(' = 100 × ') + _mf(_mr('s'), x_bar) + _mt(' %')])
    if not st.auto_filter:
        doc.para('Removal of outlying replicates is switched off for this run: all replicates are kept.')
    elif rule == 'dixon':
        doc.lead("Outlying replicates: Dixon's Q test at 95 % confidence. Only the most extreme replicate (the smallest or the "
                 'largest) is tested, once:')
        doc.math(_mr('Q') + _mt(' = ') + _mf(_md(_mv('x', 'suspect') + _mt(' − ') + _mv('x', 'nearest'), '|', '|'),
                                           _mv('x', 'largest') + _mt(' − ') + _mv('x', 'smallest')),
                 'the replicate is removed if Q > Q_crit')
        doc.table([['Replicates n'] + [str(k) for k in core.DIXON_Q95],
                   ['Q_crit (95 %)'] + [f'{v:.3f}' for v in core.DIXON_Q95.values()]],
                  [1700] + [700] * len(core.DIXON_Q95), size=17)
        doc.para('The test is used only when the result without removal is at or above the limit. Results below the limit '
                 'keep all replicates (removing one there would not change the reported "<limit").')
    else:
        doc.para(f'Outlying replicates (RSD rule): while RSD > {_n(st.rsd_limit)} % and more than 3 replicates remain, '
                 'the replicate farthest from the current mean is removed (at most 2 removals).')
    doc.para(f'After this step an RSD above {_n(st.rsd_limit)} % is flagged "high scatter". If no replicate was removed, '
             "the instrument's own mean and SD are used (they carry more digits than the exported replicates); "
             'otherwise x̄ and s are recalculated from the kept replicates.')

    doc.heading(2, 'Step 2 - Sample blank')
    doc.lead('The sample blank at measurement i is interpolated between the sample blanks measured before (a) and after (b) '
             'the samples, and subtracted:')
    doc.math([_mr('B') + _md(_mr('i')) + _mt(' = ') + _mv('B', 'a') + _mt(' + ')
             + _mf(_mr('i') + _mt(' − ') + _mr('a'), _mr('b') + _mt(' − ') + _mr('a')) + _mt(' × ')
             + _md(_mv('B', 'b') + _mt(' − ') + _mv('B', 'a')),
             _mr('y') + _mt(' = ') + x_bar + _mt(' − ') + _mr('B') + _md(_mr('i'))])

    doc.heading(2, 'Step 3 - Standards')
    doc.lead('Each standard reading has the standard blank measured before it subtracted. A standard of nominal level L is '
             'measured before (p) and after (q) the samples; its value at measurement i is interpolated in the same way:')
    doc.math([_mr('S') + _mt(' = ') + _mt('reading') + _mt(' − ') + _mt('standard blank'), _mv('S', 'L') + _md(_mr('i')) + _mt(' = ')
             + _mv('S', 'L,p') + _mt(' + ') + _mf(_mr('i') + _mt(' − ') + _mr('p'), _mr('q') + _mt(' − ') + _mr('p'))
             + _mt(' × ') + _md(_mv('S', 'L,q') + _mt(' − ') + _mv('S', 'L,p'))])
    doc.para(f'A standard more than {int(STANDARD_CHECK_TOLERANCE * 100)} % from its nominal value is marked in the standards '
             'table (information only; nothing is changed).')

    doc.heading(2, 'Step 4 - Concentration in the measured solution')
    L1, L2 = _mv('L', '1'), _mv('L', '2')
    S1, S2 = _mv('S', 'L1') + _md(_mr('i')), _mv('S', 'L2') + _md(_mr('i'))
    if model == 'two_point':
        doc.lead('Calibration line through the blank (zero), the low standard L₁ and the high standard L₂:')
        doc.math(_mr('C') + _mt(' = ') + _mf(_mr('y') + _mt(' × ') + L1, S1), 'if y ≤ S_L1(i): line through zero and the low standard')
        doc.math([_mr('C') + _mt(' = ') + L1 + _mt(' + ') + _mf(_mr('y') + _mt(' − ') + S1, _mr('a')),
                  _mr('a') + _mt(' = ') + _mf(S2 + _mt(' − ') + S1, L2 + _mt(' − ') + L1)],
                 'if y > S_L1(i): line through the low and the high standard (slope a)')
        doc.para('The SD is divided by the slope of the part of the line that was used: s_C = s / a '
                 '(below the low standard a = S_L1(i) / L₁). When the kept replicates lie on both sides of '
                 'S_L1(i), each replicate is converted with its own line, and the result and its SD are the mean '
                 'and the sample SD of these converted replicates.')
    else:
        doc.lead('One standard L is used. Its factor f and the concentration are')
        doc.math([_mr('f') + _mt(' = ') + _mf(_mv('S', 'L') + _md(_mr('i')), _mr('L')),
                  _mr('C') + _mt(' = ') + _mf(_mr('y'), _mr('f')), _mv('s', 'C') + _mt(' = ') + _mf(_mr('s'), _mr('f'))])
        if model == 'single_standard':
            doc.para(f'The low standard is used if the raw mean x̄ ≤ T = {_n(st.high_standard_boundary_fraction)} × the high '
                     'level, otherwise the high standard (unless the analyst chose one).')
        else:
            doc.para(f'One standard, asking when unclear: C is calculated with both standards; T = {_n(st.high_standard_boundary_fraction)} × '
                     'the high level. The low standard is used if only C_low ≤ T, the high one if only C_high > T; '
                     'otherwise the analyst decides.')
    doc.para('A concentration above the highest standard is extrapolated and noted ("dilute and measure again").')

    doc.heading(2, 'Step 5 - Result in the sample')
    if solid:
        doc.math([_mt('Result') + _mt(' = ') + _mr('C') + _mt(' × ') + _mf(_mr('V'), _mr('m')) + _mt(' × ') + _mr('D')
                  , _mt('SD') + _mt(' = ') + _mv('s', 'C') + _mt(' × ') + _mf(_mr('V'), _mr('m')) + _mt(' × ') + _mr('D')],
                 'in mg/kg; V final volume (mL), m sample mass (g), D extra dilution')
        if dry:
            doc.math(_mv('m', 'dry') + _mt(' = ') + _mr('m') + _mt(' × ') + _md(_mt('1 − ') + _mf(_mt('moisture'), _mt('100'))),
                     'results on dry mass')
    else:
        doc.math([_mt('Result') + _mt(' = ') + _mr('C') + _mt(' × ') + _mr('D'),
                  _mt('SD') + _mt(' = ') + _mv('s', 'C') + _mt(' × ') + _mr('D')], 'in mg/L; D extra dilution')
    if unit not in ('mg/kg', 'mg/L'):
        factor = core.unit_choices(st.sample_type)[unit]
        doc.para(f'Results, SD and limits are reported in {unit}: the value in {"mg/kg" if solid else "mg/L"} × {_n(factor)}.')

    doc.heading(2, 'Step 6 - Limit and rounding')
    limit = 'the limit (LOQ) of the wavelength from the method table'
    if solid and st.limit_policy == 'lab_stored':
        limit += ' (its mg/kg value)'
    elif solid:
        limit += ', converted with the sample\'s own V/m'
    if st.dilution_limit_policy == 'scale_with_dilution':
        limit += ', multiplied by the dilution D'
    doc.para(f'The result is compared with {limit}. A result below the limit is reported as "<limit" with SD "n/a". '
             'Rounding: below 10 three decimals, below 100 two, below 1000 one, otherwise none; the SD gets one more decimal. '
             'The rule is applied in mg/L or mg/kg; in another unit the decimals move with the unit (0.123 mg/L = 0.000123 g/L).')

    doc.heading(2, 'Choosing the wavelength')
    if st.channel_score == 'percent':
        doc.lead('For each wavelength of an element the error of the standards is averaged over the low and the high standard, '
                 'before and after the samples (N readings):')
        doc.math(_mt('score') + _mt(' = ') + _mf(_mt('1'), _mr('N')) + _mt(' Σ ')
                 + _mf(_md(_mr('S') + _mt(' − ') + _mr('L'), '|', '|'), _mr('L')) + _mt(' × 100 %'), 'smaller is better')
    else:
        doc.lead('For each wavelength of an element the error of the standards (mg/L) is averaged over the low and the high '
                 'standard, before and after the samples (N readings):')
        doc.math(_mt('score') + _mt(' = ') + _mf(_mt('1'), _mr('N')) + _mt(' Σ ')
                 + _md(_mr('S') + _mt(' − ') + _mr('L'), '|', '|') + _mt('  mg/L'), 'smaller is better')
    doc.para(f'The best preference-1 wavelength is used unless its score is more than {_n(100 * st.relative_preference_tolerance)} % '
             'worse than the best preference-2 wavelength. Preference order and limits come from: '
             + core.METHOD_SOURCES.get(st.method_source, st.method_source) + '.')


def _calc_notes(r, rec, rsd_limit):
    notes = []
    if rec.get('stop'):
        notes.append('Not calculated: ' + rec['stop'])
    if rec.get('removed'):
        notes.append('Replicate removed')
    if 'HIGH_RSD' in r.flags:
        notes.append(f'RSD > {_n(rsd_limit)} %')
    if rec.get('above'):
        notes.append('Above highest standard')
    if any(f.startswith('BELOW_') for f in r.flags):
        notes.append('Below limit')
    names = {'SUMMARY_ONLY': 'Instrument mean only', 'MISSING_SD': 'No SD', 'REVIEW': 'Review',
             'ONE_STANDARD': 'Only the low standard usable'}
    for f in r.flags:
        if f in names:
            notes.append(names[f])
        elif f.startswith('MISSING_'):
            notes.append('No ' + f[8:] + ' in the method table')
    if 'STANDARD_OFF' in (getattr(r, 'marks', None) or []):
        notes.append(f'Standard more than {STANDARD_CHECK_TOLERANCE:.0%} off (\u2020)')
    if 'OTHER_WAVELENGTH' in r.flags and r.notes:
        notes.insert(0, r.notes[0])
    if 'OTHER_BLANK' in r.flags:
        notes.extend(n for n in r.notes if n.startswith('The standard blank ') and 'were corrected with' in n)
    other = next((n for n in r.notes if n.startswith('Another wavelength was not used')
                  or n.startswith(f'No other wavelength of {r.element} has usable standards')), '')
    if other:
        notes.append(other)
    return notes


def _calc_example(results):
    """The result written out in full for an element: a normal measured one if possible."""
    def has(rec, *keys):
        return all(k in rec for k in keys)
    for pick in (lambda r, rec: r.category == 'ok' and has(rec, 'value') and rec.get('removed'),
                 lambda r, rec: r.category == 'ok' and has(rec, 'value'),
                 lambda r, rec: has(rec, 'value'),
                 lambda r, rec: True):
        for item in results:
            if pick(item[0], item[2]):
                return item
    return None


def _limit_rule_text(st, solid):
    scaled = st.dilution_limit_policy == 'scale_with_dilution'
    if solid and st.limit_policy == 'lab_stored':                 # only in projects saved with the older rule
        return 'Fixed mg/kg value from the table (mg/L limit × 200)' + (' × dilution' if scaled else '')
    if solid:
        return 'LOQ (mg/L) × final volume (mL) ÷ mass (g) × dilution, for each sample'
    return 'LOQ × dilution' if scaled else 'LOQ, not multiplied by the dilution (older rule)'


def write_calculation_docx(project, analysis, path):
    """'Calculations explained.docx': rules once, then per element the wavelength choice, the standards, one worked
    example and a table of every sample; flagged results at the end. Returns the CHECK lines (there should be none)."""
    st = project.settings
    solid = st.sample_type == 'Solid'
    dry = solid and st.reporting_basis == 'dry'
    unit = core.report_unit(st)
    _, checks, model = calculation_model(project, analysis)
    doc = _DxDoc()
    run_name = core.run_name(st)

    # --- cover ------------------------------------------------------------------------------
    doc.para('Detailed explanations', style='Title')
    doc.para(f'{run_name}  -  {APP_NAME}', style='Subtitle')
    removed = sum(len(rec.get('removed') or []) for el in model['elements'] for _, _, rec in el['results'])
    above = sum(1 for el in model['elements'] for _, _, rec in el['results'] if rec.get('above'))
    counts = defaultdict(int)
    for r in analysis.results:
        counts[r.category] += 1
    std_checks = len(getattr(analysis, 'standard_checks', None) or [])
    method_shown = st.method if st.method and st.method != core.MASTER_NAME else 'not named in the file names'
    info = [['Run', run_name], ['Method', method_shown],
            ['Sample type', st.sample_type + (f' (reported on {"dry mass" if dry else "mass as weighed"})' if solid else '')],
            ['Unit', unit], ['Files', '; '.join(Path(p).name for p in project.source_paths)],
            ['Program', APP_NAME],
            ['Written', datetime.now().strftime('%d %B %Y, %H:%M')]]
    doc.heading(2, 'Run')
    doc.table(info, [2400, 9000], header=0, size=18)
    doc.heading(2, 'Rules used in this run')
    mean_sd = ("Instrument's mean and SD (recalculated only if a replicate was removed)"
               if st.statistics_basis == 'instrument_when_unfiltered' else 'Recalculated from the exported replicates')
    rules = [['Setting', 'Used in this run'],
             ['Standard correction', core.CORRECTION_MODELS.get(st.correction_model,
                                                               'One standard, Plasmatti asks when unclear')],
             ['Outlying replicates', core.REPLICATE_RULES.get(st.replicate_rule, st.replicate_rule) if st.auto_filter else 'Switched off'],
             ['High scatter flag', f'RSD above {_n(st.rsd_limit)} %'],
             ['Choosing the wavelength', core.CHANNEL_SCORES.get(st.channel_score, st.channel_score)],
             ['Preference and limits from', core.METHOD_SOURCES.get(st.method_source, st.method_source)],
             ['Limits', _limit_rule_text(st, solid)],
             ['Mean and SD', mean_sd]]
    doc.table(rules, [3400, 8000], size=18)
    doc.heading(2, 'Overview')
    overview = [['', 'Number'],
                ['Results', str(len(analysis.results))]]
    overview += [[CATEGORY_LABELS[k], str(counts.get(k, 0))] for k in ('ok', 'below_limit', 'attention', 'blocked')]
    overview += [['Replicates removed', str(removed)], ['Above the highest standard', str(above)],
                 [f'Standards more than {int(STANDARD_CHECK_TOLERANCE * 100)} % from nominal', str(std_checks)]]
    doc.table(overview, [5000, 1600], size=18, align=['left', 'right'])
    doc.para([_dx_run('Independent check: ', bold=True),
              f'every number in this report was recalculated from the instrument values, separately from the program, '
              f'and compared with the program\'s results. Differences found: {len(checks)}.'])
    if checks:
        for line in checks[:50]:
            doc.para(_dx_run(line, color='C00000'), indent=567)

    # --- contents -----------------------------------------------------------------------------
    doc.heading(2, 'Contents')
    doc.para([_dx_link('formulas', '1  How each result is calculated')])
    doc.para([_dx_link('elements', '2  Results by element')])
    links = [_dx_link(f'el{i}', el['element']) for i, el in enumerate(model['elements'])]
    per = max(1, min(16, len(model["elements"])))
    if links:
        rows = [links[k:k + per] + [''] * (per - len(links[k:k + per])) for k in range(0, len(links), per)]
        doc.table(rows, [_DX_TEXT_W // per] * per, header=0, size=18, align=['center'] * per)
    doc.para([_dx_link('flagged', '3  Results to look at (flagged)')])
    doc.para(_dx_run('How to cite Plasmatti: ' + APP_CITATION_TEXT, italic=True, color='595959'))

    _calc_formulas(doc, st, solid, dry, unit)

    # --- per element ---------------------------------------------------------------------------
    flagged = []
    doc.heading(1, '2  Results by element', 'elements', page_break=True)
    doc.para('For each element: how the wavelength was chosen, the standards and blanks, one result written out in full, '
             'and every sample in a table. Struck-through replicates were removed. Shaded rows need attention '
             '(orange) or were not calculated (grey).')
    res_unit = unit
    first_el = True
    for i, el in enumerate(model['elements']):
        element, chosen = el['element'], el['chosen']
        doc.heading(2, f'{element}' + (f'  -  {chosen}' if chosen else '  -  no wavelength'), f'el{i}', page_break=not first_el)
        first_el = False
        # wavelength choice
        doc.heading(3, 'Choosing the wavelength')
        pct = st.channel_score == 'percent'
        nterms = max([len(c['terms']) for c in el['channels']] + [0])
        heads = []
        for c in el['channels']:
            if len(c['terms']) == nterms and nterms:
                heads = [f'{_n(t[0])} mg/L {("before" if k % 2 == 0 else "after")}' for k, t in enumerate(c['terms'])]
                break
        rows = [['Wavelength', 'Preference'] + (heads or ['Standards']) + ['Score' + (' (%)' if pct else ' (mg/L)'), 'Used']]
        fills = {}
        for c in el['channels']:
            cells = [c['channel'], str(c['preference'] or '-')]
            terms = [f'{t[2]:+.1f} %' if pct else f'{t[3]:.4g}' for t in c['terms']]
            cells += (terms + [''] * (len(heads) - len(terms))) if heads else ['incomplete']
            cells += [_n(c['score'], 4) if c['score'] is not None else 'no score', 'yes' if c['chosen'] else '']
            if c['chosen']:
                fills[len(rows)] = _DX_CHOSEN
            rows.append(cells)
        ncol = len(rows[0])
        w0 = [2600, 1100]
        rest = (_DX_TEXT_W - sum(w0) - 1400 - 800)
        mid = max(1, ncol - 4)
        widths = w0 + [min(1500, rest // mid)] * mid + [1400, 800]
        doc.table(rows, widths, size=16, fills=fills, align=['left', 'center'] + ['right'] * (ncol - 3) + ['center'])
        doc.para(el['sentence'])
        if not chosen:
            continue
        # standards and blanks
        doc.heading(3, 'Standards and blanks')
        rows = [['Standard (mg/L)', 'When', 'Measurement', 'Name', 'Reading (mg/L)', 'Standard blank (mg/L)', 'S = reading − blank',
                 'vs nominal']]
        fills = {}
        for s in el['standards']:
            off = abs(s['pct']) > STANDARD_CHECK_TOLERANCE * 100
            if off:
                fills[len(rows)] = _DX_ATTENTION
            rows.append([_n(s['level']), s['when'], str(s['seq']), s['name'],
                         _n(s['raw']) if s['raw'] is not None else '-',
                         (f'{_n(s["blank"])} (meas. {s["blank_seq"]})' if s['blank'] is not None else '-'),
                         _n(s['S']), _DxRaw(_dx_run(f'{s["pct"]:+.1f} %', bold=off, size=16))])
        doc.table(rows, [1500, 900, 1200, 2600, 1600, 2300, 1900, 1200], size=16, fills=fills,
                  align=['right', 'left', 'center', 'left', 'right', 'right', 'right', 'right'])
        for text in el['standard_checks']:
            doc.para([_dx_run('Standard check: ', bold=True), text])
        if el['blanks']:
            doc.para([_dx_run('Sample blanks: ', bold=True),
                      '; '.join(f'measurement {s} = {_n(v)} mg/L' if v is not None else f'measurement {s}: no value'
                                for s, v in el['blanks'])])
        doc.para([_dx_run('Limit of this wavelength: ', bold=True), el['limit']])
        # worked example
        ex = _calc_example(el['results'])
        if ex is not None:
            r, lines, rec = ex
            doc.heading(3, f'Worked example: {r.report_name}')
            for k, line in enumerate(lines):
                text = line.strip()
                if not text:
                    continue
                if k == 0:
                    doc.para(_dx_run(text, bold=True), keep_next=True)
                else:
                    doc.para(_dx_run(text, color='C00000') if text.startswith('CHECK') else text, style='Step')
        # every sample
        doc.heading(3, 'All samples')
        res_head = ('Result' + f' ({res_unit})')
        factor_head = '× V/m × D' if solid else 'D'
        rows = [['Sample', 'Meas.', 'Replicates (mg/L)', 'Replicate test', 'x̄ (mg/L)', 'Blank B', 'y = x̄ − B', 'Line used',
                 'C (mg/L)', factor_head, res_head, 'SD', 'Reported', 'Notes']]
        fills = {}
        for r, lines, rec in el['results']:
            vals = rec.get('values') or []
            rem = set(rec.get('removed') or [])
            reps = []
            for k, v in enumerate(vals):
                if k:
                    reps.append(_dx_run(', ', size=16))
                reps.append(_dx_run(f'{v:.4g}', size=16, strike=(k + 1) in rem, color='C00000' if (k + 1) in rem else None))
            notes = _calc_notes(r, rec, st.rsd_limit)
            name = r.report_name
            sample_cell = name
            if r.category in ('attention', 'blocked') or rec.get('above') or rec.get('removed'):
                anchor = f'res{len(flagged)}'
                sample_cell = doc.bookmark(anchor, _dx_run(name, size=16))
                flagged.append((anchor, element, r, notes))
            if r.category == 'attention':
                fills[len(rows)] = _DX_ATTENTION
            elif r.category == 'blocked':
                fills[len(rows)] = _DX_BLOCKED
            if solid and 'm' in rec:
                fac = _n(rec['V'] / rec['m'] * rec['D'], 4)
            else:
                fac = _n(rec.get('D'), 4) if 'D' in rec else ''
            reported = r.reported + ('' if r.category in ('below_limit', 'blocked') or r.sd_display in ('', NO_SD)
                                     else f' ± {r.sd_display}')
            rows.append([sample_cell, str(r.sequence), _DxRaw(''.join(reps)) if reps else '-', rec.get('test', ''),
                         _n(rec['xbar'], 4) if 'xbar' in rec else '', _n(rec['B'], 4) if 'B' in rec else '',
                         _n(rec['y'], 4) if 'y' in rec else '', rec.get('segment', ''),
                         _n(rec['C'], 4) if 'C' in rec else '', fac,
                         _n(rec['value'], 4) if 'value' in rec else '', _n(rec['sd'], 2) if rec.get('sd') is not None else '',
                         _DxRaw(_dx_run(reported, bold=True, size=16)), '; '.join(notes)])
        doc.table(rows, [1500, 550, 2300, 1250, 950, 950, 950, 750, 950, 750, 950, 750, 1100, 1698], size=16, fills=fills,
                  align=['left', 'center', 'left', 'left'] + ['right'] * 3 + ['center'] + ['right'] * 5 + ['left'])

    # --- flagged -------------------------------------------------------------------------------
    doc.heading(1, '3  Results to look at (flagged)', 'flagged', page_break=True)
    if flagged:
        doc.para('Results that need attention, were not calculated, had a replicate removed or are above the highest standard. '
                 'Click a sample to go to its row.')
        rows = [['Element', 'Sample', 'Wavelength', 'Reported', 'Why']]
        for anchor, element, r, notes in flagged:
            rows.append([element, _dx_link(anchor, r.report_name), r.channel, r.reported, '; '.join(notes)])
        doc.table(rows, [1100, 2600, 2600, 1500, _DX_TEXT_W - 7800], size=17)
    else:
        doc.para('No result was flagged.')
    doc.save(path, f'Detailed explanations - {run_name}',
             [f'{APP_NAME}  |  Detailed explanations  |  {run_name}'])
    return checks


####################################################################################################
# plasmati_build.py
####################################################################################################
# Create a self-contained Plasmatti program (Plasmatti.exe on Windows) in a folder the user chooses.
#
# The program needs no Python on the computer where it runs. It is built with PyInstaller, which is
# installed with pip the first time (internet needed once). If a code-signing certificate is installed
# on the building computer (Windows), the program is signed automatically; otherwise it is left unsigned.
#
#     python src/plasmatti.py --make-exe

import glob
import importlib.util
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

EXE_BASENAME = 'Plasmatti'
TIMESTAMP_URL = 'http://timestamp.digicert.com'
SIGN_CERT_ENV = 'PLASMATTI_SIGN_CERT'          # optional: SHA-1 thumbprint of the certificate to use


def is_windows():
    return sys.platform.startswith('win')


def is_frozen():
    """True inside the built program (there is nothing to build from)."""
    return bool(getattr(sys, 'frozen', False))


def main_script():
    """The .py file that was started (the one-file Plasmatti or the launcher), or None."""
    main = sys.modules.get('__main__')
    path = getattr(main, '__file__', None)
    if not path or is_frozen():
        return None
    path = Path(path).resolve()
    return path if path.suffix.lower() == '.py' and path.is_file() else None


def exe_path(script, out_dir=None):
    folder = Path(out_dir).resolve() if out_dir else Path(script).resolve().parent
    return folder / (EXE_BASENAME + ('.exe' if is_windows() else ''))


def needs_internet():
    """True when PyInstaller still has to be downloaded (only the first time)."""
    return importlib.util.find_spec('PyInstaller') is None


def icon_bytes():
    """The Plasmatti logo as a Windows icon (.ico)."""
    return embedded_file('plasmatti.ico') if 'plasmatti.ico' in _EMBEDDED else b''


def _build_run(cmd, log, cwd=None):
    flags = getattr(subprocess, 'CREATE_NO_WINDOW', 0) if is_windows() else 0
    log(' '.join(f'"{c}"' if ' ' in str(c) else str(c) for c in cmd))
    proc = subprocess.run([str(c) for c in cmd], cwd=cwd, capture_output=True, text=True, creationflags=flags)
    out = (proc.stdout or '') + (proc.stderr or '')
    for line in out.splitlines():
        log(line)
    return proc.returncode, out


def ensure_pyinstaller(log):
    if not needs_internet():
        return
    log('Installing PyInstaller (once)')
    code, out = _build_run([sys.executable, '-m', 'pip', 'install', '--disable-pip-version-check', 'pyinstaller'], log)
    importlib.invalidate_caches()
    if code != 0 or importlib.util.find_spec('PyInstaller') is None:
        tail = '\n'.join(out.strip().splitlines()[-8:])
        raise RuntimeError('PyInstaller could not be installed (an internet connection is needed once).\n\n' + tail)


def find_signtool():
    tool = shutil.which('signtool')
    if tool:
        return tool
    roots = [os.environ.get('ProgramFiles(x86)', r'C:\Program Files (x86)'), os.environ.get('ProgramFiles', r'C:\Program Files')]
    found = []
    for root in roots:
        found += glob.glob(os.path.join(root, 'Windows Kits', '10', 'bin', '*', 'x64', 'signtool.exe'))
    return sorted(found)[-1] if found else None


def has_code_signing_certificate(log):
    if os.environ.get(SIGN_CERT_ENV):
        return True
    code, out = _build_run(['powershell', '-NoProfile', '-NonInteractive', '-Command',
                      '(Get-ChildItem Cert:\\CurrentUser\\My -CodeSigningCert | Measure-Object).Count'], log)
    try:
        return code == 0 and int(out.strip().splitlines()[-1]) > 0
    except (ValueError, IndexError):
        return False


def sign_exe(exe, log):
    """Sign with an installed code-signing certificate. Returns a sentence for the user."""
    if not is_windows():
        return 'Not signed (signing is done on Windows only).'
    tool = find_signtool()
    if not tool or not has_code_signing_certificate(log):
        return ('Not signed: no code-signing certificate is installed on this computer. Windows will show '
                '"Windows protected your PC" the first time; click "More info" and "Run anyway".')
    cert = os.environ.get(SIGN_CERT_ENV)
    cmd = [tool, 'sign', '/fd', 'SHA256', '/tr', TIMESTAMP_URL, '/td', 'SHA256']
    cmd += ['/sha1', cert] if cert else ['/a']
    code, out = _build_run(cmd + [str(exe)], log)
    if code != 0:
        return 'Not signed: signing failed (' + (out.strip().splitlines() or ['unknown error'])[-1] + ').'
    return 'Signed with the code-signing certificate of this computer.'


def build_exe(script=None, log=None, icon=None, out_dir=None):
    """Build the self-contained program in `out_dir` (default: next to `script`). Returns (path, signing sentence)."""
    lines = []

    def say(text):
        lines.append(str(text))
        if log:
            log(str(text))
    if is_frozen():
        raise RuntimeError('This is already the built program; build it from the Python file.')
    script = Path(script).resolve() if script else main_script()
    if script is None or not script.is_file():
        raise RuntimeError('The Python file of Plasmatti was not found.')
    target = exe_path(script, out_dir)
    target.parent.mkdir(parents=True, exist_ok=True)
    ensure_pyinstaller(say)
    with tempfile.TemporaryDirectory(prefix='plasmatti_build_') as tmp:
        tmp = Path(tmp)
        cmd = [sys.executable, '-m', 'PyInstaller', '--noconfirm', '--clean', '--onefile', '--windowed',
               '--name', EXE_BASENAME, '--distpath', tmp / 'dist', '--workpath', tmp / 'work', '--specpath', tmp]
        ico = icon if icon is not None else icon_bytes()
        if ico:
            (tmp / 'plasmatti.ico').write_bytes(ico)
            cmd += ['--icon', tmp / 'plasmatti.ico']
        for module in ('openpyxl', 'pymupdf', 'fitz', 'xlrd'):
            if importlib.util.find_spec(module) is not None:
                cmd += ['--hidden-import', module]
        data = script.parent / 'data'
        if data.is_dir() and (script.parent / 'plasmati_core.py').is_file():     # the multi-file source tree
            cmd += ['--add-data', f'{data}{os.pathsep}data']
        for unused in ('tkinter', 'PySide6.QtWebEngineCore', 'PySide6.QtWebEngineWidgets', 'PySide6.Qt3DCore',
                       'PySide6.QtMultimedia', 'PySide6.QtQuick', 'PySide6.QtQml'):
            cmd += ['--exclude-module', unused]
        code, out = _build_run(cmd + [script], say, cwd=tmp)
        built = tmp / 'dist' / target.name
        if code != 0 or not built.is_file():
            tail = '\n'.join(out.strip().splitlines()[-12:])
            raise RuntimeError('The program could not be built.\n\n' + tail)
        note = sign_exe(built, say)
        if target.exists():
            target.unlink()
        shutil.move(str(built), str(target))
    say(f'Created {target} ({target.stat().st_size / 1e6:.0f} MB). {note}')
    return target, note


def make_exe_cli():
    """`python Plasmatti_x.py --make-exe`: build with progress printed to the console."""
    path, note = build_exe(log=lambda text: print(text, flush=True))
    print(f'\nDone: {path}\n{note}')
    return 0


####################################################################################################
# plasmati_gui_widgets.py
####################################################################################################
if HAVE_QT:
    # Plasmatti shared Qt widgets and dialogs.
    #
    # All dialogs edit a DRAFT (deep copy, or a table that is only read on OK) and
    # commit atomically; Cancel or a validation error leaves the active project
    # untouched. Message boxes go through ``ui`` so tests can run headless.

    import copy
    import re
    from pathlib import Path
    from typing import Optional

    from PySide6.QtCore import Qt, QTimer, Signal, QLocale
    from PySide6.QtGui import QColor, QFont
