    def split_message(text, limit=110):
        """Split a message into (headline, details). The headline is the first line (or
    first sentence if that line is long); the rest is shown only on request."""
        text = str(text).strip()
        first, _, rest = text.partition('\n')
        first = first.strip()
        if len(first) > limit:
            cut = first.rfind('. ', 0, limit + 40)
            if 20 < cut:
                rest = (first[cut + 2:] + ('\n' + rest if rest else '')).strip()
                first = first[:cut + 1]
        return first, rest.strip()


    def _box(icon, parent, title, text, buttons=QMessageBox.Ok):
        """The whole message is always shown (no 'Show Details' button)."""
        return QMessageBox(icon, title, str(text).strip(), buttons, parent)


    class _UI:
        def info(self, parent, title, text):
            _box(QMessageBox.Information, parent, title, text).exec()

        def warn(self, parent, title, text):
            _box(QMessageBox.Warning, parent, title, text).exec()

        def ask(self, parent, title, text, default_yes=False, yes='Yes', no='No'):
            """A question with buttons that say what they do (yes/no labels); True for the first button."""
            box = _box(QMessageBox.Question, parent, title, text, QMessageBox.NoButton)
            b_yes = box.addButton(yes, QMessageBox.YesRole)
            b_no = box.addButton(no, QMessageBox.NoRole)
            box.setDefaultButton(b_yes if default_yes else b_no)
            box.setEscapeButton(b_no)
            box.exec()
            return box.clickedButton() is b_yes

        def ask3(self, parent, title, text, yes='Yes', no='No'):
            box = _box(QMessageBox.Question, parent, title, text, QMessageBox.NoButton)
            b_yes = box.addButton(yes, QMessageBox.YesRole)
            b_no = box.addButton(no, QMessageBox.NoRole)
            box.addButton('Cancel', QMessageBox.RejectRole)
            box.exec()
            return 'yes' if box.clickedButton() is b_yes else 'no' if box.clickedButton() is b_no else 'cancel'

        def text(self, parent, title, label, default=''):
            value, ok = QInputDialog.getText(parent, title, label, QLineEdit.Normal, default)
            return value if ok else None


    ui = _UI()


