    _EXECUTOR = None


    def _executor():
        global _EXECUTOR
        if _EXECUTOR is None:
            # Import the submodule directly: in Python 3.15 'concurrent.futures' binds ThreadPoolExecutor as a lazy
            # import, and with PySide6 6.12 loaded 'from concurrent.futures import ThreadPoolExecutor' inside a function
            # returns the unresolved lazy object ("'lazy_import' object is not callable").
            import concurrent.futures.thread as _thread
            _EXECUTOR = _thread.ThreadPoolExecutor(max_workers=1, thread_name_prefix='plasmati-work')
        return _EXECUTOR


    def run_task(parent, title, fn):
        """Run file/CPU work off the UI thread while a busy dialog keeps the window responsive.

    The work runs in a plain Python worker thread that never touches Qt; the
    UI thread polls it with a QTimer. (A QThread signalling into a
    nested modal loop; an offscreen stress run showed a native crash there.)
    Exceptions are re-raised on the UI thread; the project is only changed by
    the caller after success.
    """
        from concurrent.futures import wait as _wait
        future = _executor().submit(fn)
        _wait([future], timeout=0.15)          # short jobs finish without flashing a dialog
        if not future.done():
            dialog = QDialog(parent)
            dialog.setWindowTitle(title)
            dialog.setWindowFlags(Qt.Dialog | Qt.WindowTitleHint | Qt.CustomizeWindowHint)
            dialog.setAttribute(Qt.WA_DeleteOnClose, False)
            layout = QVBoxLayout(dialog)
            layout.addWidget(QLabel(title))
            progress = QProgressBar()
            progress.setRange(0, 0)
            layout.addWidget(progress)
            dialog.setMinimumWidth(420)
            dialog.reject = lambda: None        # cannot be closed while the work runs
            timer = QTimer(dialog)
            timer.setInterval(40)
            timer.timeout.connect(lambda: dialog.done(0) if future.done() else None)
            timer.start()
            dialog.exec()
            timer.stop()
            dialog.deleteLater()
        return future.result()


    def readonly(text) -> QTableWidgetItem:
        item = QTableWidgetItem('' if text is None else str(text))
        item.setFlags(item.flags() & ~Qt.ItemIsEditable)
        return item


    def table_setup(table: QTableWidget, stretch_cols=(), minimum_height=200):
        table.setAlternatingRowColors(True)
        table.verticalHeader().setVisible(False)
        table.setMinimumHeight(minimum_height)
        table.setSelectionBehavior(QAbstractItemView.SelectRows)
        for c in range(table.columnCount()):
            table.horizontalHeader().setSectionResizeMode(c, QHeaderView.ResizeToContents)
        for c in stretch_cols:
            table.horizontalHeader().setSectionResizeMode(c, QHeaderView.Stretch)


    def numeric_text(value):
        return '' if value is None else f'{value:.9g}'


    def system_decimal_mark():
        """The decimal mark this computer uses (Windows regional settings): ',' or '.'."""
        try:
            mark = QLocale.system().decimalPoint()
        except Exception:
            return '.'
        return ',' if mark == ',' else '.'


    class AmbiguousNumber(ValueError):
        """A typed number with two possible meanings, such as "1,125"."""


    _ONE_COMMA = re.compile(r'^[+\-]?\d*,\d+$')
    _COMMA_GROUPS = re.compile(r'^[+\-]?[1-9]\d{0,2}(?:,\d{3})+$')


    def parse_cell(text, name, decimal='auto'):
        """A number typed by hand. On a computer that uses a decimal comma, "1,125" is 1.125;
    on a computer that uses a decimal point it could be 1.125 or 1125, so it is refused."""
        text = (text or '').strip()
        if not text:
            return None
        if decimal == 'auto':
            bare = re.sub(r"[\s'’]", '', text)
            if system_decimal_mark() == ',' and _ONE_COMMA.match(bare):
                text = bare.replace(',', '.')
            elif _COMMA_GROUPS.match(bare):
                a, b = bare.replace(',', '.'), bare.replace(',', '')
                raise AmbiguousNumber(f'{name}: is "{text}" {a} or {b}? Type {a} with a point, or {b} without the comma.')
        try:
            return number(text, decimal=decimal)
        except (TypeError, ValueError) as exc:
            raise ValueError(f'{name}: {exc}') from None


    def card(title, subtitle=''):
        frame = QFrame()
        frame.setFrameShape(QFrame.StyledPanel)
        v = QVBoxLayout(frame)
        head = QLabel(title)
        head.setWordWrap(True)
        head.setStyleSheet('font-size: 14px; font-weight: 650;')
        v.addWidget(head)
        if subtitle:
            sub = QLabel(subtitle)
            sub.setWordWrap(True)
            sub.setStyleSheet('color: #475569;')
            v.addWidget(sub)
        return frame, v


    def banner(text='', tone='info'):
        label = QLabel(text)
        label.setWordWrap(True)
        label.setTextFormat(Qt.PlainText)
        set_tone(label, tone)
        return label


    def set_tone(label, tone):
        colours = {'info': ('#EEF4FB', '#1E3A5F'), 'ok': ('#ECF8F0', '#14532D'),
                   'warn': ('#FFF4E5', '#7C2D12'), 'bad': ('#FDECEC', '#7F1D1D')}
        bg, fg = colours.get(tone, colours['info'])
        label.setStyleSheet(f'background:{bg}; color:{fg}; padding:8px 10px; border-radius:5px; font-weight:600;')


    def question_text(text):
        """Rich text for a full question: bold headline, then every line of the explanation."""
        import html
        head, _, rest = str(text).strip().partition('\n')
        parts = [f'<p style="font-size:16px; font-weight:650; margin:0 0 6px 0;">{html.escape(head)}</p>']
        for line in [x for x in rest.split('\n') if x.strip()]:
            esc = html.escape(line.strip())
            if esc.startswith('If you answer') or esc.startswith('If you do not want'):
                colon = esc.find(':')
                esc = f'<b>{esc[:colon + 1]}</b>{esc[colon + 1:]}' if colon > 0 else esc
            indent = ('margin:2px 0 2px 18px;' if esc.startswith('\u2022') else 'margin:4px 0;') + ' font-size:14px;'
            parts.append(f'<p style="{indent}">{esc}</p>')
        return ''.join(parts)


    def question_banner(parent, text):
        """The whole question with its explanation (no hidden details)."""
        label = QLabel(question_text(text))
        label.setTextFormat(Qt.RichText)
        label.setWordWrap(True)
        label.setTextInteractionFlags(Qt.TextSelectableByMouse)
        label.setStyleSheet('background:#FFF4E5; color:#1F2937; padding:10px 12px; border-radius:5px;')
        return label


