    def _help_html(text):
        """'## Heading' lines become headings; other lines become paragraphs."""
        import html as _html
        out = []
        for raw in str(text).split('\n'):
            block = raw.strip()
            if not block:
                continue
            if block.startswith('## '):
                out.append(f'<h3 style="color:#20334B; margin:14px 0 4px 0;">{_html.escape(block[3:])}</h3>')
            elif raw.startswith('    '):          # a formula: own line, indented, upright serif
                out.append(f'<p style="margin:4px 0 4px 28px; font-family:Cambria, \'Times New Roman\', serif; '
                           f'font-size:15px; white-space:pre;">{_html.escape(block)}</p>')
            else:
                out.append(f'<p style="margin:3px 0;">{_html.escape(block)}</p>')
        return ''.join(out)


    def show_help(parent, title, text, extras=True):
        """The instructions of a page, followed by the overview of the six steps and the words used."""
        dlg = QDialog(parent)
        dlg.setWindowTitle(title)
        dlg.resize(820, 680)
        v = QVBoxLayout(dlg)
        from PySide6.QtWidgets import QTextBrowser
        view = QTextBrowser()
        view.setOpenExternalLinks(False)
        view.setStyleSheet('font-size:14px;')
        view.setHtml(_help_html(text + ('\n' + HELP_OVERVIEW + '\n' + HELP_WORDS if extras else '')))
        v.addWidget(view, 1)
        buttons = QDialogButtonBox(QDialogButtonBox.Close)
        buttons.rejected.connect(dlg.reject)
        v.addWidget(buttons)
        dlg.help_view = view
        if getattr(show_help, 'no_exec', False):          # tests
            return dlg
        dlg.exec()
        dlg.deleteLater()
        return dlg


    def help_row(layout, parent, summary_text, help_title, help_text):
        """Compact page header: one bold summary line and a 'Read instructions' button
    that opens the details (same pattern as Elementti)."""
        row = QHBoxLayout()
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(6)
        label = QLabel(summary_text)
        label.setWordWrap(True)
        label.setStyleSheet('font-weight: 600;')
        button = QPushButton('Read instructions')
        button.setFixedWidth(130)
        button.setToolTip('Show instructions for this page')
        button.clicked.connect(lambda: show_help(parent, help_title, help_text))
        row.addWidget(label, 1)
        row.addWidget(button)
        layout.addLayout(row)
        return button


    def scrolling(widget):
        area = QScrollArea()
        area.setFrameShape(QFrame.NoFrame)
        area.setWidgetResizable(True)
        area.setWidget(widget)
        return area


    def pick_history_run(parent, runs):
        """Searchable list of run folders (separate runs are never pooled)."""
        dialog = QDialog(parent)
        dialog.setWindowTitle('Choose one analytical run')
        dialog.resize(940, 600)
        v = QVBoxLayout(dialog)
        v.addWidget(QLabel('Search by date, method or requester. Separate runs are never pooled.'))
        search = QLineEdit()
        search.setPlaceholderText('Filter run folders')
        v.addWidget(search)
        listing = QListWidget()
        v.addWidget(listing)
        for i, run in enumerate(runs):
            item = QListWidgetItem(run.label)
            item.setData(Qt.UserRole, i)
            listing.addItem(item)

        def filter_list(text):
            for i in range(listing.count()):
                listing.item(i).setHidden(text.casefold() not in listing.item(i).text().casefold())
        search.textChanged.connect(filter_list)
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        v.addWidget(buttons)
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        listing.itemDoubleClicked.connect(lambda *_: dialog.accept())
        if dialog.exec() != QDialog.Accepted or listing.currentItem() is None:
            return None
        return runs[listing.currentItem().data(Qt.UserRole)]


