            row.addWidget(QLabel('Other method (library):'))
            row.addWidget(self.search)
            row.addWidget(self.methods, 1)
            row.addWidget(self.apply_btn)
            row.addWidget(self.import_btn)
            v.addLayout(row)
            self.confirm = QCheckBox('I accept these missing wavelengths and want to continue with this method.')
            v.addWidget(self.confirm)
            self.wave_box = QWidget()
            wv = QVBoxLayout(self.wave_box)
            wv.setContentsMargins(0, 0, 0, 0)
            top = QHBoxLayout()
            self.wave_label = QLabel('')
            self.wave_label.setStyleSheet('font-weight: 600;')
            self.wave_note = QLabel('Without a limit, results at these wavelengths are flagged "no reporting limit". '
                                    'You can enter a priority and limits here.')
