            self.table.horizontalHeaderItem(2).setToolTip('1 = preferred wavelength, 2 = second choice (from the method table)')
            self.table.horizontalHeaderItem(5).setToolTip('LOQ = limit of quantification, DL = detection limit')
            self.table.horizontalHeaderItem(6).setToolTip('Use this wavelength for the element instead of the automatic choice')
            self.table.horizontalHeaderItem(7).setToolTip('Untick to exclude this wavelength from the automatic choice')
            self.table.setColumnHidden(4, True)      # mg/kg limits are calculated for each sample, not taken from the table
            table_setup(self.table, stretch_cols=(1,), minimum_height=110)
            wv.addWidget(self.table, 1)
