    class CompositionEditor(QWidget):
        """Standard selector + element / expected-concentration table.

    The expected concentration of each element at THIS vial is shown and
    editable; internally it becomes level x multiplier (multiplier =
    expected / prepared level). Elements not listed are not in the standard.
    """

        def __init__(self, parent=None):
            super().__init__(parent)
            self.library = load_library()
            v = QVBoxLayout(self)
            v.setContentsMargins(0, 0, 0, 0)
            grid = QGridLayout()
            self.group = QComboBox()
            self.group.addItem('Elements listed below (single-element or custom mixture)', None)
            for g in self.library.get('standard_groups', []):
                self.group.addItem(f'{g["name"]} (documented: {len(g["elements"])} elements)', g)
            self.level = QLineEdit()
            self.level.setPlaceholderText('e.g. 1 or 20')
            grid.addWidget(QLabel('Standard / mixture:'), 0, 0)
            grid.addWidget(self.group, 0, 1)
            grid.addWidget(QLabel('Prepared level on the vial label (mg/L):'), 1, 0)
            grid.addWidget(self.level, 1, 1)
            v.addLayout(grid)
            self.table = QTableWidget(0, 2)
            self.table.setHorizontalHeaderLabels(['Element', 'Expected concentration in this vial (mg/L)'])
            table_setup(self.table, stretch_cols=(1,), minimum_height=160)
            v.addWidget(self.table)
            row = QHBoxLayout()
            self.add_btn = QPushButton('Add element')
            self.del_btn = QPushButton('Remove selected')
            row.addWidget(self.add_btn)
            row.addWidget(self.del_btn)
            row.addStretch(1)
            v.addLayout(row)
            self.add_btn.clicked.connect(self.add_row)
            self.del_btn.clicked.connect(lambda: self.table.removeRow(self.table.currentRow()) if self.table.currentRow() >= 0 else None)
            self.group.currentIndexChanged.connect(self.fill_from_group)
            self.level.editingFinished.connect(self.rescale)
            self._last_level = None

        def set_values(self, level, elements_text, multipliers):
            self.level.setText(numeric_text(level))
            self._last_level = level
            self.table.setRowCount(0)
            if elements_text and elements_text not in ('?', '*'):
                for el in [x for x in elements_text.replace('+', ',').replace(';', ',').split(',') if x.strip()]:
                    el = el.strip()
                    expected = (level or 0) * multipliers.get(el, 1.0) if level else None
                    self.add_row(el, expected)

        def select_group_for(self, label):
            """Show the documented mixture matching ``label`` (display only; values unchanged)."""
            pass
            m = STANDARD_LEVEL_RE.search(str(label))
            hits = standard_group_matches(str(label)[:m.start()] if m else str(label), self.library)
            if len(hits) == 1:
                idx = next((i for i in range(self.group.count()) if (self.group.itemData(i) or {}).get('name') == hits[0]['name']), -1)
                if idx >= 0:
                    self.group.blockSignals(True)
                    self.group.setCurrentIndex(idx)
                    self.group.blockSignals(False)

        def add_row(self, element='', expected=None):
            i = self.table.rowCount()
            self.table.insertRow(i)
            self.table.setItem(i, 0, QTableWidgetItem(element if isinstance(element, str) else ''))
            self.table.setItem(i, 1, QTableWidgetItem(numeric_text(expected)))

        def fill_from_group(self, *_):
            g = self.group.currentData()
            if not g:
                return
            try:
                level = parse_cell(self.level.text(), 'Prepared level')
            except ValueError:
                level = None
            self.table.setRowCount(0)
            for el in g['elements']:
                mult = g.get('nominal_multipliers', {}).get(el, 1.0)
                self.add_row(el, level * mult if level else None)

        def rescale(self):
            try:
                new = parse_cell(self.level.text(), 'Prepared level')
            except ValueError:
                return
            old = self._last_level
            if new and old:
                for i in range(self.table.rowCount()):
                    item = self.table.item(i, 1)
                    try:
                        val = parse_cell(item.text() if item else '', 'expected')
                    except ValueError:
                        continue
                    if val is not None:
                        item.setText(numeric_text(val * new / old))
            elif new and not old:
                for i in range(self.table.rowCount()):
                    item = self.table.item(i, 1)
                    if item is not None and not item.text().strip():
                        item.setText(numeric_text(new))
            self._last_level = new

        def values(self):
            """(level, 'Ca,Fe', {element: multiplier}) or ValueError."""
            level = parse_cell(self.level.text(), 'Prepared level')
            if level is None or level <= 0:
                raise ValueError('Enter the prepared level written on the vial (mg/L).')
            elements, mult = [], {}
            for i in range(self.table.rowCount()):
                el = (self.table.item(i, 0).text() if self.table.item(i, 0) else '').strip()
                if not el:
                    continue
                el = el[:1].upper() + el[1:].lower()
                if el not in ELEMENTS:
                    raise ValueError(f'"{el}" is not a chemical element symbol.')
                if el in elements:
                    raise ValueError(f'{el} is listed twice.')
                expected = parse_cell(self.table.item(i, 1).text() if self.table.item(i, 1) else '', f'{el} expected concentration')
                if expected is None or expected <= 0:
                    raise ValueError(f'{el}: enter the expected concentration in this vial (mg/L).')
                elements.append(el)
                ratio = expected / level
                if abs(ratio - 1) > 1e-12:
                    mult[el] = ratio
            if not elements:
                raise ValueError('List at least one element contained in this standard.')
            return level, ','.join(elements), mult


