    class IdentifyDialog(QDialog):
        """Confirm or correct ONE measurement. Commits into a draft project copy."""

        def __init__(self, project, sequence, parent=None, question=''):
            super().__init__(parent)
            self.setWindowTitle(f'Identify sequence {sequence}')
            self.setMinimumWidth(680)
            self.project = copy.deepcopy(project)
            self.sequence = sequence
            a = self.project.assignments[sequence]
            records = grouped_readings(self.project)[sequence]
            names = list(dict.fromkeys([a.sample_id] + [r.sample_id for r in records]
                                       + [r.mapped_sample_id for r in records if r.mapped_sample_id]))
            v = QVBoxLayout(self)
            if question:
                v.addWidget(question_banner(self, question))
            intro = QLabel(f'Measurement {sequence}, tray position {a.position}. Your answer is saved with the project.')
            intro.setWordWrap(True)
            v.addWidget(intro)
            grid = QGridLayout()
            self.name = QComboBox()
            self.name.addItems(names)
            self.name.setEditable(True)
            self.role = QComboBox()
            self.role.addItems(ROLES)
            self.role.setCurrentText(a.role)
            grid.addWidget(QLabel('Identity to use:'), 0, 0)
            grid.addWidget(self.name, 0, 1)
            grid.addWidget(QLabel('Measurement role:'), 1, 0)
            grid.addWidget(self.role, 1, 1)
            v.addLayout(grid)
            self.composition = CompositionEditor()
            self.composition.set_values(a.standard_level if a.standard_level else self._label_level(a.sample_id),
                                        a.standard_element, a.standard_multipliers)
            self.composition.select_group_for(a.sample_id)
            v.addWidget(self.composition)
            self.known = QPushButton('Fill from library')
            v.addWidget(self.known)
            self.reason = QLineEdit()
            self.reason.setPlaceholderText('Note (optional), for example when the standard was prepared')
            v.addWidget(self.reason)
            buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
            v.addWidget(buttons)
            buttons.accepted.connect(self.apply)
            buttons.rejected.connect(self.reject)
            self.role.currentTextChanged.connect(self.toggle)
            self.known.clicked.connect(self.fill_known)
            self.toggle()

        @staticmethod
        def _label_level(text):
            m = STANDARD_LEVEL_RE.search(str(text))
            try:
                return label_number(m.group(1)) if m else None
            except ValueError:
                return None

        def toggle(self, *_):
            on = self.role.currentText() == 'Standard'
            self.composition.setVisible(on)
            self.known.setVisible(on)

        def fill_known(self):
            scope, mult, _ = standard_scope(self.name.currentText(), load_library())
            if scope == '?':
                ui.info(self, 'Unknown standard', 'This standard is not in the library. Enter the elements it contains and their concentration.')
                return
            level = self._label_level(self.name.currentText())
            self.composition.set_values(level, scope, mult)

        def apply(self):
            try:
                a = self.project.assignments[self.sequence]
                old_role = a.role
                updated = copy.deepcopy(a)
                updated.sample_id = self.name.currentText().strip()
                updated.role = self.role.currentText()
                updated.standard_level, updated.standard_element, updated.standard_multipliers = None, '?', {}
                updated.scope_source = 'Analyst-confirmed identification'
                if updated.role == 'Standard':
                    updated.standard_level, updated.standard_element, updated.standard_multipliers = self.composition.values()
                    validate_standard(updated)
                if updated.role == 'Sample':
                    if not updated.report_name or updated.report_name == a.sample_id:
                        updated.report_name = updated.sample_id
                    if old_role != 'Sample':
                        updated.report = True
                else:
                    updated.report = False
                draft = copy.deepcopy(self.project)
                draft.assignments[self.sequence] = updated
                remember_override(draft, updated, self.reason.text())
                self.project = draft
                self.accept()
            except (ValueError, TypeError) as exc:
                ui.warn(self, 'Check identification', exc)


    class GroupStandardDialog(QDialog):
        """One composition answer for several measurements of the same unknown standard."""

        def __init__(self, project, sequences, parent=None, question=''):
            super().__init__(parent)
            self.setWindowTitle('Identify a standard')
            self.setMinimumWidth(720)
            self.project = copy.deepcopy(project)
            self.sequences = list(sequences)
            v = QVBoxLayout(self)
            if question:
                v.addWidget(question_banner(self, question))
            listing = QTableWidget(0, 4)
            listing.setHorizontalHeaderLabels(['Sequence', 'Label', 'Prepared level (from label)', 'Position in run'])
            table_setup(listing, stretch_cols=(1,), minimum_height=120)
            samples = sorted(a.sequence for a in self.project.assignments.values() if a.role == 'Sample')
            for s in self.sequences:
                a = self.project.assignments[s]
                i = listing.rowCount()
                listing.insertRow(i)
                where = 'before samples' if samples and s < samples[0] else 'after samples' if samples and s > samples[-1] else ''
                for c, val in enumerate((s, a.sample_id, numeric_text(IdentifyDialog._label_level(a.sample_id)), where)):
                    listing.setItem(i, c, readonly(val))
            v.addWidget(QLabel('The same composition is saved for these measurements.'))
            v.addWidget(listing)
            self.composition = CompositionEditor()
            first = self.project.assignments[self.sequences[0]]
            self.composition.set_values(IdentifyDialog._label_level(first.sample_id), '', {})
            self.composition.level.setToolTip('Used to express the expected concentrations below; '
                                              'each measurement then uses the level on its own label.')
            v.addWidget(self.composition)
            self.reason = QLineEdit()
            self.reason.setPlaceholderText('Note (optional), for example when the standard was prepared')
            v.addWidget(self.reason)
            buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
            v.addWidget(buttons)
            buttons.accepted.connect(self.apply)
            buttons.rejected.connect(self.reject)

        def apply(self):
            try:
                level, elements, mult = self.composition.values()
                draft = copy.deepcopy(self.project)
                remember_group_standard(draft, self.sequences, elements, mult, self.reason.text())
                self.project = draft
                self.accept()
            except (ValueError, TypeError) as exc:
                ui.warn(self, 'Check the composition', exc)


    class IdentificationDetailsDialog(QDialog):
        """Optional read-only overview with Edit for a selected measurement."""

        def __init__(self, project, parent=None):
            super().__init__(parent)
            self.setWindowTitle('Identification')
            self.resize(1080, 640)
            self.project = copy.deepcopy(project)
            self.changed = False
            v = QVBoxLayout(self)
            v.addWidget(QLabel('Select a row and click Edit to correct it.'))
            self.table = QTableWidget(0, 7)
            self.table.setHorizontalHeaderLabels(['Sequence', 'A/S pos', 'Identity', 'Role', 'Std mg/L', 'Standard elements', 'Evidence'])
            table_setup(self.table, stretch_cols=(2, 6), minimum_height=380)
            v.addWidget(self.table)
            row = QHBoxLayout()
