        def initializePage(self):
            self.refresh()

        def set_sources(self, replicates, autosampler, demo=False, summary='', notes=(), dissolution=None):
            """dissolution: a path, '' for none, or None to keep the current one (or find one next to the measurements)."""
            h = self.host
            if dissolution is None:
                dissolution = h.dissolution_path
                if not dissolution and replicates and not demo:
                    folder = Path(str(replicates[0])).parent
                    try:
                        dissolution = find_dissolution_file([str(x) for x in folder.iterdir() if x.is_file()]) or ''
                    except OSError:
                        dissolution = ''
            archive = h.archive_dir
            sources = [str(p) for p in replicates] + ([str(autosampler)] if autosampler else []) + ([str(summary)] if summary else [])
            keep = archive if archive and any(Path(p).resolve().is_relative_to(Path(archive).resolve()) for p in sources) else None
            if keep:
                h.archive_dir = None
            h.reset_project()
            if keep:
                h.archive_dir = keep
            h.replicate_paths = list(replicates)
            h.autosampler_path = str(autosampler or '')
            h.summary_path = str(summary or '')
            h.dissolution_path = str(dissolution or '')
            h.paths = list(replicates) + ([str(autosampler)] if autosampler else []) + ([h.summary_path] if h.summary_path else []) \
                + ([h.dissolution_path] if h.dissolution_path else [])
            h.is_demo = bool(demo)
            self.found_notes = list(notes)
            self.session_line = ''
            self.refresh()

        @staticmethod
        def _needs_action(note):
            return 'is also here' in note or 'More than one' in note or 'possible replicate' in note

        @staticmethod
        def _hint(note):
            if 'is also here' in note:
                name = note.split(' is also here')[0]
                return f'A PDF of this session ({name}) is also here. Add it for a second check (about 1 minute).'
            return note

        def refresh(self):
            h = self.host
            self.replicates.clear()
            for p in h.replicate_paths:
                item = QListWidgetItem(f'{Path(p).name}   ({Path(p).suffix.upper()[1:]})')
                item.setToolTip(p)
                item.setData(Qt.UserRole, 'measurement')
                self.replicates.addItem(item)
            if h.summary_path and not h.is_demo:
                item = QListWidgetItem(f'{Path(h.summary_path).name}   (check only)')
                item.setToolTip(h.summary_path)
                item.setData(Qt.UserRole, 'summary')
                self.replicates.addItem(item)
            self.map_line.setText(h.autosampler_path)
            self.diss_line.setText(h.dissolution_path)
            self.diss_clear_btn.setEnabled(bool(h.dissolution_path))
            hints = ([getattr(self, 'session_line', '')] if getattr(self, 'session_line', '') else []) + \
                [self._hint(n) for n in self.found_notes if self._needs_action(n)]
            self.found_label.setText('\n'.join(hints))
            self.found_label.setVisible(bool(hints))
            if h.is_demo:
                self.status.setText(('Solid demo loaded: invented solid samples with a dissolution file' if h.dissolution_path
                                     else 'Liquid demo loaded: invented water samples') + ', no real measurements. Click Next.')
                w.set_tone(self.status, 'ok')
            elif h.project is not None and h.loaded_paths == h.paths:
                self.status.setText('Saved Plasmatti project loaded with its cached measurements and decisions. Click Next.')
                w.set_tone(self.status, 'ok')
            elif h.replicate_paths and h.autosampler_path:
                self.status.setText('Measurements and autosampler file selected. Click Next to import and check the run.')
                w.set_tone(self.status, 'info')
            elif h.replicate_paths:
                self.status.setText('Measurements selected. No autosampler file: the instrument\'s own sample labels will be used '
                                    '(Plasmatti asks for the file if the measurements carry no names). Click Next.')
                w.set_tone(self.status, 'info')
            else:
                self.status.setText('Choose a measurement file.')
                w.set_tone(self.status, 'info')
            self.completeChanged.emit()

        def isComplete(self):
            h = self.host
            return bool(h.project is not None and h.loaded_paths == h.paths) or bool(h.replicate_paths)

        def pick_replicates(self):
            paths, _ = QFileDialog.getOpenFileNames(self, 'Choose measurement file', '',
                                                    'Measurement files (*.csv *.pdf *.xls *.xlsx *.xlsm)')
            if not paths:
                return
            if any(Path(p).suffix.lower() not in MEASUREMENT_TYPES for p in paths):
                ui.warn(self, 'Measurement file', 'This file type is not supported. Use the PerkinElmer CSV or PDF, or an Excel report.')
                return
            if len({Path(p).suffix.lower() for p in paths}) != len(paths):
                ui.warn(self, 'Measurement file', 'Choose at most one file of each type.')
                return
            h = self.host
            folder = Path(paths[0]).resolve().parent
            current = {Path(p).resolve().parent for p in h.replicate_paths}
            same_session = bool(h.replicate_paths) and current == {folder} and not h.is_demo
            if same_session:
                # Another file of the same session (e.g. the PDF next to the CSV): keep what is already chosen.
                selected = {Path(p).suffix.lower(): p for p in h.replicate_paths}
                for p in paths:
                    selected[Path(p).suffix.lower()] = p
                chosen = [selected[k] for k in MEASUREMENT_TYPES if k in selected]
                found = discover_run_files(chosen)
                self.set_sources(found['replicates'] or chosen, h.autosampler_path or found['autosampler'],
                                 summary=found['summary'], notes=found['notes'])
                return
            # A new session: nothing of the previous session is kept; the files next to the new one are used.
            had_previous = bool(h.replicate_paths or h.autosampler_path or h.dissolution_path or h.summary_path)
            chosen = [p for k in MEASUREMENT_TYPES for p in paths if Path(p).suffix.lower() == k]
            found = discover_run_files(chosen)
            try:
                others = [str(x) for x in folder.iterdir() if x.is_file() and str(x) not in chosen]
            except OSError:
                others = []
            dissolution = find_dissolution_file([p for p in others if p != found['autosampler'] and p != found['summary']]) or ''
            self.set_sources(found['replicates'] or chosen, found['autosampler'], summary=found['summary'],
                             notes=found['notes'], dissolution=dissolution)
            taken = [x for x, v in (('the autosampler file', found['autosampler']), ('the dissolution file', dissolution)) if v]
            missing = [x for x, v in (('autosampler file', found['autosampler']), ('dissolution file', dissolution)) if not v]
            line = (f'New session: {" and ".join(taken)} {"were" if len(taken) > 1 else "was"} taken from the folder of '
                    f'{Path(chosen[0]).name}.' if taken else f'New session from {Path(chosen[0]).name}.')
            if missing:
                line += ' No ' + ' or '.join(missing) + ' was found next to it.'
            if had_previous:
                line += ' The files of the previous session were removed.'
            self.session_line = line
            self.refresh()

        def remove_replicate(self):
            row = self.replicates.currentRow()
            if row < 0:
                return
            kind = self.replicates.item(row).data(Qt.UserRole)
            if kind == 'summary':
                self.set_sources(self.host.replicate_paths, self.host.autosampler_path, summary='', notes=self.found_notes)
                return
            self.set_sources([p for i, p in enumerate(self.host.replicate_paths) if i != row], self.host.autosampler_path,
                             summary=self.host.summary_path, notes=self.found_notes)

        def pick_autosampler(self):
            path, _ = QFileDialog.getOpenFileName(self, 'Choose autosampler file', '', 'Autosampler (*.xls *.xlsx *.csv)')
            if not path:
                return
            try:
                mapping, _ = w.run_task(self, 'Checking autosampler file', lambda: parse_autosampler(path))
                if not mapping:
                    raise ValueError('The autosampler file is empty.')
                self.set_sources(self.host.replicate_paths, path, summary=self.host.summary_path, notes=self.found_notes)
            except Exception as exc:
                ui.warn(self, 'Autosampler file not usable', exc)

        def pick_dissolution(self):
            path, _ = QFileDialog.getOpenFileName(self, 'Choose the dissolution file', '', 'Dissolution file (*.xls *.xlsx *.csv)')
            if not path:
                return
            info = w.run_task(self, 'Reading the dissolution file', lambda: read_dissolution_file(path))
            if not info['entries']:
                ui.warn(self, 'Dissolution file', 'No sample with a mass could be read from this file. ' + ' '.join(info['problems']) +
                        '\n\nThe file is kept; in step 3 you can enter the values yourself.')
            self.set_sources(self.host.replicate_paths, self.host.autosampler_path, summary=self.host.summary_path,
                             notes=self.found_notes, dissolution=path)

        def demo(self):
            try:
                csv_path, map_path = demo_paths()
            except FileNotFoundError as exc:
                ui.warn(self, 'Demo missing', exc)
                return
            self.set_sources([csv_path], map_path, demo=True, dissolution='')

        def solid_demo(self):
            try:
                csv_path, map_path, diss_path = solid_demo_paths()
            except FileNotFoundError as exc:
                ui.warn(self, 'Demo missing', exc)
                return
            self.set_sources([csv_path], map_path, demo=True, dissolution=diss_path)

        def _select_from_run(self, paths):
            """Pick the replicate export(s) and the autosampler file from a run folder.

        Only files whose names say what they are are suggested; an arbitrary
        spreadsheet next to a CSV is not assumed to be the autosampler file.
        """
            reps = [p for p in paths if (Path(p).suffix.lower() == '.pdf' and classify_pdf(p) == 'replicate') or
                    (Path(p).suffix.lower() == '.csv' and classify_csv(p) == 'replicate')]
            found = {}
            for p in reps:
                ext = Path(p).suffix.lower()
                if ext in found:
                    raise ValueError(f'More than one replicate {ext} file in this folder. Choose the matching files manually.')
                found[ext] = p
            maps = [p for p in paths if 'autosampler' in Path(p).stem.casefold() and Path(p).suffix.lower() in ('.xls', '.xlsx', '.csv')]
            if not found:
                raise ValueError('No PerkinElmer replicate CSV/PDF export was found in this folder.')
            if len(maps) > 1:
                raise ValueError('More than one autosampler file found. Choose one manually.')
            chosen = [found[k] for k in ('.csv', '.pdf') if k in found]
            disc = discover_run_files(chosen, include_pdf=True)
            others = [p for p in paths if p not in chosen and p not in maps and p != disc['summary']]
            self.set_sources(chosen, maps[0] if maps else disc['autosampler'], summary=disc['summary'],
                             notes=[n for n in disc['notes'] if 'Autosampler file' not in n],
                             dissolution=find_dissolution_file(others) or '')
            if not maps and not disc['autosampler']:
                ui.info(self, 'Autosampler file', 'No file named as an autosampler file was found. Choose it with '
                        '"Choose file" next to the autosampler file.')

        def pick_folder(self):
            folder = QFileDialog.getExistingDirectory(self, 'Select one analytical run folder')
            if not folder:
                return
            try:
                runs = w.run_task(self, 'Indexing run folders', lambda: index_history(folder))
                if len(runs) > 1:
                    run = self._choose_run(runs)
                    if run is None:
                        return
                    paths = [str(Path(folder) / x) for x in run.files]
                elif len(runs) == 1:
                    paths = [str(Path(folder) / x) for x in runs[0].files]
                else:
                    paths = [str(p) for p in Path(folder).iterdir() if p.is_file()]
                self._select_from_run(paths)
            except Exception as exc:
                ui.warn(self, 'Run folder import failed', exc)

        def _choose_run(self, runs):
            return w.pick_history_run(self, runs)

        def pick_archive(self):
            path, _ = QFileDialog.getOpenFileName(self, 'Open a ZIP file of sessions', '', 'ZIP archives (*.zip)')
            if not path:
                return
            try:
                runs = w.run_task(self, 'Indexing history ZIP', lambda: index_history(path))
                run = self._choose_run(runs) if runs else None
                if run is None:
                    return
                self.host.reset_project()
                self.host.archive_dir = tempfile.mkdtemp(prefix='plasmati_history_')
                paths = w.run_task(self, 'Extracting the selected run', lambda d=self.host.archive_dir: materialize_run(path, run, d))
                self._select_from_run(paths)
            except Exception as exc:
                ui.warn(self, 'History archive import failed', exc)

        def open_saved(self):
            path, _ = QFileDialog.getOpenFileName(self, 'Open Plasmatti project', '', 'Plasmatti projects (*.plasmati.json);;JSON (*.json)')
            if path:
                self.load_saved(path)

        def load_saved(self, path):
            try:
                project = w.run_task(self, 'Loading Plasmatti project', lambda: load_project(path))
            except Exception as exc:
                ui.warn(self, 'Project not loaded', exc)
                return False
            h = self.host
            h.reset_project()
            h.paths = list(project.source_paths)
            h.dissolution_path = str((project.extra_fields.get(DISSOLUTION_KEY) or {}).get('path', ''))
            h.replicate_paths = [p for p in h.paths if Path(p).suffix.lower() in ('.csv', '.pdf') and p != h.dissolution_path
                                 and 'autosampler' not in Path(p).stem.casefold()]
            h.autosampler_path = next((p for p in h.paths if 'autosampler' in Path(p).stem.casefold()), '')
            if h.dissolution_path:
                h.paths = [x for x in h.paths if x != h.dissolution_path] + [h.dissolution_path]
            h.summary_path = next((p for p in h.paths if Path(p).suffix.lower() in ('.xls', '.xlsx') and p != h.dissolution_path
                                   and p != h.autosampler_path and 'autosampler' not in Path(p).stem.casefold()), '')
            h.loaded_paths = list(h.paths)
            h.is_demo = project.demo
            h.set_project(project)
            h.fresh_project = False
            self.refresh()
            if project.migration_notes:
                ui.info(self, 'Older project updated', '\n\n'.join(project.migration_notes))
            return True

        def validatePage(self):
            h = self.host
            if not self.isComplete():
                ui.warn(self, 'Import', 'Choose a measurement file.')
                return False
            try:
                if h.project is None or h.loaded_paths != h.paths:
                    if h.is_demo and h.dissolution_path:
                        project = w.run_task(self, 'Loading the solid demo session', load_solid_demo)
                    elif h.is_demo:
                        project = w.run_task(self, 'Loading the demo session', load_demo)
                    else:
                        def work(paths=list(h.paths), amap=h.autosampler_path, diss=h.dissolution_path):
                            details = {}
                            measured = [x for x in paths if x != diss]
                            readings, notes = core.load_files(measured, autosampler_path=amap, details=details)
                            check_sample_names(readings, bool(amap))
                            project = core.make_project(readings, measured, demo=False, warnings=notes, source_comparison=details)
                            if diss:
                                project.extra_fields[DISSOLUTION_KEY] = read_dissolution_file(diss)
                            return project
                        project = w.run_task(self, 'Importing measurements and identifying the run', work)
                    h.set_project(project)
                    h.fresh_project = True
                    h.loaded_paths = list(h.paths)
                h.check_identification(self)
                return True
            except Exception as exc:
                ui.warn(self, 'Could not import the run', exc)
                return False

        def nextId(self):
            return self.host.route(after=IMPORT)


