    class QuestionsPage(Page):
        def __init__(self):
            super().__init__()
            self.setTitle(step_title(QUESTIONS))
            self.setSubTitle('Plasmatti needs your answer.')
            v = QVBoxLayout(self)
            w.help_row(v, self, 'Answer the questions below, if there are any, then click Next.', 'Questions help', QUESTIONS_HELP)
            self.panel = w.QuestionsPanel(lambda: self.project, self._set_project)
            v.addWidget(self.panel, 1)

        def _set_project(self, project, report):
            self.host.set_project(project, report)
            self.completeChanged.emit()

        def initializePage(self):
            self.panel.show_report(self.host.report)
            self._subtitle()

        def _subtitle(self):
            ready = bool(self.host.report and self.host.report['ready'])
            self.setSubTitle('No questions to answer. Click Next to continue.' if ready else 'Plasmatti needs your answer.')

        def isComplete(self):
            self._subtitle()
            return bool(self.host.report and self.host.report['ready'])

        def nextId(self):
            return self.host.route(after=QUESTIONS)


